interface BulkPayloadMessages {
    messages: Array<{
        role: string;
        content: string;
        custom: {
            interview_mode: boolean;
            practice_mode: boolean;
            practice_count?: string | null;
            interview_count?: string | null;
            url: string;
        };
        createdAt: number;
    }>;
}

const useBulkMessages = () => {

    const parseChatMessagesForBulkMessagesPayload = (
        chatMessages: any[],
    ): BulkPayloadMessages | null => {
        if (!chatMessages || chatMessages.length === 0) {
            return null;
        }

        const messages = chatMessages.map((chatMessage: any) => ({
            role: chatMessage.sent_by || 'assistant',
            content: chatMessage.text || '',
            custom: {
                interview_mode: `${chatMessage?.custom?.interview_mode || false}`,
                practice_mode: `${chatMessage?.custom?.practice_mode || false}`,
                ...(chatMessage?.custom?.interview_mode && { interview_count: chatMessage?.custom?.interview_count || '0' }),
                ...(chatMessage?.custom?.practice_mode && { practice_count: chatMessage?.custom?.practice_count || '0' }),
                url: chatMessage?.custom?.url || window.location.href,
            },
            createdAt: chatMessage.createdAt || Date.now(),
        }));

        return {
            messages,
        };
    };

    return {
        parseChatMessagesForBulkMessagesPayload,
    };
};

export default useBulkMessages;