import { useEffect, useState } from "react";

const useMessageContainer = (m: any) => {
  function hasExactlyTwoOccurrences(targetString: string, pattern = "#-#-#") {
    // Count the number of occurrences of the pattern in the string
    const occurrences = targetString.split(pattern).length - 1;
    return occurrences === 2;
  }
  const parseText = (resourceString: string) => {
    const _uiComponents: any[] = [];
    const correctStructurePresent = hasExactlyTwoOccurrences(resourceString);
    const splitText = resourceString
      ?.split(correctStructurePresent ? "#-#-#" : "#-#")
      .map((value, index) => ({
        splitTextIndex: index,
        splitTextValue: value.trim(),
      }));
    const marker = {
      easyActionStart: "[easy action start]",
      easyActionEnd: "[easy action end]",
    };

    for (let i = 0; i < splitText?.length; i++) {
      const { splitTextIndex, splitTextValue } = splitText[i];
      const textDetails = splitTextValue.trim();
      
      if (textDetails.includes(marker.easyActionStart)) {
        const startIndex =
          textDetails.indexOf(marker.easyActionStart) +
          marker.easyActionStart.length;
        if (textDetails.includes(marker.easyActionEnd)) {
          const endIndex = textDetails.indexOf(marker.easyActionEnd);
          const easyActionData = textDetails.substring(startIndex, endIndex);
          try {
            const easyActionObject = JSON.parse(easyActionData);
            easyActionObject.slide_index_count = splitTextIndex;
            _uiComponents.push(easyActionObject);
          } catch (e) {
            console.error("Error Parsing quiz data", e);
          }
        }
      } else {
        _uiComponents.push({
          type: "text",
          // @ts-ignore
          data: textDetails.replaceAll(/\\n/g, "\n"),
        });
      }
    }

    return _uiComponents;
  };

  const [uiComponents, setUiComponents] = useState<any[]>(
    parseText(m.props.model.message) || []
  );

  useEffect(() => {
    setUiComponents(parseText(m.props.model.message));
  }, []);

  return { uiComponents };
};

export default useMessageContainer;