import LeetCode from "../../assets/leetcode.svg?react";
import Youtube from "../../assets/youtube.svg?react";
import ArrowIcon from "../../assets/arrow-line.svg?react";

type ResourceItem = {
  title: string;
  url: string;
  icon: any;
  problemType: "Practice Problems" | "Videos";
  difficulty?: string;
};

type Props = {
  menteeData: any;
};

const ResourcesView = ({ menteeData }: Props) => {
  const handleResourceClick = async (resource: ResourceItem) => {
    chrome.runtime.sendMessage({
      action: "sendAnalytics",
      url: window.location.href,
      eventName: "Sample Resources Clicked",
      eventProperties: {
        resource_type: resource.problemType,
        resource_title: resource.title,
        resource_url: resource.url,
        platform: resource.problemType === "Practice Problems" ? "LeetCode" : "YouTube"
      }
    });

    const { sample_resources_practice_mode_variant } = await chrome.storage.local.get("sample_resources_practice_mode_variant");
    const shouldAddPracticeMode = sample_resources_practice_mode_variant === "enabled";
    let finalUrl = resource.url;

    if (shouldAddPracticeMode && resource.problemType === "Practice Problems") {
      const url = new URL(resource.url);
      url.searchParams.set('practice_mode_session', 'true');
      finalUrl = url.toString();
    }

    window.open(finalUrl, '_blank', 'noopener,noreferrer');
  };

  const leetCodeResources: ResourceItem[] = [
    {
      title: "Two Sum Problem",
      difficulty: "Easy",
      url: "https://leetcode.com/problems/two-sum",
      icon: LeetCode,
      problemType: "Practice Problems" as const,
    },
    {
      title: "Longest Substring",
      difficulty: "Medium",
      url: "https://leetcode.com/problems/longest-substring-without-repeating-characters/description",
      icon: LeetCode,
      problemType: "Practice Problems" as const,
    },
  ];

  const youtubeResources: ResourceItem[] = [
    {
      title: "Find element that appears once | Find missing number | Max Consecutive number of 1's | Arrays Part-3",
      url: "https://www.youtube.com/watch?v=bYWLJb3vCWY",
      icon: Youtube,
      problemType: "Videos" as const,
    },
    {
      title: "How to Start LeetCode from ZERO in 2025",
      url: "https://www.youtube.com/watch?v=G5_Q2_yRFsY",
      icon: Youtube,
      problemType: "Videos" as const,
    },
  ];

  let menteeFirstName = menteeData?.name?.split(" ")?.[0];

  return (
    <>
      <div className="p-2 w-full h-full flex flex-col items-center justify-center space-y-10">
        <p className="text-white text-[20px] leading-[24px] font-semibold font-bricolage-grotesque">
          Welcome, {menteeFirstName}!<br />
          Discover all the things you can do with Leeco.
        </p>

        <div className="space-y-7 w-full max-h-[calc(100vh-150px)] overflow-y-auto scrollbar-hide">
          <div className="w-full border border-[#222430] rounded-xl p-3 flex flex-col gap-4">
            <div className="flex items-center gap-2">
              <div className="w-9 h-9 bg-white rounded-full flex items-center justify-center">
                <LeetCode className="w-[26px] h-[26px]" />
              </div>

              <div className="flex flex-col gap-0.5">
                <h3 className="text-white font-bricolage-grotesque font-medium text-base leading-[1.2] tracking-[0.5%]">
                  Leetcode
                </h3>
                <p className="text-white/60 text-[11px] leading-[1.636] tracking-[1%]">
                  Solve Leetcode Problems With Leeco's Assistance
                </p>
              </div>
            </div>

            <hr className="border-[#222430]" />

            <div className="flex flex-col gap-2.5">
              {leetCodeResources.map((resource) => (
                <div
                  key={resource.title}
                  className="bg-[#1e202b] rounded-xl p-3 flex items-center justify-between gap-3 cursor-pointer hover:bg-[#2a2d3a] transition-colors"
                  onClick={() => handleResourceClick(resource)}
                >
                  <div className="flex items-center gap-1">
                    <span className="text-white font-bricolage-grotesque font-medium text-[13px]">
                      {resource.title}
                    </span>
                    <span className="text-white/60 text-xs tracking-[1%]">({resource.difficulty})</span>
                  </div>
                  <ArrowIcon className="min-w-[20px] w-5 h-5" />
                </div>
              ))}
            </div>
          </div>

          <div className="w-full border border-[#222430] rounded-xl p-3 flex flex-col gap-4">
            <div className="flex items-center gap-2">
              <div className="w-9 h-9 bg-white rounded-full flex items-center justify-center">
                <Youtube className="w-[26px] h-[26px]" />
              </div>

              <div className="flex flex-col gap-0.5">
                <h3 className="text-white font-bricolage-grotesque font-medium text-base leading-[1.2] tracking-[0.5%]">
                  Youtube
                </h3>
                <p className="text-white/60 text-[11px] leading-[1.636] tracking-[1%]">
                  Learn with interactive quizzes on youtube videos
                </p>
              </div>
            </div>

            <hr className="border-[#222430]" />

            <div className="flex flex-col gap-2.5">
              {youtubeResources.map((resource) => (
                <div
                  key={resource.title}
                  className="bg-[#1e202b] rounded-xl p-3 flex items-center justify-between gap-3 cursor-pointer hover:bg-[#2a2d3a] transition-colors"
                  onClick={() => handleResourceClick(resource)}
                >
                  <span className="text-white font-bricolage-grotesque font-medium text-[13px] truncate">
                    {resource.title}
                  </span>

                  <ArrowIcon className="min-w-[20px] w-5 h-5" />
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

export default ResourcesView;
