import React from 'react'
import { cn } from '../../../utils/cn';

const MentorAiActiveAvatar = ({ mentoraiData, avatarClassName, indicatorClassName, isPlayerModeDefault, avatarSrcOrUrl, containerClassName }: { mentoraiData?: any, avatarClassName?: string, indicatorClassName?: string, isPlayerModeDefault?: boolean, avatarSrcOrUrl?: any, containerClassName?: string }) => {
    return (
        <>
            {(mentoraiData || avatarSrcOrUrl) && (
                <div className={cn("relative", containerClassName)}>
                    {mentoraiData?.photoUrl || mentoraiData?.aiPhotoUrl || avatarSrcOrUrl ? (
                        <img
                            src={avatarSrcOrUrl || mentoraiData?.photoUrl || mentoraiData?.aiPhotoUrl}
                            className={cn("h-[20px] w-[20px] rounded-full object-cover ", isPlayerModeDefault ? "h-[16px] w-[16px]" : "h-[20px] w-[20px]", avatarClassName)}
                            alt="avatar"
                            style={{
                                minWidth: "20px",
                                minHeight: "20px"
                            }}
                        />
                    ) : (
                        <div className={cn("w-[20px] h-[20px] rounded-full bg-[#000]", isPlayerModeDefault ? "w-[16px] h-[16px]" : "w-[20px] h-[20px]", avatarClassName)} />
                    )}
                    <span className={cn("absolute -bottom-[1px] -right-[2px] border-[2px] border-[#000] w-[8px] h-[8px] rounded-full bg-[#1FC16B]", indicatorClassName)} />
                </div>
            )}
        </>
    )
}

export default MentorAiActiveAvatar;