import { useState } from 'react'
// import PlansSheet from '../extension-paywall/plans-sheet/plans-sheet'
import PlansSheet from '../extension-paywall/plan-sheet-new/plan-sheet-new'
import BottomSheet from '../../../../common/bottom-sheet/bottom-sheet'
import { ChatUsageData } from '../../../context/chat-context/use-chat-conversations'

type Props = {
  children: React.ReactNode
  chatUsageData: ChatUsageData
  buttonId: string
  className?: string
  bannerType?: "daily-limit-left" | "limited-free-plan"
  headerType: "unlock-pro" | "free-credits-exhausted" | "available-credits"
  actionLocation: string
  disabled?: boolean
}

const PurchaseSheetButton = ({ children, className, buttonId, chatUsageData, headerType, bannerType, actionLocation, disabled = false}: Props) => {
  const [isPlansSheetOpen, setIsPlansSheetOpen] = useState(false)

  const handleOpenPlansSheet = () => {
    if (!disabled) {
      setIsPlansSheetOpen(true)
    }
  }

  return (
    <>
      <button 
        onClick={handleOpenPlansSheet} 
        disabled={disabled}
        className={`${className} ${disabled ? ' cursor-default' : ''}`}
      >
        {children}
      </button>
      <BottomSheet open={isPlansSheetOpen} handleClose={() => setIsPlansSheetOpen(false)}>
        <PlansSheet handleClose={() => setIsPlansSheetOpen(false)} chatUsageData={chatUsageData} bannerType={bannerType} headerType={headerType} buttonId={buttonId}  actionLocation={actionLocation}/>
      </BottomSheet>
    </>
  )
}

export default PurchaseSheetButton