import { useRef, useState } from "react";
import { useSidepanelSyncContext } from "../context/sidepanel-sync-context/sidepanel-sync-context";

export function useAudioRecorder(inputText: string) {
  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null); // Add this line
  const audioChunksRef = useRef<BlobPart[]>([]);
  const [transcription, setTranscription] = useState<string>("");
  const [isTranscriptionLoading, setIsTranscriptionLoading] = useState(false);
  const wasCancelledRef = useRef(false);
  const { setIsAudioLive } = useSidepanelSyncContext();

  const transcribeAudio = async (formData: any) => {
    try {
        setIsTranscriptionLoading(true);
        const response = await fetch(`${import.meta.env.VITE_PREPLACED_BACKEND_AI_URL}/resources/transcribe_audio`, {
            method: "POST",
            body: formData,
          });
    
        if (!response.body) {
          throw new Error("No response body received for sections generation");
        }
    
        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let isFirstChunk = true;
    
        while (true) {
          const { done, value } = await reader.read();
          if (done){
            break;
          }  
          const chunk = decoder.decode(value, { stream: true });
          
          // Set states only when first chunk is received
          if (isFirstChunk) {
            setIsTranscriptionLoading(false);
            setIsAudioLive(false);
            isFirstChunk = false;
          }
          setTranscription(prev => prev + chunk);
        }
    } catch (error) {
      console.error("Error in fetchSectionsStreaming:", error);
      throw error;
    }finally{
      setIsTranscriptionLoading(false);
      setIsAudioLive(false);
    }
  }

  const startRecording = async () => {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    mediaStreamRef.current = stream; // Store the stream reference
    const recorder = new MediaRecorder(stream);
    audioChunksRef.current = [];

    recorder.ondataavailable = (e) => {
      audioChunksRef.current.push(e.data);
    };

    recorder.onstop = async () => {
      // Stop all media stream tracks to release microphone access
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(track => track.stop());
        mediaStreamRef.current = null;
      }

      if (wasCancelledRef.current) {
        wasCancelledRef.current = false;
        setIsRecording(false);
        chrome.storage.local.set({
          toggleMicrophone: false
        })
        return;
      }      
      
      const audioBlob = new Blob(audioChunksRef.current, { type: "audio/webm" });
      const formData = new FormData();
      formData.append("audio", audioBlob, "audio.webm");

      try {
        await transcribeAudio(formData);
      } catch (error) {
        console.error("Transcription upload failed:", error);
      }

      setIsRecording(false);
      chrome.storage.local.set({
        toggleMicrophone: false
      })  
    };

    recorder.start();
    mediaRecorderRef.current = recorder;
    setIsRecording(true);
    setTranscription(inputText);
  };

  const stopRecording = (wasCancelled: boolean) => {
    wasCancelledRef.current = wasCancelled;
    
    // Stop the MediaRecorder
    mediaRecorderRef.current?.stop();
    
    // Immediately stop media stream tracks for cancelled recordings
    if (wasCancelled && mediaStreamRef.current) {
      mediaStreamRef.current.getTracks().forEach(track => track.stop());
      mediaStreamRef.current = null;
    }
    
    chrome.storage.local.set({
      toggleMicrophone: false
    })
  };

  return {
    isRecording,
    startRecording,
    stopRecording,
    transcription,
    isTranscriptionLoading,
  };
}
