import { createContext } from 'react';

type AuthContextType = {
  currentUser: any,
  setCurrentUser: Function,
  isUserLoggedIn: boolean,
  setIsUserLoggedIn: Function,
  isAuthLoading: boolean,
  setIsAuthLoading: Function
  activeTabUrl: string
  setActiveTabUrl: Function
}

const defaultFunction = () => {
  console.log('Default function called');
};

const defaultContextValues: AuthContextType = {
  currentUser: null,
  setCurrentUser: defaultFunction,
  isUserLoggedIn: false,
  setIsUserLoggedIn: defaultFunction,
  isAuthLoading: false,
  setIsAuthLoading: defaultFunction,
  activeTabUrl: '',
  setActiveTabUrl: defaultFunction
};

export const AuthContext = createContext<AuthContextType>(defaultContextValues);