import Modal from '../../../../common/modal/modal'
import useSignIn from '../../../screens/sign-in/use-sign-in'
import PreplacedLogoBlack from '../../../assets/preplaced-logo-black.svg'

type SignupModalProps = {
    show: boolean
    handleClose: () => void
}

const SignupModal = ({ show, handleClose }: SignupModalProps) => {

    const { handleSignInClicked } = useSignIn()
    const handleSignUpClicked = () => {
        handleSignInClicked({
            is_sign_up_later_user_signing_up: "true"
        })
        handleClose()
    }
    return (
        <Modal
            open={show}
            handleCloseOutside={() => handleClose()}
            className={{
                container: "rounded-xl",
                overlay: "!bg-[rgba(20,22,31,0.60)] !rounded-tl-[6px] !rounded-bl-[6px]"
            }}
        >

            <div className="shadow-[inset_0px_0px_48px_0px_rgba(115,109,249,0.20)] flex  justify-center items-center flex-col p-5 rounded-xl relative border border-mentorai-bg-strong bg-mentorai-bg-base">
                <img src={PreplacedLogoBlack} alt="preplaced-logo-black" className="w- h-11" />
                <p className="text-[#dddddf] text-xl font-medium leading-7 tracking-[-0.2px] text-center mt-2">You need to sign in</p>
                <p className="text-[#94939f] text-sm leading-[1.375rem] tracking-[0.084px] mt-1 text-center">A one-time activity and then we’re all set!</p>
                <button className="rounded-xl text-mentorai-text-white text-sm tracking-[0.084px]  leading-[22px] shadow-[0px_0px_12px_0px_rgba(255,255,255,0.04)] w-full mt-5 py-3 px-6 bg-[#5149F2] hover:bg-[#5149F2]/[0.8]" onClick={handleSignUpClicked}>Sign in to Use Extension</button>
            </div>
        </Modal>
    )
}

export default SignupModal