import { useContext, useEffect, useState } from "react";
import { ChatContext } from "../../../../../../context/chat-context/chat-context";
import getCurrency, { getFormattedPriceWithSymbol } from "../../../../../../../utils/currency";
import { getMostRecentSubscription } from "../../../../../../../utils/subscription-helpers";

const useExtensionPlansContainer = () => {
  const { menteeSubscription } = useContext(ChatContext);
  const mostRecentSubscription = getMostRecentSubscription(menteeSubscription?.subscriptions);
  const isTrialCancelled = mostRecentSubscription?.cancelledOn && menteeSubscription?.pricing_plan?.user_type === "trial";
  const [extensionPlans, setExtensionPlans] = useState<ExtensionPlan[] | null>(null);
  const [trialDays, setTrialDays] = useState<number | null>(null);
  const currency = getCurrency();

  const plansMapper = (plans: any) => {
    if (!plans) return [];

    const filteredPlans = plans
      .reverse()
      .filter((plan: any) => plan.validity === "1 month" || plan.validity === "1 year");

    return filteredPlans.map((plan: any) => {
      const mappedPlan: ExtensionPlan = {
        totalPrice: plan.totalPrice,
        originalPrice: plan.originalPrice,
        discount: plan.discount,
        validity: plan.validity,
        offer: plan.offer,
        pricingVariant: plan?.pricingVariant || "",
      };
      return mappedPlan;
    });
  };

  const fetchExtensionPlans = async () => {
    const response = await chrome.runtime.sendMessage({
      action: "fetch_calls",
      fetch_call: "fetch_extension_plans",
    });

    const plansResponseData = response.extension_plans;

    const mappedPlans = plansMapper(plansResponseData.pricing);
    setTrialDays(plansResponseData?.trialDays);
    setExtensionPlans(mappedPlans);
  };

  useEffect(() => {
    fetchExtensionPlans();
  }, []);

  const isOfferAvailable = extensionPlans?.find((plan) => plan?.validity === "1 month")?.offer || false;
  const pricingVariant = extensionPlans?.find((plan) => plan?.validity === "1 month")?.pricingVariant || "";
  const offerPlan = extensionPlans?.find((plan) => plan?.validity === "1 month");

  const monthlyPrice = extensionPlans?.find((plan) => plan.validity === "1 month")?.originalPrice;

  const INRCTAText = {
    v1: "Unlock Leeco Pro →",
    v2: `Claim First Month for ${getFormattedPriceWithSymbol(offerPlan?.totalPrice || 1)}`,
    v3: `Claim First Week for ${getFormattedPriceWithSymbol(offerPlan?.totalPrice || 1)}`,
    v4: isTrialCancelled ? `Reactivate your free trial to enjoy all features & unlimited chat credits` : `Claim First Month for ${getFormattedPriceWithSymbol(offerPlan?.totalPrice || 1)}`,
    v5: `Claim First Month for ${getFormattedPriceWithSymbol(offerPlan?.totalPrice || 1)}`,
    v6: `Unlock Leeco Pro Just at ${getFormattedPriceWithSymbol(offerPlan?.totalPrice || 1)}`,
    v7: `Claim First Month for ${getFormattedPriceWithSymbol(offerPlan?.totalPrice || 1)}`,
    v8: `Claim First Month for ${getFormattedPriceWithSymbol(offerPlan?.totalPrice || 1)}`,
    v9: `Unlock Leeco Pro Just at ${getFormattedPriceWithSymbol(offerPlan?.totalPrice || 1)}`,
    v10: `Unlock Leeco Pro Just at ${getFormattedPriceWithSymbol(offerPlan?.totalPrice || 1)}`,
    v11: `Unlock Leeco Pro Just at ${getFormattedPriceWithSymbol(offerPlan?.totalPrice || 1)}`,
    v12: `Claim First Month for ${getFormattedPriceWithSymbol(offerPlan?.totalPrice || 1)}`,
    v13: `Unlock Leeco Pro Just at ${getFormattedPriceWithSymbol(offerPlan?.totalPrice || 1)}`,
    v14: `Unlock Leeco Pro Just at ${getFormattedPriceWithSymbol(offerPlan?.totalPrice || 1)}`,
  };

  const USDCAText = {
    v1: "Unlock Leeco Pro →",
    v2: `Claim First Month for FREE`,
    v3: `Claim First Week for FREE`,
    v4: isTrialCancelled ? `Reactivate your free trial to enjoy all features & unlimited chat credits` : `Claim First Month for FREE`,
    v5: `Claim First Month for FREE`,
    v6: `Unlock Leeco Pro for FREE`,
    v7: `Claim First Month for FREE`,
    v8: `Claim First Month for FREE`,
    v9: `Unlock Leeco Pro for FREE`,
    v10: `Unlock Leeco Pro for Free`,
    v11: `Unlock Leeco Pro for Free`,
    v12: `Claim First Month for FREE`,
    v13: `Unlock Leeco Pro for Free`,
    v14: `Unlock Leeco Pro for Free`,
  };

  return {
    extensionPlans,
    isOfferAvailable,
    pricingVariant,
    offerPlan,
    monthlyPrice,
    INRCTAText,
    USDCAText,
    currency,
    trialDays,
    isTrialCancelled,
  };
};

export default useExtensionPlansContainer;
