import Modal from "../../../../common/modal/modal";
import Button from '../../common/common-button';
import CloseIcon from "../../../assets/close-icon.svg";
import CloseIconHovered from "../../../assets/close-hovered.svg";
import ScannerIcon from "../../../assets/scanner.svg";
import WhatsappIcon from "../../../assets/whatsapp.svg";
import { QRCodeSVG } from 'qrcode.react';
import LinkedInIcon from "../../../assets/linkedin.svg";
import SlackIcon from "../../../assets/slack.svg";
import WhatsappIcon2 from "../../../assets/whatsapp2.svg";
import CopiedIcon from "../../../assets/copied2.svg";
import CopyIcon from "../../../assets/copy.svg";
import { useContext, useEffect, useState } from "react";
import { PageContext } from "../../../context/page-context/page-context";
import checked from "./checked.gif";
import MentorAiButton from "../../../../common/button/mentorai-button";
import { MenteeContext } from "../../../context/mentee-context/mentee-context";
import CopyWhiteIcon from "../../../assets/copywhite.svg";
import CopiedWhiteIcon from "../../../assets/copiedwhite.svg";


const ShareExtension = ({ handleCopyAgain, selectedShareOption, show, handleClose, whatsappUrl, handleShareWhatsapp, handleShareLinkedin, handleShareSlack }: { handleCopyAgain: Function, selectedShareOption: any, show: boolean, handleClose: Function, whatsappUrl: string, handleShareWhatsapp: Function, handleShareLinkedin: Function, handleShareSlack: Function }) => {
    const [copied, setCopied] = useState(false)
    const { activeTabUrl } = useContext(PageContext)
    const { menteeData } = useContext(MenteeContext)


    useEffect(() => {
        if (copied) {
            setTimeout(() => {
                setCopied(false)
            }, 1500)
        }
    }, [copied])

    const ctaButtons = [
        {
            icon: WhatsappIcon2,
            text: "WhatsApp",
            handleClick: () => handleShareWhatsapp()
        },
        {
            icon: LinkedInIcon,
            text: "LinkedIn",
            handleClick: () => handleShareLinkedin()
        },
        {
            icon: SlackIcon,
            text: "Slack",
            handleClick: () => handleShareSlack()
        }
    ]

    const handleCopyExtensionLink = () => {
        chrome.runtime.sendMessage({
            action: "sendAnalytics", url: activeTabUrl,
            eventName: 'MentorAi Share Extension Medium Clicked',
            eventProperties: {
                medium: "Copy Link"
            }
        })
        navigator.clipboard.writeText(`https://explore.preplaced.in/ENjfGK?utm_content=${menteeData?.profileId}`)
        setCopied(true)
    }

    return (
        <Modal
            open={show}
            handleCloseOutside={() => handleClose()}
            className={{
                container: "rounded-xl",
                overlay: "!bg-[rgba(20,22,31,0.60)] !rounded-tl-[6px] !rounded-bl-[6px]"
            }}
        >

            <div className="shadow-[inset_0px_0px_48px_0px_rgba(115,109,249,0.20)] flex  justify-center items-center flex-col p-4 w-[17.5rem] rounded-xl relative border border-mentorai-bg-strong bg-mentorai-bg-base">
                <Button className="!cursor-pointer absolute transition-all duration-100 group"
                    style={{
                        top: "4px",
                        right: "4px"
                    }}
                    onClick={() => handleClose()}>
                    <img src={CloseIcon} alt="close" className="w-4 h-4 max-w-[16px] max-h-[16px] flex group-hover:hidden" />
                    <img src={CloseIconHovered} alt="close" className="w-4 h-4 max-w-[16px] max-h-[16px] hidden group-hover:flex" />
                </Button>

                {selectedShareOption.popupView === "primary" ?
                    <>
                        <p className="mb-0.5 text-white text-center text-sm font-medium leading-[1.375rem] tracking-[0.084px]">Help us keep AI Mentor FREE by</p>
                        <p className="text-mentorai-primary-lighter text-center text-xl font-semibold leading-7 tracking-[-0.2px]">sharing with a friend!</p>
                        <p className="w-full h-px bg-[#363645] mt-4 mb-6" > <span className="invisible">.</span></p>

                        <div className="flex flex-col items-center self-stretch">
                            <div className="flex flex-col items-center gap-3 self-stretch">
                                <div className="flex justify-center items-center gap-1 self-stretch">
                                    <img src={ScannerIcon} alt="scanner" className="w-[14px] h-[14px]" />
                                    <p className="text-mentorai-text-sub text-xs font-bold leading-[normal]">Scan to share on </p>
                                    <img src={WhatsappIcon} alt="whatsapp" className="w-[14px] h-[14px]" />
                                    <p className="text-mentorai-text-sub text-xs font-bold leading-[normal]">WhatsApp</p>
                                </div>
                                <div className="!h-[128px] !max-h-[128px] w-fit mx-auto">
                                    {whatsappUrl && (
                                        <QRCodeSVG
                                            value={whatsappUrl}
                                            size={128}
                                            bgColor="#ffffff"
                                            fgColor="#000000"
                                            level="L"
                                            marginSize={4}
                                        />
                                    )}
                                </div>
                            </div>
                            <div className="flex justify-between items-center mt-5 self-stretch">
                                <Button onClick={handleCopyExtensionLink} className="flex flex-col justify-center items-center  gap-2 py-2 px-1 w-14 rounded  hover:bg-mentorai-bg-strong">
                                    <div className="flex justify-center items-center">
                                        <img src={copied ? CopiedIcon : CopyIcon} alt="icon" className="w-6 h-6" />
                                    </div>
                                    <p className=" text-mentorai-text-sub text-center  text-[10px] font-semibold leading-[normal]">{copied ? "Copied!" : "Copy Link"}</p>
                                </Button >
                                {ctaButtons.map((button, index) => (
                                    <ShareButton key={index} {...button} />
                                ))}
                            </div>
                        </div>
                        <p className="w-full h-px bg-[#363645] mt-4" > <span className="invisible">.</span></p>
                        <p className="mt-4 text-mentorai-text-sub text-center text-xs leading-[normal] tracking-[0.24px]">3000+ users and counting ❤️</p>
                    </>
                    :
                    <>
                        <div className="mx-auto h-[120px] max-h-[120px] w-auto overflow-hidden">
                            <img src={checked} alt="checked" className="w-full h-full" />
                        </div>
                        <p className="text-mentorai-primary-lighter text-center text-xl font-semibold leading-7 tracking-[-0.2px]">Invite message copied!</p>
                        <p className="mt-0.5 text-white text-center text-sm font-medium leading-[1.375rem] tracking-[0.084px]">You can now paste it on {selectedShareOption.cta === "Slack" ? "Slack" : "LinkedIn"}</p>
                        <MentorAiButton
                            onClick={() => handleCopyAgain(selectedShareOption.cta)}
                            classNames="mt-6 w-full"
                            type="outlined"
                            size="small"
                        >
                            <div className="flex gap-1 justify-center items-center">
                                <img src={selectedShareOption.copiedAgain ? CopiedWhiteIcon : CopyWhiteIcon} alt="icon" className="w-[14px] h-[14px]" />
                                <span className="text-mentorai-text-soft text-xs font-medium leading-[18px]">{selectedShareOption.copiedAgain ? "Copied!" : "Copy again"}</span>
                            </div>
                        </MentorAiButton>
                    </>
                }
            </div>
        </Modal>
    )
}

export default ShareExtension

const ShareButton = ({ icon, text, handleClick }: { icon: any, text: string, handleClick: any }) => {
    return (
        <Button onClick={handleClick} className="flex flex-col justify-center items-center  gap-2 py-2 px-1 w-14 rounded hover:bg-mentorai-bg-strong">
            <div className="flex justify-center items-center">
                <img src={icon} alt="icon" className="w-6 h-6" />
            </div>
            <p className=" text-mentorai-text-sub text-center  text-[10px] font-semibold leading-[normal]">{text}</p>
        </Button >
    )
}
