import { useEffect, useRef, useState, useContext } from "react"
import { PageContext } from "../../../context/page-context/page-context";

const useCreateFirstPath = () => {
	const { activeTabUrl } = useContext(PageContext);

	const searchQueriesList = [
		"I want to learn DSA",
		"React",
		"Figma",
		"System Design",
		"Build AI Agents"
	]

	const [search, setSearch] = useState("")

	const handleSearchChange = (e: any) => {
		setSearch(e?.target?.value)
	}

	const [shouldSlideDown, setShouldSlideDown] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const measureTextWidth = (text: string) => {
    if (!textareaRef.current) return 0;
    const canvas = document.createElement("canvas");
    const context = canvas.getContext("2d");
    if (!context) return 0;

    const computedStyle = window.getComputedStyle(textareaRef.current);
    context.font = `${computedStyle.fontSize} ${computedStyle.fontFamily}`;

    return context.measureText(text || textareaRef.current.placeholder || "").width;
  };

  const adjustTextareaHeight = () => {
    if (!textareaRef.current) return;
    textareaRef.current.style.height = "auto";
    textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`;
  };

  useEffect(() => {
    if (!textareaRef.current || !containerRef.current) return;

    const textWidth = measureTextWidth(search);
    const containerWidth = containerRef.current.offsetWidth;
    const buttonWidth = 80;
    const padding = 24;

    const availableWidth = containerWidth - buttonWidth - padding;
    setShouldSlideDown(textWidth > availableWidth);

    adjustTextareaHeight();
  }, [search]);

  const handleTextareaKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    const inputEvent = e as unknown as React.KeyboardEvent<HTMLInputElement>;
    handleKeyDown(inputEvent);
  };

	const handleCreatePathClick = async (query: string, isEasyAction: boolean = false) => {
		if(query?.trim() === "") return;
		chrome.runtime.sendMessage({
			action: "sendAnalytics",
			url: activeTabUrl,
			eventName: "Path Creation Started",
			eventProperties: {
				first_time: true,
				type: isEasyAction ? "easy action" : "typed",
				path: query,
			}
		});
		
		await chrome.tabs.create({
			url: `${import.meta.env.VITE_LEECO_WEB_URL}/learn?initialQuery=${query}`,
			active: true,
		});
		setSearch("")
	}

	const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
		if (e.key === 'Enter') {
		  e.preventDefault();
		  handleCreatePathClick(search);
		}
	  };

	return {
		search,
		searchQueriesList,
		handleSearchChange,
		handleCreatePathClick,
		handleTextareaKeyDown,
		shouldSlideDown,
		textareaRef,
		containerRef
	}
}

export default useCreateFirstPath