import React, { useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import ChevronRight from "../../assets/chevron-right-white.svg";

interface SlidingCarouselProps<T> {
  data: T[];
  itemsPerPage?: number;
  autoRotate?: boolean;
  autoRotateInterval?: number;
  renderItem: (item: T, index: number) => React.ReactNode;
  showNavigation?: boolean;
  className?: string;
}

const SlidingCarousel = <T extends Record<string, any>>({
  data,
  itemsPerPage = 2,
  autoRotate = true,
  autoRotateInterval = 7000,
  renderItem,
  showNavigation = true,
  className = "",
}: SlidingCarouselProps<T>) => {
  const [currentPage, setCurrentPage] = React.useState(0);
  const [isAnimating, setIsAnimating] = React.useState(false);
  const [slideDirection, setSlideDirection] = React.useState<'left' | 'right' | null>(null);
  const totalPages = Math.ceil(data?.length / itemsPerPage);

  useEffect(() => {
    if (!autoRotate || totalPages <= 1) return;

    const interval = setInterval(() => {
      if (!isAnimating && currentPage < totalPages - 1) {
        goToNextPage();
      } else if (!isAnimating && currentPage >= totalPages - 1) {
        goToFirstPage();
      }
    }, autoRotateInterval);

    return () => clearInterval(interval);
  }, [currentPage, totalPages, isAnimating, autoRotate, autoRotateInterval]);

  // Get current page items
  const getCurrentPageItems = React.useCallback(() => {
    const startIndex = currentPage * itemsPerPage;
    return data?.slice(startIndex, startIndex + itemsPerPage);
  }, [currentPage, data, itemsPerPage]);

  // Navigation functions
  const goToNextPage = React.useCallback(() => {
    if (currentPage < totalPages - 1 && !isAnimating) {
      setIsAnimating(true);
      setSlideDirection('right'); // New content comes from right
      setCurrentPage((prev) => prev + 1);
      setTimeout(() => {
        setIsAnimating(false);
        setSlideDirection(null);
      }, 300);
    }
  }, [currentPage, totalPages, isAnimating]);

  const goToPreviousPage = React.useCallback(() => {
    if (currentPage > 0 && !isAnimating) {
      setIsAnimating(true);
      setSlideDirection('left'); // New content comes from left
      setCurrentPage((prev) => prev - 1);
      setTimeout(() => {
        setIsAnimating(false);
        setSlideDirection(null);
      }, 300);
    }
  }, [currentPage, isAnimating]);

  const goToFirstPage = React.useCallback(() => {
    if (!isAnimating) {
      setIsAnimating(true);
      setSlideDirection('right'); // Auto-rotate always goes forward
      setCurrentPage(0);
      setTimeout(() => {
        setIsAnimating(false);
        setSlideDirection(null);
      }, 300);
    }
  }, [isAnimating]);

  const hasNextPage = currentPage < totalPages - 1;
  const hasPreviousPage = currentPage > 0;

  if (data?.length === 0) {
    return null;
  }

  // Determine animation direction based on slideDirection
  const getAnimationProps = () => {
    if (slideDirection === 'right') {
      return {
        initial: { x: 300, opacity: 0 },
        animate: { x: 0, opacity: 1 },
        exit: { x: -300, opacity: 0 }
      };
    } else if (slideDirection === 'left') {
      return {
        initial: { x: -300, opacity: 0 },
        animate: { x: 0, opacity: 1 },
        exit: { x: 300, opacity: 0 }
      };
    } else {
      return {
        initial: { x: 0, opacity: 1 },
        animate: { x: 0, opacity: 1 },
        exit: { x: 0, opacity: 1 }
      };
    }
  };

  const animationProps = getAnimationProps();

  return (
    <div className={`space-y-4 ${className}`}>
      <div className="relative overflow-hidden">
        <AnimatePresence mode="wait">
          <motion.div
            key={currentPage}
            className="space-y-4"
            {...animationProps}
            transition={{
              type: "tween",
              duration: 0.3,
              ease: "easeInOut",
            }}
          >
            {getCurrentPageItems().map((item, index) => (
              <motion.div
                key={`${currentPage}-${index}`}
                initial={{ opacity: 0, y: 0 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{
                  delay: index * 0.1,
                  duration: 0.3,
                  ease: "easeOut",
                }}
              >
                {renderItem(item, index)}
              </motion.div>
            ))}
          </motion.div>
        </AnimatePresence>
      </div>

      {showNavigation && totalPages > 1 && (
        <div className="flex w-full justify-center">
          <div className="flex gap-[7px] items-center">
            <motion.button
              className={`bg-[#212431] rounded p-[2px] ${
                hasPreviousPage ? "opacity-100" : "opacity-50 cursor-not-allowed"
              }`}
              onClick={goToPreviousPage}
              disabled={!hasPreviousPage || isAnimating}
              whileHover={hasPreviousPage ? { backgroundColor: "#4B4E63" } : {}}
              transition={{ duration: 0.1 }}
            >
              <img src={ChevronRight} alt="chevron-left.svg" className="rotate-180" />
            </motion.button>
            <p className="text-[#FFFFFF] text-[12px] leading-[13px]">
              {currentPage + 1}/{totalPages}
            </p>
            <motion.button
              className={`bg-[#212431] rounded p-[2px] ${
                hasNextPage ? "opacity-100" : "opacity-50 cursor-not-allowed"
              }`}
              onClick={goToNextPage}
              disabled={!hasNextPage || isAnimating}
              whileHover={hasNextPage ? { backgroundColor: "#4B4E63" } : {}}
              transition={{ duration: 0.1 }}
            >
              <img src={ChevronRight} alt="chevron-right.svg" />
            </motion.button>
          </div>
        </div>
      )}
    </div>
  );
};

export default SlidingCarousel;
