import Modal from "../../../../common/modal/modal"
import MentorAiButton from "../../../../common/button/mentorai-button"
import { PageContext } from "../../../context/page-context/page-context"
import { useContext } from "react"
import { extractQuestionDifficulty } from "../../../utils/side-panel-helper"
import { INTERVIEW_PROGRESS_THRESHOLDS } from "../../../constant/interview-progress"
import AltIcon from "../../../assets/alt.svg"
import ControlIcon from "../../../assets/control-icon.svg"
import CloseIcon from "../../../assets/close-icon.svg";
import CloseIconHovered from "../../../assets/close-hovered.svg";
import Button from "../../common/common-button"
import MicIcon from "../../../assets/mic.svg?react"

type Props = {
  show: boolean
  handleClose: () => void
  sendMessage: Function
}

const InterviewStarterPopup = ({ show, handleClose, sendMessage }: Props) => {
  const { setInterviewModeStatus, startTimer, scrapedData, incrementInterviewCount, activeTabUrl, interviewCount } =
    useContext(PageContext)

  const isUserDeviceIsMac = navigator.userAgent.includes("Macintosh")

  const statements = [
    {
      element: (
        <p className="self-stretch text-mentorai-text-sub text-sm leading-[1.375rem] tracking-[0.084px]">
          ⏲️ Timer starts as soon as we begin
        </p>
      ),
    },
    {
      element: (
        <p className="self-stretch text-mentorai-text-sub text-sm leading-[1.375rem] tracking-[0.084px]">
          🔮 Expect minimum guidance from me
        </p>
      ),
    },
    {
      element: (
        <p className="self-stretch text-mentorai-text-sub text-sm leading-[1.375rem] tracking-[0.084px] text-center">
          ✍🏼 Once done, I'll send you a report on chat
        </p>
      ),
    },
  ]

  const handleLetsBeginClicked = async () => {
    setInterviewModeStatus("ONGOING")
    await chrome.storage.local.set({ interviewModeStatus: "ONGOING", feedbackGenerating: false })
    incrementInterviewCount()
    startTimer()
    sendMessage("Start Interview", true, null, true)
    chrome.runtime.sendMessage({
      action: "sendAnalytics", url: activeTabUrl, eventName: 'MentorAi Interview Mode Started', eventProperties: {
        interview_mode_version: 'beta',
        interview_count: interviewCount,
      }
    })
  }

  const formatTimeInMinutes = (time: number) => {
    const minutes = Math.floor(time / 60)
    return `${minutes} minutes`
  }

  const getInterviewTime = () => {
    const difficulty = extractQuestionDifficulty(scrapedData || "") as keyof typeof INTERVIEW_PROGRESS_THRESHOLDS
    const startTime = INTERVIEW_PROGRESS_THRESHOLDS[difficulty || "Unknown"].startTime
    return formatTimeInMinutes(startTime)
  }

  return (
    <Modal
      open={show}
      handleCloseOutside={handleClose}
      className={{
        container: "rounded-xl",
        overlay:
          "!bg-[rgba(20,22,31,0.60)] !rounded-tl-[6px] !rounded-bl-[6px]",
      }}
    >
      <div className="shadow-[inset_0px_0px_48px_0px_rgba(115,109,249,0.20)] flex justify-start items-center flex-col p-4 max-w-[350x] rounded-xl relative border border-[#363645] bg-mentorai-bg-base">
        <Button className="!cursor-pointer absolute transition-all duration-100 group"
          style={{
            top: "4px",
            right: "4px"
          }}
          onClick={() => handleClose()}>
          <img src={CloseIcon} alt="close" className="w-4 h-4 max-w-[16px] max-h-[16px] flex group-hover:hidden" />
          <img src={CloseIconHovered} alt="close" className="w-4 h-4 max-w-[16px] max-h-[16px] hidden group-hover:flex" />
        </Button>
        <p className="text-xl font-medium leading-7 -tracking-[0.2px] text-mentorai-text-white text-center">
          We'll solve this problem <br /> <span className="text-mentorai-primary-lighter">in a {getInterviewTime()} interview </span>
        </p>
        <div className="rounded-xl border border-mentorai-stroke-strong bg-mentorai-bg-strong p-3 gap-1 flex flex-col mt-4 text-[14px] leading-[22px] items-center justify-center tracking-[0.084px] w-full">
          <div className="flex items-center justify-center gap-2 flex-wrap">
            <span className="text-mentorai-text-white font-semibold">Click</span>
            <div className="rounded-full p-[6px] border border-mentorai-stroke-base">
              <MicIcon className="w-[12px] h-[12px] text-mentorai-primary-lighter" />
            </div>
            <span className="text-mentorai-text-white font-semibold">or Hold</span>
            <span className="bg-mentorai-bg-sub py-1 px-2 rounded-lg text-[12px] h-[26px] leading-[18px] tracking-[0.072px] text-mentorai-text-soft flex items-center justify-center font-normal" style={{ fontFamily: 'Fira Code' }}>
              <span>
                {isUserDeviceIsMac ? "control" : "alt"}
              </span>
            </span>
            <span className="bg-mentorai-bg-sub py-1 px-2 rounded-lg flex items-center justify-center h-[26px]">
              <img src={isUserDeviceIsMac ? ControlIcon : AltIcon} alt="icon" />
            </span>
          </div>
          <span className="text-mentorai-text-sub">to speak quickly instead of typing</span>
        </div>

        <div className="mx-auto flex flex-col gap-2 mt-8">
          {statements.map((statement, index) => (
            <div key={index} className="flex items-center gap-0.5 justify-center">
              {statement.element}
            </div>
          ))}
        </div>

        <MentorAiButton
          onClick={handleLetsBeginClicked}
          type="primary"
          size="medium"
          classNames="w-full mt-8"
        >
          <div className=" text-sm font-medium leading-[1.375rem]">
            Let's Begin
          </div>
        </MentorAiButton>
      </div>
    </Modal>
  )
}

export default InterviewStarterPopup
