import React, { useEffect, useRef, useState } from 'react'
import { formatDateToDayMonthYear } from '../../../utils/str-time-to-seconds'
import { handleCommonPost, handlePost } from '../../../../core/Axios'
import { identifyUser } from '../../../../core/Analytics';
import { mentorAiSubscriptionGetCall } from '../../../background/apiCalls';
import checkValidSubscription from '../../../../utils/check-valid-subscription';
import { redirectToCheckout } from '../../../utils/checkout-redirect';
import { getMostRecentSubscription } from '../../../../utils/subscription-helpers';

const useProfileSheet = ({ menteeData, menteeSubscription, activeTabUrl, chatUsageData, mentoraiData }: { menteeData: any, menteeSubscription: any, activeTabUrl: string, chatUsageData: any, mentoraiData: any }) => {

    const [resetInTimer, setResetInTimer] = useState(`00h:00m`);
    const [showCancelPlanOptionPopup, setShowCancelPlanOptionPopup] = useState(false);
    const [showCancelPlanPopup, setShowCancelPlanPopup] = useState(false);
    const [showCancelPlanReasonPopup, setShowCancelPlanReasonPopup] = useState(false);
    const [cancelPlanLoading, setCancelPlanLoading] = useState(false);
    const [cancelPlanHovered, setCancelPlanHovered] = useState(false);
    const [planCancellationStatus, setPlanCancellationStatus] = useState("");
    const [selectedCancelReason, setSelectedCancelReason] = useState("");
    const [additionalComments, setAdditionalComments] = useState("");
    const userJoinDate = formatDateToDayMonthYear(menteeData?.created)
    const cancelPlanPopupRef = useRef<HTMLDivElement>(null);
    const cancelPlanReasonPopupRef = useRef<HTMLDivElement>(null);
    const isLoading = chatUsageData?.menteeDataLoading && menteeData;
    const isUserPaid = checkValidSubscription(menteeSubscription)
    const menteeSubscriptionDetails = getMostRecentSubscription(menteeSubscription.subscriptions);;
    const currentPlanCreatedDate = formatDateToDayMonthYear(menteeSubscriptionDetails?.lastChargeDate || menteeSubscriptionDetails?.created)
    const isPlanExpired = menteeSubscriptionDetails?.status === "Expired";
    const isPlanASubscription = !!menteeSubscriptionDetails?.subscriptionId;
    const isPlanActive = menteeSubscriptionDetails?.status === "Active";
    const isPlanCancelled = menteeSubscriptionDetails?.status === "Active" && !!menteeSubscriptionDetails?.cancelledOn;

    const getNextRenewalDate = () => {
        if (isPlanASubscription && isPlanActive && menteeSubscriptionDetails?.nextRenewalDate) {
            return formatDateToDayMonthYear(menteeSubscriptionDetails?.nextRenewalDate);
        }
        return "";
    };
    const getActualExpirationDate = () => {
        if (isPlanASubscription && menteeSubscriptionDetails?.actualExpirationDate) {
            return formatDateToDayMonthYear(menteeSubscriptionDetails?.actualExpirationDate);
        }
        return "";
    };
    const nextRenewalDate = getNextRenewalDate()
    const actualExpirationDate = getActualExpirationDate()

    const planType = menteeSubscriptionDetails?.packageVersion === "1 year" ? "Pro - Yearly Plan" : menteeSubscriptionDetails?.packageVersion === "3 months" ? "Pro - Quarterly Plan" : menteeSubscriptionDetails?.packageVersion === "1 month" ? "Pro - Monthly Plan" : "Pro - Weekly Plan";

    useEffect(() => {
        const updateResetInTimer = () => {
            const now = new Date();
            const nextMidnight = new Date(now);
            nextMidnight.setHours(24, 0, 0, 0);
            const diffMs = nextMidnight.getTime() - now.getTime();

            const totalMinutes = Math.floor(diffMs / 60000);
            const hours = Math.floor(totalMinutes / 60);
            const minutes = totalMinutes % 60;

            const formatted = `${hours.toString().padStart(2, "0")}h:${minutes
                .toString()
                .padStart(2, "0")}m`;

            setResetInTimer(formatted);
        };

        updateResetInTimer();
        const interval = setInterval(updateResetInTimer, 1000 * 60);
        return () => clearInterval(interval);
    }, []);

    const handleUpgradeToProClick = async () => {
        const isTrialCancelled = menteeSubscriptionDetails?.cancelledOn && menteeSubscription?.pricing_plan?.user_type === "trial";
        redirectToCheckout({
            location: isTrialCancelled ? "Trial Cancelled Banner" : "Profile Sheet",
            menteeSubscription: menteeSubscription
        });
    };

    const handleRedirectToPlanDetails = () => {
        if (isPlanASubscription && menteeSubscriptionDetails?.subscriptionManagementUrl) {
            window.open(`${menteeSubscriptionDetails?.subscriptionManagementUrl}`, "_blank");
        }
        setShowCancelPlanOptionPopup(false);
    }

    const handleCancelPlan = async () => {
        setCancelPlanLoading(true);
        try {
            if (!isPlanASubscription) {
                return;
            }

            const url = `/subscriptions/cancel?subscription_id=${menteeSubscriptionDetails.subscriptionId}&airtable_update=false`;
            const response = await handleCommonPost(url, {}, {}, false);
            if (response?.status === 200) {
                chrome.runtime.sendMessage({
                    action: "sendAnalytics",
                    eventName: "Leeco Plan Cancelled",
                    url: activeTabUrl,
                    eventProperties: {}
                });
                setPlanCancellationStatus("success");
                setShowCancelPlanReasonPopup(false);
                setSelectedCancelReason("");
                setAdditionalComments("");
                handleRedirectToPlanDetails();
                await mentorAiSubscriptionGetCall(menteeData?.recordId, mentoraiData?.recordId, true);
            } else {
                chrome.runtime.sendMessage({
                    action: "sendAnalytics",
                    eventName: "Leeco Plan Cancellation Failed",
                    url: activeTabUrl,
                    eventProperties: {}
                });
                setPlanCancellationStatus("error");
            }
        } catch (error) {
            console.error("Failed to cancel subscription:", error);
            chrome.runtime.sendMessage({
                action: "sendAnalytics",
                eventName: "Leeco Plan Cancellation Failed",
                url: activeTabUrl,
                eventProperties: {}
            });
            setPlanCancellationStatus("error");
        } finally {
            setCancelPlanLoading(false);
            setShowCancelPlanPopup(false);
            setTimeout(() => {
                setPlanCancellationStatus("");
            }, 3000);
        }
    }

    const handleClickOutsideOfCancelPlanPopup = (e: React.MouseEvent<HTMLDivElement>) => {
        if (cancelPlanPopupRef.current && !cancelPlanPopupRef.current.contains(e.target as Node)) {
            setShowCancelPlanPopup(false);
        }
    }

    const handleClickOutsideOfCancelPlanReasonPopup = (e: React.MouseEvent<HTMLDivElement>) => {
        if (cancelPlanReasonPopupRef.current && !cancelPlanReasonPopupRef.current.contains(e.target as Node)) {
            setShowCancelPlanReasonPopup(false);
        }
    }

    const handleProceedToCancel = async () => {
        if (!selectedCancelReason) {
            return;
        }
        setShowCancelPlanReasonPopup(false)
        setShowCancelPlanPopup(true);
        setShowCancelPlanOptionPopup(false);
        chrome.runtime.sendMessage({
            action: "sendAnalytics",
            eventName: "Plan Cancellation Reason Submitted",
            url: activeTabUrl,
            eventProperties: {
                reason: selectedCancelReason,
                comment: additionalComments
            }
        });
        try {
            if (menteeData?.recordId) {
                await handlePost("/candidates/profile", {
                    recordId: menteeData.recordId,
                    leecoCancellationReason: selectedCancelReason
                }, { airtable_update: false });
            }
        } catch (error) {
            console.error("Error updating candidate data:", error);
        }
        try {
            if (menteeData?.email) {
                await identifyUser(menteeData.email, {
                    cancellation_reason: selectedCancelReason
                });
            }
        } catch (error) {
            console.error("Error identifying user:", error);
        }
        setSelectedCancelReason("")
        setAdditionalComments("")
    }

    return ({
        resetInTimer,
        showCancelPlanOptionPopup,
        showCancelPlanPopup,
        showCancelPlanReasonPopup,
        cancelPlanLoading,
        cancelPlanHovered,
        setCancelPlanHovered,
        planCancellationStatus,
        selectedCancelReason,
        additionalComments,
        userJoinDate,
        cancelPlanPopupRef,
        cancelPlanReasonPopupRef,
        isLoading,
        isUserPaid,
        menteeSubscriptionDetails,
        currentPlanCreatedDate,
        isPlanExpired,
        isPlanASubscription,
        isPlanActive,
        nextRenewalDate,
        actualExpirationDate,
        planType,
        isPlanCancelled,
        getNextRenewalDate,
        handleUpgradeToProClick,
        handleRedirectToPlanDetails,
        handleCancelPlan,
        handleClickOutsideOfCancelPlanPopup,
        handleClickOutsideOfCancelPlanReasonPopup,
        setShowCancelPlanOptionPopup,
        setShowCancelPlanPopup,
        setShowCancelPlanReasonPopup,
        setSelectedCancelReason,
        setAdditionalComments,
        setPlanCancellationStatus,
        setCancelPlanLoading,
        handleProceedToCancel

    })
}

export default useProfileSheet