import React from "react";
import { motion } from "framer-motion";
import SelecterOptionIcon from "../assets/selecter-otpion-icon.svg";

type SelectorArrayOfOptionsProps = {
  data: string[];
  shouldAnimate?: boolean
  className?: {
    containerClassName?: string;
    buttonContainerClassName?: string;
    iconClassName?: string;
  }
  id?: string;
  sendMessage: Function;
};

const SelectorArrayOfOptions = ({
  data,
  id,
  sendMessage,
  className,
  shouldAnimate
}: SelectorArrayOfOptionsProps) => {
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2,
        delayChildren: 0.1,
      },
    },
  };

  const itemVariants = {
    hidden: {
      opacity: 0,
      y: 20,
    },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.3,
        ease: "easeOut"
      }
    },
  };

  return (
    <motion.div
      id={id}
      className={`font-manrope flex flex-row w-full flex-wrap items-start gap-2 overflow-x-auto scrollbar-hide pt-4 text-mentorai-text-white ${className?.containerClassName || ""}`}
      variants={shouldAnimate ? containerVariants : {}}
      initial="hidden"
      animate="visible"
    >
      {data?.length &&
        data?.map((item, index) => {
          return (
            <motion.div
              className={`cursor-pointer flex items-center gap-1.5 py-[6px] px-[8px] rounded-lg border border-[#363645] bg-mentorai-bg-strong  text-[#dddddf] text-[12px] !font-medium leading-[16px] hover:bg-mentorai-bg-sub hover:text-[#F2F2F2] hover:border-mentorai-stroke-base ${className?.buttonContainerClassName || ""}`}
              style={{
                fontWeight: "500",
              }}
              variants={shouldAnimate ? itemVariants : {}}
              key={index}
              onClick={() => sendMessage(item)}
            >
              <img src={SelecterOptionIcon} alt="selecter-option-icon" height={8.4} width={8.4} className={`w-[8.4px] h-[8.4px] ${className?.iconClassName}`} />
              {item}
            </motion.div>
          );
        })}
    </motion.div>
  );
};

export default SelectorArrayOfOptions;
