const extractQuestionDifficulty = (text: string): string => {
  if (!text) return "Unknown"

  // Look for the pattern "Leetcode Question Difficulty: X"
  const difficultyMatch = text.match(/Leetcode Question Difficulty:\s*(\w+)/i)
  if (difficultyMatch && difficultyMatch[1]) {
    return difficultyMatch[1] // Return the captured difficulty level
  }

  // Alternative patterns that might indicate difficulty
  if (text.includes("Difficulty: Easy") || text.includes("difficulty: easy")) {
    return "Easy"
  } else if (
    text.includes("Difficulty: Medium") ||
    text.includes("difficulty: medium")
  ) {
    return "Medium"
  } else if (
    text.includes("Difficulty: Hard") ||
    text.includes("difficulty: hard")
  ) {
    return "Hard"
  }

  return "Unknown"
}

export { extractQuestionDifficulty }
