import { ReactNode } from 'react'

type Props = {
  icon: ReactNode
  title: string
  description: string
  iconColor: string
}

const SuccessFeatureItem = ({ icon, title, description, iconColor }: Props) => {
  return (
    <div className="flex gap-3">
      <div className={`w-[22px] h-[22px] ${iconColor} flex-shrink-0`}>
        {icon}
      </div>
      <div className="flex flex-col gap-1.5">
        <h3 className="text-white font-medium text-[13px] leading-[1.21] tracking-[0.01em]">{title}</h3>
        <p className="text-white/60 text-xs leading-[1.5]">{description}</p>
      </div>
    </div>
  )
}

export default SuccessFeatureItem 