import React from 'react'

type Props = {
  headerTitleText: React.ReactNode
  isCancelled: boolean
}

const FreeCreditsExhausted = ({ headerTitleText, isCancelled }: Props) => {
  return (
    <h1 className="text-white text-[22px] leading-[28px] font-semibold tracking-[-0.88px] font-bricolage-grotesque">
      {(headerTitleText !== null && isCancelled) ?
        headerTitleText :
        <>
          You have exhausted all free
          < br />
          credits for today. Upgrade to
          <br/>
          go unlimited.
        </>
      }

    </h1 >
  )
}

export default FreeCreditsExhausted