import Modal from "../../../../common/modal/modal"
import MentorAiButton from "../../../../common/button/mentorai-button"
import useInterviewFeedbackPopup from "./use-interview-feedback-popup"
import { useContext, useState } from "react"
import { PageContext } from "../../../context/page-context/page-context"
import Loading from "../../../assets/loading.gif"
import YellowWarning from "../../../../src/assets/yellow-warning.svg"
import Button from "../../common/common-button"
import CloseIcon from "../../../../src/assets/close-icon.svg"
import CloseIconHovered from "../../../../src/assets/close-icon-hovered.svg"

type Props = {
  show: boolean
  handleClose: () => void
  chatMessages: any[]
}

const InterviewFeedbackPopup = ({ show, handleClose, chatMessages }: Props) => {
  const { setInterviewModeStatus, resetTimer, timer, scrapedData } = useContext(PageContext)
  const {
    ratingValues,
    selectedRatingAndOption,
    setSelectedRatingAndOption,
    ratingSubmitted,
    handleSubmitRating,
    feedbackSubmitted,
    handleSubmitFeedback,
    isLoading,
    feedback,
    setFeedback,
    isTimeSpentLessThanFiveMinutesAndLessThanFiveMessagesSent,
  } = useInterviewFeedbackPopup(chatMessages)

  const handleViewOnChat = () => {
    setInterviewModeStatus("IDLE")
    chrome.storage.local.set({
      interviewModeStatus: "IDLE",
    })
    resetTimer()
  }

  // const formatTimer = () => {
  //   const difficulty = extractQuestionDifficulty(scrapedData || "") as keyof typeof INTERVIEW_PROGRESS_THRESHOLDS
  //   const startTime = INTERVIEW_PROGRESS_THRESHOLDS[difficulty || "Unknown"].startTime
  //   const timeTaken = startTime - timer // Calculate actual time taken

  //   const hours = Math.floor(timeTaken / 3600)
  //   const minutes = Math.floor((timeTaken % 3600) / 60)
  //   const seconds = timeTaken % 60

  //   if (hours > 0) {
  //     return `${hours} hour${hours !== 1 ? "s" : ""} ${minutes} minute${minutes !== 1 ? "s" : ""}`
  //   } else if (minutes > 0) {
  //     return `${minutes} minute${minutes !== 1 ? "s" : ""}`
  //   } else {
  //     return `${seconds} second${seconds !== 1 ? "s" : ""}`
  //   }
  // }


  const getFeedbackHeader = () => {


    if (timer < 0) {
      return <p className="text-xl font-medium leading-7 -tracking-[0.2px] text-mentorai-text-white text-center">
        Nice! However, our interview
        <br />
        went a bit over time.
      </p>
    } else if (isTimeSpentLessThanFiveMinutesAndLessThanFiveMessagesSent) {
      return <p className="text-xl font-medium leading-7 -tracking-[0.2px] text-mentorai-text-white text-center">
        You ended our interview
        <br />
        too early!
      </p>
    } else {
      return <p className="text-xl font-medium leading-7 -tracking-[0.2px] text-mentorai-text-white text-center">
        Nice! You wrapped up
        <br />
        our interview in time.
      </p>
    }
  }

  return (
    <Modal
      open={show}
      handleCloseOutside={isLoading ? () => { } : handleClose}
      className={{
        container: "rounded-xl",
        overlay:
          "!bg-[rgba(20,22,31,0.60)] !rounded-tl-[6px] !rounded-bl-[6px]",
      }}
    >
      <Button className="!cursor-pointer absolute transition-all duration-100 group"
        style={{
          top: "8px",
          right: "8px",
          zIndex: '10'
        }}
        onClick={() => handleClose()}>
        <img src={CloseIcon} alt="close" className="w-4 h-4 max-w-[16px] max-h-[16px] flex group-hover:hidden" />
        <img src={CloseIconHovered} alt="close" className="w-4 h-4 max-w-[16px] max-h-[16px] hidden group-hover:flex" />
      </Button>

      <div className="shadow-[inset_0px_0px_48px_0px_rgba(115,109,249,0.20)] flex items-center justify-center flex-col p-4 max-w-[350px]   rounded-xl relative border border-[#363645] bg-mentorai-bg-base">
        {getFeedbackHeader()}
        {!isTimeSpentLessThanFiveMinutesAndLessThanFiveMessagesSent ? (
          <p className="text-mentorai-text-soft text-sm leading-[1.375rem] tracking-[0.084px] self-baseline mt-3 w-full">
            {isLoading ? (
              <div className="flex items-center gap-1 justify-center w-full">
                <img
                  src={Loading}
                  alt="loading"
                  className="inline-block h-4 w-4"
                />
                <span>Generating Interview Report</span>
              </div>
            ) : (
              <div className="flex items-center gap-1 justify-center w-full">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  width="20"
                  height="20"
                  viewBox="0 0 20 20"
                  fill="none"
                >
                  <rect
                    x="2"
                    y="2"
                    width="16"
                    height="16"
                    rx="8"
                    fill="#3EE089"
                  />
                  <path
                    fill-rule="evenodd"
                    clip-rule="evenodd"
                    d="M14.5294 8.03039L8.99908 13.5607L5.46875 10.0304L6.52941 8.96973L8.99908 11.4394L13.4688 6.96973L14.5294 8.03039Z"
                    fill="#0B4627"
                  />
                </svg>
                <span className="text-mentorai-green-300">
                  Report Sent
                </span>
                <span
                  className="text-[#736df2] hover:text-[#A5A1F7] cursor-pointer"
                  onClick={handleViewOnChat}
                >
                  {" "}
                  View on Chat →
                </span>
              </div>
            )}
          </p>
        ) : (
          <div className="flex justify-center items-center gap-1 self-stretch pr-2 mt-3">
            <img src={YellowWarning} alt="yellow-warning" />
            <span className=" text-[#ffe097] text-center font text-sm leading-[1.375rem]">Not enough to generate a report</span>
          </div>
        )}

        {isTimeSpentLessThanFiveMinutesAndLessThanFiveMessagesSent ?
          (<MentorAiButton
            onClick={() => handleClose()}
            type="primary"
            size="medium"
            classNames="w-full mt-6"
          >
            <div className="text-sm font-medium leading-[1.375rem]">
              Back To Chat
            </div>
          </MentorAiButton>)
          :
          (!feedbackSubmitted && (
            <div className="rounded-xl border border-mentorai-stroke-strong bg-mentorai-bg-strong p-3 gap-2 flex flex-col text-sm leading-[1.375rem] tracking-[0.084px] mt-6">
              <span className="text-mentorai-text-white font-medium">
                How was Interview Mode?
              </span>
              <span className="text-mentorai-text-sub">
                Your feedback will shape the future of this feature
                for developers.
              </span>
              {!ratingSubmitted && (
                <div className="flex justify-between">
                  {ratingValues.map((item: any, index: number) => {
                    return (
                      <div
                        key={index}
                        className="flex flex-col items-start gap-1 self-stretch"
                      >
                        <div
                          className={`max-w-8 duration-50 flex h-8 w-8 cursor-pointer items-center justify-center gap-1 rounded-xl px-1 py-2 transition-all hover:rotate-[25deg] ${item.rating === selectedRatingAndOption.rating
                            ? "border border-mentorai-primary-base bg-mentorai-primary-darker"
                            : "hover:bg-[rgba(223,222,229,0.10)] "
                            }`}
                          onClick={() => {
                            setSelectedRatingAndOption({
                              rating: item.rating,
                              options: item.options,
                              text: item.text,
                              id: item.id,
                            })
                            handleSubmitRating(item.rating)
                          }}
                        >
                          {item.emoji && (
                            <img src={item.emoji} alt={item.rating} />
                          )}
                        </div>
                        <p
                          className={`w-8 text-center text-xs leading-[normal] tracking-[0.12px] ${item.rating === selectedRatingAndOption.rating
                            ? "text-mentorai-text-white"
                            : "text-mentorai-text-sub "
                            }`}
                        >
                          {item.rating}
                        </p>
                      </div>
                    )
                  })}
                </div>
              )}
              {ratingSubmitted && !feedbackSubmitted && (
                <div className="flex flex-col items-start gap-1 self-stretch">
                  <textarea
                    className="w-full h-24 rounded-xl border border-mentorai-stroke-strong bg-mentorai-bg-base p-2 text-sm leading-[1.375rem] tracking-[0.084px] text-mentorai-text-white placeholder:text-mentorai-text-disabled placeholder:text-sm placeholder:leading-[1.375rem] placeholder:tracking-[0.14px]"
                    placeholder="Can you tell us a bit more? (optional)"
                    onChange={(e) => {
                      setFeedback(e.target.value)
                    }}
                  />
                </div>
              )}
              {ratingSubmitted && !feedbackSubmitted && (
                <MentorAiButton
                  onClick={handleSubmitFeedback}
                  type="outlined"
                  size="medium"
                  classNames="w-full"
                  disabled={feedback.length === 0}
                >
                  <div className="text-sm font-medium leading-[1.375rem]">
                    Submit Feedback
                  </div>
                </MentorAiButton>
              )}
            </div>
          ))}

        {feedbackSubmitted && (
          <div className="mt-6 rounded-xl border border-mentorai-stroke-strong bg-mentorai-bg-strong p-3 w-full">
            <p className="text-mentorai-text-sub text-center text-sm leading-[1.375rem] tracking-[0.084px]">{`Thanks for the feedback :)`}</p>
          </div>
        )}
      </div>
    </Modal>
  )
}

export default InterviewFeedbackPopup
