import React, { useEffect, useState, useRef } from 'react';

const JobAgent: React.FC = () => {
    const [isRunning, setIsRunning] = useState(false);
    const [logs, setLogs] = useState<string[]>([]);
    const logsEndRef = useRef<HTMLDivElement>(null);
    const [stats, setStats] = useState({ applied: 0, skipped: 0 });

    useEffect(() => {
        // Initial state load
        const loadState = async () => {
            const data = await chrome.storage.local.get(['autoApplyState', 'autoApplyLogs', 'autoApplyStats']);
            if (data.autoApplyState?.running) setIsRunning(true);
            if (data.autoApplyLogs) setLogs(data.autoApplyLogs.map((l: any) => l.message));
            if (data.autoApplyStats) setStats(data.autoApplyStats);
        };
        loadState();

        // Listen for updates from Content Script
        const handleMessage = (message: any) => {
            if (message.action === 'logAutoApply') {
                setLogs(prev => [...prev, message.message]);
            }
            if (message.action === 'autoApplyStateUpdate') {
                if (message.isRunning !== undefined) setIsRunning(message.isRunning);
                if (message.stats) setStats(message.stats);
            }
        };

        chrome.runtime.onMessage.addListener(handleMessage);
        return () => chrome.runtime.onMessage.removeListener(handleMessage);
    }, []);

    useEffect(() => {
        if (logsEndRef.current) {
            logsEndRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    }, [logs]);

    const handleStop = async () => {
        console.log('Auto Apply stopped bbb');
        // Send message to Background Script to stop globally
        chrome.runtime.sendMessage({ action: 'stopAutoApplyGlobal' });

        // Update local state
        setIsRunning(false);

        // Clear/Update storage state to prevent auto-resume
        await chrome.storage.local.set({
            autoApplyState: { running: false }
        });
    };

    const handleStart = async () => {
        // Clear previous logs
        setLogs([]);
        setStats({ applied: 0, skipped: 0 });

        // Set running state
        setIsRunning(true);
        await chrome.storage.local.set({
            autoApplyState: { running: true },
            autoApplyLogs: [],
            autoApplyStats: { applied: 0, skipped: 0 }
        });

        // Send message to background to activate auto-apply
        // This will open LinkedIn jobs page and start the process
        chrome.runtime.sendMessage({ action: 'activateAutoApply' });
    };

    return (
        <div className="flex flex-col h-full bg-gray-900 text-white p-4">
            <div className="flex justify-between items-center mb-4">
                <h2 className="text-xl font-bold">Job Agent</h2>
                <div className={`px-3 py-1 rounded-full text-xs ${isRunning ? 'bg-green-600' : 'bg-gray-600'}`}>
                    {isRunning ? 'Running' : 'Stopped'}
                </div>
            </div>

            <div className="grid grid-cols-2 gap-4 mb-4">
                <div className="bg-gray-800 p-3 rounded-lg text-center">
                    <div className="text-2xl font-bold text-blue-400">{stats.applied}</div>
                    <div className="text-xs text-gray-400">Applied</div>
                </div>
                <div className="bg-gray-800 p-3 rounded-lg text-center">
                    <div className="text-2xl font-bold text-gray-400">{stats.skipped}</div>
                    <div className="text-xs text-gray-400">Skipped</div>
                </div>
            </div>

            <div className="flex-1 bg-black rounded-lg p-3 overflow-y-auto font-mono text-xs border border-gray-800 mb-4">
                {logs.length === 0 ? (
                    <div className="text-gray-500 text-center mt-10">Waiting for logs...</div>
                ) : (
                    logs.map((log, i) => (
                        <div key={i} className="mb-1 text-gray-300 border-b border-gray-900 pb-1 last:border-0">
                            <span className="text-gray-500 mr-2">[{new Date().toLocaleTimeString()}]</span>
                            {log}
                        </div>
                    ))
                )}
                <div ref={logsEndRef} />
            </div>

            {isRunning ? (
                <button
                    onClick={handleStop}
                    className="w-full bg-red-600 hover:bg-red-700 text-white py-3 rounded-lg font-bold transition-colors"
                >
                    Stop Agent
                </button>
            ) : (
                <button
                    onClick={handleStart}
                    className="w-full bg-green-600 hover:bg-green-700 text-white py-3 rounded-lg font-bold transition-colors"
                >
                    Start Auto Apply
                </button>
            )}
        </div>
    );
};

export default JobAgent;
