import { useRef } from "react";
import useSignIn from "./use-sign-in";
import TopLampLights from "./top-lamp-lights.svg?react";
import DottedBgPattern from "./dotted-bg-pattern.svg?react";

const SignIn = () => {
  const { handleSignInClicked } = useSignIn();
  const videoRef = useRef<HTMLVideoElement>(null);

  const handleVideoHover = () => {
    if (videoRef.current) {
      videoRef.current.currentTime = 0;
      videoRef.current.play();
    }
  };

  return (
    <>
      <main className="w-full h-full bg-[#14161f] relative max-h-screen overflow-hidden">
        <TopLampLights className="absolute top-0 left-0 w-full z-0 max-h-screen overflow-hidden" />
        <DottedBgPattern className="absolute top-1/2 -translate-y-1/2 z-0 left-0 w-full max-h-screen overflow-hidden" />
        <div className="relative flex flex-col items-center justify-center w-full h-full px-4 z-[1]">
          <video
            ref={videoRef}
            src={"https://www.leeco.ai/videos/leeco-waving-hello.webm"}
            controls={false}
            playsInline
            autoPlay
            muted
            className="w-[152px]"
            onMouseEnter={handleVideoHover}
          />

          <p className="text-[22px] font-semibold font-bricolage-grotesque text-center pt-6">
            Hey, I am Leeco, your personal learning companion
          </p>

          <p className="text-white/60 pt-2 pb-11 text-[13px] text-center">
            Personalized your learning experience by signing up
          </p>

          <button
            className="w-full bg-[#5149F2] text-[#F2F2F2] font-medium text-base leading-[1.5] duration-200 tracking-[0.006em] p-3 rounded-xl flex items-center justify-center gap-1.5 shadow-[inset_0px_-3px_0px_0px_rgba(255,255,255,0.25)] hover:bg-[#5149F2]/90 transition-colors"
            onClick={() => handleSignInClicked({})}
          >
            Sign in &rarr;
          </button>
        </div>
      </main>
    </>
  );
};

export default SignIn;
