import CreateFirstPathIcon from "../../../assets/create-first-path-plus-icon.svg";
import useCreateFirstPath from "./use-create-first-path";
import CreatePathSparkleVector from "../../../assets/create-path-sparkle-vector.svg";
import { motion } from "framer-motion";

const CreateFirstPath = () => {
  const { search, searchQueriesList, handleSearchChange, handleCreatePathClick, handleTextareaKeyDown, shouldSlideDown, textareaRef, containerRef } = useCreateFirstPath();

  return (
    <div className="h-full px-3 flex flex-col justify-center items-center max-w-[300px]">
      <div className="flex flex-col gap-4 items-center">
        <img src={CreateFirstPathIcon} alt="create-first-path-icon.svg" />
        <div className="space-y-1 text-center">
          <p className="text-[#F2F2F2] text-[20px] font-semibold -tracking-[0.2px] font-bricolage-grotesque">
            Create Your First Path
          </p>
          <p className="text-[#94939F] text-xs font-medium font-manrope">Tell me what you want to learn</p>
        </div>
      </div>
      <div className="mt-6 space-y-4">
        <div className="space-y-2">
          <div ref={containerRef} className={`${shouldSlideDown ? "flex flex-col" : "relative"}`}>
            <textarea
              ref={textareaRef}
              placeholder="I want to learn..."
              autoFocus
              value={search}
              onChange={(e) => handleSearchChange(e)}
              onKeyDown={handleTextareaKeyDown}
              className={`border-none outline-none placeholder:text-[#606071] text-[#fff] text-[14px] font-medium font-manrope bg-transparent resize-none overflow-y-auto scrollbar-hide transition-all duration-300 ease-in-out ${
                shouldSlideDown ? "w-full" : "w-[calc(100%-90px)]"
              }`}
              rows={1}
              style={{
                minHeight: "20px",
                maxHeight: "100px",
              }}
            />
            <motion.button
              onClick={() => handleCreatePathClick(search, false)}
              className="shrink-0 bg-[#5149F2] hover:bg-[#736DF2] text-[#DDDDDF] text-[12px] font-semibold leading-[18px] font-manrope py-1 px-2 rounded-lg"
              animate={{
                position: shouldSlideDown ? "static" : "absolute",
                top: shouldSlideDown ? "auto" : "0px",
                right: shouldSlideDown ? "auto" : "0px",
                marginTop: shouldSlideDown ? "8px" : "0px",
                alignSelf: shouldSlideDown ? "flex-end" : "auto",
              }}
              transition={{
                duration: 0.4,
                ease: "easeOut",
                position: { duration: 0 },
                top: { duration: 0.2 },
                right: { duration: 0.2 },
                marginTop: { duration: 0.2 },
                alignSelf: { duration: 0 },
              }}
            >
              Create Path
            </motion.button>
          </div>
          <div
            className="w-full h-[1px] border-b border-[#45475F]"
            style={{
              borderStyle: "dashed",
              borderWidth: "0 0 1px 0",
              borderImage:
                "repeating-linear-gradient(to right, #45475F 0, #45475F 4px, transparent 4px, transparent 8px) 1",
            }}
          />
        </div>

        <div className="flex gap-2 flex-wrap justify-center">
          {searchQueriesList?.map((query) => (
            <button
              key={query}
              className="flex gap-1 items-center py-1.5 px-1.5 bg-[#212431] hover:bg-[#2F3241] rounded-lg border border-[#363645] text-[#DDDDDF] text-[12px] leading-[15px] font-medium font-manrope"
              onClick={() => handleCreatePathClick(`${query}`, true)}
            >
              <img src={CreatePathSparkleVector} alt="create-path-sparkle-vector.svg" />
              {query}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default CreateFirstPath;
