import React, { useRef } from "react";
import useFeatures from "./use-features";
import ChevronLeftWhiteBox from "../../../../../../assets/extension-plan-features/chevron-left-white-box.svg";
import ChevronRightWhiteBox from "../../../../../../assets/extension-plan-features/chevron-right-white-box.svg";
import MentorAiButton from "../../../../../../../common/button/mentorai-button";

type FeaturesProps = {
  type?: "stack" | "scroll";
};

const Features = ({ type = "stack" }: FeaturesProps) => {
  const { PlanFeaturesData, scrollLeft, scrollRight } = useFeatures();
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const handleScrollLeft = () => {
    scrollLeft(scrollContainerRef);
  };

  const handleScrollRight = () => {
    scrollRight(scrollContainerRef);
  };

  return (
    <>
      {type === "stack" ? (
        <div className="space-y-4">
          <p className="text-[10px] font-semibold leading-[15px] tracking-[0.5px] font-manrope">FEATURES</p>
          <div className="flex flex-col gap-4">
            {PlanFeaturesData.map((feature, index) => (
              <div className="relative p-3 bg-[#14161F] rounded-[10px] flex gap-2 items-center" key={index}>
                <img src={feature?.primaryIcon} alt={feature?.text} className="w-[36px] h-[36px]" />
                <div className="space-y-1.5">
                  <p className="text-[12px] font-semibold text-[#F2F2F2] -tracking-[0.12px] font-bricolage-grotesque">
                    {feature?.text}
                  </p>
                  <p className="text-[11px] text-[#94939F] font-bricolage-grotesque">{feature?.subText}</p>
                </div>
                <img src={feature?.secondaryIcon} alt={feature?.text} className="absolute top-0 right-0" />
              </div>
            ))}
          </div>
        </div>
      ) : (
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <p className="text-[10px] font-semibold leading-[15px] tracking-[0.5px] font-manrope text-white">
              FEATURES
            </p>
            <div className="flex gap-2">
              <button onClick={handleScrollLeft} className="cursor-pointer">
                <img src={ChevronLeftWhiteBox} alt="Scroll left" className="w-4 h-4" />
              </button>
              <button onClick={handleScrollRight} className="cursor-pointer">
                <img src={ChevronRightWhiteBox} alt="Scroll right" className="w-4 h-4" />
              </button>
            </div>
          </div>

          <div
            ref={scrollContainerRef}
            className="w-full flex gap-3 overflow-x-auto pb-2 scrollbar-hide"
          >
            {PlanFeaturesData.map((feature, index) => (
              <div
                key={index}
                className="relative p-3 bg-[#14161F] rounded-[10px] flex flex-col gap-2 min-w-[258px] flex-shrink-0"
              >
                <div className="flex items-center gap-2">
                  <img src={feature?.primaryIcon} alt={feature?.text} className="w-[36px] h-[36px]" />
                  <div className="flex-1">
                    <p className="text-[12px] font-semibold text-[#F2F2F2] -tracking-[0.12px] font-bricolage-grotesque">
                      {feature?.text}
                    </p>
                    <p className="text-[11px] text-[#94939F] font-bricolage-grotesque">{feature?.subText}</p>
                  </div>
                </div>
                <img src={feature?.secondaryIcon} alt={feature?.text} className="absolute top-0 right-0 opacity-60" />
              </div>
            ))}
          </div>
        </div>
      )}
    </>
  );
};

export default Features;
