import ErrorIcon from "../../../../assets/error.svg";
import MentorAiButton from "../../../../../common/button/mentorai-button";

type ErrorMessageProps = {
  message: string;
  sendMessage: Function;
  isLiveMessageStreaming?: boolean;
};

const ErrorMessageRedTheme = ({
  message,
  sendMessage,
  isLiveMessageStreaming,
}: ErrorMessageProps) => {
  const handleRetry = async () => {
    const { pendingMessage } = await chrome.storage.local.get("pendingMessage");
    sendMessage(pendingMessage?.message, false);
    chrome.storage.local.remove("pendingMessage");
  };

  return (
    <div className="border border-mentorai-stroke-error rounded-lg bg-[rgba(255,104,117,0.10)] p-3 flex flex-col gap-3" style={{ padding: "12px" }}>
      <div className="flex flex-col gap-2">
        <img src={ErrorIcon} alt="error" className="w-5 h-5" style={{ width: "20px", height: "20px" }} />
        <span
          className="text-mentorai-red-400 text-sm leading-[22px] font-medium tracking-[0.084px]"
          style={{ fontSize: "14px", lineHeight: "22px" }}
        >
          {message}
        </span>
      </div>
      <MentorAiButton
        type="outlined"
        onClick={handleRetry}
        disabled={isLiveMessageStreaming}
        style={{  height:"28px", paddingTop:"12px", paddingBottom:"12px" }}
      >
        Retry
      </MentorAiButton>
    </div>
  );
};

export default ErrorMessageRedTheme;
