import useLeecoRebrandingEducationBanner from "./use-leeco-rebranding-education-banner";
import BottomSheet from "../../../common/bottom-sheet/bottom-sheet";
import DiamondStar from "../../assets/diamond-star.svg?react";
import ProPilotIcon from "./pro-pilot-icon.svg?react";
import TransitionArrow from "./transition-arrow.svg?react";
import BgGradientAbstract from "./bg-gradient-abstract.svg?react";

const LeecoRebrandingEducationSheet = () => {
  const { isLeecoRebrandingEducationBannerOpen, handleCloseLeecoRebrandingEducationBanner, changesList } =
    useLeecoRebrandingEducationBanner();

  return (
    <BottomSheet
      open={isLeecoRebrandingEducationBannerOpen}
      handleClose={handleCloseLeecoRebrandingEducationBanner}
      className={{
        container: "relative bg-[#0e0a15]",
      }}
    >
      <BgGradientAbstract className="w-1/2 absolute top-0 left-0" />
      <BgGradientAbstract className="w-1/2 absolute top-0 right-0 -scale-x-100" />
      <div className="max-h-[94vh] overflow-y-auto space-y-9 p-5 relative z-[1]">
        <div className="flex flex-col items-center">
          <div className="flex gap-6 relative">
            <ProPilotIcon className="w-[76px]" />

            <TransitionArrow className="absolute bottom-4 left-1/2 -translate-x-1/2 w-[51px]" />

            <video
              src={"https://www.leeco.ai/videos/leeco-waving-hello.webm"}
              controls={false}
              playsInline
              autoPlay
              muted
              className="w-[83px]"
            />
          </div>

          <h1 className="text-white text-2xl font-medium pb-2 pt-6 font-bricolage-grotesque leading-[1.42] tracking-[-0.02em] text-center">
            ProPilot is now Leeco!
          </h1>
          <p className="text-white/60 text-sm font-normal leading-[1.57] tracking-[-0.02em] text-center">
            New name, more commitment to hold your hand
            <br /> and help you achieve every career goal
          </p>
        </div>

        <hr className="w-full border-[#1c1923]" />

        <div className="flex flex-col justify-center gap-9">
          {changesList.map((change) => (
            <div className="flex flex-row gap-1.5" key={change.title}>
              <DiamondStar className="w-2 h-2 text-white mt-2" />

              <div className="flex flex-col gap-1.5 flex-1">
                <p className="text-white text-[15px] font-semibold font-bricolage-grotesque tracking-[-0.015em]">
                  {change.title}
                </p>
                <p className="text-white/60 text-[11px] font-normal tracking-[0.01em]">{change.description}</p>
              </div>
            </div>
          ))}
        </div>
        <div className="sticky -bottom-5 bg-black py-5 w-full">
          <button
            className="w-full bg-[#5149F2] text-[#F2F2F2] font-medium text-base leading-[1.5] tracking-[0.006em] p-3 rounded-xl flex items-center justify-center gap-1.5 shadow-[inset_0px_-3px_0px_0px_rgba(255,255,255,0.25)] hover:bg-[#5149F2]/90 transition-colors"
            onClick={handleCloseLeecoRebrandingEducationBanner}
          >
            Explore Leeco →
          </button>
        </div>
      </div>
    </BottomSheet>
  );
};

export default LeecoRebrandingEducationSheet;
