import React, { useState, useEffect } from "react";
import { cn } from "../../../utils/cn";
import { LoaderWithThreeDots } from "../../loader/loader";
// import { MentorAiContext } from "../../../context/mentorai-context/mentorai-context";

const ContextCollectionOptions = ({
  data,
  sendMessage,
  setLiveMessages,
  mentoraiData,
}: {
  data: any;
  sendMessage: Function;
  setLiveMessages: Function;
  mentoraiData: any;
}) => {
  // const { mentoraiData } = useContext(MentorAiContext);
  const [loadingIndex, setLoadingIndex] = useState<number | null>(null);
  const [isDisabled, setIsDisabled] = useState(false);

  useEffect(() => {
    const storageListener = async (changes: any) => {
      if (changes.context_collection?.newValue === "completed") {
        // Get pendingMessage from storage and send it
        try {
          const { pendingMessage } = await chrome.storage.local.get([
            "pendingMessage",
          ]);
          if (pendingMessage) {
            setTimeout(() => {
              setLoadingIndex(null);
              sendMessage(pendingMessage?.message, false);
            }, 5000);
          }
        } catch (error) {
          console.error("Error getting pendingMessage:", error);
        }
      }
    };

    chrome.storage.onChanged.addListener(storageListener);
    return () => {
      chrome.storage.onChanged.removeListener(storageListener);
    };
  }, [data, sendMessage]);

  const handleClick = async (item: string, index: number) => {
    setIsDisabled(true);
    const activeTab = (
      await chrome.tabs.query({ active: true, currentWindow: true })
    )[0];
    const currentUrl: string = activeTab?.url || "";
    if (index === 0 && item !== "Continue") {
      // Send message to content script to trigger profile data collection
      setLoadingIndex(0);
      chrome.tabs.query({ active: true, currentWindow: true }, function (tabs) {
        const activeTab = tabs[0];
        if (activeTab?.id) {
          chrome.tabs.sendMessage(
            activeTab.id,
            {
              action: "triggerProfileDataCollection",
            },
            (response) => {
              if (response.status === "error") {
                setTimeout(async () => {
                  setLiveMessages([
                    {
                      props: {
                        model: {
                          id: new Date().getTime().toString(),
                          message: `It seems like you are logged out of leetcode. Thus I’m unable to access your profile. Continuing with your query for now. I can later analyse your profile. Once you’ve signed in to leetcode, you can re-analyse from the settings icon below ⬇️.
                          #-#-#[easy action start]
                          {"easy_action":"leetcode profile data collection","data": ["Continue"]}
                          [easy action end]#-#-#
                          `,
                          sentTime: new Date().getTime().toString(),
                          sender: "assistant",
                          direction: "incoming",
                          position: "single",
                          senderPhotoUrl: mentoraiData?.aiPhotoUrl,
                          senderName: mentoraiData?.name,
                        },
                        children: <></>,
                      },
                    },
                  ]);
                  setLoadingIndex(null);
                  setIsDisabled(false);
                }, 2000);
              }
            }
          );
        }
      });
    } else {
      const { pendingMessage } = await chrome.storage.local.get([
        "pendingMessage",
      ]);
      sendMessage(pendingMessage?.message, false);
      chrome.storage.local.set({
        skippedContextCollection: {
          [new URL(currentUrl).origin]: {
            profileData: true,
          },
        },
      });
    }

    chrome.runtime.sendMessage({
      action: "sendAnalytics",
      url: currentUrl,
      eventName: "Button Clicked",
      eventProperties: {
        button_name: item,
        url: currentUrl,
        location: "Chat",
      },
    });
  };

  return (
    <div className="flex flex-col gap-2">
      <ul className="flex flex-wrap items-center gap-2 overflow-x-auto scrollbar-hide pb-2 pt-6">
        {data?.length &&
          data?.map((item: any, index: any) => {
            return (
              <button
                key={index}
                onClick={() => handleClick(item, index)}
                disabled={isDisabled}
                className={cn(
                  "cursor-pointer max-h-[28px] flex items-center bg-mentorai-primary-base p-3 rounded-lg text-[#f2f2f2] text-xs leading-[0.12px] transition-all duration-300",
                  !isDisabled && "hover:bg-mentorai-primary-light",
                  index === 1 && [
                    "border border-mentorai-stroke-base bg-transparent text-mentorai-text-disabled cursor-pointer shadow-[0px_2px_8px_0px_rgba(255,255,255,0.04)]",
                    !isDisabled &&
                      "hover:border-mentorai-stroke-light hover:bg-mentorai-bg-hover-outlined hover:!text-mentorai-text-white active:border-mentorai-stroke-light active:bg-mentorai-bg-hover-outlined active:text-mentorai-text-white",
                  ],
                  isDisabled && "cursor-not-allowed opacity-80"
                )}
              >
                {loadingIndex === index ? (
                  <div className="flex items-center gap-2">
                    <LoaderWithThreeDots
                      color="#D0CFD4"
                      height="4"
                      width="16"
                    />
                    <span>Analysing</span>
                  </div>
                ) : (
                  item
                )}
              </button>
            );
          })}
      </ul>
      <span className="text-mentorai-text-sub text-[10px] leading-[14px] tracking-[0.06px]">
        *This is a one-time access only. You can change this later.
      </span>
    </div>
  );
};

export default ContextCollectionOptions;
