import { handlePost } from '../../core/Axios';

export const uploadReplacedPostImageToBackend = async (imageFile: File) => {
  if (imageFile) {
    const formData = new FormData();
    const fileName = imageFile.name + Math.random().toString();
    formData.append('file', imageFile, fileName);
    const uploadedFileResponse = await handlePost('common/upload?requestType=mentors&filepath=mentorai-extension/support-center', formData)
    const imageUrl = `${uploadedFileResponse.url}?alt=media&token=${uploadedFileResponse.token}`;
    return imageUrl;
  }
  return '';
};
