import { useContext, useEffect, useState } from "react";
import { MentorAiContext } from "../../context/mentorai-context/mentorai-context";

const useLeecoRebrandingEducationBanner = () => {
  const [isLeecoRebrandingEducationBannerOpen, setIsLeecoRebrandingEducationBannerOpen] = useState(false);
  const { mentoraiData, setMentoraiData } = useContext(MentorAiContext);

  const changesList = [
    {
      title: "Leeco is your all-in-one career companion",
      description: "Get help, insights & guidance wherever you learn or practice.",
    },
    {
      title: "Get guidance while solving on LeetCode",
      description: "Instant explanations & hints — right when you need them.",
    },
    {
      title: "Turn passive watching into active learning with smart quizes.",
      description: "Turn passive watching into active learning with smart quizes.",
    },
  ];

  const refetchMentoraiData = async () => {
    const mentoraiDataResponse = await chrome.runtime.sendMessage({
      action: "fetch_calls",
      fetch_call: "fetch_mentorai",
      refetch: true,
    });

    setMentoraiData(mentoraiDataResponse.mentorai_data);
  };

  useEffect(() => {
    if (mentoraiData?.name === "ProPilot") {
      setIsLeecoRebrandingEducationBannerOpen(true);
      refetchMentoraiData();
    }
  }, [mentoraiData?.recordId]);

  const handleCloseLeecoRebrandingEducationBanner = () => {
    setIsLeecoRebrandingEducationBannerOpen(false);
  };

  return {
    isLeecoRebrandingEducationBannerOpen,
    handleCloseLeecoRebrandingEducationBanner,
    changesList,
  };
};

export default useLeecoRebrandingEducationBanner;
