import { useEffect, useMemo, useState } from "react"

const useMentorai = () => {
  const [mentoraiData, setMentoraiData] = useState(null)
  const [loading, setLoading] = useState(false)

  const mentoraiContextValue = useMemo(
    () => ({
      mentoraiData,
      setMentoraiData,
      loading,
    }),
    [mentoraiData, loading]
  )

  const fetchMentoraiData = async () => {
    setLoading(true)
    const mentoraiDataResponse = await chrome.runtime.sendMessage({
      action: "fetch_calls",
      fetch_call: "fetch_mentorai",
    })
    setMentoraiData(mentoraiDataResponse.mentorai_data)
    setLoading(false)
  }

  useEffect(() => {
    fetchMentoraiData()
  }, [])

  return {
    mentoraiContextValue,
  }
}

export default useMentorai
