import LoadingIcon from "../../assets/loading.gif";

const Loading = () => {
    return (
        <>
            <main className="flex flex-col gap-2 self-stretch p-3 mx-auto my-auto w-full">
                <div className="flex flex-col gap-2  justify-center items-center m-auto">
                    <img src={LoadingIcon} alt="loading" className="h-8 w-8" />
                    <p className="text-[14px] leading-[22px] tracking-[0.084px] whitespace-nowrap bg-gradient-to-r from-[#F2F2F2] via-[#F2F2F2] to-[#4D4D57] bg-clip-text text-transparent font-medium">
                        Just a moment...
                    </p>
                </div>
            </main>
        </>
    );
};

export default Loading;
