import { useEffect, useState } from "react";

const useMenteeSubscription = (menteeData: any, mentoraiData: any) => {
  const [menteeSubscription, setMenteeSubscription] = useState(null);

  const updateMenteeSubscriptionOnLocalStorageChange = (changes: any) => {
    if (changes.menteeSubscription) {
      setMenteeSubscription(changes.menteeSubscription.newValue);
    }
  };

  const mentoraiRecordId = mentoraiData?.recordId || "";
  const menteeRecordId = menteeData?.recordId || "";

  useEffect(() => {
    if (menteeData && mentoraiData) {
      fetchMenteeSubscription(menteeRecordId, mentoraiRecordId);

      chrome.storage.local.onChanged.removeListener(updateMenteeSubscriptionOnLocalStorageChange);
      chrome.storage.local.onChanged.addListener(updateMenteeSubscriptionOnLocalStorageChange);
    }

    return () => {
      chrome.storage.local.onChanged.removeListener(updateMenteeSubscriptionOnLocalStorageChange);
    };
  }, [menteeRecordId, mentoraiRecordId]);

  const fetchMenteeSubscription = async (mentee_id: string, mentorai_id: string, forceRefetch: boolean = false) => {
    const menteeSubscription = await chrome.runtime.sendMessage({
      action: "fetch_calls",
      fetch_call: "fetch_mentee_subscription",
      mentee_id: mentee_id,
      mentorai_id: mentorai_id,
      refetch: forceRefetch,
    });

    setMenteeSubscription(menteeSubscription.mentee_subscription);
  };

  return { menteeSubscription, setMenteeSubscription };
};

export default useMenteeSubscription;
