import { motion } from "framer-motion";
import MentorAiButton from "../../../../../../common/button/mentorai-button";
import { cn } from "../../../../../../utils/cn";
import Button from "../../../../common/common-button";
import { useState } from "react";

type NpsRatingProps = {
    nps: number | null;
    setNps: Function;
    setStep: Function;
    getSelectedRatingClassName: Function;
    getDefaultRatingClassName: Function;
    setReasons: Function;
    setComment: Function;
    submitting: boolean;
    handlePostNps: Function;
    handleCancelNps: Function;
}

const NpsRating = ({ nps, setNps, setStep, getSelectedRatingClassName, getDefaultRatingClassName, setReasons, setComment, submitting, handlePostNps, handleCancelNps }: NpsRatingProps) => {
    const [hoveredNum, setHoveredNum] = useState(-1)
    const handleSubmit = () => {
        handlePostNps()
        setStep("feedback")
    }

    return (
        <>
            <p className="text-mentorai-text-white text-[16px] font-medium leading-[23px] tracking-[-0.16px] font-bricolage-grotesque">How likely are you to recommend Leeco to a friend?</p>
            <div className="w-full flex flex-col gap-2 mt-4">
                <div className="flex justify-between items-center gap-2 self-stretch">
                    {Array.from({ length: 10 }, (_, i) => i + 1).map((num) => {
                        const npsPresent = nps !== null && nps !== undefined;
                        const isSelected = npsPresent && num <= nps;
                        const selectedStyle = npsPresent ? getSelectedRatingClassName(nps) : "";
                        const defaultStyle = getDefaultRatingClassName(num);

                        const getTippyText = (rating: number) => {
                            if (rating >= 9) return "I'd love to!";
                            if (rating >= 7) return "Maybe I will";
                            return "No I wouldn't";
                        };

                        return (
                            <Button
                                onMouseEnter={() =>
                                    setHoveredNum(num)
                                }
                                onMouseLeave={() => {
                                    setHoveredNum(-1)
                                }}
                                key={num}
                                onClick={() => {
                                    setNps(num)
                                    setReasons([])
                                    setComment('')
                                }}
                                className={`h-6 w-6 rounded-md border-[0.8px]  text-center  text-xs relative 
                            leading-[1.125rem] tracking-[0.12px] ${npsPresent ? (isSelected
                                        ? selectedStyle
                                        : "border-[#45475f] bg-[#2f3241] hover:border-[#84848c] hover:bg-[#4b4e63]  hover:text-[#f2f2f2] text-[#dddddf]")
                                        : defaultStyle
                                    }`}
                            >
                                {num}
                                {hoveredNum === num && (
                                    <motion.div
                                        style={{
                                            left: num === 10 ? "-24px" : "-18px"
                                        }}
                                        className="whitespace-nowrap absolute top-[-28px] bg-[#4B4E63] flex items-center h-[23px] justify-center text-mentorai-text-white font-manrope text-xs leading-[normal] tracking-[-0.12px] px-1.5 rounded-md">
                                        {getTippyText(num)}
                                    </motion.div>
                                )}
                            </Button>
                        );
                    })}
                </div>

                <div className="flex justify-between items-start self-stretch">
                    <p className=" text-[#94939f]  text-[10px] leading-[14px] font-manrope font-medium tracking-[0.1px]">Not likely</p>
                    <p className=" text-[#94939f] text-right text-[10px] leading-[14px] font-manrope font-medium tracking-[0.1px]">Very likely</p>
                </div>
            </div>
            <div className="flex justify-between items-center gap-2 w-full mt-7">
                <MentorAiButton size="xSmall" type="outlined" classNames="flex-1 font-bricolage-grotesque" onClick={handleCancelNps}>
                    Maybe Later
                </MentorAiButton>
                <MentorAiButton size="xSmall" type="primary" disabled={submitting || !nps} classNames={cn("flex-1 font-bricolage-grotesque", submitting || !nps && "!bg-[#4D45E5] !opacity-[.3] !text-[#f2f2f2]")} onClick={handleSubmit}>
                    Submit
                </MentorAiButton>
            </div>
        </>
    )
}

export default NpsRating