import React, { useCallback, useContext, useEffect, useState } from "react";
import { useChatContext } from "../../context/chat-context/chat-context";
import { cn } from "../../../utils/cn";
import { SCREEN } from "../../types/type";
import BottomSheet from "../../../common/bottom-sheet/bottom-sheet";
import SupportCenter from "../conversation-container/support-center/support-center";
import ShareExtensionV2 from "./components/share-extension/share-extension-v2";
import SettingsV2 from "./components/settings/settings-v2";
import { PageContext } from "../../context/page-context/page-context";
import MentorAiActiveAvatar from "../../../content/components/mentorai-active-avatar/mentorai-active-avatar";
import { NavTabTypes } from "../../App";
import SettingsIcon from "../../assets/nav-settings.svg";
import HeartIcon from "../../assets/nav-heart.svg";
import ShareIcon from "../../assets/nav-share.svg";
import SupportIcon from "../../assets/nav-help-center.svg";
import SupportIconActive from "../../assets/nav-help-center-active.svg";
import ShareIconActive from "../../assets/nav-share-active.svg";
import ZapIconGreen from "../../assets/zap-green2.svg";
import ZapIconWhite from "../../assets/zap-white2.svg";
import SettingsIconActive from "../../assets/nav-settings-active.svg";
import CrownIcon from "../../assets/nav-crown.svg";
import CrownSmallIcon from "../../assets/crown-small.svg";
import ProIcon from "../../assets/nav-pro.svg";
import Tippy from "@tippyjs/react";
import ProfileSheet from "./components/profile-sheet";
// import PlansSheet from "../conversation-container/extension-paywall/plans-sheet/plans-sheet";
import PlansSheet from "../conversation-container/extension-paywall/plan-sheet-new/plan-sheet-new";
import SettingsGif from "../../assets/gif/settings-load.gif";
import SettingsHoverGif from "../../assets/gif/settings-hover.gif";
import HeartGif from "../../assets/gif/rate-load.gif";
import HeartHoverGif from "../../assets/gif/rate-hover.gif";
import ShareGif from "../../assets/gif/share-load.gif";
import ShareHoverGif from "../../assets/gif/share-hover.gif";
import HelpCenterGif from "../../assets/gif/help-centre-load.gif";
import HelpCenterHoverGif from "../../assets/gif/help-centre-hover.gif";
import { motion } from "framer-motion";
import { getUserStatus } from '../../../utils/subscription-helpers';
import { getAllUITextVariants } from '../../../utils/subscription-ui-helpers';


type SidebarNavProps = {
  navTabs: NavTabTypes[];
  currentScreen: SCREEN;
  onScreenChange: (screen: SCREEN) => void;
  show: boolean;
  mentoraiData: any;
  menteeData: any;
  menteeSubscription: any;
}

export type NavActionType = 'SETTINGS' | 'RATE' | 'SHARE' | 'SUPPORT' | 'PROFILE' | 'UPGRADE_PRO';
type NavigationTabType = 'CHAT' | 'PATHS'

const navActions: NavTabTypes[] = [
  {
    id: 1,
    label: "Settings",
    type: "SETTINGS",
    defaultIcon: SettingsIcon,
    activeIcon: SettingsIconActive,
    loadGif: SettingsGif,
    hoverGif: SettingsHoverGif,
    tippyContent: "Settings",
    delayOnFirstLoadAnimation: 700,
  },
  {
    id: 2,
    label: "Rate",
    type: "RATE",
    defaultIcon: HeartIcon,
    activeIcon: HeartIcon,
    loadGif: HeartGif,
    hoverGif: HeartHoverGif,
    tippyContent: "Rate us on Chrome",
    delayOnFirstLoadAnimation: 900,
  },
  {
    id: 3,
    label: "Share",
    type: "SHARE",
    defaultIcon: ShareIcon,
    activeIcon: ShareIconActive,
    loadGif: ShareGif,
    hoverGif: ShareHoverGif,
    tippyContent: "Share extension",
    delayOnFirstLoadAnimation: 1100,
  },
  {
    id: 4,
    label: "Support",
    type: "SUPPORT",
    defaultIcon: SupportIcon,
    activeIcon: SupportIconActive,
    loadGif: HelpCenterGif,
    hoverGif: HelpCenterHoverGif,
    tippyContent: "Support Centre",
    delayOnFirstLoadAnimation: 1300,
  },
  {
    id: 5,
    label: "Upgrade to Pro",
    type: "UPGRADE_PRO",
    defaultIcon: CrownIcon,
    activeIcon: CrownIcon,
    tippyContent: "View Pro Plans",
  }
]

const badgeVariant = (chatUsageData: any) => {
  let variant = "default";
  if (chatUsageData.dailyMessagesLeft === 0) {
    variant = "error"
  } else if (chatUsageData.dailyMessagesLeft < 11 && chatUsageData.dailyMessagesLeft > 0) {
    variant = "warning"
  } else {
    variant = "default"
  }
  return variant
}

const FreeCreditsBanner = ({ freeCredits, chatUsageData }: { freeCredits: number, chatUsageData: any }) => {
  let variant = badgeVariant(chatUsageData)
  return (
    <div className={`flex items-center gap-[1px] rounded-[100px] py-0.5 px-[4px]
    ${variant === "error" ? "bg-[#5E212C] hover:bg-[#792A39]" : (variant === "warning" ? "bg-[#5D491F] hover:bg-[#7A6029]" : "bg-[#16392E] hover:bg-[#1C4A3B]")}
    `}>
      <img src={variant === "default" ? ZapIconGreen : ZapIconWhite} alt="zap-icon" className="h-[8x] w-[7px]" />
      <div className=" text-center font-manrope text-[8px]  font-[700] leading-[10px] tracking-[-0.08px]" style={{ color: variant === "default" ? "#3EE089" : "#F2F2F2" }}>{freeCredits}</div>
    </div >
  )
}

function SidebarNav({
  navTabs,
  currentScreen,
  onScreenChange,
  show,
  mentoraiData,
  menteeData,
  menteeSubscription
}: SidebarNavProps) {


  const { activeTabUrl } = useContext(PageContext);
  const [showActionSheet, setShowActionSheet] = useState(false);
  const { setLiveMessages, fetchMessages, chatUsageData } = useChatContext();
  const [isSidePanelWidthMoreThanDefaultWidth, setIsSidePanelWidthMoreThanDefaultWidth] = useState(false);
  const [hoveredNavigationTab, setHoveredNavigationTab] = useState<string | null>(null);
  const [profileHovered, setProfileHovered] = useState(false);
  const [activeAction, setActiveAction] = useState<NavActionType | null>(null);
  const [iconLoadStates, setIconLoadStates] = useState<Record<string, boolean>>({});
  const [lastOpenedSheet, setLastOpenedSheet] = useState<string | null>(null);
  const { isPaidUser = false, dailyMessageLimit = 0, dailyMessagesLeft = 0, menteeDataLoading = false, todayOutgoingChatMessagesCount = 0 } = chatUsageData
  const isUserPaid = !menteeDataLoading && menteeData && isPaidUser;
  const userStatus = getUserStatus(menteeSubscription);

  // const isUserPaid = true;
  const handleResize = useCallback(() => {
    setIsSidePanelWidthMoreThanDefaultWidth(window.innerWidth > 360);
  }, [isSidePanelWidthMoreThanDefaultWidth]);

  useEffect(() => {
    if (window.innerWidth > 360) {
      setIsSidePanelWidthMoreThanDefaultWidth(true);
    }
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [handleResize]);

  useEffect(() => {
    const initialLoadStates: Record<string, boolean> = {};
    navTabs.forEach((tab) => {
      if (tab.delayOnFirstLoadAnimation) {
        initialLoadStates[`nav-${tab.label}`] = false;
        setTimeout(() => {
          setIconLoadStates(prev => ({
            ...prev,
            [`nav-${tab.label}`]: true
          }));
        }, tab.delayOnFirstLoadAnimation);

        setTimeout(() => {
          setIconLoadStates(prev => ({
            ...prev,
            [`nav-${tab.label}`]: false
          }));
        }, tab.delayOnFirstLoadAnimation + 2000);
      }
    });

    navActions.forEach((action) => {
      if (action.delayOnFirstLoadAnimation) {
        initialLoadStates[`action-${action.label}`] = false;
        setTimeout(() => {
          setIconLoadStates(prev => ({
            ...prev,
            [`action-${action.label}`]: true
          }));
        }, action.delayOnFirstLoadAnimation);

        setTimeout(() => {
          setIconLoadStates(prev => ({
            ...prev,
            [`action-${action.label}`]: false
          }));
        }, action.delayOnFirstLoadAnimation + 2000);
      }
    });

    setIconLoadStates(initialLoadStates);
  }, []);

  const handleTabClick = (tab: any, eventProperties?: any) => {
    onScreenChange(tab.screen as SCREEN);
    chrome.runtime.sendMessage({
      action: "sendAnalytics",
      url: activeTabUrl,
      eventName: "Extension Tab Visited",
      eventProperties: eventProperties || {}
    });
  };

  const handleAction = (action: NavActionType, actionLocation?: string) => {
    setActiveAction(action);
    if (action === 'RATE') {
      window.open("https://chromewebstore.google.com/detail/preplaced-ai-the-mentor-t/phbhomcaiapjeoghkpegkkccfidalfaa/reviews?hl=en", "_blank");
      chrome.runtime.sendMessage({
        action: "sendAnalytics",
        url: activeTabUrl,
        eventName: "Button Clicked",
        eventProperties: {
          button_name: "Rate us on Chrome",
          location: actionLocation || "Sidebar"
        },
      });
      setLastOpenedSheet("Rate On Chrome");
      return;
    }
    setShowActionSheet(true);

    let sheet = "";
    switch (action) {
      case 'SETTINGS':
        sheet = "Settings";
        break;
      case 'SHARE':
        sheet = "Share";
        break;
      case 'SUPPORT':
        sheet = "Support";
        break;
      case 'PROFILE':
        sheet = "Profile";
        break;
      case 'UPGRADE_PRO':
        sheet = "Pricing";
        break;
      default:
        break;
    }
    if (sheet) {
      if (sheet !== "Pricing") {
        chrome.runtime.sendMessage({
          action: "sendAnalytics",
          url: activeTabUrl,
          eventName: "Extension Sheet Opened",
          eventProperties: {
            sheet,
            location: actionLocation || "Sidebar"
          },
        });
      }
      setLastOpenedSheet(sheet);
    }
  };

  const handleCloseActionSheet = () => {
    setShowActionSheet(false);
    setActiveAction(null);
    if (lastOpenedSheet) {
      chrome.runtime.sendMessage({
        action: "sendAnalytics",
        url: activeTabUrl,
        eventName: "Extension Sheet Closed",
        eventProperties: {
          sheet: lastOpenedSheet
        },
      });
      setLastOpenedSheet(null);
    }
  };

  const handleToggleSettings = () => {
    setActiveAction((prev) => prev === 'SETTINGS' ? null : prev);
    setShowActionSheet(!showActionSheet);
    chrome.runtime.sendMessage({
      action: "sendAnalytics",
      url: activeTabUrl,
      eventName: 'Button Clicked',
      eventProperties: {
        button_name: "Settings",
        state: showActionSheet ? "opened" : "closed"
      },
    })
  }

  const renderActionContent = () => {
    switch (activeAction) {
      case 'SETTINGS':
        return (
          <BottomSheet open={showActionSheet} handleClose={handleCloseActionSheet} hideCloseButton={false}>
            <SettingsV2 setShowSettings={setShowActionSheet} setLiveMessages={setLiveMessages} fetchMessages={fetchMessages} chatUsageData={chatUsageData} handleToggleSettings={handleToggleSettings} />
          </BottomSheet>
        );
      case 'RATE':
        return (
          <a href="https://chromewebstore.google.com/detail/preplaced-ai-the-mentor-t/phbhomcaiapjeoghkpegkkccfidalfaa/reviews?hl=en" target="_blank" />
        );
      case 'SHARE':
        return (
          <BottomSheet open={showActionSheet} handleClose={handleCloseActionSheet} hideCloseButton={false}>
            <ShareExtensionV2 handleCloseSheet={handleCloseActionSheet} mentoraiData={mentoraiData} />
          </BottomSheet>
        );
      case 'SUPPORT':
        return (
          <BottomSheet open={showActionSheet} handleClose={handleCloseActionSheet}>
            <SupportCenter
              setSupportCenterOpen={setShowActionSheet}
              supportCenterOpen={showActionSheet}
              onClose={handleCloseActionSheet}
            />
          </BottomSheet>
        );
      case 'PROFILE':
        return (
          <BottomSheet open={showActionSheet} handleClose={handleCloseActionSheet} hideCloseButton={false}>
            <ProfileSheet menteeData={menteeData} mentoraiData={mentoraiData} chatUsageData={chatUsageData} onClose={handleCloseActionSheet} handleAction={handleAction} menteeSubscription={menteeSubscription} activeTabUrl={activeTabUrl} />
          </BottomSheet>
        );
      case 'UPGRADE_PRO':
        return (
          <BottomSheet open={showActionSheet} handleClose={handleCloseActionSheet}>
            <PlansSheet handleClose={handleCloseActionSheet} chatUsageData={chatUsageData} headerType="unlock-pro" actionLocation="Sidebar" />
          </BottomSheet>
        );
      default:
        return null;
    }
  }

  let variant = badgeVariant(chatUsageData)

  if (!show) return null;
  return (
    <>
      <nav className={cn("flex flex-col items-center justify-between h-full py-2",
        isSidePanelWidthMoreThanDefaultWidth ? "w-[52px]" : "w-[44px]"
      )}>

        <motion.li className="flex flex-col items-center justify-center w-full pt-1 relative"
          style={{
            gap: isSidePanelWidthMoreThanDefaultWidth ? "12px" : "8px"
          }}
        >
          <MentorAiActiveAvatar mentoraiData={mentoraiData} indicatorClassName="hidden" avatarClassName="w-[28px] h-[28px] rounded-full" />
          <div className="bg-[#363645] h-px w-[32px]">
            <span className="invisible">.</span>
          </div>

          <motion.div
            className="absolute left-0 w-0.5 bg-mentorai-bg-white"
            style={{
              height: isSidePanelWidthMoreThanDefaultWidth ? "56px" : "40px",
              top: navTabs.findIndex(tab => tab.screen === currentScreen) * (isSidePanelWidthMoreThanDefaultWidth ? 58 : 49) + (isSidePanelWidthMoreThanDefaultWidth ? 58 : 49) + ((navTabs.findIndex(tab => tab.screen === currentScreen) === 1 && isSidePanelWidthMoreThanDefaultWidth) ? 9 : 0) + ((navTabs.findIndex(tab => tab.screen === currentScreen) === 2 && isSidePanelWidthMoreThanDefaultWidth) ? 18 : 0),
            }}
            animate={{
              top: navTabs.findIndex(tab => tab.screen === currentScreen) * (isSidePanelWidthMoreThanDefaultWidth ? 58 : 49) + (isSidePanelWidthMoreThanDefaultWidth ? 58 : 49) + ((navTabs.findIndex(tab => tab.screen === currentScreen) === 1 && isSidePanelWidthMoreThanDefaultWidth) ? 9 : 0) + ((navTabs.findIndex(tab => tab.screen === currentScreen) === 2 && isSidePanelWidthMoreThanDefaultWidth) ? 18 : 0),
            }}
            transition={{
              type: "spring",
              stiffness: 300,
              damping: 30,
            }}
          />

          {navTabs.map((tab, index) => {
            const isActive = tab.screen === currentScreen;
            const isHovered = hoveredNavigationTab === tab.screen;
            const shouldShowLoadGif = tab.delayOnFirstLoadAnimation ? iconLoadStates[`nav-${tab.label}`] : false;
            return (
              <Tippy
                delay={0}
                duration={0}
                visible={isHovered}
                content={
                  <div className="bg-[#4B4E63] flex items-center h-[23px] justify-center text-mentorai-text-white font-manrope text-xs leading-[normal] tracking-[-0.12px] px-1.5 rounded-md">
                    {tab.tippyContent}
                  </div>
                }
                placement="left"
                offset={isSidePanelWidthMoreThanDefaultWidth ? [-6, -7] : [0, -4]}
                key={`${tab.id}-${index}`}
              >
                <button
                  onMouseEnter={() => setHoveredNavigationTab(String(tab.screen))}
                  onMouseLeave={() => setHoveredNavigationTab(null)}
                  key={tab.id}
                  className={cn(
                    "flex flex-col items-center justify-center relative box-border w-full",
                    isSidePanelWidthMoreThanDefaultWidth ? "h-[56px]" : "h-[40px]"
                  )}
                  onClick={() => handleTabClick(tab, {
                    tab: tab.label,
                    action: "Tab Toggled",
                  })}
                >
                  <div className={cn(
                    "w-[32px] h-[32px] rounded-lg p-1 relative flex items-center justify-center",
                    (isHovered || isActive) ? "bg-mentorai-bg-sub" : "",
                  )}>
                    <img src={shouldShowLoadGif ? (isActive ? tab.activeLoadHoverGif : tab.loadGif) : (isHovered ? (isActive ? tab.activeIcon : tab.hoverGif) : (isActive ? tab.activeIcon : tab.defaultIcon))} alt={tab.label} className="w-[24px] h-[24px] max-h-[24px] min-h-[24px] max-w-[24px] min-w-[24px]" />
                  </div>
                  {isSidePanelWidthMoreThanDefaultWidth &&
                    <div className={`h-[12px] font-bricolage-grotesque text-[10px] leading-[normal] tracking-[-0.12px] font-semibold pt-0.5 ${isActive ? "text-mentorai-text-white" : "text-mentorai-text-sub"}`}>
                      {tab.label}
                    </div>
                  }
                </button>
              </Tippy>
            )
          })}
        </motion.li>


        <li className="flex flex-col items-center justify-center gap-2 pb-[12px]">
          {navActions.map((action) => {
            const isActive = action.type !== "RATE" && action.type === activeAction;
            const isHovered = hoveredNavigationTab === action.type;
            const shouldShowLoadGif = action.delayOnFirstLoadAnimation ? iconLoadStates[`action-${action.label}`] : false;
            if (action.type === "UPGRADE_PRO" && isUserPaid) {
              return <></>;
            }
            return (
              <Tippy
                visible={isHovered}
                delay={0}
                duration={0}
                content={
                  <div className="bg-[#4B4E63] flex items-center h-[23px] justify-center text-mentorai-text-white font-manrope text-xs leading-[normal] tracking-[-0.12px] px-1.5 rounded-md">
                    {action.tippyContent}
                  </div>
                }
                placement="left"
                offset={[0, 3.5]}
                key={action.id}
              >
                <button
                  onMouseEnter={() => setHoveredNavigationTab(String(action.type))}
                  onMouseLeave={() => setHoveredNavigationTab(null)}
                  key={action.id}
                  className={cn(
                    "flex flex-col items-center justify-center rounded-lg relative",
                  )}
                  onClick={() => handleAction(action.type as NavActionType)}
                >
                  <div className={cn(
                    "w-[28px] h-[28px] rounded-lg p-1 relative flex items-center justify-center",
                    (isHovered || isActive) ? "bg-mentorai-bg-sub" : "",
                  )}>
                    {action.type === "UPGRADE_PRO" ?
                      <img src={action.defaultIcon} alt={action.label} className="w-[20px] h-[20px] max-h-[20px] min-h-[20px] max-w-[20px] min-w-[20px]" />
                      :
                      <img src={shouldShowLoadGif ? action.loadGif : (isHovered ? action.hoverGif : (isActive ? action.activeIcon : action.defaultIcon))} alt={action.label} className="w-[20px] h-[20px] max-h-[20px] min-h-[20px] max-w-[20px] min-w-[20px]" />
                    }
                  </div>
                </button>
              </Tippy>
            )
          })}

          <Tippy
            delay={0}
            duration={0}
            content={
              <div className="bg-[#4B4E63] flex items-center h-[23px] justify-center text-mentorai-text-white font-manrope text-xs leading-[normal] tracking-[-0.12px] px-1.5 rounded-md">
                View Profile
              </div>
            }
            placement="left"
            offset={[0, 3.5]}
          >
            <div
              onMouseEnter={() => setProfileHovered(true)}
              onMouseLeave={() => setProfileHovered(false)}
              style={{
                border: isUserPaid ? "1.5px solid #4D3B17" : `1.5px solid  ${variant === "error" ? (profileHovered ? "#792A39" : "#5E212C") : (variant === "warning" ? (profileHovered ? "#7A6029" : "#5D491F") : (profileHovered ? "#1C4A3B" : "#16392E"))}`,
              }}
              onClick={() => handleAction('PROFILE')}
              className={cn(`flex justify-center item-center relative w-[28px] h-[28px] rounded-full cursor-pointer`,
              )}>
              <MentorAiActiveAvatar mentoraiData={menteeData} indicatorClassName="hidden" avatarClassName="rounded-full mt-[2.4px] w-[20px] h-[20px] min-w-[20px] min-h-[20px] max-w-[20px] max-h-[20px]" />
              {!menteeDataLoading && menteeData &&
                <div className={`absolute bottom-[-8px] ${userStatus?.isCancelled ? ' w-max' : ''}`}>
                  {isUserPaid ?
                    <>
                      {userStatus?.isCancelled ?
                        <PaidPlanProfileBadge />
                        :
                        <img src={ProIcon} alt="Pro" className="w-[36px] h-[14px] scale-[1.2]" />
                      }
                    </>
                    :
                    <FreeCreditsBanner freeCredits={dailyMessagesLeft} chatUsageData={chatUsageData} />
                  }
                </div>
              }
            </div>
          </Tippy>
        </li>
      </nav >
      {renderActionContent()}
    </>
  );
}

const PaidPlanProfileBadge = () => {
  const { menteeSubscription } = useChatContext();
  const userStatus = getUserStatus(menteeSubscription);
  const [profileIcon, setProfileIcon] = useState('');

  useEffect(() => {
    const loadProfileIcon = async () => {
      try {
        const variants = await getAllUITextVariants(userStatus);
        setProfileIcon(variants.profileIcon);
      } catch (error) {
        console.error('Error loading profile icon:', error);
        setProfileIcon('');
      }
    };
    loadProfileIcon();
  }, [userStatus]);

  const getClassName = () => {
    let className = "";
    switch (profileIcon) {
      case "paid_last_days":
        className = " bg-[linear-gradient(90deg,_#4D3B17_0%,_#740E16_55.28%)] hover:bg-[linear-gradient(90deg,_#411914_0%,_#88111A_50%)] ";
        break;
      case "paid_during_days":
        className = " bg-[linear-gradient(90deg,_#4D3B17_0%,_#724803_55.28%)] hover:bg-[linear-gradient(88deg,_#392C11_21.86%,_#724803_96.38%)] ";
        break;
      case "paid_left_days":
        className = " bg-[#392C11] hover:bg-[#433314] ";
        break;
      default:
        break;
    }
    return className;
  }
  return (
    <div className={`flex items-center gap-[1px] rounded-[100px] py-0.5 px-[4px] whitespace-nowrap h-[14px] ${getClassName()}`}>
      <img src={CrownSmallIcon} alt="Pro" className="w-[10px] h-[10px]" />
      <span className="text-[8px] font-bold leading-[10px] text-[#E6BE6E] font-manrope">{userStatus.daysRemaining}d</span>
    </div>
  )
}


export default SidebarNav