
import { useContext } from "react";
import { PageContext } from "../../../context/page-context/page-context";

const useOtherActivePaths = () => {
	const { activeTabUrl } = useContext(PageContext);

  const handlePathClick = async (recordId: string, pathTitle: string) => {
    chrome.runtime.sendMessage({
      action: "sendAnalytics",
      url: activeTabUrl,
      eventName: "Path Clicked",
      eventProperties: {
        tab: "Paths",
        type: "other active",
        path: pathTitle,
      }
    });
    
    await chrome.tabs.create({
      url: `${import.meta.env.VITE_LEECO_WEB_URL}/learn/${recordId}`,
      active: true,
    });
  };

  return {
    handlePathClick,
  }
}

export default useOtherActivePaths