import { useContext, useEffect, useState } from "react";
// import LanguageAndTonePreference from "./language-and-tone-preferences/language-and-tone-preferences";
import ConversationFeedback from "./conversation-feedback/conversation-feedback";
import { ChatUsageData, NPS_STATUS } from "../../../context/chat-context/use-chat-conversations";
import ReplyRegion from "./reply-region/reply-region";
// import Settings from "../settings/settings";
import { PageContext } from "../../../context/page-context/page-context";

interface CustomUserInputProps {
    isLiveMessageStreaming?: boolean;
    conversationFeedbackStatus: string;
    setConversationFeedbackStatusToCancel: Function;
    setConversationFeedbackStatusToSubmitted: Function;
    npsStatus: string
    setNpsStatus: Function
    setLiveMessages: Function
    fetchMessages: Function
    inputHeight: number
    chatUsageData: ChatUsageData,
}

const CustomUserInput = ({
    isLiveMessageStreaming,
    conversationFeedbackStatus,
    npsStatus,
    setNpsStatus,
    setConversationFeedbackStatusToCancel,
    setConversationFeedbackStatusToSubmitted,
    setLiveMessages,
    fetchMessages,
    inputHeight,
    chatUsageData,
}: CustomUserInputProps) => {

    const [customUserInput, setCustomUserInput] = useState<string>("");
    const { selectedText, setSelectedText } = useContext(PageContext)


    useEffect(() => {
        chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
            if (message.action === "askInChat") {
                setSelectedText(message.text || "");
                chrome.storage.local.set({
                    "selectedText": message.text
                })
            }
            if (message.action === "textSelected") {
                setSelectedText(message.text || "");
                chrome.storage.local.set({
                    "selectedText": message.text
                })
            }
        })
    }, [])

    useEffect(() => {

        let customUserInput: any = "";
        if (selectedText) {
            customUserInput = "selectedText";
        }
        else if (npsStatus === NPS_STATUS.SHOW) {
            customUserInput = "npsFeedback";
        }
        else if (conversationFeedbackStatus === "show") {
            customUserInput = "conversationFeedback";
        }
        else if (!isLiveMessageStreaming) {
            customUserInput = "languageAndTonePreference";
        } else {
            customUserInput = ''
        }
        setCustomUserInput(customUserInput);
    }, [conversationFeedbackStatus, isLiveMessageStreaming, npsStatus, selectedText]);

    return (
        <div
            style={{
                bottom: !!inputHeight ?
                    `${inputHeight + 23}px`
                    : "82px"
            }}
            className={`absolute right-[10px] z-[9]`}>
            {customUserInput === "conversationFeedback" &&
                <div className="absolute bottom-[40px] right-[-10px] w-[calc(100vw)] z-[1]">
                    <ConversationFeedback
                        conversationFeedbackStatus={conversationFeedbackStatus}
                        setConversationFeedbackStatusToCancel={() => setConversationFeedbackStatusToCancel("cancel")}
                        setConversationFeedbackStatusToSubmitted={() => setConversationFeedbackStatusToSubmitted("submitted")}
                    />
                </div>
            }
            {customUserInput === "languageAndTonePreference" &&
                <></>
                // <div className="flex items-start gap-1 h-7 mb-3">
                //     <Settings fetchMessages={fetchMessages} setLiveMessages={setLiveMessages} chatUsageData={chatUsageData} />
                //     <LanguageAndTonePreference />
                // </div>
            }

            {customUserInput === "selectedText" && selectedText &&
                <ReplyRegion
                    selectedText={selectedText}
                    onRemove={() => {
                        setSelectedText("");
                        chrome.storage.local.remove("selectedText");
                    }}
                />
            }
        </div>
    );
};

export default CustomUserInput;
