import { useContext, useEffect, useState, useRef } from "react";
import { MenteeContext } from "../../../../context/mentee-context/mentee-context";
import { ChatUsageData } from "../../../../context/chat-context/use-chat-conversations";
import useExtensionPlansContainer from "./components/extension-plans/use-extension-plans-container";
import getCurrency from "../../../../../utils/currency";
import { redirectToCheckout } from "../../../../utils/checkout-redirect";
import { ChatContext } from "../../../../context/chat-context/chat-context";
import { getMostRecentSubscription } from "../../../../../utils/subscription-helpers";

const usePlansSheet = (handleClose: () => void, chatUsageData: ChatUsageData, activeTabUrl: string) => {
  const [selectedPlan, setSelectedPlan] = useState<"1 month" | "1 year">("1 year");
  const { menteeData } = useContext(MenteeContext);
  const { menteeSubscription } = useContext(ChatContext);
  const { extensionPlans, trialDays } = useExtensionPlansContainer();
  const isComponentStable = useRef(false);

  const pricingVariant = extensionPlans?.[0]?.pricingVariant;
  const currency = getCurrency();

  const handleChangePlan = (plan: string) => {
    if (plan === "1 month") {
      setSelectedPlan("1 month");
    } else {
      setSelectedPlan("1 year");
    }
  };

  useEffect(() => {
    const timer = setTimeout(() => {
      isComponentStable.current = true;
    }, 500);
    return () => clearTimeout(timer);
  }, []);
  useEffect(() => {
    if (!isComponentStable.current) {
      return;
    }

    if (selectedPlan === "1 month") {
      const planObj = extensionPlans?.find((p) => p.validity === "1 month");
      const pricing = planObj ? planObj.totalPrice : "";
      if (pricing) {
        chrome.runtime.sendMessage({
          action: "sendAnalytics",
          url: activeTabUrl,
          eventName: "Pricing Plan Toggled",
          eventProperties: {
            plan: "month",
            pricing: `${pricing}/month`,
          },
        });
      }
    } else if (selectedPlan === "1 year") {
      const planObj = extensionPlans?.find((p) => p.validity === "1 year");
      const pricing = planObj ? planObj.totalPrice : "";
      if (pricing) {
        chrome.runtime.sendMessage({
          action: "sendAnalytics",
          url: activeTabUrl,
          eventName: "Pricing Plan Toggled",
          eventProperties: {
            plan: "year",
            pricing: `${pricing}/year`,
          },
        });
      }
    }
  }, [selectedPlan]);

  const handlePurchaseSuccess = (message: any) => {
    if (message.action === "purchaseSuccess") {
      handleClose();
    }
  };

  useEffect(() => {
    chrome.runtime.onMessage.addListener(handlePurchaseSuccess);

    return () => {
      chrome.runtime.onMessage.removeListener(handlePurchaseSuccess);
    };
  }, []);

  const handlePaymentClick = async () => {
    const mostRecentSubscription = getMostRecentSubscription(menteeSubscription?.subscriptions);
    const isTrialCancelled = mostRecentSubscription?.cancelledOn && menteeSubscription?.pricing_plan?.user_type === "trial";
    if (isTrialCancelled) {
      await redirectToCheckout({
        location: "Trial Cancelled Banner",
        menteeSubscription: menteeSubscription,
      });
    } else {
      await redirectToCheckout({
        chatUsageData,
        location: "Pricing Sheet",
        selectedPlan: selectedPlan,
        menteeData: menteeData,
        menteeSubscription: menteeSubscription,
      });
    }
    handleClose();
  };

  const today = new Date();

  const oneMonthFromToday = new Date(today);
  oneMonthFromToday.setMonth(today.getMonth() + 1);

  const oneDayBeforeOneMonth = new Date(oneMonthFromToday);
  oneDayBeforeOneMonth.setDate(oneMonthFromToday.getDate() - 1);

  const seventhDayFromToday = new Date(today);
  seventhDayFromToday.setDate(today.getDate() + 7);

  const sixthDayFromToday = new Date(today);
  sixthDayFromToday.setDate(today.getDate() + 6);

  const formatDate = (date: Date) => {
    return date.toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
      year: "numeric",
    });
  };

  const offerPlan = extensionPlans?.find((plan) => plan?.validity === "1 month");

  return {
    selectedPlan,
    handleChangePlan,
    handlePaymentClick,
    pricingVariant,
    oneMonthFromToday,
    oneDayBeforeOneMonth,
    seventhDayFromToday,
    sixthDayFromToday,
    offerPlan,
    formatDate,
    currency,
    trialDays,
  };
};

export default usePlansSheet;
