import Loading from "../../assets/loading.gif";
const webUrl = import.meta.env.VITE_LEECO_WEB_URL;

const SignupInProgress = () => {
  return (
    <>
      <main className="flex flex-col p-3 w-full h-full items-center justify-center">
        <img src={Loading} alt="loading" className="h-8 w-8" />
        <p className="text-[22px] font-semibold font-bricolage-grotesque text-center pt-6">Sign up in progress</p>
        <p className="text-white/60 pt-2 text-sm text-center">
          Something wrong?
          <button
            className="ml-1 text-[#736DF2]"
            onClick={() => {
              window.open(`${webUrl}/authenticate-extension`, "_blank");
            }}
          >
            Restart sign up
          </button>
        </p>
      </main>
    </>
  );
};

export default SignupInProgress;
