import React, { useEffect, useRef } from 'react';
import { motion } from 'framer-motion';

interface ProgressBarWithAvatarsProps {
    fixedPositionIcon: string;
    varPositionIcon: string;
    completedPercentage: number;
}

const ProgressBarWithAvatars: React.FC<ProgressBarWithAvatarsProps> = ({
    fixedPositionIcon,
    varPositionIcon,
    completedPercentage,
}) => {
    const userAvatarRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (userAvatarRef.current) {
            userAvatarRef.current.style.setProperty('--target-left', `${completedPercentage - 4}%`);
        }
    }, [completedPercentage]);

    return (
        <div className="relative w-full h-2 rounded-full  bg-progress-unfilled-bg  overflow-visible">
            <motion.div
                className="absolute left-0 top-0 h-2 rounded-full bg-progress-filled-bg transition-all duration-700"
                style={{
                    width: `${completedPercentage}%`,
                    zIndex: 1,
                }}
                initial={{ width: 0 }}
                animate={{ width: `${completedPercentage}%` }}
                transition={{ duration: 1, ease: "easeInOut" }}
            />


            <div
                className="absolute left-0 top-0 h-2 rounded-full bg-progress-filled-bg"
                style={{ width: `${completedPercentage}%`, zIndex: 1 }}
            />
            <div
                ref={userAvatarRef}
                className="user-avatar absolute top-1/2 transform -translate-y-1/2 rounded-full overflow-hidden z-10"
            >
                <img src={varPositionIcon} alt="User" className=" object-cover rounded-full w-4 h-4 border border-[rgba(255,255,255,0.32)] " />
            </div>

            <div className="absolute right-0 top-1/2 transform -translate-y-1/2 rounded-full overflow-hidden z-10">
                <img src={fixedPositionIcon} alt="Mentor" className=" object-cover rounded-full w-4 h-4 border border-[rgba(255,255,255,0.32)] " />
            </div>
        </div>
    );
};

export default ProgressBarWithAvatars;
