import ZapIconGreen from '../../../assets/zap-green.svg';
import ZapIconWite from '../../../assets/zap-white.svg';
import ArrowRightIcon from '../../../assets/arrow-right-line.svg'
import Coupon from '../../../assets/gif/coupon-sky-blue.gif'
import PurchaseSheetButton from './purchase-sheet-button'
import { ChatUsageData } from '../../../context/chat-context/use-chat-conversations'
import { cn } from '../../../../utils/cn'
import useExtensionPlansContainer from '../extension-paywall/plans-sheet/components/extension-plans/use-extension-plans-container';
import { getFormattedPriceWithSymbol } from '../../../../utils/currency';
import { motion, AnimatePresence } from 'framer-motion';
import { useRef, useEffect, useState } from 'react';

type Props = {
  chatUsageData: ChatUsageData
}

const DailyLimitLeft = ({ chatUsageData }: Props) => {
  const { extensionPlans } = useExtensionPlansContainer()
  const hasAnimatedRef = useRef(false);
  const [shouldAnimate, setShouldAnimate] = useState(false);
  
  const badgeVariant = () => {
    let variant = "default";
    if (chatUsageData.dailyMessagesLeft === 0) {
      variant = "error"
    } else if (chatUsageData.dailyMessagesLeft < 11 && chatUsageData.dailyMessagesLeft > 0) {
      variant = "warning"
    } else {
      variant = "default"
    }
    return variant
  }
  const showPricingValue = chatUsageData?.todayOutgoingChatMessagesCount > 2 && chatUsageData?.dailyMessagesLeft > 10;
  const variant = badgeVariant()
  const monthlyPriceString = getFormattedPriceWithSymbol(extensionPlans?.find((plan) => plan?.validity === "1 month")?.totalPrice!);

  useEffect(() => {
    if (showPricingValue && !hasAnimatedRef.current) {
      hasAnimatedRef.current = true;
      setShouldAnimate(true);
    }
  }, [showPricingValue]);

  return (
    <PurchaseSheetButton chatUsageData={chatUsageData} buttonId="daily-limit-below-chatbox" headerType='available-credits' bannerType='limited-free-plan' className={cn("purchase-subscription-button flex items-center pl-1 py-[5px] rounded-[100px] h-[20px] font-bricolage-grotesque",
      variant === "error" ? "bg-[#5E212C] hover:bg-[#792A39]" : (variant === "warning" ? "bg-[#5D491F] hover:bg-[#7A6029]" : " bg-[#16392E] hover:bg-[#1C4A3B]")
    )} actionLocation="Credit Count">
      <img src={variant === "default" ? ZapIconGreen : ZapIconWite} alt='zap-icon' className='h-3 w-3' />
      <span className="text-xs leading-normal font-medium tracking-[-0.12px]" style={{ color: variant === "default" ? "#3EE089" : "#F2F2F2" }}>{chatUsageData.dailyMessagesLeft}</span>
      <AnimatePresence>
        {showPricingValue && (
          <motion.span 
            className="text-xs flex items-center whitespace-nowrap font-medium leading-normal tracking-[-0.12px] text-[#47C2FF] pl-[4px] overflow-hidden"
            initial={shouldAnimate ? { width: 0, opacity: 0 } : { width: "auto", opacity: 1 }}
            animate={{ width: "auto", opacity: 1 }}
            exit={{ width: 0, opacity: 0 }}
            transition={{ 
              duration: 0.3, 
              ease: "easeInOut",
              width: { duration: 0.4, ease: "easeOut" }
            }}
          >
            Upgrade at {monthlyPriceString}
            <img src={Coupon} alt="Coupon" className="h-[15px] w-[15px] ml-[2px]" />
          </motion.span>
        )}
      </AnimatePresence>
      <img src={ArrowRightIcon} className="" />
    </PurchaseSheetButton>
  )
}

export default DailyLimitLeft