import React from "react";
import { createPortal } from "react-dom";
import { motion, AnimatePresence } from "framer-motion";
import MentorAiButton from "../button/mentorai-button";
import CloseIcon from "../../src/assets/close-icon.svg";
import CloseIconHovered from "../../src/assets/close-icon-hovered.svg";

interface BottomSheetProps {
  open: boolean;
  children: React.ReactNode;
  handleClose?: () => void;
  className?: {
    overlay?: string;
    container?: string;
  };
  hideCloseButton?: boolean;
}

const BottomSheet: React.FC<BottomSheetProps> = ({
  open,
  children,
  handleClose,
  className,
  hideCloseButton = true
}) => {
  // Animation variants for the bottom sheet
  const sheetVariants = {
    hidden: {
      y: "100%",
      transition: {
        type: "spring",
        velocity: 1000,
        stiffness: 300,
        damping: 20,
        mass: 0.4,
      },
    },
    visible: {
      y: 0,
      transition: {
        type: "spring",
        velocity: 1000,
        stiffness: 300,
        damping: 20,
        mass: 0.4,
      },
    },
  };

  // Animation variants for the overlay
  const overlayVariants = {
    hidden: {
      opacity: 0,
      transition: {
        duration: 0.2,
      },
    },
    visible: {
      opacity: 1,
      transition: {
        duration: 0.2,
      },
    },
  };

  // Handle outside click
  const onOverlayClick = () => {
    if (handleClose) {
      handleClose();
    }
  };

  // Prevent click propagation when clicking on the sheet content
  const onSheetClick = (e: React.MouseEvent) => {
    e.stopPropagation();
  };

  const modalContent = (
    <AnimatePresence>
      {open && (
        <div
          className="fixed inset-0 z-[9999] flex items-end justify-center"
          role="dialog"
          aria-modal="true"
          aria-labelledby="bottom-sheet-title"
        >
          {/* Overlay */}
          <motion.div
            className={`fixed inset-0 bg-[rgba(0,0,0,0.60)] backdrop-blur-[1.5px] !rounded-tl-[6px] !rounded-bl-[6px] ${className?.overlay || ""}`}
            variants={overlayVariants}
            initial="hidden"
            animate="visible"
            exit="hidden"
            onClick={onOverlayClick}
          />

          {/* Bottom Sheet */}
          <motion.div
            className={`
              relative w-full h-fit rounded-t-xl
              ${className?.container || ""}
            `}
            variants={sheetVariants}
            initial="hidden"
            animate="visible"
            exit="hidden"
            onClick={onSheetClick}
          >
            {!hideCloseButton &&
              <MentorAiButton classNames="!cursor-pointer transition-all duration-100 group !w-[28px] !h-[28px] absolute top-2 right-2 !z-[10000]"
                type="outlined"
                size="small"
                semiRounded
                onClick={() => handleClose && handleClose()}>
                <img src={CloseIcon} alt="close" className="w-[16px] h-[16px] max-w-[16px] max-h-[16px] flex group-hover:hidden" />
                <img src={CloseIconHovered} alt="close" className="w-[16px] h-[16px] max-w-[16px] max-h-[16px] hidden group-hover:flex" />
              </MentorAiButton>
            }
            {/* Content area */}
            {children}
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );

  // Render to portal if document is available (client-side)
  if (typeof document !== "undefined") {
    return createPortal(modalContent, document.body);
  }

  // Fallback for SSR
  return null;
};

export default BottomSheet;
