import React, { useRef, useState, useEffect, useContext } from 'react';
import { motion } from 'framer-motion';
import CrownLarge from '../../assets/crown-large.svg';
import LeecoMascot from '../../assets/LeecoGOT.webp';
import RightArrowGradiant from '../../assets/right-arrow-gradiant.svg';
import useExtensionPlansContainer from '../conversation-container/extension-paywall/plan-sheet-new/components/extension-plans/use-extension-plans-container';
import getCurrency, { getFormattedPriceWithSymbol } from '../../../utils/currency';
import MentorAiRoundedButtonIcon from '../../assets/mentorai-rounded-button-icon.svg';
import MentorAiRoundedButtonIconHover from '../../assets/mentorai-rounded-button-icon-hover.svg';
import { getCreditLimitConfig } from '../../../utils/credit-limit-utils';
import { redirectToCheckout } from '../../utils/checkout-redirect';
import { ChatContext } from '../../context/chat-context/chat-context';
import { trackSoftTriggerEvent } from '../../../core/Analytics';
import { getMostRecentSubscription } from '../../../utils/subscription-helpers';

interface CreditPromotionalCardProps {
  chatUsageData: any;
}

const CreditPromotionalCard: React.FC<CreditPromotionalCardProps> = ({
  chatUsageData,
}) => {
  const { extensionPlans } = useExtensionPlansContainer();
  const monthlyPriceString = getFormattedPriceWithSymbol(extensionPlans?.find((plan) => plan?.validity === "1 month")?.totalPrice!);
  const [isIconHovered, setIsIconHovered] = useState(false);
  const [showComponent, setShowComponent] = useState(false);
  const creditsLeft = chatUsageData.dailyMessagesLeft;
  const isComponentMounted = useRef(false);
  const { menteeSubscription } = useContext(ChatContext);
  const latestSubscription = getMostRecentSubscription(menteeSubscription?.subscriptions);
  const isTrialCancelled = latestSubscription?.cancelledOn && menteeSubscription?.pricing_plan?.user_type === "trial";
  useEffect(() => {
    if (isComponentMounted.current) {
      return;
    }
    trackSoftTriggerEvent(
      `free_soft_trigger_${creditsLeft}`,
      "Soft Trigger Shown",
      {
        soft_trigger_type: "Free",
        daily_messages_left: creditsLeft,
      }
    );
    isComponentMounted.current = true;
    setTimeout(() => {
      setShowComponent(true);
    }, 1300);
  }, [creditsLeft]);

  useEffect(() => {
    return () => {
      isComponentMounted.current = false;
    };
  }, []);

  const config = getCreditLimitConfig(chatUsageData.dailyMessageLimit);
  const showCardOnLeftCredits = config.softTriggerThresholds;
  const currentIndex = showCardOnLeftCredits.indexOf(creditsLeft);

  const getCardContent = () => {
    if (currentIndex === -1) {
      return null;
    }
    switch (currentIndex) {
      case 0:
        return {
          title: (
            <div className="flex items-center gap-1">
              <span className="text-white font-bold text-[10px] leading-[15px] whitespace-nowrap font-manrope">{isTrialCancelled ? `Reactivate Free Trial ${getCurrency() === "INR" ? "at ₹1" : "for FREE"}` : `Join Pro at ${monthlyPriceString} for 1 month`}</span>
              <img src={RightArrowGradiant} alt="Right Arrow Gradiant" className="w-[12px] h-[12px] min-w-[12px] min-h-[12px]" />
            </div>
          ),
          subtitle: "Enjoy unlimited messages, path creations and much more.",
          icon: (
            <></>
          ),
        };
      case 1:
        return {
          title: "Get advanced responses from Leeco",
          subtitle: "With Pro, get unlimited GPT-5 for faster and advanced reasoning.",
          icon: (
            <img src={isIconHovered ? MentorAiRoundedButtonIconHover : MentorAiRoundedButtonIcon} alt={`${isIconHovered ? "MentorAi Rounded Button Icon Hover" : "MentorAi Rounded Button Icon"}`} className={`w-[32px] h-[32px]`} />
          ),
        };
      case 2:
        return {
          title: "More than unlimited messages",
          subtitle: "Get Interview Mode, Company specific DSA Paths, GPT-5 and more with Pro.",
          icon: (
            <img src={isIconHovered ? MentorAiRoundedButtonIconHover : MentorAiRoundedButtonIcon} alt={`${isIconHovered ? "MentorAi Rounded Button Icon Hover" : "MentorAi Rounded Button Icon"}`} className={`w-[32px] h-[32px]`} />
          ),
        };
      default:
        return null;
    }
  };

  const cardContent = getCardContent();

  if (!cardContent || !showComponent) return null;

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      transition={{ duration: 0.3 }}
      className={`relative bg-[linear-gradient(32deg,_rgba(127,_98,_255,_0.12)_35.65%,_rgba(236,_110,_255,_0.24)_60.96%,_rgba(255,_155,_83,_0.80)_98.67%)] hover:bg-[linear-gradient(32deg,_rgba(127,_98,_255,_0.16)_35.65%,_rgba(236,_110,_255,_0.36)_60.96%,_rgba(255,_155,_83,_0.90)_98.67%)]
        cursor-pointer rounded-[11px] mt-5 mb-3
      w-full  ${currentIndex === 0 ? "" : "overflow-hidden"}`}
    >
      <div 
        onClick={() => redirectToCheckout({
          chatUsageData,
          location: isTrialCancelled ? "Trial Cancelled Banner" : "Soft Trigger",
          menteeSubscription: menteeSubscription
        })}
        className="w-full cursor-pointer"
      >
        <div className="flex items-center justify-between border border-[rgba(255,255,255,0.16)] px-3 pt-3 pb-[14px] rounded-[12px] w-full">
          <div className="flex flex-col gap-0.5 max-w-[198px]">
            <h3 className="text-white font-bold text-[11px] leading-[16px] whitespace-nowrap font-manrope text-left">
              {cardContent.title}
            </h3>
            <h3 className="text-[rgba(255,255,255,0.55)] font-semibold text-[10px] leading-[15px] font-manrope text-left">
              {cardContent.subtitle}
            </h3>
          </div>
          <div className="ml-[14px] z-10"
            onMouseEnter={() => {
              setIsIconHovered(true);
            }}
            onMouseLeave={() => {
              setIsIconHovered(false);
            }}>
            {cardContent.icon}
          </div>
        </div>

        {currentIndex === 2 || currentIndex === 1 ? (
          <div className="absolute top-[-8px] right-0 opacity-20">
            <img src={CrownLarge} alt="crown" className="w-[105px] h-[105px]" />
          </div>
        ) : currentIndex === 0 ? (<div className="absolute top-[-21px] right-2">
          <img src={LeecoMascot} alt="Leeco Mascot" className="w-[64px] h-[94px] min-w-[64px] min-h-[94px]" />
        </div>) : null}
      </div>
    </motion.div>
  );
};

export default CreditPromotionalCard;
