import { MentorAiContext } from "../../context/mentorai-context/mentorai-context"
import { useContext, useEffect, useRef, useState } from "react"
import { MenteeContext } from "../../context/mentee-context/mentee-context"
import { PageContext } from "../../context/page-context/page-context"
import { useSidepanelSyncContext } from "../../context/sidepanel-sync-context/sidepanel-sync-context"
import { redirectToCheckout } from "../../utils/checkout-redirect"
import useExtensionPlansContainer from "./extension-paywall/plans-sheet/components/extension-plans/use-extension-plans-container"
import getCurrency, { getFormattedPriceWithSymbol } from "../../../utils/currency"
import { motion } from "framer-motion"
import { shouldShowUpgradeBanner, shouldShowExhaustedBanner, shouldShowTrialCancelledBanner } from "../../../utils/credit-limit-utils"
import { ChatContext } from "../../context/chat-context/chat-context"
import { getMostRecentSubscription, getUserStatus } from "../../../utils/subscription-helpers"
import { shouldShowInputBoxBanner } from "../../../utils/subscription-ui-helpers"
import AlertFillSmIcon from "../../assets/alert-fill-sm.svg?react"

type Props = {
  sendMessage: Function;
  chatMessages: any;
  isLiveMessageStreaming: boolean;
  loading: boolean;
  chatUsageData: any
}

const useConversationContainer = ({ sendMessage, chatMessages, isLiveMessageStreaming, loading, chatUsageData }: Props) => {
  const [inputText, setInputText] = useState("");
  const { setWidgetState, widgetState, transcription, isAudioLive } = useSidepanelSyncContext();
  const { menteeSubscription } = useContext(ChatContext);
  const userStatus = getUserStatus(menteeSubscription);
  const [shouldShowCancelledInputBoxBanner, setShouldShowCancelledInputBoxBanner] = useState(false);
  const { triggerPeriod, isTrial, daysRemaining } = userStatus


  useEffect(() => {
    const checkShouldShow = async () => {
      const result = await shouldShowInputBoxBanner(userStatus);
      setShouldShowCancelledInputBoxBanner(result);
    }
    checkShouldShow();
  }, [userStatus]);

  const handleSubmit = (text: string) => {
    if (!text || text === "<br>") return;
    // small delay to allow for smooth animation before sending
    setTimeout(() => {
      sendMessage(text);
    }, 300);

    setInputText("");
    chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
      tabs.forEach(tab => {
        if (tab.id) {
          chrome.tabs.sendMessage(tab.id, { action: "stopListening" });
        }
      });
      // setIsAudioLive(false)
      setWidgetState("HIDE")
    });
  };


  useEffect(() => {
    const messageContainer = document.querySelectorAll(
      ".cs-message-list__scroll-wrapper"
    );
    messageContainer?.[0]?.classList.remove("cs-message-list__scroll-wrapper");
    chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
      if (message.action === "textSelected") {
        chrome.storage.local.set({
          "selectedText": message.text
        })
      }
    });
  }, []);

  let userQuery =
    chatMessages?.[chatMessages.length - 2]?.props?.model?.message || ""
  const devUrl = import.meta.env.VITE_CURRENT_DEV_URL
  const { mentoraiData } = useContext(MentorAiContext)
  const { menteeData } = useContext(MenteeContext)
  const { activeTabUrl, setTriggerShowShareExtension, triggerShowShareExtension } = useContext(PageContext)
  const [roadmapCtaHover, setRoadmapCtaHover] = useState(false);
  const [findMentorCtaHover, setFindMentorCtaHover] = useState(false);
  const [rateUsHover, setRateUsHover] = useState(false);
  const [supportCenterHover, setSupportCenterHover] = useState(false);
  const [supportCenterOpen, setSupportCenterOpen] = useState(false);
  const [shareExtension, setShareExtension] = useState({
    hover: false,
    open: false
  });
  const [ctaRedirectUrl, setCtaRedirectUrl] = useState({
    whatsapp: "",
    slack: "",
    linkedin: "",
  });
  const [selectedShareOption, setSelectedShareOption] = useState({
    popupView: "primary",
    cta: "",
    copiedAgain: false,
    open: false
  })
  const messageInputRef = useRef<any>(null);
  const [inputHeight, setInputHeight] = useState(0);


  const { extensionPlans } = useExtensionPlansContainer()
  const monthlyPriceString = getFormattedPriceWithSymbol(extensionPlans?.find((plan) => plan?.validity === "1 month")?.totalPrice!);


  const [isUpgradeBannerOpen, setIsUpgradeBannerOpen] = useState(false);
  const [shouldAnimateBanner, setShouldAnimateBanner] = useState(false);

  const handleCloseBanner = () => {
    setIsUpgradeBannerOpen(false);
    chrome.storage.local.set({
      showHeaderCreditBanner: false,
    });
  };

  useEffect(() => {
    chrome.storage.local.get("showHeaderCreditBanner", (result) => {
      if (result.showHeaderCreditBanner !== false) {
        setIsUpgradeBannerOpen(true);
      }
    });
  }, []);





  useEffect(() => {
    if (!isAudioLive) {
      messageInputRef.current.focus();
    }
  }, [isLiveMessageStreaming, loading, isAudioLive]);

  useEffect(() => {
    const updateHeight = () => {
      const container = document.getElementById("message-input-container");
      if (container) {
        setInputHeight(container.clientHeight + 46);
      }
    };

    updateHeight();

    const container = document.getElementById("message-input-container");
    if (!container) return;

    const resizeObserver = new ResizeObserver((entries) => {
      for (let entry of entries) {
        setInputHeight(entry.contentRect.height + 46);
      }
    });
    resizeObserver.observe(container);

    return () => {
      resizeObserver.disconnect();
    };
  }, [isAudioLive]);


  const links = [
    {
      url: `https://explore.preplaced.in/Ibv5Ol?utm_content=${menteeData?.profileId}`,
      text: "I've been using this Chrome extension that works like an AI Mentor while solving DSA problems on LeetCode. It's really helped me improve my problem-solving skills, so I thought you might find it useful too. Here's the link: ",
    },
    {
      url: ` https://explore.preplaced.in/gw0oYp?utm_content=${menteeData?.profileId}`,
      text: ""
    },
    {
      url: `https://explore.preplaced.in/nv0fKq?utm_content=${menteeData?.profileId}`,
      text: "I've been using this Chrome extension that works like an AI Mentor while solving DSA problems on LeetCode. It's really helped me improve my problem-solving skills, so I thought you might find it useful too. Here's the link: ",
    },
  ];

  const generateRedirectUrls = (link: any) => ({
    whatsapp: `https://wa.me/?text=${encodeURIComponent(link.text + ' ' + link.url)}`,
    linkedin: `https://www.linkedin.com/sharing/share-offsite/?mini=true&url=${encodeURIComponent(link.url)}`,
    slack: `https://slack.com`,
  });

  useEffect(() => {
    if (menteeData?.profileId) {
      setCtaRedirectUrl({
        whatsapp: generateRedirectUrls(links[0]).whatsapp,
        linkedin: generateRedirectUrls(links[1]).linkedin,
        slack: generateRedirectUrls(links[2]).slack,
      })
    }
  }, [menteeData])



  const isRoadmapPresent = !!menteeData?.mentorAiRoadmapConfigurations?.[mentoraiData?.["publicProfileId(FromMentors)"]?.[0]]

  const handleRoadmapCtaClick = (button_name: string) => {
    chrome.runtime.sendMessage({
      action: "sendAnalytics", url: activeTabUrl, eventName: 'Button Clicked', eventProperties: {
        button_name: button_name
      }
    })

    if (isRoadmapPresent) {
      window.open(
        `${devUrl}/mentorai/${mentoraiData?.["publicProfileId(FromMentors)"]?.[0] ||
        "pro-pilot"
        }/dashboard?screen=roadmap&onboarding=true`,
        "_blank"
      )
    }
    else {
      chrome.storage.local.get("utmParams", (result) => {
        const { utmParams } = result;
        const url = new URL(import.meta.env.VITE_LEECO_WEB_URL + "/path-creator/v2");
        if (utmParams) {
          url.searchParams.append("utm_campaign", utmParams.utm_campaign);
          url.searchParams.append("utm_content", utmParams.utm_content);
          url.searchParams.append("utm_medium", utmParams.utm_medium);
          url.searchParams.append("utm_source", utmParams.utm_source);
          url.searchParams.append("utm_term", utmParams.utm_term);
        }

        window.open(url.toString());
      });
    }
  }

  const lastAssistantMessage = chatMessages.reverse().find((m: any) => m.props.model.sender === "assistant")?.props?.model?.message
  const lastUserMessage = chatMessages.reverse().find((m: any) => m.props.model.sender === "user")?.props?.model?.message


  const handleShareWhatsapp = () => {
    chrome.runtime.sendMessage({
      action: "sendAnalytics", url: activeTabUrl, eventName: 'MentorAi Share Extension Medium Clicked', eventProperties: {
        medium: "WhatsApp"
      }
    })
    window.open(ctaRedirectUrl.whatsapp, '_blank');
  }


  const handleShareLinkedin = () => {
    navigator.clipboard.writeText(`🔥 Just tried something that made solving LeetCode problems way easier for me I've been using the Preplaced AI Mentor Chrome extension while solving DSA problems lately. 
      It reads the question and my code in real-time, helps me debug, optimise, and discuss approaches—exactly like a mentor sitting beside me. 
      It doesn't just throw the answer at me. Instead, it helps me understand why something works, shows how to fix mistakes when I'm stuck on tough problems, and saves so much time — I don't have to jump between tabs or try to explain my code to a chatbot. 
      Sharing this here in case you're serious about improving your problem-solving skills: 
      
      ${links[1].url}

      #DSA #LeetCode #AImentor #ProductivityTools #PreplacedAI
      `)
    setSelectedShareOption((prev: any) => ({ ...prev, popupView: "secondary", cta: "LinkedIn", copiedAgain: false, open: true }))
    chrome.runtime.sendMessage({
      action: "sendAnalytics", url: activeTabUrl, eventName: 'MentorAi Share Extension Medium Clicked', eventProperties: {
        medium: "LinkedIn"
      }
    })
    window.open(ctaRedirectUrl.linkedin, '_blank');
  }

  const handleShareSlack = () => {
    setSelectedShareOption((prev: any) => ({ ...prev, popupView: "secondary", cta: "Slack", copiedAgain: false, open: true }))
    navigator.clipboard.writeText(`
       ${links[2].text} 


       ${links[2].url}
       `)
    chrome.runtime.sendMessage({
      action: "sendAnalytics", url: activeTabUrl, eventName: 'MentorAi Share Extension Medium Clicked', eventProperties: {
        medium: "Slack"
      }
    })
    window.open(ctaRedirectUrl.slack, '_blank');
  }

  const handleCopyAgain = (selectedShareOption: any) => {
    if (selectedShareOption.cta === "Slack") {
      navigator.clipboard.writeText(`${links[2].text} ${links[2].url}`)
    } else if (selectedShareOption.cta === "LinkedIn") {
      navigator.clipboard.writeText(`🔥Just tried something that made solving LeetCode problems way easier for me I've been using the Preplaced AI Mentor Chrome extension while solving DSA problems lately. 
        It reads the question and my code in real-time, helps me debug, optimise, and discuss approaches—exactly like a mentor sitting beside me. 
        It doesn't just throw the answer at me. Instead, it helps me understand why something works, shows how to fix mistakes when I'm stuck on tough problems, and saves so much time — I don't have to jump between tabs or try to explain my code to a chatbot. 
        Sharing this here in case you're serious about improving your problem-solving skills: 
       
        ${links[1].url}

        #DSA #LeetCode #AImentor #ProductivityTools #PreplacedAI
         `)
    }
    setSelectedShareOption((prev: any) => ({ ...prev, copiedAgain: true }))
    setTimeout(() => {
      setSelectedShareOption((prev: any) => ({ ...prev, copiedAgain: false }))
    }, 1500)
  }


  const showShareExtensionPopup = () => {
    setSelectedShareOption((prev: any) => ({
      ...prev,
      open: false,
      copiedAgain: false,
      cta: "",
      popupView: "primary",
    }))
    setShareExtension((prev: any) => ({ ...prev, open: true }))
  }


  const handleShareExtensionClick = () => {
    showShareExtensionPopup()
    chrome.runtime.sendMessage({
      action: "sendAnalytics",
      url: activeTabUrl,
      eventName: "MentorAi Share Extension Clicked",
      eventProperties: {},
    })
  }

  const upgradeBanners = () => {
    const banners: { show: boolean, value: React.ReactNode } = {
      show: false,
      value: null
    }
    const latestSubscription = getMostRecentSubscription(menteeSubscription?.subscriptions);
    const isTrialCancelled = latestSubscription?.cancelledOn && menteeSubscription?.pricing_plan?.user_type === "trial";
    if (menteeData && chatUsageData !== undefined && !chatUsageData.menteeDataLoading) {
      if (chatUsageData.isPaidUser) {
        if (shouldShowCancelledInputBoxBanner) {
          banners.value = (
            <motion.div
              initial={shouldAnimateBanner ? { y: 10, opacity: 0 } : { y: 0, opacity: 1 }}
              animate={{ y: 0, opacity: 1 }}
              exit={{ y: 10, opacity: 0 }}
              transition={{ duration: 0.3 }}
              style={{
                width: "calc(100% + 2px)",
              }}
              className={`text-[#FFD268] hover:text-[#FFD268] flex justify-center font-medium items-center gap-0.5 py-1 w-full ml-[-1px] text-xs leading-normal font-manrope px-3 rounded-t-[12px] absolute left-0 h-[26px] top-[-26px] 
              ${triggerPeriod === 'last_day' ? ' bg-[linear-gradient(88deg,_#411914_21.86%,_#740E16_96.38%)] hover:bg-[linear-gradient(88deg,_#411914_21.86%,_#88111A_59.12%)]' : `${triggerPeriod === 'during' ? ' bg-[linear-gradient(88deg,_#392C11_21.86%,_#724803_96.38%)] hover:bg-[linear-gradient(88deg,_#392C11_21.86%,_#774B03_59.12%)]' : ' bg-[#392C11] hover:bg-[#433314] '}`}`}>
              <div
                onClick={() => redirectToCheckout({
                  chatUsageData,
                  location: "Reminder Banner",
                  menteeSubscription: menteeSubscription
                })}
                className="cursor-pointer flex justify-center items-center w-full gap-0.5"
              >
                <p style={{ fontSize: "12px" }}>
                  {isTrial ?
                    triggerPeriod === 'last_day' ? 'Pro Trial ends today.' : `Pro Trial ends in ${daysRemaining} days.`
                    :
                    triggerPeriod === 'last_day' ? 'Pro expires today.' : `Pro expires in ${daysRemaining} days.`}
                </p>


                <span style={{ fontSize: "12px", fontWeight: "500" }} className="font-manrope leading-normal underline text-[#DDDDDF] underline-offset-[20%]">
                  {isTrial ? `Upgrade now →` : `Renew now →`}
                </span>
              </div>
            </motion.div>
          )
          banners.show = true;
        }
        return banners
      } 
      else if (shouldShowUpgradeBanner(chatUsageData.dailyMessagesLeft, chatUsageData.dailyMessageLimit)) {
        if (!shouldAnimateBanner) {
          setShouldAnimateBanner(true);
        }

        banners.value = (
          <motion.div
            initial={shouldAnimateBanner ? { y: 10, opacity: 0 } : { y: 0, opacity: 1 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: 10, opacity: 0 }}
            transition={{ duration: 0.3 }}
            style={{
              width: "calc(100% + 2px)",
            }}
            className="text-[#FFD268] hover:text-[#FFD268] bg-[#5D491F] hover:bg-[#7A6029] flex justify-center font-medium items-center gap-0.5 py-1 w-full ml-[-1px] text-xs leading-normal font-manrope px-3 rounded-t-[12px] absolute left-0 h-[26px] top-[-26px]">
            <div
              onClick={() => redirectToCheckout({
                chatUsageData,
                location: isTrialCancelled ? "Trial Cancelled Banner" : "Credit Banner",
                menteeSubscription: menteeSubscription
              })}
              className="cursor-pointer flex justify-center items-center w-full gap-0.5"
            >
              <p style={{ fontSize: "12px" }}>
                {chatUsageData.dailyMessagesLeft} {chatUsageData.dailyMessagesLeft > 1 ? ' credits' : ' credit'} left for today.
              </p>

              <span style={{ fontSize: "12px", fontWeight: "500" }} className="font-manrope leading-normal underline text-mentorai-text-soft underline-offset-[20%]">{isTrialCancelled ? `Reactivate at ${getCurrency() === "INR" ? "₹1" : "FREE"}` : `Upgrade at ${monthlyPriceString}`} →</span>
            </div>
          </motion.div>
        )
        banners.show = true;
        return banners
      }
      else if (shouldShowTrialCancelledBanner(menteeSubscription)){
        // Set animation state when banner first becomes visible
        if (!shouldAnimateBanner) {
          setShouldAnimateBanner(true);
        }

        banners.value = (
          <motion.div
            initial={shouldAnimateBanner ? { y: 10, opacity: 0 } : { y: 0, opacity: 1 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: 10, opacity: 0 }}
            transition={{ duration: 0.3 }}
            style={{
              width: "calc(100% + 2px)",
            }}
            className="text-[#FD782D] bg-[#522B21] flex justify-between font-medium items-center gap-0.5 py-1  w-full ml-[-1px]  text-xs leading-normal font-manrope px-3 rounded-t-[12px] scale-[1.008] absolute left-0 h-[26px] top-[-26px]">
            <div
              onClick={() => redirectToCheckout({
                chatUsageData,
                location:"Trial Cancelled Banner",
                menteeSubscription: menteeSubscription
              })}
              className="cursor-pointer flex justify-between items-center w-full gap-0.5"
            >
              <div className="flex items-center gap-1">
                <AlertFillSmIcon />
                <p style={{ fontSize: "10px"}}>You've cancelled your free trial</p>
              </div>
              <span style={{ fontSize: "10px", fontWeight: "500" }} className="font-manrope leading-normal underline text-mentorai-text-soft underline-offset-[20%]">Reactivate at {getCurrency() === "INR" ? "₹1" : "FREE"} →</span>
            </div>
          </motion.div>
        )
        banners.show = true;
        return banners
      }
      else if (shouldShowExhaustedBanner(chatUsageData.dailyMessagesLeft)) {
        // Set animation state when banner first becomes visible
        if (!shouldAnimateBanner) {
          setShouldAnimateBanner(true);
        }

        banners.value = (
          <motion.div
            initial={shouldAnimateBanner ? { y: 10, opacity: 0 } : { y: 0, opacity: 1 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: 10, opacity: 0 }}
            transition={{ duration: 0.3 }}
            style={{
              width: "calc(100% + 2px)",
            }}
            className="text-[#FF97A0] hover:text-[#FF97A0] bg-[#5E212C] hover:bg-[#792A39] flex justify-center font-medium items-center gap-0.5 py-1  w-full ml-[-1px]  text-xs leading-normal font-manrope px-3 rounded-t-[12px] scale-[1.008] absolute left-0 h-[26px] top-[-26px]">
            <div
              onClick={() => redirectToCheckout({
                chatUsageData,
                location: isTrialCancelled ? "Trial Cancelled Banner" : "Credit Banner",
                menteeSubscription: menteeSubscription
              })}
              className="cursor-pointer flex justify-center items-center w-full gap-0.5"
            >
              <p style={{ fontSize: "12px" }}>0 credits left for today.</p>
              <span style={{ fontSize: "12px", fontWeight: "500" }} className="font-manrope leading-normal underline text-mentorai-text-soft underline-offset-[20%]">{isTrialCancelled ? `Reactivate at ${getCurrency() === "INR" ? "₹1" : "FREE"}` : `Upgrade at ${monthlyPriceString}`} →</span>
            </div>
          </motion.div>
        )
        banners.show = true;
        return banners
      } 
      else {
        return banners
      }
    } else {
      return banners
    }
  }



  const handleMessage = (message: any, sender: any, sendResponse: any) => {
    // Handle live transcription messages
    if (message.action === "sendTranscriptionToSidePanel" && message.source === "Bottom Input Live") {
      setInputText(message.message)
    }
    if (message.action === "openShareExtensionModal") {
      showShareExtensionPopup()
    }
    return true
  }

  useEffect(() => {
    // console.log("chat-view adding listener")
    chrome.runtime.onMessage.addListener(handleMessage)
    return () => {
      chrome.runtime.onMessage.removeListener(handleMessage)
    }
  }, [])

  const toggleShowMicrophonePermission = () => {
    if (widgetState === "MICROPHONE_PREMISSION") {
      setWidgetState("HIDE")
    } else {
      setWidgetState("MICROPHONE_PREMISSION")
    }
  }

  useEffect(() => {
    if (transcription) {
      setInputText(transcription)
    }
  }, [])

  // Reset animation state when banner is hidden
  useEffect(() => {
    const banners = upgradeBanners();
    if (banners && !banners.show && shouldAnimateBanner) {
      setShouldAnimateBanner(false);
    }
  }, [chatUsageData, shouldAnimateBanner]);

  return ({
    handleSubmit,
    inputHeight,
    roadmapCtaHover,
    setRoadmapCtaHover,
    rateUsHover,
    setRateUsHover,
    supportCenterHover,
    setSupportCenterHover,
    shareExtension,
    setShareExtension,
    ctaRedirectUrl,
    setCtaRedirectUrl,
    messageInputRef,
    lastAssistantMessage,
    lastUserMessage,
    userQuery,
    menteeData,
    isRoadmapPresent,
    handleRoadmapCtaClick,
    handleShareWhatsapp,
    handleShareLinkedin,
    handleShareSlack,
    activeTabUrl,
    setTriggerShowShareExtension,
    triggerShowShareExtension,
    selectedShareOption,
    setSelectedShareOption,
    handleCopyAgain,
    findMentorCtaHover,
    setFindMentorCtaHover,
    supportCenterOpen,
    setSupportCenterOpen,
    inputText,
    setInputText,
    toggleShowMicrophonePermission,
    widgetState,
    handleShareExtensionClick,
    upgradeBanners,
    isUpgradeBannerOpen,
    setIsUpgradeBannerOpen,
    handleCloseBanner,
    shouldAnimateBanner
  }
  )
};

export default useConversationContainer;