import React, { useContext, useEffect, useState } from 'react';
import CloseIcon from "../../../../content/assets/icons/close-icon.svg"
import CloseIconHovered from "../../../../content/assets/icons/close-icon-hovered.svg"
import MentorAiButton from '../../../../common/button/mentorai-button';
import { PageContext } from '../../../context/page-context/page-context';
import Modal from '../../../../common/modal/modal';
import ParticalAbstract from "../../../assets/partical-abstract.svg"
import AbstractLeft from "../../../assets/abstract-left-desing.svg"
import AbstractRight from "../../../assets/abstract-right-design.svg"
import SpeakingIcon from "../../../../src/assets/speaking-fill.svg"
import MentorAiActiveAvatar from '../../../../content/components/mentorai-active-avatar/mentorai-active-avatar';
import { MentorAi } from '../../../types/type';
import CheckedIcon from "../../../../content/assets/icons/checked-checkbox.svg"
import UncheckedIcon from "../../../../content/assets/icons/unchecked-checkbox.svg"
import ProgressBarWithAvatars from './progress-percentage';
import { motion } from 'framer-motion';
import GreenFlag from "../../../assets/gif/green-flag.gif"
import DottedPath1 from "../../../assets/dotted-path-1.svg"
import DottedPath2 from "../../../assets/dotted-path-2.svg"
import DottedPath3 from "../../../assets/dotted-path-3.svg"
import LocationPinIcon from "../../../assets/location-pin.svg"
import LeecoMic from "../../../assets/LeecoMic.webp";

const PRACTICE_STEPS = [
    'I explain the problem to myself',
    'I explain all edge cases and constraints',
    'I start with brute force approach',
    'I try out more optimal approaches',
    'I explain my approaches to myself',
];
const PRACTICE_STEPS_NTH_TIME = [
    'Explaining the problem in your words',
    'Explaining all edge cases and constraints',
    'Starting with brute force approach',
    'Trying out more optimal approaches',
    'Explaining your approaches to someone',
];


type Props = {
    show: boolean
    handleClose: () => void
    setPracticeCount: Function
    setPracticeModeStatus: Function
    sendMessage: Function
    showPracticeModeWelcomeScreen: boolean
    practiceModeStatus: string,
    mentoraiData?: MentorAi,
    menteeData?: any
    setShowPracticeModeWelcomeScreen: Function
}

const PracticeModeStarterPopup = ({ show, mentoraiData, menteeData, setShowPracticeModeWelcomeScreen, handleClose, setPracticeCount, setPracticeModeStatus, sendMessage, showPracticeModeWelcomeScreen, practiceModeStatus }: Props) => {
    const [selectedSteps, setSelectedSteps] = useState<string[]>([]);
    const [submitted, setSubmitted] = useState(false);
    const { activeTabUrl, incrementPracticeCount, practiceCount, setInterviewModeStatus } = useContext(PageContext)
    const [currentProblemName, setCurrentProblemName] = useState("");
    const handleToggle = (step: string) => {
        setSelectedSteps(prev =>
            prev.includes(step) ? prev.filter(s => s !== step) : [...prev, step]
        );
    };

    const handleSubmit = async () => {
        setSubmitted(true);
        const currentInterviewStatus = await chrome.storage.local.get("interviewModeStatus");
        if (["ONGOING", "FEEDBACK", "FEEDBACK_GENERATED"].includes(currentInterviewStatus.interviewModeStatus)) {
            chrome.storage.local.set({
                interviewModeStatus: "IDLE",
            });
            setInterviewModeStatus("IDLE");
        }

        setPracticeModeStatus("PM_PREVIEW")
        const tabs = await chrome.tabs.query({ active: true, currentWindow: true });
        const tabId = tabs[0]?.id;
        chrome.storage.local.set({
            practiceModeStatus: "PM_PREVIEW",
            practiceModeStartedUrl: activeTabUrl,
            practiceModeTabId: tabId,
            isPracticeModeWelcomeScreenShown: true
        });
        chrome.runtime.sendMessage({
            action: "sendAnalytics",
            url: activeTabUrl,
            eventName: 'MentorAi Practice Mode Onboarding Complete',
            eventProperties: {
                options_chosen_number: selectedSteps.length,
                options_chosen: selectedSteps,
                practice_mode_version: 'beta',
            },
        })
    };

    const handleBeginPractice = async () => {
        try {
            const currentInterviewStatus = await chrome.storage.local.get("interviewModeStatus");
            if (["ONGOING", "FEEDBACK", "FEEDBACK_GENERATED"].includes(currentInterviewStatus.interviewModeStatus)) {
                chrome.storage.local.set({
                    interviewModeStatus: "IDLE",
                });
                setInterviewModeStatus("IDLE");
            }

            setPracticeModeStatus("PM_ONGOING");
            const getPracticeCount = await chrome.storage.local.get('practiceCount');
            const tabs = await chrome.tabs.query({ active: true, currentWindow: true });
            const tabId = tabs[0]?.id;

            // Get the current practice count for analytics
            const currentPracticeCount = getPracticeCount.practiceCount || 0;
            const newPracticeCount = currentPracticeCount + 1;

            chrome.runtime.sendMessage({
                action: "sendAnalytics",
                url: activeTabUrl,
                eventName: 'MentorAi Practice Mode Started',
                eventProperties: {
                    practice_mode_version: 'beta',
                    practice_count: newPracticeCount,
                },
            })

            await incrementPracticeCount();
            await chrome.storage.local.set({
                practiceModeStatus: "PM_ONGOING",
                practiceModeStartedUrl: activeTabUrl,
                practiceModeTabId: tabId
            });
            sendMessage("Start Structured Coaching Session", true, null, true);
            setShowPracticeModeWelcomeScreen(false);
        } catch (error) {
            console.error("Error starting practice mode from welcome screen:", error);
        }
    };

    const getPercentage = () => Math.floor((selectedSteps.length / PRACTICE_STEPS.length) * 100);
    const isReadyToStartPractice = submitted || practiceModeStatus === "PM_PREVIEW"

    const isLeetCodeOrGFGProblemPage = activeTabUrl?.includes("https://leetcode.com/problems/") || activeTabUrl?.includes("https://www.geeksforgeeks.org/problems/");
    useEffect(() => {
        chrome.storage.local.get(['question_data'], (result) => {
            if (result.question_data?.title) {
                setCurrentProblemName(result.question_data.title);
            }
        });

        const storageListener = async (changes: any) => {
            if (changes.question_data?.newValue) {
                try {
                    setCurrentProblemName(changes.question_data.newValue?.title || "");
                } catch (error) {
                    console.error("Error getting question_data:", error);
                }
            }
        };

        chrome.storage.onChanged.addListener(storageListener);
        return () => {
            chrome.storage.onChanged.removeListener(storageListener);
        };
    }, []);

    return (
        <Modal
            open={show}
            handleCloseOutside={handleClose}
            className={{
                container: "rounded-t-[20px] rounded-b-[0px]",
                overlay:
                    "!bg-[rgba(0,0,0,0.60)] backdrop-blur-[2px] !rounded-tl-[6px] !rounded-bl-[6px]",
            }}
        >
            <motion.div
                initial={{ opacity: 0, y: 20, height: "0%" }}
                animate={{ opacity: 1, y: 0, height: "auto" }}
                exit={{ opacity: 0, y: 20, height: "0%" }}
                transition={{ duration: 0.3, ease: "easeInOut" }}
                className={`fixed bottom-0 left-0 flex items-center justify-center flex-col px-4 pb-4 w-screen rounded-t-[20px] rounded-b-[0px] bg-mentorai-bg-black font-bricolage-grotesque max-h-[calc(90vh)] overflow-y-auto scrollbar-hide
                ${practiceModeStatus === "PM_PREVIEW" ? "border-t border-mentorai-stroke-strong bg-practice-feedback-popup-bg" : ""}
                `}>

                <div className="fixed bottom-0 left-0 w-screen h-[102px]">
                    <img src={ParticalAbstract} alt="partical-abstract" className="w-full h-full" />
                </div>
                {showPracticeModeWelcomeScreen &&
                    <>
                        <img src={AbstractRight} alt="abstract-right" className="absolute top-0 right-0 rounded-tr-[20px]" />
                        <img src={AbstractLeft} alt="abstract-left" className="absolute top-0 left-0 rounded-tl-[20px]" />
                    </>
                }

                <div className="z-50 relative w-full max-w-md max-h-[calc(90vh)] overflow-y-auto scrollbar-hide">
                    <MentorAiButton
                        type='outlined'
                        size='small'
                        semiRounded={true}
                        semiRoundedClass=' !rounded-[12px]'
                        classNames='!cursor-pointer sticky transition-all duration-100 group z-50 !w-[28px] !h-[28px]'
                        style={{
                            top: "12px",
                            left: "100%"
                        }}
                        onClick={() => handleClose()}
                    >
                        <>
                            <img src={CloseIcon} alt="close" className="w-[16px] h-[16px] max-w-[16px] max-h-[16px] flex group-hover:hidden" />
                            <img src={CloseIconHovered} alt="close" className="w-[16px] h-[16px] max-w-[16px] max-h-[16px] hidden group-hover:flex" />
                        </>
                    </MentorAiButton>

                    <div className="relative z-10">
                        <div className="flex justify-center items-center">
                            <div className="relative h-[40px]">
                                <MentorAiActiveAvatar mentoraiData={mentoraiData} avatarSrcOrUrl={LeecoMic} indicatorClassName='hidden' avatarClassName='w-[40px] h-[40px] rounded-full object-contain absolute left-0' containerClassName='h-[40px] w-[40px] mr-[10px] ' />
                                <MentorAiActiveAvatar avatarSrcOrUrl={menteeData?.photoUrl} mentoraiData={mentoraiData} indicatorClassName="hidden" avatarClassName="w-[40px] h-[40px] rounded-full object-contain" containerClassName='h-[40px] w-[40px] top-[-40px] left-[30px] z-[-1]' />
                            </div>
                        </div>
                        <div className="flex mt-2">
                            <h2 className={`text-mentorai-text-white w-full leading-[22px] text-center text-[18px] tracking-[-0.36px] font-medium
                                ${!showPracticeModeWelcomeScreen && "h-[44ppx]"}
                                `}>
                                {showPracticeModeWelcomeScreen ?
                                    'Welcome to our coaching session!'
                                    :
                                    <span>
                                        Welcome! Here's the structure <br /> in our coaching session
                                    </span>
                                }
                            </h2>
                        </div>
                        {showPracticeModeWelcomeScreen &&
                            <p className={` text-mentorai-text-sub text-center text-[12px] leading-normal font-manrope mt-1 h-4`}>
                                Let’s understand what we’ll be doing
                            </p>
                        }

                        <div className='h-[1px] bg-mentorai-stroke-strong my-5' > <span className='invisible'>.</span></div>

                        {showPracticeModeWelcomeScreen && (
                            <>
                                <p className="text-mentorai-text-white font-medium mb-2 flex whitespace-nowrap tracking-[-0.14px] text-[14px] leading-normal">
                                    Which of the following do you do  <span className='bg-clip-text text-transparent bg-gradient-text decoration-wavy underline decoration-[11%] underline-offset-[25%] font-semibold [text-decoration-color:gradient-text]'>&nbsp;everyday?</span>
                                </p>
                                <div className="flex flex-col gap-2 mb-6">
                                    {PRACTICE_STEPS.map(step => {
                                        const isChecked = selectedSteps.includes(step);
                                        return (
                                            <label key={step} className={`flex items-center justify-start gap-2 pr-1.5 pl-1 py-0.5 h-[26px] rounded 
                                                ${submitted ? "" : "hover:bg-[rgba(223,222,229,0.10)] hover:text-mentorai-text-white cursor-pointer "}
                                            `}>
                                                <input
                                                    type="checkbox"
                                                    checked={isChecked}
                                                    onChange={() => handleToggle(step)}
                                                    className="hidden"
                                                    disabled={submitted}
                                                />
                                                <img
                                                    src={isChecked ? CheckedIcon : UncheckedIcon}
                                                    alt={isChecked ? 'Checked' : 'Unchecked'}
                                                    className="w-3 h-3"
                                                />
                                                <span className={`text-sm tracking-[-0.14px] ${isChecked ? "text-mentorai-text-white" : "text-mentorai-text-sub"}`}>{step}</span>
                                            </label>
                                        )
                                    })}
                                </div>

                                {submitted &&
                                    <>
                                        <div className='h-[1px] bg-mentorai-stroke-strong my-5 w-full min-w-full' > <span className='invisible'>.</span></div>
                                        {selectedSteps.length === PRACTICE_STEPS.length ? (
                                            <div className="bg-practice-mode-starter-popup-progress-bg rounded-xl p-3 text-mentorai-text-white mb-6">
                                                <p className="font-medium mb-3 text-mentorai-text-white text-sm tracking-[-0.14px]">Whoa! You already practise <span className='bg-clip-text text-transparent bg-gradient-text'>100% of what is expected in interviews</span></p>
                                                <ProgressBarWithAvatars fixedPositionIcon={mentoraiData?.aiPhotoUrl || ""} varPositionIcon={menteeData?.photoUrl || ""} completedPercentage={97} />
                                                <p className='mt-5 text-[18px] leading-[24px] tracking-[-0.2px] font-medium text-mentorai-text-white'>We’ll continue this and I’ll give you detailed feedback to make you confident for interviews!</p>
                                            </div>
                                        ) : (
                                            <div className="bg-practice-mode-starter-popup-progress-bg rounded-xl p-3 text-mentorai-text-white mb-6">
                                                <p className="mb-3 font-medium text-sm tracking-[-0.14px]">
                                                    Awesome! You already practise <span className='bg-clip-text text-transparent bg-gradient-text'> {getPercentage()}% of what is expected in interviews</span>
                                                </p>
                                                <ProgressBarWithAvatars fixedPositionIcon={mentoraiData?.aiPhotoUrl || ""} varPositionIcon={menteeData?.photoUrl || ""} completedPercentage={getPercentage()} />
                                                <p className='mt-5 text-[18px] leading-[24px] tracking-[-0.2px] font-medium text-mentorai-text-white'>
                                                    Together, for every problem, we’ll follow ALL the steps to make you confident for interviews!
                                                </p>
                                            </div>
                                        )}
                                    </>
                                }

                            </>
                        )}

                        {(practiceModeStatus === "PM_PREVIEW" && !submitted) &&
                            <motion.div
                                className="relative mb-5 max-w-[320px] mx-auto"
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                transition={{ duration: 0.5 }}
                            >
                                <motion.div
                                    className="flex items-start justify-start gap-2"
                                    initial={{ opacity: 0, y: -20 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    transition={{ duration: 0.6, delay: 0.2 }}
                                >
                                    <img src={LocationPinIcon} alt="location pin" className="w-7 h-7" />
                                    <div className='flex flex-col gap-0.5'>
                                        <h3 className="text-mentorai-text-white font-medium text-[14px] leading-normal tracking-[-0.28px]">1. Problem Exploration</h3>
                                        <p className="text-mentorai-text-sub font-manrope text-[12px] leading-normal font-medium">We'll simplify the problem statement together</p>
                                    </div>
                                </motion.div>

                                <motion.div
                                    className="w-full h-[40px] relative overflow-hidden"
                                    initial={{ opacity: 0, scaleY: 0 }}
                                    animate={{ opacity: 1, scaleY: 1 }}
                                    transition={{ duration: 0.8, delay: 0.4 }}
                                    style={{ transformOrigin: 'top' }}
                                >
                                    <img src={DottedPath1} alt="dotted path" className="w-full h-full" style={{ objectFit: 'fill', width: '100%', height: '100%', transform: 'scaleX(1.2)' }} />
                                </motion.div>

                                <motion.div
                                    className="flex items-start justify-end gap-2"
                                    initial={{ opacity: 0, y: -20 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    transition={{ duration: 0.6, delay: 0.6 }}
                                >
                                    <div className='flex flex-col gap-0.5'>
                                        <h3 className="text-mentorai-text-white font-medium text-[14px] leading-normal tracking-[-0.28px] text-right">2. Edge Case Discussion</h3>
                                        <p className="text-mentorai-text-sub font-manrope text-[12px] leading-normal font-medium">We'll discuss all edge cases and constraints</p>
                                    </div>
                                    <img src={LocationPinIcon} alt="location pin" className="w-7 h-7" />
                                </motion.div>

                                <motion.div
                                    className="w-full h-[40px] relative overflow-hidden"
                                    initial={{ opacity: 0, scaleY: 0 }}
                                    animate={{ opacity: 1, scaleY: 1 }}
                                    transition={{ duration: 0.8, delay: 0.8 }}
                                    style={{ transformOrigin: 'top' }}
                                >
                                    <img src={DottedPath2} alt="dotted path" className="w-full h-full" style={{ objectFit: 'fill', width: '100%', height: '100%', transform: 'scaleX(1.2)' }} />
                                </motion.div>

                                <motion.div
                                    className="flex items-start justify-start gap-2"
                                    initial={{ opacity: 0, y: -20 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    transition={{ duration: 0.6, delay: 1.0 }}
                                >
                                    <img src={LocationPinIcon} alt="location pin" className="w-7 h-7" />
                                    <div className='flex flex-col gap-0.5'>
                                        <h3 className="text-mentorai-text-white font-medium text-[14px] leading-normal tracking-[-0.28px]">3. Brute Force Discussion</h3>
                                        <p className="text-mentorai-text-sub font-manrope text-[12px] leading-normal font-medium">We'll try simplest solution and its inefficiencies</p>
                                    </div>
                                </motion.div>

                                <motion.div
                                    className="w-full h-[40px] relative overflow-hidden"
                                    initial={{ opacity: 0, scaleY: 0 }}
                                    animate={{ opacity: 1, scaleY: 1 }}
                                    transition={{ duration: 0.8, delay: 1.2 }}
                                    style={{ transformOrigin: 'top' }}
                                >
                                    <img src={DottedPath3} alt="dotted path" className="w-full h-full" style={{ objectFit: 'fill', width: '100%', height: '100%', transform: 'scaleX(1.2)' }} />
                                </motion.div>

                                <motion.div
                                    className="flex items-start justify-end gap-2"
                                    initial={{ opacity: 0, y: -20, scale: 0.9 }}
                                    animate={{ opacity: 1, y: 0, scale: 1 }}
                                    transition={{ duration: 0.7, delay: 1.4 }}
                                >
                                    <div className='flex flex-col gap-0.5'>
                                        <h3 className="text-[#4FFC5B] font-medium text-[14px] leading-normal tracking-[-0.28px] text-right">4. Optimal Solution</h3>
                                        <p className="text-mentorai-text-sub font-manrope text-[12px] leading-normal font-medium">Finally, we will reach the acceptable solution</p>
                                    </div>
                                    <motion.img
                                        src={GreenFlag}
                                        alt="location pin"
                                        className="w-7 h-7"
                                        initial={{ rotate: -10, scale: 0.8 }}
                                        animate={{ rotate: 0, scale: 1 }}
                                        transition={{ duration: 0.5, delay: 1.6 }}
                                    />
                                </motion.div>
                            </motion.div>
                        }

                        <motion.div
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ duration: 0.8, delay: 1.8 }}
                        >
                            <MentorAiButton
                                onClick={(isReadyToStartPractice) ? handleBeginPractice : handleSubmit}
                                type={(isReadyToStartPractice) ? 'primary' : 'neutral'}
                                size='medium'
                                classNames='w-full'
                                disabled={(!selectedSteps.length && practiceModeStatus !== "PM_PREVIEW") || (isReadyToStartPractice && !isLeetCodeOrGFGProblemPage)}
                            >
                                {isReadyToStartPractice ?
                                    <span className='flex gap-1 w-full items-center justify-center'>
                                        Start Session
                                        {currentProblemName && isLeetCodeOrGFGProblemPage &&
                                            <span className='truncate max-w-[120px]'>
                                                : "{currentProblemName}"
                                            </span>
                                        }
                                        →
                                    </span>
                                    :
                                    <span className='flex w-full items-center justify-center'>
                                        Submit →
                                    </span>}
                            </MentorAiButton>
                        </motion.div>
                    </div>
                </div>
            </motion.div>
        </Modal>
    );
};

export default PracticeModeStarterPopup;

