import React from 'react'
import ReactDOM from 'react-dom/client'
import App from './App'
import './index.css'

// Function to notify panel state
const notifyPanelState = async (isOpen: boolean) => {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  const activeTabUrl = tab?.url || '';
  if (isOpen) {
    chrome.runtime.sendMessage({ action: "sendAnalytics", url: activeTabUrl, eventName: 'Side Panel Opened', eventProperties: {} })
    chrome.runtime.sendMessage({
      action: "sendAnalytics",
      url: activeTabUrl,
      eventName: "Extension Tab Visited",
      eventProperties: {
        tab: "Chat",
        action: "Sidepanel Open",
      },
    });
  }
  chrome.runtime.sendMessage({
    action: isOpen ? 'sidePanelOpenActivityDetected' : 'sidePanelCloseActivityDetected'
  });
};

// Listen for connection state changes
let port = chrome.runtime.connect({ name: 'sidepanel' });

port.onDisconnect.addListener(async () => {
  await notifyPanelState(false);
  // Try to reconnect
  setTimeout(() => {
    port = chrome.runtime.connect({ name: 'sidepanel' });
  }, 1000);
});

// Initial state notification
notifyPanelState(true);

// Heartbeat to maintain connection
setInterval(() => {
  try {
    port.postMessage({ type: 'heartbeat' });
  } catch (e) {
    port = chrome.runtime.connect({ name: 'sidepanel' });
  }
}, 5000);

ReactDOM.createRoot(document.getElementById('root') as HTMLElement).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
); 