import { useContext } from "react";
import { PageContext } from "../../context/page-context/page-context";

const useExplore = () => {
  const { pathsData , activeTabUrl} = useContext(PageContext);

  const handlePathClick = async (pathUrl: string, type: 'trending' | 'other', title: string) => {
    chrome.runtime.sendMessage({
      action: "sendAnalytics",
      url: activeTabUrl,
      eventName: "Path Clicked",
      eventProperties: {
        tab: "Explore",
        type: type,
        path: title,
      }
    });
    await chrome.tabs.create({
      url: pathUrl,
      active: true,
    });
  };

  const trendingPathsData = pathsData?.filter((item) => item?.trending);
  const otherPathsData = pathsData?.filter((item) => !item?.trending)?.sort((a, b) => a.title.localeCompare(b.title));

  return {
    otherPathsData,
    trendingPathsData,
    handlePathClick,
    pathsData,
  };
};

export default useExplore;
