import React, { useEffect, useRef, useState } from "react";
import { ChatContainer, MessageList } from "@chatscope/chat-ui-kit-react";
import "@chatscope/chat-ui-kit-styles/dist/default/styles.min.css";
import { cn } from "../../utils/cn";
import { LoaderWithThreeDots } from "../loader/loader";
import MessageContainer from "./message-container/message-container";
import LiveMessageContainer from "./message-container/live-message-container";

type ChatMessagesContainerProps = {
  source: "content" | "sidebar";
  isLiveMessageStreaming: boolean;
  loading: boolean;
  chatMessages: any;
  lastAssistantMessage: any;
  liveMessages: any;
  setLiveMessages: Function;
  userLiveMessage: any;
  sendMessage: Function;
  userQuery: any;
  mentoraiData: any;
  menteeData: any;
  activeTabUrl: string;
  messagesContainerClassName?: string;
  userMessageWrapperClassName?: string;
  aiMessageWrapperClassName?: string;
  mainChatContainerClassName?: string;
  playerMode?: string;
  customTypingIndicator?: React.ReactNode;
};

const ChatMessagesContainer = ({
  messagesContainerClassName,
  source,
  isLiveMessageStreaming,
  loading,
  chatMessages,
  lastAssistantMessage,
  liveMessages,
  setLiveMessages,
  userLiveMessage,
  sendMessage,
  userQuery,
  mentoraiData,
  menteeData,
  activeTabUrl,
  userMessageWrapperClassName,
  aiMessageWrapperClassName,
  mainChatContainerClassName,
  playerMode,
  customTypingIndicator
}: ChatMessagesContainerProps) => {


  const shouldShowInitialMsgTitle = chatMessages?.length === 1 && !isLiveMessageStreaming && activeTabUrl.includes('youtube.com')
  const [shouldAnimate, setShouldAnimate] = useState(false)
  useEffect(() => {
    setTimeout(() => {
      setShouldAnimate(true)
    }, 1000)
  }, [])

  // const prevIsLiveMessageStreaming = useRef(isLiveMessageStreaming);

  // useEffect(() => {
  //   // scroll when streaming ends, not during streaming
  //   if (prevIsLiveMessageStreaming.current && !isLiveMessageStreaming) {
  //     const lastSidebarMsg = document.getElementById("sidebar-chat-conversation-last-message");
  //     const lastContentMsg = document.getElementById("content-chat-conversation-last-message");
  //     if (lastSidebarMsg) {
  //       lastSidebarMsg.scrollIntoView({ behavior: "smooth", block: "end" });
  //     }
  //     if (lastContentMsg) {
  //       lastContentMsg.scrollIntoView({ behavior: "smooth", block: "end" });
  //     }
  //   }
  //   prevIsLiveMessageStreaming.current = isLiveMessageStreaming;
  // }, [isLiveMessageStreaming, chatMessages, liveMessages, userLiveMessage]);


  return (
    <>
      <ChatContainer
        className={`!bg-[#14161F] relative flex flex-col h-full rounded-[14px] ${messagesContainerClassName}`}
      >
        <MessageList
          // scrollBehavior="smooth"
          id="main-chat-container"
          className={cn("flex-1", mainChatContainerClassName)}
          typingIndicator={
            isLiveMessageStreaming && (
              customTypingIndicator ? (customTypingIndicator) : (
                <div className={`w-fit rounded-[12px] h-7 flex gap-1 items-center ${playerMode === "NOT_DEFAULT" ? 'mt-[-34px]' : 'mt-[16px]'}`}>
                  <LoaderWithThreeDots color="#D0CFD4" height="4" width="16" />
                  <p className="bg-gradient-to-r from-[#F2F2F2] via-[#F2F2F2] italic !to-[#575762] bg-clip-text text-transparent text-[12px] leading-[18px]">
                    Typing
                  </p>
                </div>
              )
            )
          }
          autoScrollToBottom={false}
          autoScrollToBottomOnMount={true}
          loading={loading}
        >
          {shouldShowInitialMsgTitle && (
            <p
              style={{
                position: playerMode === "NOT_DEFAULT" ? 'absolute' : 'relative',
                top: playerMode === "NOT_DEFAULT" ? '48%' : '',
                color: '#66666B',
                paddingRight:'8px',
                paddingTop: playerMode === "NOT_DEFAULT" ? '' : '32px',
                fontSize: playerMode === "NOT_DEFAULT" ? '24px' : '20px',
                fontWeight: playerMode === "NOT_DEFAULT" ? '700' : '600',
                lineHeight: playerMode === "NOT_DEFAULT" ? '34px' : '30px',
                letterSpacing: playerMode === "NOT_DEFAULT" ? '-0.24px' : '-0.2px',
                textAlign: playerMode === "NOT_DEFAULT" ? 'center' : 'left',
              }}
            >
              Ask me any questions about the video
            </p>
          )}
          {chatMessages.map((m: any, i: number) => {
            const isLastMessage = i === chatMessages.length - 1;
            const isCreditExhaustedMessage = m.props.model.message === `You've used all free credits today./nUpgrade or wait until tomorrow's credit reset.`

            return (
              <div
                id={
                  isLastMessage
                    ? source === "content"
                      ? "content-chat-conversation-last-message"
                      : "sidebar-chat-conversation-last-message"
                    : source === "content"
                      ? "content-chat-conversation-message"
                      : "sidebar-chat-conversation-message"
                }
                className={cn(
                  "group",
                  (isLastMessage && "pb-[36px]"),
                  shouldShowInitialMsgTitle && (playerMode === "NOT_DEFAULT" ? "absolute top-[calc(100%-154px)]" : "mt-[-8%]"),
                  m.props.model.sender === "user" ? ` !my-5` : `${isCreditExhaustedMessage ? ' !mt-[-4px]' : ' !pt-[24.8px]'}`,
                  (isLastMessage && [...userLiveMessage, ...liveMessages].length === 0) && (source === "sidebar" ? (`${shouldShowInitialMsgTitle ? '' : 'min-h-[calc(100vh-220px)]'}`) : (`${chatMessages?.length === 1 ? '' : 'min-h-[calc(100vh-420px)]'}`))
                )}
              >
                <MessageContainer
                  m={m}
                  i={i}
                  key={`${m.props.model.message}-${i}`}
                  isLastMessage={isLastMessage}
                  sendMessage={sendMessage}
                  isLiveMessageStreaming={isLiveMessageStreaming}
                  loading={loading}
                  userQuery={userQuery}
                  setLiveMessages={setLiveMessages}
                  mentoraiData={mentoraiData}
                  menteeData={menteeData}
                  activeTabUrl={activeTabUrl}
                  userMessageWrapperClassName={userMessageWrapperClassName}
                  aiMessageWrapperClassName={aiMessageWrapperClassName}
                  source={source}
                  shouldShowInitialMsgTitle={shouldShowInitialMsgTitle}
                  shouldAnimate={shouldAnimate}
                />
              </div>
            );
          })}
          {[...userLiveMessage, ...liveMessages].length > 0 && (
            <LiveMessageContainer
              source={source}
              liveMessages={liveMessages}
              setLiveMessages={setLiveMessages}
              userLiveMessage={userLiveMessage}
              isLiveMessageStreaming={isLiveMessageStreaming}
              sendMessage={sendMessage}
              mentoraiData={mentoraiData}
              menteeData={menteeData}
              activeTabUrl={activeTabUrl}
              userMessageWrapperClassName={userMessageWrapperClassName}
              aiMessageWrapperClassName={aiMessageWrapperClassName}
            />
          )}
        </MessageList>
      </ChatContainer>
    </>
  );
};

export default ChatMessagesContainer;
