import React from "react";
import { useState } from "react";

const CopyClipboard = ({ text }: { text: string }) => {
  const [isCopied, setIsCopied] = useState(false);
  const handleCopy = () => {
    navigator.clipboard.writeText(text).then(
      () => {
        setIsCopied(true);
        setTimeout(() => setIsCopied(false), 2000); // Reset after 2 seconds
      },
      (err) => {
        setIsCopied(false);
        console.error("Failed to copy text: ", err);
      }
    );
  };

  return (
    <div
      className="absolute right-[4px] top-[2px] cursor-pointer flex h-[22px] w-[22px] items-center justify-center bg-layer-02 dark:bg-layer-02 hover:bg-fill-tertiary dark:hover:bg-fill-tertiary rounded-[4px]"
      data-state="closed"
      onClick={handleCopy}
    >
      {!isCopied ? (
        <svg
          aria-hidden="true"
          focusable="false"
          data-prefix="far"
          data-icon="clone"
          className="svg-inline--fa fa-clone absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2"
          role="img"
          xmlns="http://www.w3.org/2000/svg"
          viewBox="0 0 512 512"
        >
          <path
            fill="currentColor"
            d="M64 464H288c8.8 0 16-7.2 16-16V384h48v64c0 35.3-28.7 64-64 64H64c-35.3 0-64-28.7-64-64V224c0-35.3 28.7-64 64-64h64v48H64c-8.8 0-16 7.2-16 16V448c0 8.8 7.2 16 16 16zM224 304H448c8.8 0 16-7.2 16-16V64c0-8.8-7.2-16-16-16H224c-8.8 0-16 7.2-16 16V288c0 8.8 7.2 16 16 16zm-64-16V64c0-35.3 28.7-64 64-64H448c35.3 0 64 28.7 64 64V288c0 35.3-28.7 64-64 64H224c-35.3 0-64-28.7-64-64z"
          ></path>
        </svg>
      ) : (
        <svg
          width="16px"
          height="16px"
          viewBox="0 0 48 48"
          version="1"
          xmlns="http://www.w3.org/2000/svg"
          enable-background="new 0 0 48 48"
        >
          <polygon
            fill="#43A047"
            points="40.6,12.1 17,35.7 7.4,26.1 4.6,29 17,41.3 43.4,14.9"
          />
        </svg>
      )}
    </div>
  );
};

export default CopyClipboard;
