import Awful from "../../../assets/emoji-awful.svg"
import Bad from "../../../assets/emoji-bad.svg"
import Okay from "../../../assets/emoji-okay.svg"
import Good from "../../../assets/emoji-good.svg"
import Great from "../../../assets/emoji-great.svg"
import { useEffect, useState } from "react"
import { useContext } from "react"
import { PageContext } from "../../../context/page-context/page-context"
import { MenteeContext } from "../../../context/mentee-context/mentee-context"
import { MentorAiContext } from "../../../context/mentorai-context/mentorai-context"
import { extractQuestionDifficulty } from "../../../utils/side-panel-helper"
import { estimatedTimeMapping } from "../../../constant"
import { INTERVIEW_PROGRESS_THRESHOLDS } from "../../../constant/interview-progress"
const useInterviewFeedbackPopup = (chatMessages: any[]) => {
  const [feedback, setFeedback] = useState<string>("")
  const { activeTabUrl, interviewCount, scrapedData, timer, interviewModeStatus } =
    useContext(PageContext)
  const { menteeData } = useContext(MenteeContext)
  const { mentoraiData } = useContext(MentorAiContext)
  const [selectedRatingAndOption, setSelectedRatingAndOption] = useState<any>({
    rating: null,
    options: null,
  })
  const [ratingSubmitted, setRatingSubmitted] = useState<boolean>(false)
  const [feedbackSubmitted, setFeedbackSubmitted] = useState<boolean>(false)
  const [isLoading, setIsLoading] = useState<boolean>(true)
  const questionDifficulty = extractQuestionDifficulty(scrapedData)
  const estimatedTime =
    estimatedTimeMapping[
    questionDifficulty as keyof typeof estimatedTimeMapping
    ]


  const difficulty = extractQuestionDifficulty(scrapedData || "") as keyof typeof INTERVIEW_PROGRESS_THRESHOLDS
  const startTime = INTERVIEW_PROGRESS_THRESHOLDS[difficulty || "Unknown"].startTime
  const timeInMinutes = Math.floor(startTime / 60)
  const isTimeSpentLessThanFiveMinutesAndLessThanFiveMessagesSent = timeInMinutes * 60 - timer < 5 * 60 && chatMessages.length < 11


  const handleSubmitRating = (rating: string) => {
    setRatingSubmitted(true)
    chrome.runtime.sendMessage({
      action: "sendAnalytics",
      url: activeTabUrl,
      eventName: "MentorAi Interview Mode Feedback Submitted",
      eventProperties: {
        reaction: rating,
      },
    })
  }

  const handleSubmitFeedback = () => {
    setFeedbackSubmitted(true)
    chrome.runtime.sendMessage({
      action: "sendAnalytics",
      url: activeTabUrl,
      eventName: "MentorAi Interview Mode Feedback Submitted",
      eventProperties: {
        comments: feedback,
      },
    })
  }

  const ratingValues = [
    {
      id: 1,
      rating: "Awful",
      emoji: Awful,
      options: [
        "Doesn't align with your goals",
        "Hard to follow",
        "Too detailed, overwhelming",
        "Lacks clarity, focus",
        "Feels visually cluttered",
        "Needs more practical steps",
      ],
      text: "I'm sorry! What are the issues? (Optional)",
    },
    {
      id: 2,
      rating: "Bad",
      emoji: Bad,
      options: [
        "Doesn't align with your goals",
        "Hard to follow",
        "Too detailed, overwhelming",
        "Lacks clarity, focus",
        "Feels visually cluttered",
        "Needs more practical steps",
      ],
      text: "I'm sorry! What are the issues? (Optional)",
    },
    {
      id: 3,
      rating: "Okay",
      emoji: Okay,
      options: [
        "Align better with your goals",
        "Include more skills",
        "Focus on fewer skills",
        "Explain roadmap better",
        "Simplify the roadmap",
        "Improve visual layout",
        "Suggest more practical steps",
      ],
      text: "I see! What could I improve? (Optional)",
    },
    {
      id: 4,
      rating: "Good",
      emoji: Good,
      options: [
        "Align better with your goals",
        "Include more skills",
        "Focus on fewer skills",
        "Explain roadmap better",
        "Simplify the roadmap",
        "Improve visual layout",
        "Suggest more practical steps",
      ],
      text: "I see! What could I improve? (Optional)",
    },
    {
      id: 5,
      rating: "Great",
      emoji: Great,
      options: [
        "Aligns with your goals",
        " Clearly Structured",
        " Covers everything you need",
        " Easy to follow",
        " Good visual layout",
      ],
      text: "I'm glad! What stood out to you? (Optional)",
    },
  ]

  const generateFeedback = async () => {
    const { feedbackGenerating } = await chrome.storage.local.get("feedbackGenerating")
    if (feedbackGenerating) {
      setIsLoading(true)
      return
    }
    const payload = {
      user_id: menteeData?.recordId, // TODO: Get from context
      mentor_ai_id: mentoraiData?.recordId, // TODO: Get from context
      page_context: {
        url: activeTabUrl,
        content: scrapedData,
      },
      messages: chatMessages.map((msg: any) => ({
        role: msg.props.model.sender,
        content: msg.props.model.message,
      })),
      interview_count: interviewCount,
      time_taken: estimatedTime - timer,
      estimated_time: estimatedTime,
      candidate_data: menteeData,
    }

    try {
      // Use a Promise to wait for the complete response from the background script
      const response: any = await new Promise((resolve, reject) => {
        chrome.runtime.sendMessage(
          {
            action: "generate-feedback",
            url: "/extension/generate-feedback",
            payload: payload,
            waitForCompletion: true,
            activeTabUrl: activeTabUrl, // Signal that we want to wait for the complete process
          },
          (response) => {
            if (chrome.runtime.lastError) {
              reject(chrome.runtime.lastError);
            } else {
              resolve(response);
            }
          }
        );
      });

      // Check if the response indicates an error
      if (response && response.error) {
        throw new Error(response.error);
      }

      chrome.runtime.sendMessage({
        action: "sendAnalytics",
        url: activeTabUrl,
        eventName: "MentorAi Interview Mode Report Generated",
        eventProperties: {},
      })
      
    } catch (error) {
      console.error("[ERROR] Failed to generate feedback:", error);
      chrome.runtime.sendMessage({
        action: "sendAnalytics",
        url: activeTabUrl,
        eventName: "MentorAi Interview Mode Report Generation Failed",
        eventProperties: {},
      }) 
    } finally {
      setIsLoading(false);
      chrome.storage.local.set({
        feedbackGenerating: false,
      });
    }
  }

  useEffect(() => {
    if (interviewModeStatus === "FEEDBACK" && !isTimeSpentLessThanFiveMinutesAndLessThanFiveMessagesSent) {
      generateFeedback()
    } else {
      setIsLoading(false)
    }
  }, [interviewModeStatus])


  useEffect(() => {
    chrome.storage.local.onChanged.addListener((changes) => {
      if (changes.feedbackGenerating) {
        if (changes.feedbackGenerating.newValue) {
          setIsLoading(true)
        } else {
          setIsLoading(false)
        }
      }
    })
  }, [])

  return {
    ratingValues,
    selectedRatingAndOption,
    setSelectedRatingAndOption,
    ratingSubmitted,
    handleSubmitRating,
    feedbackSubmitted,
    handleSubmitFeedback,
    isLoading,
    feedback,
    setFeedback,
    isTimeSpentLessThanFiveMinutesAndLessThanFiveMessagesSent
  }
}

export default useInterviewFeedbackPopup
