import React, { createContext, useContext, useState, useEffect, ReactNode, useCallback, useRef } from 'react';
import { MicrophonePermissionStatus } from '../../../content/contexts/content-sync-context/content-sync-context';

interface SidepanelSyncContextType {
  permissionStatus: MicrophonePermissionStatus;
  isAudioLive: boolean;
  setIsAudioLive: (isAudioLive: boolean) => void;
  transcription: string;
  setTranscription: (transcription: string) => void;
  widgetState: WidgetState;
  setWidgetState: (widgetState: WidgetState) => void;
  volume: number;
  setVolume: (volume: number) => void;
  browserInfo: any;
  setBrowserInfo: (browserInfo: any) => void;
}

const SidepanelSyncContext = createContext<SidepanelSyncContextType | undefined>(undefined);

type WidgetState = "HIDE" | "MICROPHONE_PREMISSION" | "MICROPHONE_PREMISSION_ERROR" | "SHOW" | "LISTENING";

export const SidepanelSyncProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [browserInfo, setBrowserInfo] = useState<any>(null);
  const [permissionStatus, setPermissionStatus] = useState<MicrophonePermissionStatus>('prompt');
  const [isAudioLive, setIsAudioLive] = useState(false);
  const [transcription, setTranscription] = useState<string>('');
  const [widgetState, setWidgetState] = useState<WidgetState>("HIDE");
  const [volume, setVolume] = useState(0);
  const isLocalUpdate = useRef(false);

  // useEffect(() => {
  //   const initializeStates = async () => {
  //     const activeTab = await chrome.tabs.query({active: true, currentWindow: true});
  //     if (activeTab[0]?.id) {
  //       chrome.tabs.sendMessage(activeTab[0].id, { 
  //         type: 'getInitialStates' 
  //       });
  //     }
  //   };
  //   initializeStates();
  // }, []);

  const handleMessage = useCallback(async (message: any) => {    
    if (message.type === 'syncStatesToSidepanel' || message.type === 'initialStates') {
      isLocalUpdate.current = false;
      
      // Only update states if they've changed
      if (message.permissionStatus !== permissionStatus) {
        setPermissionStatus(message.permissionStatus);
      }
      if (message.isAudioLive !== isAudioLive) {
        setIsAudioLive(message.isAudioLive);
      }
      if (message.transcription !== transcription) {
        setTranscription(message.transcription);
        setVolume(message.volume)
      }
      if (message.widgetState !== widgetState) {
        setWidgetState(message.widgetState);
      }
      if (message.browserInfo !== browserInfo) {
        setBrowserInfo(message.browserInfo);
      }
    }
  }, [permissionStatus, isAudioLive, transcription, widgetState, volume, browserInfo]);

  const handleLocalStateChange = useCallback((type: string, value: any) => {
    isLocalUpdate.current = true;
    switch(type) {
      case 'isAudioLive':
        setIsAudioLive(value);
        break;
      case 'transcription':
        setTranscription(value);
        break;
      case 'widgetState':
        setWidgetState(value);
        break;
      case 'volume':
        setVolume(value);
        break;
    }
  }, []);

  // useEffect(() => {
  //   chrome.runtime.onMessage.addListener(handleMessage);
  //   return () => {
  //     chrome.runtime.onMessage.removeListener(handleMessage);
  //   };
  // }, [handleMessage]);

  // useEffect(() => {
  //   if (isLocalUpdate.current) {
  //     const syncStatesToContext = async () => {
  //       const activeTab = await chrome.tabs.query({active: true, currentWindow: true});
  //       if (activeTab[0]?.id) {
  //         chrome.tabs.sendMessage(activeTab[0].id, { 
  //           type: 'syncStatesToContext', 
  //           permissionStatus, 
  //           isAudioLive, 
  //           transcription, 
  //           widgetState ,
  //         });
  //       }
  //     }
  //     syncStatesToContext();
  //   }
  // }, [permissionStatus, isAudioLive, transcription, widgetState]);

  return (
    <SidepanelSyncContext.Provider
      value={{
        permissionStatus,
        isAudioLive,
        setIsAudioLive: (value) => handleLocalStateChange('isAudioLive', value),
        transcription,
        setTranscription: (value) => handleLocalStateChange('transcription', value),
        widgetState,
        setWidgetState: (value) => handleLocalStateChange('widgetState', value),
        volume,
        setVolume: (value) => handleLocalStateChange('volume', value),
        browserInfo,
        setBrowserInfo: (value) => handleLocalStateChange('browserInfo', value),
      }}
    >
      {children}
    </SidepanelSyncContext.Provider>
  );
};

export const useSidepanelSyncContext = () => {
  const context = useContext(SidepanelSyncContext);
  if (!context) {
    throw new Error('useSidepanelSyncContext must be used within a SidepanelSyncContextProvider');
  }
  return context;
}; 