import React from "react";
import { motion } from "framer-motion";
import { Message, Avatar } from "@chatscope/chat-ui-kit-react";
import "@chatscope/chat-ui-kit-styles/dist/default/styles.min.css";
import rehypeRaw from "rehype-raw";
import remarkGfm from "remark-gfm";
import ReactMarkdown from "react-markdown";
import rehypeKatex from "rehype-katex";
import "katex/dist/katex.min.css";
import { Highlight, themes } from "prism-react-renderer";
import { cn } from "../../../utils/cn";
import useMessageContainer from "./use-message-container";
import SelectorArrayOfOptions from "../../select-array-of-options/select-array-of-options";
import Dot from "../../assets/green-dot.svg";
import MessageFeedback from "../message-feedback/message-feedback";
import CopyClipboard from "../../utils/copy-clipboard";
import remarkMath from "remark-math";
import { useContext, useEffect, useState } from "react";
import ContextCollectionOptions from "../context-collection-options/context-collection-options";
import ErrorMessageRedTheme from "../../../src/components/conversation-container/message-container/error-messages/error-message-red-theme";
import ErrorMessageYellowTheme from "../../../src/components/conversation-container/message-container/error-messages/error-message-yello-theme";
import { customMessages } from "../../../configs/custom-messages";
import { PageContext } from "../../../src/context/page-context/page-context";
import MicIcon from "../../../src/assets/mic.svg?react";
import { useSidepanelSyncContext } from "../../../src/context/sidepanel-sync-context/sidepanel-sync-context";
import { AnimatePresence } from "framer-motion";
import { ChatContext } from "../../../src/context/chat-context/chat-context";
import PromotionalCard from "../../../src/components/promotional-cards/credit-promotional-card";
import { shouldShowSoftTrigger } from "../../../utils/credit-limit-utils";
import CancelledSoftTrigger from "../../../src/components/cancelled-soft-trigger/cancelled-soft-trigger";

const SpeakActionButton = ({ className }: { className?: string }) => {
  const { isAudioLive } = useSidepanelSyncContext();

  const handleSpeak = () => {
    chrome.storage.local.set({
      toggleMicrophone: !isAudioLive
    })
  }

  useEffect(() => {
    chrome.storage.local.set({
      toggleMicrophone: false
    })
  }, []);

  return <motion.button
    initial={{ opacity: 0 }}
    animate={{ opacity: isAudioLive ? 0.5 : 1 }}
    exit={{ opacity: 0 }}
    whileHover={!isAudioLive ? { opacity: 0.8 } : {}}
    transition={{ duration: 0.3 }}
    disabled={isAudioLive}
    onClick={handleSpeak}
    className={`px-2 mt-6 py-[5px] border flex font-bricolage-grotesque items-center text-[12px] 
      transition-all duration-300 leading-[18px] font-medium text-mentorai-text-soft gap-1 border-[#4B298E] 
      rounded-lg [background:radial-gradient(49.71%_107.81%_at_50.29%_100%,_#763CEA_0%,_#461C9C_18.11%,_#09092A_71.3%)]
      ${className || ""}`}>
    <MicIcon className="w-[12px] h-[12px] text-mentorai-primary-lighter" />
    Speak your answer
  </motion.button>
}

const MessageContainer = ({
  m,
  i,
  isLastMessage,
  sendMessage,
  isLiveMessageStreaming,
  loading = false,
  userQuery,
  setLiveMessages,
  mentoraiData,
  menteeData,
  activeTabUrl,
  userMessageWrapperClassName,
  aiMessageWrapperClassName,
  source,
  shouldShowInitialMsgTitle,
  shouldAnimate
}: {
  m: any;
  i: number;
  isLastMessage: boolean;
  sendMessage: Function;
  isLiveMessageStreaming?: boolean;
  loading?: boolean;
  userQuery?: string;
  setLiveMessages: Function;
  mentoraiData: any;
  menteeData: any;
  activeTabUrl: string;
  userMessageWrapperClassName?: string;
  aiMessageWrapperClassName?: string;
  source: "content" | "sidebar";
  shouldShowInitialMsgTitle?: boolean;
  shouldAnimate?: boolean
}) => {
  const { uiComponents } = useMessageContainer(m);
  const [suggestedActions, setSuggestedActions] = useState<any[]>([]);
  const { practiceModeStatus, interviewModeStatus } = useContext(PageContext);
  const { chatUsageData } = useContext(ChatContext);
  const shouldShowSoftTriggers = m.props.model.sender === "assistant" && isLastMessage && !isLiveMessageStreaming && !chatUsageData.isPaidUser && chatUsageData.dailyMessagesLeft > 0 && shouldShowSoftTrigger(chatUsageData.dailyMessagesLeft, chatUsageData.dailyMessageLimit)
  const shouldShowCancelledSoftTriggers = m.props.model.sender === "assistant" && isLastMessage && !isLiveMessageStreaming
  const fetchSuggestedEasyActions = async () => {
    const res = await chrome.storage.local.get("suggestedEasyActions");
    setSuggestedActions(
      res?.suggestedEasyActions?.[activeTabUrl]?.suggestions || []
    );
  };

  useEffect(() => {
    fetchSuggestedEasyActions();
  }, []);

  const isCustomUserMessage = m.props.model.sender === "user" && customMessages.includes(m.props.model.message);
  const isCreditExhaustedMessage = m.props.model.message === `You've used all free credits today./nUpgrade or wait until tomorrow's credit reset.`

  const renderComponents = (data: any, index: number) => {
    try {
      if (data.easy_action === "selector") {
        return null;
      }

      if (m.props.error) {
        if (m.props.theme === "yellow") {
          return (
            <ErrorMessageYellowTheme message={m.props.model.message}>
              {m.props.children}
            </ErrorMessageYellowTheme>
          );
        }

        return (
          <ErrorMessageRedTheme
            message={m.props.model.message}
            sendMessage={sendMessage}
            isLiveMessageStreaming={isLiveMessageStreaming}
          />
        );
      }

      return (
        <ReactMarkdown
          rehypePlugins={[rehypeRaw, rehypeKatex]}
          remarkPlugins={[remarkGfm, remarkMath]}
          className={cn(
            `prose markdown-prose !text-[14px]/[22px] !tracking-[0.14px] ${m.props.model.sender === "user" &&
              suggestedActions?.includes(m.props.model.message)
              ? "  font-medium  !bg-gradient-to-r !from-[#F25E55] !to-[#8D3DF2] !bg-clip-text !text-transparent "
              : " !text-[#DDDDDF] !font-normal"
            }`,
            isCustomUserMessage ? "!bg-[linear-gradient(94deg,#FF9B53_6.12%,#EC6EFF_52.18%,#7F62FF_96.4%)] !bg-clip-text !text-transparent !font-[500]" : ""
          )}
          key={`${m.props.model.message?.slice(0, 10)}-${i}`}
          components={{
            code({ className, children, ...props }) {
              const match = /language-(\w+)/.exec(className || "");
              const isInline = !match;
              const codeContent = String(children).replace(/\n$/, "");
              return !isInline ? (
                <div className="!font-mono my-2 relative max-w-[calc(100vw-80px)] mx-auto">
                  <CopyClipboard text={codeContent} />
                  <Highlight
                    theme={themes.vsDark}
                    code={codeContent}
                    language={match[1].toLowerCase()}
                  >
                    {({
                      className,
                      style,
                      tokens,
                      getLineProps,
                      getTokenProps,
                    }) => (
                      <pre
                        className={`${className} overflow-x-auto coding-scrollbar min-h-[44px]`}
                        style={{
                          ...style,
                          margin: 0,
                          padding: "1rem",
                          borderRadius: "0.375rem",
                          scrollbarWidth: "thin",
                          scrollbarColor: "#6B7280 #2D2D2D",
                        }}
                      >
                        {tokens.map((line, i) => (
                          <div key={i} {...getLineProps({ line })}>
                            <span className="mr-4 text-gray-500">{i + 1}</span>
                            {line.map((token, key) => (
                              <span key={key} {...getTokenProps({ token })} />
                            ))}
                          </div>
                        ))}
                      </pre>
                    )}
                  </Highlight>
                </div>
              ) : (
                <code className="bg-[#1e1e1e] !px-1 !pt-0.5 rounded !text-[13px]/[18px] !font-fira-code" {...props}>
                  {children}
                </code>
              );
            },
            a: ({ node, ...props }) => {
              return <a className="text-mentorai-primary-lighter hover:underline" {...props} />;
            },
            p: ({ node, ...props }) => {
              return <p className="" {...props} />;
            },
            h1: ({ node, ...props }) => {
              return <h1 className="pt-3 font-medium" {...props} />;
            },
            h2: ({ node, ...props }) => {
              return <h2 className="pt-3 font-medium" {...props} />;
            },
            h3: ({ node, ...props }) => {
              return <h3 className="pt-3 font-medium" {...props} />;
            },
            h4: ({ node, ...props }) => {
              return <h4 className="pt-3 font-medium" {...props} />;
            },
            h5: ({ node, ...props }) => {
              return <h5 className="pt-3 font-medium" {...props} />;
            },
            h6: ({ node, ...props }) => {
              return <h6 className="pt-3 font-medium" {...props} />;
            },
            hr: ({ node, ...props }) => {
              return (
                <div className="bg-[#6b7280] my-3 h-px w-full" {...props}>
                  <span className="invisible">.</span>
                </div>
              );
            },
            ol: ({ node, ...props }) => {
              return <ol className="pt-3" {...props} />;
            },
            li: ({ node, ...props }) => {
              return <li className="text-[14px]/[22px] tracking-[0.14px]" {...props} />;
            },
            strong: ({ node, ...props }) => {
              return <strong className="" {...props} />
            },
            em: ({ node, ...props }) => {
              return <em className="text-[14px]/[22px] tracking-[0.14px]" {...props} />
            },
            pre: ({ node, ...props }) => {
              const content = props.children?.toString() || "";
              return (
                <div
                  style={{
                    scrollbarWidth: "thin",
                    scrollbarColor: "#6B7280 #2D2D2D",
                  }}
                  className="!font-mono my-2 relative max-w-[calc(100vw-80px)] mx-auto min-h-[44px]"
                >
                  <CopyClipboard text={content} />
                  <pre {...props} />
                </div>
              );
            },
          }}
        >
          {data?.data}
        </ReactMarkdown>
      );
    } catch (e) {
      console.log("error rendering data: ", data);
      return <></>;
    }
  };

  const renderEasyActions = (data: any, index: number) => {
    // Remove the speak button logic from here - it should only handle specific easy_action types
    if (data.easy_action === "selector") {
      return (
        <SelectorArrayOfOptions
          shouldAnimate={shouldAnimate}
          data={data?.data as any}
          key={index}
          sendMessage={sendMessage}
          className={{
            containerClassName: isLastMessage && !isLiveMessageStreaming && !loading && shouldAnimate ? "" : "hidden",
          }}
        />
      );
    }
    if (
      data.easy_action === "leetcode profile data collection" &&
      isLastMessage
    ) {
      return (
        <ContextCollectionOptions
          data={data?.data}
          sendMessage={sendMessage}
          setLiveMessages={setLiveMessages}
          mentoraiData={mentoraiData}
        />
      );
    }
  };

  if (m.props.model.sender === "system") {
    return (
      <div className="flex items-center justify-between gap-2">
        <svg
          width="24"
          height="24"
          viewBox="0 0 24 24"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          className="mt-1 shrink-0"
        >
          <path
            fill-rule="evenodd"
            clip-rule="evenodd"
            d="M5 6C5.55228 6 6 6.44772 6 7V11C6 11.5523 6.44772 12 7 12H16.5858L14.2929 9.70711C13.9024 9.31658 13.9024 8.68342 14.2929 8.29289C14.6834 7.90237 15.3166 7.90237 15.7071 8.29289L19.7071 12.2929C20.0976 12.6834 20.0976 13.3166 19.7071 13.7071L15.7071 17.7071C15.3166 18.0976 14.6834 18.0976 14.2929 17.7071C13.9024 17.3166 13.9024 16.6834 14.2929 16.2929L16.5858 14H7C5.34315 14 4 12.6569 4 11V7C4 6.44772 4.44772 6 5 6Z"
            fill="#9b9b9b"
          ></path>
        </svg>
        <p className="text-[14px]/[22px] text-[#DDDDDF] line-clamp-1">
          {m.props.model.message}
        </p>
      </div>
    );
  }

  if (m.props.error && !isLastMessage) {
    return;
  }

  if (m.props.model.message.includes("Simplify this video for me") && m.props.model.sender === "assistant" && i === 0 && (!isLastMessage || isLiveMessageStreaming)) {
    return;
  }
  const shouldAnimateUserMessage = m.props.model.sender === "user" && isLastMessage && isLiveMessageStreaming;
  return (
    <>
      <motion.div
        initial={shouldAnimateUserMessage ? { opacity: 0, y: "50vh" } : {}}
        animate={shouldAnimateUserMessage ? { opacity: 1, y: 0 } : {}}
        transition={shouldAnimateUserMessage ? {
          duration: 0.4,
          ease: "linear",
          y: { duration: 0.4, ease: "linear" }
        } : {}}
      >
        <Message
          key={`${m.props.model.message}-${i}`}
          {...(m.props as any)}
          className={cn(
            `font-bricolage-grotesque`,
            `flex flex-col !text-[#DDDDDF] cursor-default gap-[8px] 
            ${source === "content" ? "!max-w-[100%]" : ""} 
            ${isCreditExhaustedMessage ? "w-full" : "!w-fit max-w-fit "}
            `,
            m.props.model.sender === "user"
              ? `!ml-auto !rounded-[8px] bg-[#212431] !py-[8px] !px-[12px] max-w-[calc(100%-44px)] ${userMessageWrapperClassName}`
              : `bg-[#14161F] !mx-0 ${aiMessageWrapperClassName}  ${isLiveMessageStreaming && ' !pt-[24.8px]'}`
          )}
        >
          {/* {m.props.children} */}
          {m.props.model.sender == "assistant" && !shouldShowInitialMsgTitle && (
            <Avatar
              src={
                m.props.model.senderPhotoUrl ||
                "https://cdn-icons-png.flaticon.com/512/6596/6596121.png"
              }
              name={m.props.model.sender === "user" ? "user" : "mentor"}
              size="sm"
              className="!h-[20px]"
              children={
                <div className="flex gap-[2px]">
                  <div className="relative flex items-center">
                    <div
                      className={`flex h-[28px] w-[28px] items-center rounded-full `}
                    >
                      <img
                        className="h-[20px] w-[20px] rounded-full min-w-5 min-h-5"
                        src={
                          m.props.model.senderPhotoUrl ||
                          "https://cdn-icons-png.flaticon.com/512/6596/6596121.png"
                        }
                        alt={m.props.model.sender === "user" ? "user" : "mentor"}
                      />
                    </div>
                    <span className={cn("absolute bottom-[1px] left-[13px]")}>
                      <img src={Dot} className="h-[12px] w-[12px]" alt="dot" />
                    </span>
                  </div>
                  <p
                    className="flex  items-center text-[#94939f] text-center text-[12px] leading-normal font-medium font-manrope"
                    style={{
                      fontSize: "12px",
                      fontWeight: "500",
                    }}
                  >
                    {m.props.model.senderName}
                  </p>
                </div>
              }
            />
          )}
          <Message.CustomContent>
            {uiComponents?.map((data: any, index: number) => {
              return <div className={``}>{renderComponents(data, index)}</div>;
            })}
          </Message.CustomContent>
        </Message>

        {/* Easy actions */}
        {uiComponents?.map((data: any, index: number) => {
          return <div className={``}>{renderEasyActions(data, index)}</div>;
        })}

        {/* Message feedback */}
        {/* {m.props.model.sender === "assistant" && !shouldShowInitialMsgTitle && (
          <div className={"opacity-0 group-hover:opacity-100 transition-opacity"}>
            <MessageFeedback
              message={m.props.model.message}
              messageId={m?.props?.model?.id || m?.props?.model?.sentTime}
              className=" "
              userQuery={userQuery || ""}
              mentoraiData={mentoraiData}
              menteeData={menteeData}
              activeTabUrl={activeTabUrl}
            />
          </div>
        )} */}

        {/* Soft Triggers for free users */}
        {shouldShowSoftTriggers && (
          <PromotionalCard
            chatUsageData={chatUsageData}
          />
        )}
        {/* Soft Triggers for cancelled users */}
        {shouldShowCancelledSoftTriggers &&
          <CancelledSoftTrigger
            chatUsageData={chatUsageData}
          />
        }

        {/* Message feedback */}
        {m.props.model.sender === "assistant" && !shouldShowInitialMsgTitle && (
          <div className={"opacity-0 group-hover:opacity-100 transition-opacity"}>
            <MessageFeedback
              message={m.props.model.message}
              messageId={m?.props?.model?.id || m?.props?.model?.sentTime}
              className=" "
              userQuery={userQuery || ""}
              mentoraiData={mentoraiData}
              menteeData={menteeData}
              activeTabUrl={activeTabUrl}
            />
          </div>
        )}

        {/* Speak button - render once outside the loop */}
        {((practiceModeStatus === "PM_ONGOING" || interviewModeStatus === "ONGOING") &&
          source === "sidebar" &&
          isLastMessage &&
          !isLiveMessageStreaming &&
          !loading) && (
            <AnimatePresence mode="wait">
              <SpeakActionButton key="speak-button" />
            </AnimatePresence>
          )}
      </motion.div>
    </>
  );
};

export default MessageContainer;
