import CrownSmallIcon from '../../../assets/crown-small.svg';
import ArrowRightIcon from '../../../assets/arrow-right-line.svg'
import PurchaseSheetButton from './purchase-sheet-button'
import { ChatUsageData } from '../../../context/chat-context/use-chat-conversations'
import { cn } from '../../../../utils/cn'
import { motion, AnimatePresence } from 'framer-motion';
import { useRef, useEffect, useState, useContext } from 'react';
import { ChatContext } from '../../../context/chat-context/chat-context';
import { getUserStatus } from '../../../../utils/subscription-helpers';
import { shouldShowExpandedLimitInfoBanner } from '../../../../utils/subscription-ui-helpers';

type Props = {
    chatUsageData: ChatUsageData
}

const DailyLimitInfo = ({ chatUsageData }: Props) => {
    const hasAnimatedRef = useRef(false);
    const [shouldAnimate, setShouldAnimate] = useState(false);
    const { menteeSubscription } = useContext(ChatContext);
    const userStatus = getUserStatus(menteeSubscription);
    const [shouldShowExpandedBanner, setShouldShowExpandedBanner] = useState(false);
    const { daysRemaining, isTrial, triggerPeriod } = userStatus;

    useEffect(() => {
        const checkShouldShow = async () => {
            const result = await shouldShowExpandedLimitInfoBanner(userStatus);
            setShouldShowExpandedBanner(result);
        }
        checkShouldShow();
    }, [userStatus]);


    useEffect(() => {
        if (shouldShowExpandedBanner && !hasAnimatedRef.current) {
            setShouldAnimate(true);
            hasAnimatedRef.current = true;
        }
    }, [shouldShowExpandedBanner]);

    return (
        <PurchaseSheetButton
            chatUsageData={chatUsageData}
            buttonId="daily-limit-below-chatbox"
            headerType='available-credits'
            bannerType='limited-free-plan'
            disabled={triggerPeriod === "none"}
            className={cn("purchase-subscription-button flex items-center pl-1 py-[5px] rounded-[100px] h-[20px] font-bricolage-grotesque",
                triggerPeriod === 'last_day' ? ' bg-[linear-gradient(88deg,_#411914_21.86%,_#740E16_96.38%)] hover:bg-[linear-gradient(88deg,_#411914_21.86%,_#88111A_59.12%)]' : `${triggerPeriod === 'during' ? ' bg-[linear-gradient(88deg,_#392C11_21.86%,_#724803_96.38%)] hover:bg-[linear-gradient(88deg,_#392C11_21.86%,_#774B03_59.12%)]' : ` bg-[#392C11]  ${triggerPeriod === "none" ? '' : 'hover:bg-[#433314] '}`}`,
                (shouldShowExpandedBanner || triggerPeriod !== "none") ? 'pr-0' : 'pr-2'
            )}
            actionLocation="Paid">
            <img src={CrownSmallIcon} alt='crown-small-icon' className='h-3 w-3 scale-1.04' />
            <span className="text-[11px] leading-[14px] font-[700] tracking-[0.11px] font-manrope text-[#E6BE6E] pl-[2.5px]">
                {triggerPeriod === "none" ?
                    'Unlimited Credits'
                    :
                    (isTrial ? 'Pro Trial' : 'Pro')
                }
            </span>
            <AnimatePresence>
                {shouldShowExpandedBanner && (
                    <motion.span
                        className="text-[11px] flex items-center whitespace-nowrap font-medium leading-normal tracking-[0.11px] font-manrope pt-[1px] text-[#FFFFFF99] pl-[4px] overflow-hidden"
                        initial={shouldAnimate ? { width: 0, opacity: 0 } : { width: "auto", opacity: 1 }}
                        animate={{ width: "auto", opacity: 1 }}
                        exit={{ width: 0, opacity: 0 }}
                        transition={{
                            duration: 0.3,
                            ease: "easeInOut",
                            width: { duration: 0.4, ease: "easeOut" }
                        }}
                    >
                        {isTrial ?
                            triggerPeriod === "last_day" ? 'Ends today' : (triggerPeriod === "during" ? `Ends in ${daysRemaining} days` : `for ${daysRemaining} days 🎉`)
                            : triggerPeriod === "last_day" ? 'Expires today' : (triggerPeriod === "during" ? `Expires in ${daysRemaining} days` : `for ${daysRemaining} days 🎉`)
                        }
                    </motion.span>
                )}
            </AnimatePresence>
            {(shouldShowExpandedBanner || triggerPeriod !== "none") &&
                <img src={ArrowRightIcon} className="" />
            }
        </PurchaseSheetButton>
    )
}

export default DailyLimitInfo