import React from "react";
import MessageContainer from "./message-container";
import "../chat-message-container.css";

const LiveMessageContainer = ({
  source,
  liveMessages,
  userLiveMessage,
  setLiveMessages,
  isLiveMessageStreaming,
  sendMessage,
  mentoraiData,
  menteeData,
  activeTabUrl,
  userMessageWrapperClassName,
  aiMessageWrapperClassName,
}: {
  source: "content" | "sidebar";
  liveMessages: any;
  userLiveMessage: any;
  isLiveMessageStreaming: boolean;
  setLiveMessages: Function;
  sendMessage: Function;
  mentoraiData: any;
  menteeData: any;
  activeTabUrl: string;
  userMessageWrapperClassName?: string;
  aiMessageWrapperClassName?: string;
}) => {
  return (
    <>
      {[...userLiveMessage].map((m, i) => {
        const isLastMessage =
          i === [...userLiveMessage, ...liveMessages].length - 1;
        return (
          <div
            id={
              source === "content"
                ? "content-chat-conversation-live-message"
                : "sidebar-chat-conversation-live-message"
            }
            className={`!my-5 ${
              isLastMessage
                ? source === "sidebar"
                  ? "min-h-[calc(100vh-181px)]"
                  : "min-h-[calc(100vh-420px)]"
                : ""
            }`}
          >
            <MessageContainer
              m={m}
              i={i}
              key={`${m.props.model.message}-${i}`}
              isLastMessage={isLastMessage}
              sendMessage={sendMessage}
              isLiveMessageStreaming={isLiveMessageStreaming}
              setLiveMessages={setLiveMessages}
              mentoraiData={mentoraiData}
              menteeData={menteeData}
              activeTabUrl={activeTabUrl}
              userMessageWrapperClassName={userMessageWrapperClassName}
              aiMessageWrapperClassName={aiMessageWrapperClassName}
              source={source}
            />
          </div>
        );
      })}
      {[...liveMessages].map((m, i) => {
        const isLastMessage = i === [...liveMessages].length - 1;
        return (
          <div
            id={
              source === "content"
                ? "content-chat-conversation-live-message"
                : "sidebar-chat-conversation-live-message"
            }
            className={`${
              isLastMessage
                ? source === "sidebar"
                  ? "min-h-[calc(100vh-220px)]"
                  : "min-h-[calc(100vh-420px)]"
                : ""
            }`}
          >
            <MessageContainer
              m={m}
              i={i}
              key={`${m.props.model.message}-${i}`}
              isLastMessage={isLastMessage}
              sendMessage={sendMessage}
              isLiveMessageStreaming={isLiveMessageStreaming}
              setLiveMessages={setLiveMessages}
              mentoraiData={mentoraiData}
              menteeData={menteeData}
              activeTabUrl={activeTabUrl}
              userMessageWrapperClassName={userMessageWrapperClassName}
              aiMessageWrapperClassName={aiMessageWrapperClassName}
              source={source}
            />
          </div>
        );
      })}
    </>
  );
};

export default LiveMessageContainer;
