import MicIcon from "../../../assets/mic.svg"
import MicIconHover from "../../../assets/mic-hover.svg"
import PauseIcon from "../../../assets/pause.svg?react"
import { cn } from "../../../../utils/cn";
import { useSidepanelSyncContext } from "../../../context/sidepanel-sync-context/sidepanel-sync-context";
import { AnimatePresence, motion } from "framer-motion";
import Tippy from "@tippyjs/react";
import { useState } from "react";

const MicrophoneButton = ({ toggleMicrophone }: { toggleMicrophone: (from: "Easy Action" | "Button" | "Keyboard") => void }) => {
  const { isAudioLive } = useSidepanelSyncContext();
  const [hoverMicrophoneButton, setHoverMicrophoneButton] = useState(false);

  return (
    <Tippy
      visible={hoverMicrophoneButton}
      content={
        <AnimatePresence>
          {(hoverMicrophoneButton) && (
            <motion.span
              initial={{ opacity: 0, y: 5 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: 5 }}
              transition={{ duration: 0.3 }}
              className={"flex items-center h-[23px] bg-[#4B4E63] justify-center text-mentorai-text-white font-manrope text-xs leading-[normal] tracking-[-0.12px] px-1.5 rounded-md"}
            >
              Voice Input
            </motion.span>
          )}
        </AnimatePresence>
      }
    >
      <button onMouseEnter={() => setHoverMicrophoneButton(true)} onMouseLeave={() => setHoverMicrophoneButton(false)} className={cn("", isAudioLive && "bg-[linear-gradient(90deg,_#4E19D2_0%,_#8F5BF4_112.5%)]")} onClick={() => toggleMicrophone("Button")}>
        {
          isAudioLive ? <PauseIcon className="w-[12px] h-[12px] text-mentorai-text-soft" /> : <img alt="mic" src={hoverMicrophoneButton ? MicIconHover : MicIcon} className="w-[24px] h-[24px]" />
        }
      </button>
    </Tippy>
  )
}

export default MicrophoneButton