import { useContext, useEffect, useRef, useState } from 'react';
import MentorAiButton from '../../../common/button/mentorai-button';
import { getUserStatus } from '../../../utils/subscription-helpers';
import { ChatContext } from '../../context/chat-context/chat-context';
import { motion } from 'framer-motion';
import HoverGlass from '../../../src/assets/gif/hourglass.gif';
import { redirectToCheckout } from '../../utils/checkout-redirect';

const PlanExpiredPopup = () => {
    const [show, setShow] = useState(false);
    const { menteeSubscription, chatUsageData } = useContext(ChatContext);
    const userStatus = getUserStatus(menteeSubscription);
    const [hoveredClose, setHoveredClose] = useState(false);
    const isComponentMounted = useRef(false);


    const handleClose = () => {
        chrome.storage.local.set({ 'isExpiredPopupShownAlready': true }).then(() => {
            setShow(false);
        });
    }

    const handleRedirectToCheckout = async () => {
        handleClose();
        await redirectToCheckout({
            location: "Plan Expired Popup",
            menteeSubscription: menteeSubscription
        });
    }

    useEffect(() => {
        chrome.storage.local.get('isExpiredPopupShownAlready').then((result) => {
            if (result && result.isExpiredPopupShownAlready) {
                setShow(false);
            } else {
                setShow(userStatus.isExpired);
            }
        });
    }, [userStatus]);

    useEffect(() => {
        if (isComponentMounted.current) {
            return;
        }
        if (show) {
            chrome.runtime.sendMessage({
                action: "sendAnalytics", url: window.location.href, eventName: "Expiry Popup Shown", eventProperties: {}
            })
        }
        isComponentMounted.current = true;
    }, [show]);


    if (!show) return null;

    return (
        <>
            <div
                onClick={handleClose}
                className={`fixed w-full h-full bottom-0 left-0 bg-[rgba(20,22,31,0.60)] backdrop-blur-[2px] z-10`}
            >
                <span className="invisible">.</span>
            </div>

            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: 20 }}
                transition={{ type: "spring", stiffness: 500, damping: 30 }}
                className="flex flex-col px-1 pb-1 fixed bottom-0 right-0 w-full bg-[#06060B] rounded-t-xl z-10">
                <div className="bg-[linear-gradient(181deg,_rgba(212,91,72,0.60)_1.1%,_rgba(162,47,39,0.60)_13.52%,_rgba(103,25,14,0.60)_24.4%,_rgba(6,6,11,0.60)_39.15%)] 
                rounded-xl p-5 w-full max-h-[80vh] overflow-y-auto border-t border-t-[#363645]">

                    <div className="flex justify-center items-center">
                        <img src={HoverGlass} alt="hover-glass" className="w-[56px] h-[56px] mx-auto" />
                    </div>
                    <MentorAiButton classNames="!cursor-pointer transition-all duration-100 group !w-[28px] !h-[28px] absolute top-2.5 right-2.5"
                        type="outlined"
                        size="small"
                        semiRounded
                        onClick={() => handleClose()}
                        onMouseEnter={() => setHoveredClose(true)}
                        onMouseLeave={() => setHoveredClose(false)}
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16" fill="none">
                            <path d="M8.00004 7.15164L10.97 4.18164L11.8184 5.03004L8.84844 8.00004L11.8184 10.97L10.97 11.8184L8.00004 8.84844L5.03004 11.8184L4.18164 10.97L7.15164 8.00004L4.18164 5.03004L5.03004 4.18164L8.00004 7.15164Z" fill={`${hoveredClose ? "#F2F2F2" : "#DDDDDF"}`} />
                        </svg>
                    </MentorAiButton>

                    <p className="text-white text-[22px] font-bricolage-grotesque leading-[28px] tracking-[-0.88px] font-semibold text-center mt-2">
                        {userStatus.isTrial ? <span>Pro Trial has ended - <br />You’re back on the Free Plan</span> : <span>Pro Plan has ended - <br />You’re back on the Free Plan</span>}
                    </p>
                    <p className=" text-[#94939F] text-[14px] leading-[20px] mt-1 font-manrope font-medium text-center tracking-[-0.14px]">
                        On Free, you only get {chatUsageData?.dailyMessageLimit || 5} credits daily - and lose Interview Mode, Paths, and GPT-5.
                    </p>



                    <MentorAiButton
                        type="primary"
                        size="medium"
                        onClick={handleRedirectToCheckout}
                        classNames="w-full mt-8 text-center font-bricolage-grotesque"
                    >
                        {userStatus.isTrial ? 'Upgrade to Pro' : 'Renew Your Pro'} →
                    </MentorAiButton>
                </div>
            </motion.div>
        </>
    );
};

export default PlanExpiredPopup;

