import ArrowRightLineBlue from "../../../assets/arrow-right-line-blue.svg";
import SlidingCarousel from "../../../components/sliding-carousel/sliding-carousel";
import { MenteeCreatedPathType } from "../../../context/page-context/index.type";
import useOtherActivePaths from "./use-other-active-paths";

type Props = {
  autoRotate?: boolean;
  otherActivePaths: MenteeCreatedPathType[];
};

const OtherActivePaths = ({ autoRotate = true, otherActivePaths }: Props) => {
  const { handlePathClick } = useOtherActivePaths();

  const renderActivePath = (item: MenteeCreatedPathType) => (
    <div
      key={item?.recordId}
      className="group flex gap-3 items-center p-3 border rounded-xl border-[#363645] hover:bg-[#212431] cursor-pointer"
      onClick={() => handlePathClick(item?.recordId, item?.title)}
    >
      <div className="h-[56px] w-[56px] shrink-0">
        <img src={item?.coverImage} alt="continue-latest-path-icon.svg" className="h-[56px] w-[56px] rounded-[10px]" />
      </div>

      <div className="flex-1 min-w-0">
        <p className="font-bricolage-grotesque text-[#DDDDDF] text-[14px] font-medium -tracking-[0.14px] truncate">
          {item?.title}
        </p>
        <div className="mt-2 h-[6px] w-full bg-[#2F3241] rounded-full">
          <div className="h-full bg-[#3EE089] rounded-full" style={{ width: `${item?.completionPercentage}%` }} />
        </div>
        <div className="mt-1.5 flex justify-between items-center">
          <p className="text-[#DDDDDF] text-[12px] font-medium font-manrope">
            {item?.completionPercentage?.toFixed(0)}% complete
          </p>
          <button className="flex gap-[2px] items-center">
            <p className="text-[#736DF2] group-hover:text-[#A5A1F7] text-[12px] font-semibold font-manrope leading-[13px]">
              View Path
            </p>
            <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 14 14" fill="none" className="group-hover:[&>path]:fill-[#A5A1F7]">
              <path
                d="M9.1901 6.47495L6.374 3.65885L7.11635 2.9165L11.1998 6.99995L7.11635 11.0834L6.374 10.3411L9.1901 7.52495H2.7998V6.47495H9.1901Z"
                fill="#736DF2"
                className="transition-colors duration-100"
              />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-4">
      <div className="space-y-1">
        <p className="text-[#F2F2F2] text-[16px] font-medium -tracking-[0.16px] font-bricolage-grotesque">
          Other active paths
        </p>
        <p className="text-[#94939F] text-[12px] leading-[18px] font-medium font-manrope">
          Revisit paths that you haven&apos;t in a while
        </p>
      </div>

      <SlidingCarousel
        data={otherActivePaths || []}
        itemsPerPage={2}
        autoRotate={autoRotate}
        autoRotateInterval={7000}
        renderItem={renderActivePath}
        showNavigation={true}
      />
    </div>
  );
};

export default OtherActivePaths;
