import useNpsFeedbackV2 from "./use-nps-feedback-v2";
import NpsRating from "./components/nps-rating/nps-rating";
import FeedbackForm from "./components/feedback-form/feedback-form";
import LeecoKing from "../../../../src/assets/leeco-king2.svg"


const NpsFeedback = ({ setNpsStatus, npsStatus }: { setNpsStatus: Function, npsStatus: string }) => {
    const {
        getSelectedRatingClassName,
        getDefaultRatingClassName,
        nps,
        setNps,
        setReasons,
        setComment,
        step,
        setStep,
        handleReasonChange,
        handlePostNps,
        submitting,
        reasons,
        removeEmojis,
        handleCancelNps
    } = useNpsFeedbackV2({ setNpsStatus, npsStatus })

    let componentToRender = <></>

    if (step === "rating") {
        componentToRender = <NpsRating nps={nps} handlePostNps={handlePostNps} setNps={setNps} setStep={setStep} getSelectedRatingClassName={getSelectedRatingClassName} getDefaultRatingClassName={getDefaultRatingClassName} setReasons={setReasons} setComment={setComment} submitting={submitting} handleCancelNps={handleCancelNps} />
    }
    else {
        componentToRender = <FeedbackForm nps={nps} setNpsStatus={setNpsStatus} reasons={reasons} setStep={setStep} handleReasonChange={handleReasonChange} handlePostNps={handlePostNps} removeEmojis={removeEmojis} />
    }

    return (
        <>
            <div
                onClick={handleCancelNps}
                className={`fixed w-full h-full bottom-0 left-0 bg-[rgba(20,22,31,0.60)] backdrop-blur-[2px]`}
            >
                <span className="invisible">.</span>
            </div>
            <div className="flex flex-col px-[4px] pb-[4px] absolute bottom-0 left-0 right-0 w-full bg-black rounded-t-xl">
                <div className="flex flex-col items-start w-full bg-mentorai-bg-black border-y border-y-[#45475F] rounded-xl p-4">
                    <div className="flex flex-col gap-2 w-full">
                        <img alt='leeco-king' src={LeecoKing} className='w-[64px] h-[64px]' />
                        <h1 className="text-mentorai-text-white text-[20px] leading-[28px] font-medium tracking-[-0.2px] font-bricolage-grotesque">Thanks for being a regular! <br /> One quick question:</h1>
                        <div className="w-full h-px bg-[#FFFFFF33] mt-3 mb-5"><span className="invisible">.</span></div>
                    </div>
                    {componentToRender}
                </div>
            </div>
        </>
    );
};

export default NpsFeedback;
