import { useEffect, useCallback, useRef, useContext } from "react";
import { useSidepanelSyncContext } from "../context/sidepanel-sync-context/sidepanel-sync-context";
import { getBrowserInfo } from "../../core/Analytics";
import { PageContext } from "../context/page-context/page-context";

interface UseKeyboardShortcutsProps {
    startRecording: () => void;
    stopRecording: (wasCancelled: boolean) => void;
    recorderControls: any;
}

const useKeyboardShortcuts = ({
    startRecording,
    stopRecording,
    recorderControls,
}: UseKeyboardShortcutsProps) => {
    const {activeTabUrl}=useContext(PageContext)
    const { isAudioLive, setIsAudioLive } = useSidepanelSyncContext();
    const triggerKey = getBrowserInfo()?.os_family?.includes("Windows") ? "Alt" : "Control";
    
    const keyHoldTimeoutRef = useRef<NodeJS.Timeout | null>(null);
    const isKeyHeldRef = useRef(false);

    const cleanup = useCallback(() => {
        if (keyHoldTimeoutRef.current) {
            clearTimeout(keyHoldTimeoutRef.current);
            keyHoldTimeoutRef.current = null;
        }
        isKeyHeldRef.current = false;
    }, []);

    const stopRecordingAndCleanup = useCallback((cancelled: boolean) => {
        stopRecording(cancelled);
        recorderControls.stopRecording();
        setIsAudioLive(false);
        cleanup();
    }, [stopRecording, recorderControls, setIsAudioLive, cleanup]);

    const checkMicrophonePermission = useCallback(async () => {
        try {
            const permission = await navigator.permissions.query({ name: 'microphone' as PermissionName });
            if (permission.state !== "granted") {
                const activeTab = await chrome.tabs.query({ active: true, currentWindow: true });
                chrome.tabs.create({
                    url: `${window.location.href}?action=microphone-permission&originalTabId=${activeTab[0].id}`,
                    active: true
                });
                return false;
            }
            return true;
        } catch {
            return false;
        }
    }, []);

    const handleVisibilityChange = useCallback(() => {
        if (document.hidden && isAudioLive) {
            stopRecordingAndCleanup(true);
        }
    }, [isAudioLive, stopRecordingAndCleanup]);

    const handleWindowBlur = useCallback(() => {
        // Reset key state when window loses focus (e.g., Alt+Tab)
        if ((isKeyHeldRef.current || isAudioLive) && document.hidden) {
            if (isAudioLive) {
                stopRecordingAndCleanup(true);
            } else {
                cleanup();
            }
        }
    }, [isAudioLive, stopRecordingAndCleanup, cleanup]);

    const handleWindowFocus = useCallback(() => {
        // Ensure clean state when window regains focus
        if (document.hidden) {
            cleanup();
        }
    }, [cleanup]);

    const handleKeyDown = useCallback((event: KeyboardEvent) => {
        // Handle key combinations (cancel recording)
        if (isKeyHeldRef.current && event.key !== triggerKey) {
            if (isAudioLive) stopRecordingAndCleanup(true);
            else cleanup();
            return;
        }
        
        // If recording is active and any other key is pressed, stop recording
        if (isAudioLive && event.key !== triggerKey) {
            stopRecordingAndCleanup(true);
            return;
        }
        
        // Only handle our trigger key
        if (event.key !== triggerKey || isAudioLive || isKeyHeldRef.current) return;
        
        // Ignore if other modifiers are pressed (indicating shortcuts)
        const hasOtherModifiers = event.shiftKey || event.metaKey || 
            (event.altKey && event.key !== "Alt") || 
            (event.ctrlKey && event.key !== "Control");
        
        if (hasOtherModifiers) return;
        
        event.preventDefault();
        event.stopPropagation();
        
        isKeyHeldRef.current = true;
        
        // Delay to prevent accidental triggers
        keyHoldTimeoutRef.current = setTimeout(async () => {
            if (isKeyHeldRef.current && !isAudioLive) {
                const hasPermission = await checkMicrophonePermission();
                if (hasPermission) {
                    startRecording();
                    recorderControls.startRecording();
                    setIsAudioLive(true);
                    chrome.runtime.sendMessage({ action: "sendAnalytics", url: activeTabUrl, eventName: 'MentorAi Voice-to-Text Used', eventProperties: {
                        triggered_by: "Keyboard",
                        trigger_in:"Inside Sidebar"
                    } })
                }
            }
        }, 300);
        
    }, [triggerKey, isAudioLive, startRecording, recorderControls, setIsAudioLive, stopRecordingAndCleanup, cleanup, checkMicrophonePermission]);

    const handleKeyUp = useCallback((event: KeyboardEvent) => {
        if (event.key !== triggerKey) return;
        
        isKeyHeldRef.current = false;
        
        // Clear timeout if key released before delay
        if (keyHoldTimeoutRef.current) {
            clearTimeout(keyHoldTimeoutRef.current);
            keyHoldTimeoutRef.current = null;
        }
        
        // Stop recording if active
        if (isAudioLive) {
            stopRecording(false);
            recorderControls.stopRecording();
        }
    }, [triggerKey, isAudioLive, stopRecording, recorderControls, setIsAudioLive]);

    useEffect(() => {
        // Add event listeners
        document.addEventListener("keydown", handleKeyDown);
        document.addEventListener("keyup", handleKeyUp);
        document.addEventListener("visibilitychange", handleVisibilityChange);
        window.addEventListener("blur", handleWindowBlur);
        window.addEventListener("focus", handleWindowFocus);

        // Cleanup function
        return () => {
            document.removeEventListener("keydown", handleKeyDown);
            document.removeEventListener("keyup", handleKeyUp);
            document.removeEventListener("visibilitychange", handleVisibilityChange);
            window.removeEventListener("blur", handleWindowBlur);
            window.removeEventListener("focus", handleWindowFocus);
            cleanup();
        };
    }, [handleKeyDown, handleKeyUp, handleVisibilityChange, handleWindowBlur, handleWindowFocus, cleanup]);
};

export default useKeyboardShortcuts;
