import Awful from "../../../assets/emoji-awful2.svg"
import Bad from "../../../assets/emoji-bad2.svg"
import Okay from "../../../assets/emoji-okay2.svg"
import Good from "../../../assets/emoji-good2.svg"
import Great from "../../../assets/emoji-great2.svg"
import { useEffect, useState } from "react"
import { useContext } from "react"
import { PageContext } from "../../../context/page-context/page-context"
import { MenteeContext } from "../../../context/mentee-context/mentee-context"
import { MentorAiContext } from "../../../context/mentorai-context/mentorai-context"
import { extractQuestionDifficulty } from "../../../utils/side-panel-helper"
import { estimatedTimeMapping } from "../../../constant"
const usePracticeFeedbackPopup = (chatMessages: any[]) => {
  const [feedback, setFeedback] = useState<string>("")
  const { activeTabUrl, interviewCount, scrapedData, timer, practiceModeStatus, practiceCount } =
    useContext(PageContext)
  const { menteeData } = useContext(MenteeContext)
  const { mentoraiData } = useContext(MentorAiContext)
  const [selectedRatingAndOption, setSelectedRatingAndOption] = useState<any>({
    rating: null,
    options: null,
  })
  const [ratingSelected, setRatingSelected] = useState<boolean>(false)
  const [feedbackSubmitted, setFeedbackSubmitted] = useState<boolean>(false)
  const [isLoading, setIsLoading] = useState<boolean>(true)
  const questionDifficulty = extractQuestionDifficulty(scrapedData)
  const estimatedTime =
    estimatedTimeMapping[
    questionDifficulty as keyof typeof estimatedTimeMapping
    ]


  const isSentMessagesLessThanFiveInPracticeMode = chatMessages.length < 11;

  const handleSelectRating = (rating: string) => {
    setRatingSelected(true)
  }

  const handleSubmitFeedback = (rating: string) => {
    setFeedbackSubmitted(true)
    chrome.runtime.sendMessage({
      action: "sendAnalytics",
      url: activeTabUrl,
      eventName: "MentorAi Practice Mode Feedback Submitted",
      eventProperties: {
        reaction: rating,
        comments: feedback,
        practice_mode_version: 'beta',
      },
    })
  }

  const ratingValues = [
    {
      id: 1,
      rating: "Awful",
      emoji: Awful,
      options: [
        "Doesn't align with your goals",
        "Hard to follow",
        "Too detailed, overwhelming",
        "Lacks clarity, focus",
        "Feels visually cluttered",
        "Needs more practical steps",
      ],
      text: "I'm sorry! What are the issues? (Optional)",
    },
    {
      id: 2,
      rating: "Bad",
      emoji: Bad,
      options: [
        "Doesn't align with your goals",
        "Hard to follow",
        "Too detailed, overwhelming",
        "Lacks clarity, focus",
        "Feels visually cluttered",
        "Needs more practical steps",
      ],
      text: "I'm sorry! What are the issues? (Optional)",
    },
    {
      id: 3,
      rating: "Okay",
      emoji: Okay,
      options: [
        "Align better with your goals",
        "Include more skills",
        "Focus on fewer skills",
        "Explain roadmap better",
        "Simplify the roadmap",
        "Improve visual layout",
        "Suggest more practical steps",
      ],
      text: "I see! What could I improve? (Optional)",
    },
    {
      id: 4,
      rating: "Good",
      emoji: Good,
      options: [
        "Align better with your goals",
        "Include more skills",
        "Focus on fewer skills",
        "Explain roadmap better",
        "Simplify the roadmap",
        "Improve visual layout",
        "Suggest more practical steps",
      ],
      text: "I see! What could I improve? (Optional)",
    },
    {
      id: 5,
      rating: "Great",
      emoji: Great,
      options: [
        "Aligns with your goals",
        " Clearly Structured",
        " Covers everything you need",
        " Easy to follow",
        " Good visual layout",
      ],
      text: "I'm glad! What stood out to you? (Optional)",
    },
  ]

  const generatePracticeFeedback = async () => {
    const { practiceModeFeedbackGenerating } = await chrome.storage.local.get("practiceModeFeedbackGenerating")
    if (practiceModeFeedbackGenerating) {
      setIsLoading(true)
      return
    }
    const payload = {
      user_id: menteeData?.recordId,
      mentor_ai_id: mentoraiData?.recordId,
      page_context: {
        url: activeTabUrl,
        content: scrapedData,
      },
      messages: chatMessages.map((msg: any) => ({
        role: msg.props.model.sender,
        content: msg.props.model.message,
      })),
      practice_count: practiceCount || 1,
      time_taken: estimatedTime - timer,
      estimated_time: estimatedTime,
      candidate_data: menteeData,
      session_type: "Practice Mode",
    }

    try {
      // Use a Promise to wait for the complete response from the background script
      const response: any = await new Promise((resolve, reject) => {
        chrome.runtime.sendMessage(
          {
            action: "generate-practice-feedback",
            url: "/extension/generate-feedback",
            payload: payload,
            waitForCompletion: true,
            activeTabUrl: activeTabUrl,
          },
          (response) => {
            if (chrome.runtime.lastError) {
              reject(chrome.runtime.lastError);
            } else {
              resolve(response);
              chrome.runtime.sendMessage({
                action: "sendAnalytics",
                url: activeTabUrl,
                eventName: "MentorAi Practice Mode Report Generated",
                eventProperties: {
                  practice_mode_version: 'beta',
                },
              })
            }
          }
        );
      });

      // Check if the response indicates an error
      if (response && response.error) {
        throw new Error(response.error);
      }
    } catch (error) {
      console.error("[ERROR] Failed to generate feedback:", error);
      chrome.runtime.sendMessage({
        action: "sendAnalytics",
        url: activeTabUrl,
        eventName: "MentorAi Practice Mode Report Generation Failed",
        eventProperties: {
          practice_mode_version: 'beta',
        },
      })
    } finally {
      setIsLoading(false);
      chrome.storage.local.set({
        practiceModeFeedbackGenerating: false,
      });
    }
  }

  useEffect(() => {
    if (practiceModeStatus === "PM_FEEDBACK" && !isSentMessagesLessThanFiveInPracticeMode) {
      generatePracticeFeedback()
    } else {
      setIsLoading(false)
    }
  }, [practiceModeStatus])


  useEffect(() => {
    chrome.storage.local.onChanged.addListener((changes) => {
      if (changes.practiceModeFeedbackGenerating) {
        if (changes.practiceModeFeedbackGenerating.newValue) {
          setIsLoading(true)
        } else {
          setIsLoading(false)
        }
      }
    })
  }, [])

  return {
    ratingValues,
    selectedRatingAndOption,
    setSelectedRatingAndOption,
    ratingSelected,
    handleSelectRating,
    feedbackSubmitted,
    handleSubmitFeedback,
    isLoading,
    feedback,
    setFeedback,
    isSentMessagesLessThanFiveInPracticeMode
  }
}

export default usePracticeFeedbackPopup
