/**
 * Generate appropriate text variants based on user subscription status and trigger periods
 */

import { getTodaysMessageCount } from './helper';
import { UserStatus } from './subscription-helpers';

/**
 * Generate daily credits left limit text variants
 */
export const getDailyCreditsText = (userStatus: UserStatus): string => {
  const { isCancelled, isTrial, isPaid, triggerPeriod } = userStatus;

  // Non-cancelled trial/paid users
  if (!isCancelled && (isTrial || isPaid)) {
    return "unlimited_credits_non_cancelled";
  }

  // Only cancelled users see changes
  if (!isCancelled) return "";

  // Before trigger period
  if (triggerPeriod === 'before') {
    if (isTrial) {
      return "trial_before_trigger";
    } else if (isPaid) {
      return "paid_before_trigger";
    }
  }

  // During trigger period
  if (triggerPeriod === 'during') {
    if (isTrial) {
      return "trial_during_trigger";
    } else if (isPaid) {
      return "paid_during_trigger";
    }
  }

  // Last day
  if (triggerPeriod === 'last_day') {
    if (isTrial) {
      return "trial_last_day";
    } else if (isPaid) {
      return "paid_last_day";
    }
  }

  return "";
};

/**
 * Generate profile icon text variants
 * Always shows days remaining for cancelled plans
 */
export const getProfileIconText = (userStatus: UserStatus): string => {
  const { triggerPeriod } = userStatus;

  if (triggerPeriod === 'last_day') {
    return "paid_last_days";
  } else if (triggerPeriod === 'during') {
    return "paid_during_days";
  } else {
    return "paid_left_days";
  }
};

/**
 * Generate pricing sheet banner text variants
 */
export const getPricingSheetBannerText = (userStatus: UserStatus): string => {
  const { isCancelled, isTrial, isPaid, triggerPeriod } = userStatus;

  // Non-cancelled users see no change
  if (!isCancelled) return "";


  // Last day
  if (triggerPeriod === 'last_day') {
    if (isTrial) {
      return "pricing_trial_last_day";
    } else if (isPaid) {
      return "pricing_paid_last_day";
    }
  }

  // During trigger period
  if (triggerPeriod === 'during') {
    if (isTrial) {
      return "pricing_trial_during_trigger";
    } else if (isPaid) {
      return "pricing_paid_during_trigger";
    }
  }


  // Before trigger period
  if (triggerPeriod === 'before') {
    if (isTrial) {
      return "pricing_trial_before_trigger";
    } else if (isPaid) {
      return "pricing_paid_before_trigger";
    }
  }

  return "";
};

