/**
 * Generate soft trigger text variants (shown on first message of the day)
 */
export const getSoftTriggerText = (userStatus: UserStatus): string => {
  const { isCancelled, isTrial, isPaid, triggerPeriod } = userStatus;

  // Only cancelled users see soft triggers
  if (!isCancelled) return "";

  // Before trigger period - no soft trigger
  if (triggerPeriod === 'before') return "";

  // During trigger period
  if (triggerPeriod === 'during') {
    if (isTrial) {
      return "soft_trigger_trial_during";
    } else if (isPaid) {
      return "soft_trigger_paid_during";
    }
  }

  // Last day
  if (triggerPeriod === 'last_day') {
    if (isTrial) {
      return "soft_trigger_trial_last_day";
    } else if (isPaid) {
      return "soft_trigger_paid_last_day";
    }
  }

  return "";
};

/**
 * Generate input box banner text variants (shown on third message of the day)
 */
export const getInputBoxBannerText = (userStatus: UserStatus): string => {
  const { isCancelled, isTrial, isPaid, triggerPeriod } = userStatus;

  // Only cancelled users see banners
  if (!isCancelled) return "";

  // Before trigger period - no banner
  if (triggerPeriod === 'before') return "";

  // During trigger period
  if (triggerPeriod === 'during') {
    if (isTrial) {
      return "input_banner_trial_during";
    } else if (isPaid) {
      return "input_banner_paid_during";
    }
  }

  // Last day
  if (triggerPeriod === 'last_day') {
    if (isTrial) {
      return "input_banner_trial_last_day";
    } else if (isPaid) {
      return "input_banner_paid_last_day";
    }
  }

  return "";
};

/**
 * Generate expired plan popup text variants
 */
export const getExpiredPlanPopupText = (userStatus: UserStatus): string => {
  const { isTrial, isPaid, isExpired } = userStatus;

  if (!isExpired) return '';

  if (isTrial) {
    return "expired_popup_trial";
  } else if (isPaid) {
    return "expired_popup_paid";
  }

  return "";
};

/**
 * Check if soft trigger should be shown (first message of the day)
 */
export const shouldShowCancelledSoftTrigger = async (userStatus: UserStatus): Promise<boolean> => {
  const count = await getTodaysMessageCount();
  return userStatus.isCancelled && count === 1 && (userStatus.triggerPeriod === 'during' || userStatus.triggerPeriod === 'last_day');
};

/**
 * Check if input box banner should be shown (third message of the day)
 */
export const shouldShowInputBoxBanner = async (userStatus: UserStatus): Promise<boolean> => {
  const count = await getTodaysMessageCount();
  return userStatus.isCancelled && count >= 3 && (userStatus.triggerPeriod === 'during' || userStatus.triggerPeriod === 'last_day');
};


export const shouldShowExpandedLimitInfoBanner = async (userStatus: UserStatus): Promise<boolean> => {
  const count = await getTodaysMessageCount();
  return userStatus.isCancelled && count >= 3 && (userStatus.triggerPeriod === 'before' || userStatus.triggerPeriod === 'during' || userStatus.triggerPeriod === 'last_day');
};

/**
 * Get all UI text variants for a user status
 */
export const getAllUITextVariants = async (userStatus: UserStatus) => {
  return {
    dailyCredits: getDailyCreditsText(userStatus),
    profileIcon: getProfileIconText(userStatus),
    pricingSheetBanner: getPricingSheetBannerText(userStatus),
    pricingSheetTitle: getPricingSheetTitleText(userStatus),
    pricingSheetButton: getPricingSheetButtonText(userStatus),
    softTrigger: getSoftTriggerText(userStatus),
    inputBoxBanner: getInputBoxBannerText(userStatus),
    expiredPlanPopup: getExpiredPlanPopupText(userStatus),
    shouldShowCancelledSoftTrigger: await shouldShowCancelledSoftTrigger(userStatus),
    shouldShowInputBoxBanner: await shouldShowInputBoxBanner(userStatus),
    shouldShowExpandedLimitInfoBanner: await shouldShowExpandedLimitInfoBanner(userStatus),
  };
};
