import { useEffect, useMemo, useState } from "react";
import { getTitleSlug, getCurrentExtensionUsedDaysCount } from "../../../utils/helper";
import { extractQuestionDifficulty } from "../../utils/side-panel-helper";
import { estimatedTimeMapping } from "../../constant";
import { handleAibackendGet } from "../../../core/Axios";
import { Mentee, SCREEN } from "../../types/type";
import checkValidSubscription from "../../../utils/check-valid-subscription";
import { normalizeUrlForAnalytics } from "../../background/tabUpdated";
import { InterviewModeStatus, PracticeModeStatus, CompanyPathType, MenteeCreatedPathType } from "./index.type";
import { safeIncrementPracticeCount, validatePracticeCount } from "../../../utils/practice-count-utils";

const usePage = (menteeSubscription: any) => {
  const [activeTabUrl, setActiveTabUrl] = useState("");
  const [isReadingPageContent, setIsReadingPageContent] = useState(false);
  const [triggerShowShareExtension, setTriggerShowShareExtension] = useState(false);
  const [interviewModeStatus, setInterviewModeStatus] = useState<InterviewModeStatus>("IDLE");
  const [practiceModeStatus, setPracticeModeStatus] = useState<PracticeModeStatus>("PM_IDLE");
  const [practiceCount, setPracticeCount] = useState(0);
  const [interviewCount, setInterviewCount] = useState(0);
  const [timer, setTimer] = useState(0);
  const [scrapedData, setScrapedData] = useState(null);
  const [intervalId, setIntervalId] = useState<NodeJS.Timeout | null>(null);
  const [isInterviewModeEnabled, setIsInterviewModeEnabled] = useState(false);
  const [menteeData, setMenteeData] = useState<Mentee | null>(null);
  const [showSignupModal, setShowSignupModal] = useState(false);
  const [extensionUsedDaysCount, setExtensionUsedDaysCount] = useState(0);
  const [selectedText, setSelectedText] = useState("");
  const [showPracticeModeWelcomeScreen, setShowPracticeModeWelcomeScreen] = useState(false);
  const [screen, setScreen] = useState<SCREEN>("LOADING");
  const [pathsData, setPathsData] = useState<CompanyPathType[]>([]);
  const [menteeCreatedPathsData, setMenteeCreatedPathsData] = useState<MenteeCreatedPathType[]>([]);

  const incrementInterviewCount = () => {
    setInterviewCount((prev) => prev + 1);
    chrome.storage.local.set({ interviewCount: interviewCount + 1 });
  };

  const incrementPracticeCount = async () => {
    await safeIncrementPracticeCount(practiceCount, setPracticeCount);
  };

  const startTimer = (resume?: any, lastTime?: any) => {
    // First, make sure to clear any existing intervals
    stopTimer();

    const questionDifficulty = extractQuestionDifficulty(scrapedData || "");

    const estimatedTime = estimatedTimeMapping[questionDifficulty as keyof typeof estimatedTimeMapping];

    // Initialize timer with estimated time if it's zero
    if (!resume) {
      setTimer(estimatedTime);
      chrome.storage.local.set({ timer: estimatedTime });
    } else {
      setTimer(lastTime);
    }

    const interval = setInterval(() => {
      setTimer((prevTimer) => {
        const newValue = prevTimer - 1;
        chrome.storage.local.set({ timer: newValue });
        return newValue;
      });
    }, 1000);

    // Store the interval ID in component state instead of Chrome storage
    setIntervalId(interval);
  };

  const stopTimer = () => {
    if (intervalId) {
      clearInterval(intervalId);
      setIntervalId(null);
    }
    // Still clear any interval that might be in storage (for backward compatibility)
    chrome.storage.local.get(["timerInterval"], (result) => {
      if (result.timerInterval) {
        clearInterval(result.timerInterval);
        chrome.storage.local.remove("timerInterval");
      }
    });
  };

  const resetTimer = () => {
    stopTimer();
    setTimer(0);
    chrome.storage.local.set({ timer: 0 });
  };

  const getCompanyPathsData = async () => {
    const response = await fetch(
      `${import.meta.env.VITE_PREPLACED_DASHBOARD_API_URL}/configuration/get?config=company-learning-paths`,
      {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
        },
      },
    );
    const data = await response?.json();
    if (data?.learningPaths) {
      const mappedPathsData = data?.learningPaths?.map((item: any) => {
        return {
          learners: item?.learners || 0,
          companyLogo: item?.companyLogo || "",
          pathUrl: item?.pathUrl || "",
          title: item?.title || "",
          trending: item?.trending || false,
          questions: item?.questions || 0,
        };
      });
      setPathsData(mappedPathsData);
    }
  };

  useEffect(() => {
    getCompanyPathsData();
  }, []);

  const getUserAllLearningPaths = async () => {
    if (!menteeData?.recordId) return;
    try {
      const response = await handleAibackendGet("/leeco/learning-paths/v3", {
        user_id: menteeData.recordId,
      });
      // console.log("response", response);

      if (response?.data?.length > 0) {
        const mappedPathsData = response?.data?.map((item: any) => {
          return {
            recordId: item?.recordId,
            title: item?.title || "",
            publicId: item?.publicId || "",
            coverImage: item?.coverImage || "",
            completionPercentage: item?.completionPercentage || 0,
            nextLessonIndex: item?.nextLessonIndex || "",
            topics: item?.topics || [],
          };
        });
        setMenteeCreatedPathsData(mappedPathsData);
      }
    } catch (error) {
      console.error("Error in getting user all learning paths:", error);
    }
  };

  const getUserRecommendedPaths = async () => {
    if (!menteeData?.recordId) return;
    try {
      const response = await handleAibackendGet("/leeco/learning-paths-templates/user/recommended", {
        user_id: menteeData.recordId,
        limit: 10,
      });
      // console.log("response", response);
    } catch (error) {
      console.error("Error in getting user recommended paths:", error);
    }
  };

  useEffect(() => {
    getUserAllLearningPaths();
    // getUserRecommendedPaths();
  }, [menteeData]);

  const pageContextValue = useMemo(
    () => ({
      activeTabUrl,
      setActiveTabUrl,
      isReadingPageContent,
      setIsReadingPageContent,
      triggerShowShareExtension,
      setTriggerShowShareExtension,
      interviewModeStatus,
      setInterviewModeStatus,
      practiceModeStatus,
      setPracticeModeStatus,
      incrementPracticeCount,
      interviewCount,
      incrementInterviewCount,
      timer,
      startTimer,
      stopTimer,
      resetTimer,
      scrapedData,
      isInterviewModeEnabled,
      setIsInterviewModeEnabled,
      showSignupModal,
      setShowSignupModal,
      extensionUsedDaysCount,
      setExtensionUsedDaysCount,
      selectedText,
      setSelectedText,
      showPracticeModeWelcomeScreen,
      setShowPracticeModeWelcomeScreen,
      practiceCount,
      setPracticeCount,
      screen,
      setScreen,
      pathsData,
      menteeCreatedPathsData,
    }),
    [
      activeTabUrl,
      isReadingPageContent,
      triggerShowShareExtension,
      interviewModeStatus,
      practiceModeStatus,
      interviewCount,
      timer,
      scrapedData,
      isInterviewModeEnabled,
      showSignupModal,
      extensionUsedDaysCount,
      selectedText,
      showPracticeModeWelcomeScreen,
      practiceCount,
      screen,
      setScreen,
      pathsData,
      menteeCreatedPathsData,
    ],
  );

  const handleFetchQuestionData = async () => {
    const questionData = await chrome.storage.local.get("question_data");
    const isSameQuestion =
      getTitleSlug(activeTabUrl) === questionData?.question_data?.title?.replaceAll(" ", "-")?.toLowerCase();
    if (activeTabUrl.includes("leetcode.com") && (!questionData || !questionData?.question_data || !isSameQuestion)) {
      chrome.runtime.sendMessage({
        action: "fetchQuestionData",
        titleSlug: getTitleSlug(activeTabUrl),
      });
    }
  };
  useEffect(() => {
    handleFetchQuestionData();
  }, [activeTabUrl]);

  const fetchScrapedData = async (result: any) => {
    const activeTab = (await chrome.tabs.query({ active: true, currentWindow: true }))[0];
    const scrapedData = (
      await chrome.tabs.sendMessage(activeTab?.id || 0, {
        action: "scrapeCurrentPageContent",
      })
    )?.scraped_data;
    setScrapedData(scrapedData);
    return scrapedData;
  };

  useEffect(() => {
    chrome.storage.local.get(
      [
        "interviewCount",
        "timer",
        "interviewModeStatus",
        "extensionUsedDaysCount",
        "practiceCount",
        "practiceModeStatus",
      ],
      async (result) => {
        setInterviewCount(result.interviewCount || 0);
        setInterviewModeStatus(result.interviewModeStatus || "IDLE");
        setPracticeCount(validatePracticeCount(result.practiceCount));
        setPracticeModeStatus(result.practiceModeStatus || "PM_IDLE");
        setTimer(result.timer || 0);
        setExtensionUsedDaysCount(await getCurrentExtensionUsedDaysCount());
        await fetchScrapedData(result);
        if (result.interviewModeStatus === "ONGOING") {
          setTimeout(() => {
            startTimer(true, result.timer);
          }, 2000);
        }
      },
    );
    chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
      async function handleStartInterviewModeInSidePanel() {
        setInterviewModeStatus("PREVIEW");
        const tabs = await chrome.tabs.query({ active: true, currentWindow: true });
        const tabId = tabs[0]?.id;
        chrome.storage.local.set({
          interviewModeStatus: "PREVIEW",
          interviewModeStartedUrl: activeTabUrl,
          interviewModeTabId: tabId,
        });
      }
      if (message.action === "startInterviewModeInSidePanel") {
        setScreen("CHAT");
        handleStartInterviewModeInSidePanel();
      }

      if (message.action === "startPracticeModeInSidePanel") {
        chrome.storage.local.get("isPracticeModeWelcomeScreenShown", async (result) => {
          if (!result.isPracticeModeWelcomeScreenShown) {
            setScreen("CHAT");
            setShowPracticeModeWelcomeScreen(true);
          } else {
            async function handleStartPracticeModeInSidePanel() {
              if (["ONGOING", "FEEDBACK", "FEEDBACK_GENERATED"].includes(interviewModeStatus)) {
                setInterviewModeStatus("IDLE");
                chrome.storage.local.set({
                  interviewModeStatus: "IDLE",
                });
                setInterviewModeStatus("IDLE");
              }

              setScreen("CHAT");
              setPracticeModeStatus("PM_PREVIEW");
              const tabs = await chrome.tabs.query({ active: true, currentWindow: true });
              const tabId = tabs[0]?.id;
              chrome.storage.local.set({
                practiceModeStatus: "PM_PREVIEW",
                practiceModeStartedUrl: activeTabUrl,
                practiceModeTabId: tabId,
              });
            }
            handleStartPracticeModeInSidePanel();
          }
        });
      }
    });

    // Clean up timer when component unmounts
    return () => {
      stopTimer();
      chrome.runtime.onMessage.removeListener((message, sender, sendResponse) => {
        if (message.action === "startInterviewModeInSidePanel") {
          setInterviewModeStatus("PREVIEW");
        }
        if (message.action === "startPracticeModeInSidePanel") {
          setPracticeModeStatus("PM_PREVIEW");
        }
      });
    };
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      const result = await chrome.storage.local.get(["menteeData"]);
      if (result.menteeData) {
        setMenteeData(result.menteeData);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    const handleEnableInterviewMode = async () => {
      if (!menteeData?.recordId) return;
      try {
        const referralResponse = await handleAibackendGet("/extension/interview-mode-referrals", {
          candidate_id: menteeData.recordId,
        });

        const isPaidUser = checkValidSubscription(menteeSubscription);
        // remove true for restricting interview mode for free users
        const shouldEnableInterviewMode =
          true ||
          referralResponse?.data?.count > 0 ||
          menteeData?.interviewModeBetaAccess ||
          isPaidUser ||
          menteeData?.email?.endsWith("preplaced.in");
        if (shouldEnableInterviewMode) {
          chrome.storage.local.set({ isInterviewModeEnabled: true });
          setIsInterviewModeEnabled(true);
        }
      } catch (error) {
        console.error("Error in handleEnableInterviewMode:", error);
      }
    };
    handleEnableInterviewMode();
    const checkTrialScreen = async () => {
      const { show_trial_screen } = await chrome.storage.local.get(["show_trial_screen"]);
      console.log('show_trial_screen', show_trial_screen)
      if (!menteeSubscription && show_trial_screen === "true") {
        setScreen("FREE_TRIAL");
      } else if ((!menteeSubscription.subscriptions || menteeSubscription.subscriptions.length === 0) && show_trial_screen === "true") {
        setScreen("FREE_TRIAL");
      }
    };

    if (menteeSubscription !== undefined) {
      checkTrialScreen();
    }
  }, [menteeData, menteeSubscription]);

  useEffect(() => {
    chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
      if (message.action === "showSignupModalInSidePanel") {
        setShowSignupModal(true);
      }
    });
    return () => {
      chrome.runtime.onMessage.removeListener((message, sender, sendResponse) => {
        if (message.action === "showSignupModalInSidePanel") {
          setShowSignupModal(false);
        }
      });
    };
  }, []);

  // Listen for storage changes to sync practice count and mode status
  useEffect(() => {
    const handleStorageChange = (changes: { [key: string]: chrome.storage.StorageChange }) => {
      if (changes.practiceCount) {
        setPracticeCount(validatePracticeCount(changes.practiceCount.newValue));
      }
      if (changes.practiceModeStatus) {
        setPracticeModeStatus(changes.practiceModeStatus.newValue || "PM_IDLE");
      }
    };

    chrome.storage.onChanged.addListener(handleStorageChange);
    return () => {
      chrome.storage.onChanged.removeListener(handleStorageChange);
    };
  }, []);

  return {
    pageContextValue,
    activeTabUrl,
    setActiveTabUrl,
    triggerShowShareExtension,
    setTriggerShowShareExtension,
    interviewModeStatus,
    practiceModeStatus,
    setPracticeModeStatus,
    interviewCount,
    timer,
    startTimer,
    stopTimer,
    resetTimer,
    isInterviewModeEnabled,
    setIsInterviewModeEnabled,
    showSignupModal,
    setShowSignupModal,
    extensionUsedDaysCount,
    showPracticeModeWelcomeScreen,
    setShowPracticeModeWelcomeScreen,
    practiceCount,
    setPracticeCount,
    screen,
    setScreen,
    pathsData,
    menteeCreatedPathsData,
  };
};

export default usePage;
