import { MenteeCreatedPathType } from "../../../context/page-context/index.type";
import { useContext } from "react";
import { PageContext } from "../../../context/page-context/page-context";

const useContinueLatestPath = ({latestPath}: {latestPath: MenteeCreatedPathType}) => {
	const { activeTabUrl } = useContext(PageContext);

  const nextTopicIndex = Number(latestPath?.nextLessonIndex?.split("")?.[0]);
  const nextSubTopicIndex = Number(latestPath?.nextLessonIndex?.split("")?.[1]);
  const nextLessonIndex = Number(latestPath?.nextLessonIndex?.split("")?.[2]);

  const nextTopic = latestPath?.topics?.[nextTopicIndex];
  const nextSubTopic = nextTopic?.subTopics?.[nextSubTopicIndex];
  const nextLesson = nextSubTopic?.lessons?.[nextLessonIndex];

  const handlePathClick = async (recordId: string) => {
    chrome.runtime.sendMessage({
      action: "sendAnalytics",
      url: activeTabUrl,
      eventName: "Path Clicked",
      eventProperties: {
        tab: "Paths",
        type: "latest",
        path: latestPath?.title,
      }
    });
    
    await chrome.tabs.create({
      url: `${import.meta.env.VITE_LEECO_WEB_URL}/learn/${recordId}`,
      active: true,
    });
  };

  const handleStartLesson = async (recordId: string) => {
    chrome.runtime.sendMessage({
      action: "sendAnalytics",
      url: activeTabUrl,
      eventName: "Button Clicked",
      eventProperties: {
        button_name: "Start Lesson",
      }
    });
    
    await chrome.tabs.create({
      url: `${import.meta.env.VITE_LEECO_WEB_URL}/learn/${recordId}?startNextLesson=true`,
      active: true,
    });
  };

  return {
    handlePathClick,
    handleStartLesson,
    nextLesson
  }
}

export default useContinueLatestPath