/**
 * Utility functions for handling credit limit logic based on daily credit variants
 */

import { getMostRecentSubscription } from "./subscription-helpers";

export type DailyCreditLimit = 20 | 10 | 5;

export interface CreditLimitConfig {
  dailyLimit: DailyCreditLimit;
  softTriggerThresholds: number[];
  upgradeBannerThreshold: number;
}

/**
 * Get credit limit configuration based on daily message limit
 */
export const getCreditLimitConfig = (dailyMessageLimit: number): CreditLimitConfig => {
  switch (dailyMessageLimit) {
    case 20:
      return {
        dailyLimit: 20,
        softTriggerThresholds: [17, 14, 11], // Soft triggers at 17, 14, 11 credits left
        upgradeBannerThreshold: 10 // Upgrade banner after 10 credits left
      };
    case 10:
      return {
        dailyLimit: 10,
        softTriggerThresholds: [8, 6], // Soft triggers at 8, 6 credits left
        upgradeBannerThreshold: 5 // Upgrade banner after 5 credits left
      };
    case 5:
      return {
        dailyLimit: 5,
        softTriggerThresholds: [3], // Soft trigger at 3 credits left
        upgradeBannerThreshold: 2 // Upgrade banner after 2 credits left
      };
    default:
      // Fallback to 20 credit limit for unknown values
      return {
        dailyLimit: 20,
        softTriggerThresholds: [17, 14, 11],
        upgradeBannerThreshold: 10
      };
  }
};

/**
 * Check if soft trigger should be shown based on credits left
 */
export const shouldShowSoftTrigger = (
  dailyMessagesLeft: number,
  dailyMessageLimit: number
): boolean => {
  const config = getCreditLimitConfig(dailyMessageLimit);
  return config.softTriggerThresholds.includes(dailyMessagesLeft);
};

/**
 * Check if upgrade banner should be shown based on credits left
 */
export const shouldShowUpgradeBanner = (
  dailyMessagesLeft: number,
  dailyMessageLimit: number
): boolean => {
  const config = getCreditLimitConfig(dailyMessageLimit);
  return dailyMessagesLeft <= config.upgradeBannerThreshold && dailyMessagesLeft > 0;
};

/**
 * Check if upgrade banner should be shown for exhausted credits
 */
export const shouldShowExhaustedBanner = (dailyMessagesLeft: number): boolean => {
  return dailyMessagesLeft === 0;
};

/**
 * Check if full credits banner should be shown (when user has all credits)
 */
export const shouldShowFullCreditsBanner = (
  dailyMessagesLeft: number,
  dailyMessageLimit: number
): boolean => {
  return dailyMessagesLeft === dailyMessageLimit;
};

/**
 * Check if trial cancelled banner should be shown
 */

export const shouldShowTrialCancelledBanner = (menteeSubscription: any): boolean => {
  const mostRecentSubscription = getMostRecentSubscription(menteeSubscription.subscriptions);   
  return menteeSubscription.pricing_plan.user_type === "trial" && mostRecentSubscription?.cancelledOn;
};