import HiLeeco from "../../assets/hi-im-leeco.webp";
import HeyImLeeco from "../../assets/hey-im-leeco.webp";
import YouTube from "../../assets/youtube-medium.svg";
import LeetCode from "../../assets/leetcode-medium.svg";
import Amazon from "../../assets/amazon-medium.svg";
import CombinedAvatars from "../../assets/three-avatar-combined.svg";
import MentorAiButton from "../../../common/button/mentorai-button";
import { redirectToCheckout } from "../../utils/checkout-redirect";
import useExtensionPlansContainer from "../../components/conversation-container/extension-paywall/plans-sheet/components/extension-plans/use-extension-plans-container";
import { getFormattedPriceWithSymbol } from "../../../utils/currency";

const FreeTrial = () => {
    const { extensionPlans } = useExtensionPlansContainer()
    const monthlyPriceString = getFormattedPriceWithSymbol(extensionPlans?.find((plan) => plan?.validity === "1 month")?.totalPrice!);

    return (
        <div className="flex flex-col p-1 bg-mentorai-bg-black w-full h-full items-center justify-center">
            <div className="flex flex-col bg-mentorai-bg-base w-full h-full items-center justify-center max-h-screen overflow-auto scrollbar-hide rounded-[14px] p-4 relative">
                <div className="flex flex-col mt-[150px] relative w-full">
                    <img
                        src={HiLeeco}
                        alt="Leeco mascot"
                        className="w-[110px] h-[110px]"
                    />
                    <img
                        src={HeyImLeeco}
                        alt="Leeco mascot"
                        className="absolute top-0 left-[85px]  w-[74px] h-[44px]"
                    />
                    <div className="bg-[#FFFFFF14] h-px w-full"> <span className="invisible">.</span></div>
                </div>

                <div className="font-bricolage-grotesque mt-5 text-white text-[20px] font-semibold leading-[28px] tracking-[-0.3px] w-full">
                    Start your 1 Month Trial and let's<br />
                    begin learning together!
                </div>

                <div className="w-full mt-6 flex flex-col gap-6  mb-[150px]">
                    <div className="flex items-start gap-2">
                        <img src={YouTube} alt="YouTube" className="w-6 h-6 min-w-6 min-h-6" />
                        <div className="flex flex-col gap-1">
                            <div className="font-bricolage-grotesque text-white leading-[20px] font-semibold text-[14px] tracking-[-0.084px]">
                                Create Quizzes From YouTube
                            </div>
                            <p className="text-mentorai-text-sub text-[12px] font-medium leading-[18px] font-manrope">
                                Convert any video on YouTube into an interactive quiz. Retain 3x more.
                            </p>
                        </div>
                    </div>
                    <div className="flex items-start gap-2">
                        <img src={LeetCode} alt="YouTube" className="w-6 h-6 min-w-6 min-h-6" />
                        <div className="flex flex-col gap-1">
                            <div className="font-bricolage-grotesque text-white leading-[20px] font-semibold text-[14px] tracking-[-0.084px]">
                                Crack problem-solving patterns
                            </div>
                            <p className="text-mentorai-text-sub text-[12px] font-medium leading-[18px] font-manrope">
                                On LeetCode and GFG, Leeco trains you to find patterns, saving you hours in solving problems.
                            </p>
                        </div>
                    </div>
                    <div className="flex items-start gap-2">
                        <img src={Amazon} alt="YouTube" className="w-6 h-6 min-w-6 min-h-6" />
                        <div className="flex flex-col gap-1">
                            <div className="font-bricolage-grotesque text-white leading-[20px] font-semibold text-[14px] tracking-[-0.084px]">
                                Get 50+ Company Paths
                            </div>
                            <p className="text-mentorai-text-sub text-[12px] font-medium leading-[18px] font-manrope">
                                From FAANG to startups, get DSA sheets for any job you want. Leeco helps you complete them.
                            </p>
                        </div>
                    </div>
                </div>

                <div className="flex flex-col px-1 pb-1 rounded-b-[14px] bg-mentorai-bg-black items-center justify-center fixed bottom-0 w-full">
                    <div className="flex items-center flex-col justify-center gap-3  w-full  p-4  bg-mentorai-bg-base rounded-b-[12px]">
                        <span className="flex justify-center items-center gap-1.5">
                            <img
                                src={CombinedAvatars}
                                alt="User avatars"
                                className="w-[44px] h-[16px]"
                            />
                            <span className="text-mentorai-text-sub text-[12px] font-semibold leading-[18px] font-manrope">
                                Join 30,000+ learners today
                            </span>
                        </span>
                        <MentorAiButton
                            type="primary"
                            size="large"
                            classNames="w-full !font-bricolage-grotesque !font-semibold"
                            onClick={() => redirectToCheckout({
                                location: "Extension Locked Screen"
                            })}
                        >
                            Claim First Month at {monthlyPriceString || '₹1'}
                        </MentorAiButton>

                        <p className="text-mentorai-text-sub text-[12px] font-semibold leading-[16px] font-manrope">
                            Cancel any time, no questions asked.
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default FreeTrial;
