import { useContext, useEffect, useState } from 'react'
import { MentorAiContext } from '../../../../context/mentorai-context/mentorai-context'
import { MenteeContext } from '../../../../context/mentee-context/mentee-context'
import { getTodaysDate } from '../../../../../utils/helper'
import { handleAibackendPost } from '../../../../../core/Axios'
import Like from "../../../../assets/like.svg"
import LikeHover from "../../../../assets/like-hover.svg"
import Dislike from "../../../../assets/dislike.svg"
import DislikeHover from "../../../../assets/dislike-hover.svg"
import Cancel from "../../../../assets/cross.svg"
import CancelHover from "../../../../assets/cross-hover.svg"
import { sendAnalyticsWithBackend } from '../../../../../core/Analytics'
import { PageContext } from '../../../../context/page-context/page-context'
import toast from 'react-hot-toast'

type Props = {
    setConversationFeedbackStatusToCancel: any
    setConversationFeedbackStatusToSubmitted: any
    conversationFeedbackStatus: string
}

type CTAs = 'helpful' | 'not_helpful' | ''

const ConversationFeedback = ({ setConversationFeedbackStatusToCancel, conversationFeedbackStatus, setConversationFeedbackStatusToSubmitted }: Props) => {
    const [hoveredItem, setHoveredItem] = useState<string>("");
    const { mentoraiData } = useContext(MentorAiContext);
    const { menteeData } = useContext(MenteeContext);
    const { activeTabUrl } = useContext(PageContext)
    const [clickedCta, setClickedCta] = useState<CTAs>('');

    const handleCancel = () => {
        sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "Conversation Feedback Cancelled", {});
        setConversationFeedbackStatusToCancel()
    }

    const handleSubmitHelpfulResponse = async () => {
        try {
            setConversationFeedbackStatusToSubmitted();
            await handleAibackendPost(`/extension/update_ai_conversation`, {
                recordId: `${mentoraiData?.recordId}_${menteeData?.recordId}`,
                candidates: [`${menteeData?.recordId}`],
                mentorAi: [`${mentoraiData?.recordId}`],
                conversationFeedback: [{
                    submittedDate: getTodaysDate(),
                    feedback: "helpful"
                }]
            }, {});
            toast(
                <div className="bg-transparent pr-[40px]">
                    <div className="flex items-center gap-2 py-2 px-3 h-7 rounded bg-[#4b4e63] text-[#f2f2f2] text-xs font-medium leading-[1.125rem] mb-[96px]">
                        Thanks for the feedback!
                    </div>
                </div>
                , {
                    position: 'bottom-center',
                    icon: <></>
                });
            sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "Conversation Feedback Submitted", { feedback: { helpfulness: "Helpful" } });
        } catch (error) {
            console.error("Error submitting helpful response:", error);
        }
    };

    const handleSubmitUnhelpfulResponse = async () => {
        try {
            setConversationFeedbackStatusToSubmitted();
            await handleAibackendPost(`/extension/update_ai_conversation`, {
                recordId: `${mentoraiData?.recordId}_${menteeData?.recordId}`,
                candidates: [`${menteeData?.recordId}`],
                mentorAi: [`${mentoraiData?.recordId}`],
                conversationFeedback: [{
                    submittedDate: getTodaysDate(),
                    feedback: "not helpful"
                }]
            }, {});
            toast(
                <div className="bg-transparent pr-[40px]">
                    <div className="flex items-center gap-2 py-2 px-3 h-7 rounded bg-[#4b4e63] text-[#f2f2f2] text-xs font-medium leading-[1.125rem] mb-[96px]">
                        Thanks for the feedback!
                    </div>
                </div>
                , {
                    position: 'bottom-center',
                    icon: <></>
                });
            sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "Conversation Feedback Submitted", { feedback: { helpfulness: "Not Helpful" } });
        } catch (error) {
            console.error("Error submitting helpful response:", error);
        }
    }

    useEffect(() => {
        if (clickedCta === "helpful") {
            setTimeout(() => {
                handleSubmitHelpfulResponse();
            }, 1000);
        } else if (clickedCta === "not_helpful") {
            setTimeout(() => {
                handleSubmitUnhelpfulResponse();
            }, 1000);
        }
    }, [clickedCta])

    return (
        <div className="relative flex flex-col items-center justify-center gap-4 self-stretch py-4 px-3 border-t border-t-[#363645] border-b border-b-[#363645] bg-[#2F3241] pl-[54px]">
            <p className="  text-[#f2f2f2] text-center  text-xs font-medium leading-[1.125rem]">How are you finding the conversation so far?</p>

            <div className="flex justify-center items-center gap-2 self-stretch">
                {clickedCta === "helpful" ?
                    <div className=" flex justify-center items-center gap-1 py-1 pl-1 pr-2 h-6 rounded border border-[#3ee089]/[.30] bg-[#3ee089]/[.20]">
                        <svg width={13} height={12} viewBox="0 0 13 12" fill="none" xmlns="http://www.w3.org/2000/svg">
                            <path d="M2.00078 4.65005H3.35078V10.05H2.00078C1.88143 10.05 1.76697 10.0026 1.68258 9.91825C1.59819 9.83386 1.55078 9.7194 1.55078 9.60005V5.10005C1.55078 4.9807 1.59819 4.86624 1.68258 4.78185C1.76697 4.69746 1.88143 4.65005 2.00078 4.65005ZM4.38263 4.0682L7.26263 1.1882C7.30091 1.14981 7.35176 1.12654 7.40583 1.12265C7.4599 1.11876 7.51356 1.13453 7.55693 1.16705L7.94078 1.45505C8.04739 1.53508 8.12791 1.64488 8.1722 1.77062C8.21648 1.89635 8.22255 2.03238 8.18963 2.16155L7.67078 4.20005H10.5508C10.7895 4.20005 11.0184 4.29487 11.1872 4.46365C11.356 4.63244 11.4508 4.86136 11.4508 5.10005V6.04685C11.4509 6.16446 11.428 6.28096 11.3833 6.38975L9.99053 9.7715C9.95656 9.85395 9.89885 9.92444 9.82474 9.97404C9.75063 10.0236 9.66346 10.0501 9.57428 10.05H4.70078C4.58143 10.05 4.46697 10.0026 4.38258 9.91825C4.29819 9.83386 4.25078 9.7194 4.25078 9.60005V4.38635C4.25081 4.26701 4.29823 4.15257 4.38263 4.0682Z" fill="#3EE089" />
                        </svg>
                        <div className=" text-[#3ee089] text-center text-xs leading-[1.125rem]">Helpful</div>
                    </div>
                    :
                    <button onMouseEnter={() => setHoveredItem("helpful")} onMouseLeave={() => setHoveredItem("")} onClick={() => setClickedCta('helpful')} className="group flex justify-center items-center gap-1 py-0 px-2 h-6 rounded border-[0.8px] border-[#45475f] bg-[#2f3241] hover:border-[#84848c] hover:bg-[#4b4e63]">
                        {hoveredItem === "helpful" ?
                            <img src={LikeHover} alt="like" className='h-3 w-3' />
                            :
                            <img src={Like} alt="like" className='h-3 w-3' />
                        }
                        <div className=" hover:text-[#f2f2f2] text-[#dddddf]  text-center  text-xs leading-[1.125rem]">Helpful</div>
                    </button>
                }
                {clickedCta === "not_helpful" ?
                    <div className="frame_2147227742 flex justify-center items-center gap-1 py-0 px-2 h-6 rounded border-[0.8px] border-[#ff6875]/[.40] bg-[#ff6875]/[.20]">
                        <svg width={13} height={12} viewBox="0 0 13 12" fill="none" xmlns="http://www.w3.org/2000/svg">
                            <path d="M1.99922 7.35019L3.34922 7.35019L3.34922 1.95019L1.99922 1.95019C1.87987 1.95019 1.76541 1.99761 1.68102 2.082C1.59663 2.16639 1.54922 2.28085 1.54922 2.40019L1.54922 6.90019C1.54922 7.01954 1.59663 7.134 1.68102 7.21839C1.76541 7.30278 1.87987 7.35019 1.99922 7.35019ZM4.38107 7.93204L7.26107 10.812C7.29934 10.8504 7.3502 10.8737 7.40427 10.8776C7.45834 10.8815 7.51199 10.8657 7.55537 10.8332L7.93922 10.5452C8.04582 10.4652 8.12635 10.3554 8.17063 10.2296C8.21492 10.1039 8.22099 9.96787 8.18807 9.8387L7.66922 7.8002L10.5492 7.8002C10.7879 7.8002 11.0168 7.70537 11.1856 7.53659C11.3544 7.36781 11.4492 7.13889 11.4492 6.9002L11.4492 5.9534C11.4493 5.83578 11.4264 5.71929 11.3817 5.6105L9.98852 2.2292C9.95464 2.14673 9.89704 2.07619 9.82301 2.02652C9.74898 1.97685 9.66187 1.95028 9.57272 1.9502L4.69922 1.95019C4.57987 1.95019 4.46541 1.99761 4.38102 2.082C4.29663 2.16639 4.24922 2.28085 4.24922 2.40019L4.24922 7.6139C4.24924 7.73323 4.29667 7.84767 4.38107 7.93204Z" fill="#FF6875" />
                        </svg>
                        <div className="text-[#ff6875] text-center text-xs leading-[1.125rem]">Not Helpful</div>
                    </div>
                    :
                    <button onMouseEnter={() => setHoveredItem("not_helpful")} onMouseLeave={() => setHoveredItem("")} onClick={() => setClickedCta('not_helpful')} className="group flex justify-center items-center gap-1 py-0 px-2 h-6 rounded border-[0.8px] border-[#45475f] bg-[#2f3241] hover:border-[#84848c]  hover:bg-[#4b4e63]">
                        {hoveredItem === "not_helpful" ?
                            <img src={DislikeHover} alt="dislike" className='h-3 w-3' />
                            :
                            <img src={Dislike} alt="dislike" className='h-3 w-3' />
                        }
                        <div className=" hover:text-[#f2f2f2] text-[#dddddf] text-center  text-xs leading-[1.125rem]">Not Helpful</div>
                    </button>
                }
            </div>
            <button onMouseEnter={() => setHoveredItem("cancel")} onMouseLeave={() => setHoveredItem("")} onClick={handleCancel} className="absolute top-1 right-1">
                {hoveredItem === "cancel" ?
                    <img src={CancelHover} alt="cancel" className='h-4 w-4' />
                    :
                    <img src={Cancel} alt="cancel" className='h-4 w-4' />
                }
            </button>
        </div>
    )
}

export default ConversationFeedback