import React, { useState, useEffect } from "react";
import Like from "../../assets/message-feedback/like.svg";
import Dislike from "../../assets/message-feedback/dislike.svg";
import Clipboard from "../../assets/message-feedback/copy.svg";
import LikeHover from "../../assets/message-feedback/like-hover.gif";
import DislikeHover from "../../assets/message-feedback/dislike-hover.gif";
import CopyHover from "../../assets/message-feedback/copy-hover.gif";
import Copied from "../../assets/message-feedback/copy-selected.gif";
import Liked from "../../assets/message-feedback/like-selected.gif";
import Disliked from "../../assets/message-feedback/dislike-selected.gif";
import { handleAibackendPost } from "../../../core/Axios";
// import { MentorAiContext } from "../../../context/mentorai-context/mentorai-context";
// import { MenteeContext } from "../../../context/mentee-context/mentee-context";
import { sendAnalyticsWithBackend } from "../../../core/Analytics";
// import { PageContext } from "../../../context/page-context/page-context";
import toast from "react-hot-toast";

type MessageFeedbackProps = {
  className?: string;
  message: string;
  messageId: string;
  userQuery: string;
  mentoraiData: any;
  menteeData: any;
  activeTabUrl: string;
};

const MessageFeedback = ({
  className,
  message,
  messageId,
  userQuery,
  mentoraiData,
  menteeData,
  activeTabUrl,
}: MessageFeedbackProps) => {
  const [hoveredItem, setHoveredItem] = useState<string>("");
  const [feedback, setFeedback] = useState<string | null>(null); // Stores 'liked' or 'disliked'
  //   const { mentoraiData } = useContext(MentorAiContext);
  //   const { menteeData } = useContext(MenteeContext);
  //   const { activeTabUrl } = useContext(PageContext);
  const [showCopied, setShowCopied] = useState(false);

  useEffect(() => {
    chrome.storage.local.get([messageId], (result) => {
      if (result[messageId]) {
        setFeedback(result[messageId]);
      }
    });
  }, [messageId]);

  const handleCopyToClipboard = () => {
    const textToCopy = message;
    setShowCopied(true);
    toast(
      <div className="bg-transparent pr-[40px]">
        <div className="flex items-center gap-2 py-2 px-3 h-7 rounded bg-[#4b4e63] text-[#f2f2f2] text-xs font-medium leading-[1.125rem] mb-[96px]">
          Message Copied
        </div>
      </div>
      ,
      {
        position: "bottom-center",
        icon: <></>,
      }
    );
    sendAnalyticsWithBackend(
      menteeData?.email || "",
      activeTabUrl,
      "Message Copied To Clipboard",
      {}
    );
    navigator.clipboard
      .writeText(textToCopy)
      .then(() => {
        console.log("Text copied to clipboard!");
      })
      .catch((err) => {
        console.error("Error copying text: ", err);
      });
    setTimeout(() => {
      setShowCopied(false);
    }, 2000);
  };

  const handleLike = async () => {
    try {
      await handleAibackendPost(
        `/extension/update_ai_conversation`,
        {
          recordId: `${mentoraiData?.recordId}_${menteeData?.recordId}`,
          candidates: [`${menteeData?.recordId}`],
          mentorAi: [`${mentoraiData?.recordId}`],
          messageFeedback: [
            {
              messageId: messageId,
              feedback: "liked",
            },
          ],
        },
        {}
      );
      sendAnalyticsWithBackend(
        menteeData?.email || "",
        activeTabUrl,
        "Message Feedback Submitted",
        {
          feedback: { react: "liked" },
          message: {
            message_id: messageId,
            ai_response: message,
            user_query: userQuery,
          },
        }
      );
      chrome.storage.local.set({ [messageId]: "liked" });
      setFeedback("liked");
      toast(
        <div className="bg-transparent pr-[40px]">
          <div className="flex items-center gap-2 py-2 px-3 h-7 rounded bg-[#4b4e63] text-[#f2f2f2] text-xs font-medium leading-[1.125rem] mb-[96px]">
            Thanks for the feedback!
          </div>
        </div>,
        {
          position: "bottom-center",
          icon: <></>,
        }
      );
    } catch (error) {
      console.error("Error submitting helpful response:", error);
    }
  };

  const handleDislike = async () => {
    try {
      await handleAibackendPost(
        `/extension/update_ai_conversation`,
        {
          recordId: `${mentoraiData?.recordId}_${menteeData?.recordId}`,
          candidates: [`${menteeData?.recordId}`],
          mentorAi: [`${mentoraiData?.recordId}`],
          messageFeedback: [
            {
              messageId: messageId,
              feedback: "disliked",
            },
          ],
        },
        {}
      );
      toast(
        <div className="bg-transparent pr-[40px]">
          <div className="flex items-center gap-2 py-2 px-3 h-7 rounded bg-[#4b4e63] text-[#f2f2f2] text-xs font-medium leading-[1.125rem] mb-[96px]">
            Thanks for the feedback!
          </div>
        </div>,
        {
          position: "bottom-center",
          icon: <></>,
        }
      );
      sendAnalyticsWithBackend(
        menteeData?.email || "",
        activeTabUrl,
        "Message Feedback Submitted",
        {
          feedback: { react: "disliked" },
          message: {
            message_id: messageId,
            ai_response: message,
            user_query: userQuery,
          },
        }
      );
      chrome.storage.local.set({ [messageId]: "disliked" });
      setFeedback("disliked");
    } catch (error) {
      console.error("Error submitting helpful response:", error);
    }
  };

  return (
    <div className={`flex mt-2 ${className}`}>
      <button
        onClick={handleCopyToClipboard}
        onMouseEnter={() => setHoveredItem('clipboard')}
        onMouseLeave={() => setHoveredItem('')}
        className="flex justify-center items-center w-6 h-6 box-border rounded-[8px] hover:bg-[#2F3241]"
      >
        <img
          src={showCopied ? Copied : (hoveredItem === "clipboard" ? CopyHover : Clipboard)}
          alt="clipboard"
          className='w-4 h-4'
        />
      </button>

      <button
        onClick={handleLike}
        onMouseEnter={() => setHoveredItem('like')}
        onMouseLeave={() => setHoveredItem('')}
        className="flex justify-center items-center w-6 h-6 box-border rounded-[8px] hover:bg-[#2F3241]"
      >
        <img
          src={hoveredItem === "like" ? (feedback === "liked" ? Liked : LikeHover) : feedback === "liked" ? Liked : Like}
          alt="like"
          className='w-4 h-4'
        />
      </button>
      <button
        onClick={handleDislike}
        onMouseEnter={() => setHoveredItem('dislike')}
        onMouseLeave={() => setHoveredItem('')}
        className="flex justify-center items-center w-6 h-6 box-border rounded-[8px] hover:bg-[#2F3241]"
      >
        <img
          src={hoveredItem === "dislike" ? (feedback === "disliked" ? Disliked : DislikeHover) : feedback === "disliked" ? Disliked : Dislike}
          alt="dislike"
          className='w-4 h-4'
        />
      </button>
    </div>
  );
};

export default MessageFeedback;
