export const timeToSeconds = (timeStr: string | undefined) => {
    if (!timeStr) return 0;
    const normalizedTime = timeStr.split(':').length === 2 ? `00:${timeStr}` : timeStr;
    const [hours, minutes, seconds] = normalizedTime.split(':').map(Number);
    return hours * 3600 + minutes * 60 + seconds;
};

export const formatDateToDayMonthYear = (dateString: any): string => {
    if (!dateString) return "";
    let date: any = new Date(dateString);
    if (`${date}`.includes("Invalid")) {
        date = new Date(dateString?.split('T')?.[0]);
    }

    const day = date.getDate();
    const month = date.toLocaleString("default", { month: "long" });
    const year = date.getFullYear();
    function getOrdinal(n: number) {
        if (n > 3 && n < 21) return "th";
        switch (n % 10) {
            case 1: return "st";
            case 2: return "nd";
            case 3: return "rd";
            default: return "th";
        }
    }
    return `${month} ${day}, ${year}`;
}