import { useState } from "react";
import { useContext } from "react";
import { MenteeContext } from "../../../context/mentee-context/mentee-context";
import { MentorAiContext } from "../../../context/mentorai-context/mentorai-context";
import { PageContext } from "../../../context/page-context/page-context";
import { NPS_STATUS } from "../../../context/chat-context/use-chat-conversations";
import { sendAnalyticsWithBackend } from "../../../../core/Analytics";
import { toast } from "react-hot-toast";
import { handlePost } from "../../../../core/Axios";
import { npsConfig } from "./constants/constant.d";
import { getCurrentExtensionUsedDaysCount } from "../../../../utils/helper";

const getCategoryFromRating = (rating: number) => {
    if (rating >= 9) return "high";
    if (rating >= 7) return "medium";
    return "low";
};


type Step = "rating" | "feedback"


const useNpsFeedbackV2 = ({ setNpsStatus, npsStatus }: { setNpsStatus: Function, npsStatus: string }) => {
    const { menteeData, setMenteeData } = useContext(MenteeContext);
    const { mentoraiData } = useContext(MentorAiContext);
    const { activeTabUrl, setTriggerShowShareExtension } = useContext(PageContext)
    const [step, setStep] = useState<Step>("rating")
    const [nps, setNps] = useState<number | null>(null);
    const [reasons, setReasons] = useState<string[]>([]);
    const [comment, setComment] = useState("");
    const [submitting, setSubmitting] = useState(false)


    let category: string | null = null;
    let question = "";
    let options: string[] = [];

    if (nps !== null) {
        category = getCategoryFromRating(nps);
        question = npsConfig[category].question;
        options = npsConfig[category].options;
    }

    const handleCancelNps = async () => {
        let extensionUsedDaysCount = await getCurrentExtensionUsedDaysCount();
        setNpsStatus(NPS_STATUS.CANCELED)
        await chrome.storage.local.set({ npsCanceledOnDay: extensionUsedDaysCount });
        await chrome.storage.local.set({ npsStatusFromLocalStorage: NPS_STATUS.CANCELED });
        sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "Mentee NPS Cancelled", { version: "v2" });
    };

    const refetchAndUpdateMenteeData = async () => {
        let refetchedMenteeData;
        let attempts = 0;
        const maxAttempts = 3;
        const prevRecordId = menteeData?.recordId;

        do {
            refetchedMenteeData = await chrome.runtime.sendMessage({
                action: "fetch_calls",
                fetch_call: "fetch_mentee",
                refetch: true,
            });
            if (refetchedMenteeData.mentee_data?.recordId !== prevRecordId) {
                sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "Mentee Refetch Success", {});
                break;
            }
            attempts++;
            if (attempts < maxAttempts) {
                await new Promise(res => setTimeout(res, 2000));
            }
        } while (attempts < maxAttempts);

        if (attempts === maxAttempts) {
            sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "Mentee Refetch Failed", {});
        }

        setMenteeData(refetchedMenteeData.mentee_data)
        await chrome.storage.local.set({ menteeData: refetchedMenteeData.mentee_data })
    }

    const handlePostNps = async (props: { recordId?: string, reasons?: string[], comment?: string }) => {
        if (nps === null) return;
        setSubmitting(true)
        const payload = {
            recordId: props?.recordId,
            nps: nps,
            mentee: [menteeData?.recordId],
            source: "Extension",
            updatedTime: new Date().toISOString(),
            reason: props?.reasons,
            comments: props?.comment,
            mentorAi: [mentoraiData?.recordId],
        };

        try {
            const response = await handlePost("nps", payload, {});
            if (!response.ok) {
                console.error("Network response was not ok");
            }
        } catch (error) {
            console.error("Error posting NPS feedback:", error);
        }
        // setNpsStatus(NPS_STATUS.SUBMITTED)
        await chrome.storage.local.set({ npsStatusFromLocalStorage: NPS_STATUS.SUBMITTED });
        sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "Mentee NPS Submitted", { reason: reasons, comment: comment, nps: nps, version: "v2" });
        // Polling logic to ensure menteeData is updated if recordId hasn't changed
        await refetchAndUpdateMenteeData();

        setSubmitting(false)
        setTriggerShowShareExtension(true)
        setTimeout(() => {
            setTriggerShowShareExtension(false)
        }, 5000)
        toast(
            <div className="bg-transparent pr-[40px]">
                <div className="flex items-center gap-2 py-2 px-3 h-7 rounded bg-[#4b4e63] text-[#f2f2f2] text-xs font-medium leading-[1.125rem] mb-[96px]">
                    Thanks for the feedback!
                </div>
            </div>
            , {
                position: 'bottom-center',
                icon: <></>
            });
    };

    const handleReasonChange = (option: string) => {
        if (reasons.includes(option)) {
            setReasons((prev) => prev.filter((item) => item !== option));
        } else {
            setReasons((prev) => [...prev, option]);
        }
    };

    function removeEmojis(text: string) {
        return text.replace(/[\p{Emoji}\uFE0F]/gu, '');
    }

    const getSelectedRatingClassName = (rating: number) => {
        if (rating >= 9) {
            return " bg-[#3EE089] border-[#3EE089] text-mentorai-text-white font-[600]";
        } else if (rating >= 7) {
            return " bg-[#FFD268] border-[#FFD268] text-mentorai-text-white font-[600]";
        } else {
            return " bg-[#FF6875] border-[#FF6875] text-mentorai-text-white font-[600]";
        }
    };

    const getDefaultRatingClassName = (rating_number: number) => {
        if (rating_number >= 9) {
            return " bg-[#14161F] hover:bg-[#3EE089] border-[#3EE089] text-[#3EE089] hover:text-mentorai-text-white";
        } else if (rating_number >= 7) {
            return " bg-[#14161F] hover:bg-[#FFD268] border-[#FFD268] text-[#FFD268] hover:text-mentorai-text-white";
        } else {
            return " bg-[#14161F] hover:bg-[#FF6875] border-[#FF6875] text-[#FF6875] hover:text-mentorai-text-white";
        }
    };

    return {
        handleCancelNps,
        handlePostNps,
        getSelectedRatingClassName,
        getDefaultRatingClassName,
        handleReasonChange,
        removeEmojis,
        nps,
        setNps,
        setReasons,
        setComment,
        submitting,
        step,
        setStep,
        question,
        options,
        category,
        reasons,
        comment,
    }
}

export default useNpsFeedbackV2