  mentorAiData: any
  liveMessages: any
  setLiveMessages: Function
  userLiveMessage: any
  chatMessages: any
  sendMessage: Function
  loading: boolean
  isLiveMessageStreaming: boolean
  isMentorAiSession: boolean
  conversationFeedbackStatus: string
  npsStatus: string
  setNpsStatus: Function
  setConversationFeedbackStatusToCancel: Function
  setConversationFeedbackStatusToSubmitted: Function
  fetchMessages: Function
  chatUsageData: ChatUsageData
