import Plus from '../../assets/plus.svg'
import GreenCheck from '../../assets/green-check.svg'
import { useState, useEffect } from 'react'

type Props = {}

const BlacklistedSite = ({ }: Props) => {
    const [showCheck, setShowCheck] = useState(false);
    const [currentUrl, setCurrentUrl] = useState<string>("");

    useEffect(() => {
        const fetchTabAndStorageData = async () => {
            try {
                chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
                    const activeTabUrl = tabs?.[0]?.url || '';
                    setCurrentUrl(activeTabUrl);
                });

                const { requestedUrls = [] } = await chrome.storage.local.get('requestedUrls');
                setShowCheck(requestedUrls.includes(currentUrl));
            } catch (error) {
                console.error('Error fetching data:', error);
                setShowCheck(false);
            }
        };

        fetchTabAndStorageData();
    }, [currentUrl]);

    const saveRequestedUrl = async () => {
        try {
            const { requestedUrls = [] } = await chrome.storage.local.get('requestedUrls');

            if (!requestedUrls.includes(currentUrl)) {
                await chrome.storage.local.set({
                    requestedUrls: [...requestedUrls, currentUrl]
                });
            }
            setShowCheck(true);
        } catch (error) {
            console.error('Error saving requested URL:', error);
        }
    };

    const handleShowCheck = () => {
        chrome.runtime.sendMessage({ action: "sendAnalytics", url: currentUrl, eventName: 'Extension Usage Requested', eventProperties: {} }, () => {
        });
        saveRequestedUrl();
    };

    return (
        <>
            <section className="flex flex-col gap-2 self-stretch p-3 mx-auto my-auto w-full">
                <p className="text-[#dddddf] text-xl font-medium leading-7 tracking-[-0.2px]">We do not support this site yet.</p>
                <p className="text-[#94939f] text-sm leading-[1.375rem] tracking-[0.084px]">Do you use this site to study and would like it supported by the extension?</p>
                {showCheck ? (
                    <p className="text-[#1daf61] text-sm leading-[1.375rem] flex gap-1 my-2">
                        <img src={GreenCheck} alt="check" />
                        Sent to our list
                    </p>
                ) : (
                    <button onClick={handleShowCheck}
                        className="text-[#736df2] text-sm leading-[1.375rem] flex gap-1 my-2">
                        <img src={Plus} alt="check" />
                        Send this website to our list
                    </button>
                )}
            </section>
        </>
    );
}

export default BlacklistedSite;
