import React from "react";
import getCurrency from "../../../../../../../utils/currency";

type UnlockProHeaderProps = {
  pricingVariant?: string;
  headerTitleText: React.ReactNode;
  isCancelled: boolean;
  trialDays: number | null;
  isTrialCancelled: boolean;
};

const UnlockProHeader = ({ pricingVariant, headerTitleText, isCancelled, trialDays, isTrialCancelled }: UnlockProHeaderProps) => {
  const INRPricingVarintHeaderTexts = {
    v1: isTrialCancelled ? ["Reactivate your free trial", "to enjoy all features & unlimited chat credits"] : ["Unlock the full power of", "Leeco Pro now at 50% off."],
    v2: ["New User get leeco Pro for", "just at ₹1 for the first month"],
    v3: ["New User get leeco Pro for", "just at ₹1 for the first week"],
    v4: isTrialCancelled ? ["Reactivate your free trial", "to enjoy all features & unlimited chat credits"] : ["New User get leeco Pro for", "just at ₹1 for the first month"],
    v5: ["New User get leeco Pro for", "just at ₹1 for the first month"],
    v6: ["New user get Leeco AI Pro", "for only ₹1 for a limited time"],
    v7: ["Get Unlimited Credits", "just at ₹1 for the first month"],
    v8: ["New User get leeco Pro for", "just at ₹1 for the first month"],
    v9: ["New user get Leeco AI Pro", "for only ₹1 for a limited time"],
    v10: ["Get Unlimited Credits", "just at ₹1 for the first month"],
    v11: ["Get Unlimited Credits", "just at ₹1 for the first week"],
    v12: ["New User get leeco Pro for", "just at ₹1 for the first month"],
    v13: ["New users get Leeco Pro", "for FREE for the first week"],
    v14: ["New users get Leeco Pro", "for FREE for the first week"],
  };

  const USDPricingVarintHeaderTexts = {
    v1: isTrialCancelled ? ["Reactivate your free trial", "to enjoy all features & unlimited chat credits"] :   ["Unlock the full power of", "Leeco Pro now at 50% off."],
    v2: ["New User get leeco Pro for", "FREE, for the first month"],
    v3: ["New User get leeco Pro for", "FREE for the first week"],
    v4: isTrialCancelled ? ["Reactivate your free trial", "to enjoy all features & unlimited chat credits"] : ["New User get leeco Pro for", "FREE, for the first month"],
    v5: ["New User get leeco Pro for", "FREE for the first month"],
    v6: ["New user get Leeco AI Pro", "for FREE for a limited time"],
    v7: ["Get Unlimited Credits", "FREE for the first month"],
    v8: ["New User get leeco Pro for", "FREE for the first month"],
    v9: ["New user get Leeco AI Pro", "for FREE for a limited time"],
    v10: ["Get Unlimited Credits", "for FREE for a limited time"],
    v11: ["Get Unlimited Credits", "for FREE for a limited time"],
    v12: ["New User get leeco Pro for", "FREE for the first month"],
    v13: ["New users get Leeco Pro", "for FREE for the first week"],
    v14: ["New users get Leeco Pro", "for FREE for the first week"],
  };

  const inrHeaderText = Object.keys(INRPricingVarintHeaderTexts).includes(pricingVariant!)
    ? INRPricingVarintHeaderTexts?.[pricingVariant as keyof typeof INRPricingVarintHeaderTexts]
    : trialDays === 7
    ? INRPricingVarintHeaderTexts.v3
    : trialDays === 30
    ? INRPricingVarintHeaderTexts.v4
    : ["", ""];

  const usdHeaderText = Object.keys(USDPricingVarintHeaderTexts).includes(pricingVariant!)
    ? USDPricingVarintHeaderTexts?.[pricingVariant as keyof typeof USDPricingVarintHeaderTexts]
    : trialDays === 7
    ? USDPricingVarintHeaderTexts.v3
    : trialDays === 30
    ? USDPricingVarintHeaderTexts.v4
    : ["", ""];

  const currency = getCurrency();

  return (
    <div className="flex flex-col gap-3">
      <h1 className="text-white text-[22px] leading-[28px] font-semibold tracking-[-0.88px] font-bricolage-grotesque">
        {headerTitleText !== null && isCancelled ? (
          headerTitleText
        ) : (
          <>
            {currency === "INR" ? inrHeaderText?.[0] : usdHeaderText?.[0]}
            <br />
            {currency === "INR" ? inrHeaderText?.[1] : usdHeaderText?.[1]}
          </>
        )}
      </h1>
    </div>
  );
};

export default UnlockProHeader;
