import LeetcodeIcon from "../../../assets/leetcode.svg";
import VerticalLineDeepGray from "../../../assets/vertical-line-deep-gray.svg";
import useRecommendedPath from "./use-recommended-path";
import SlidingCarousel from "../../../components/sliding-carousel/sliding-carousel";
import { CompanyPathType } from "../../../context/page-context/index.type";

interface ChooseARecommendedPathProps {
  autoRotate?: boolean;
  itemsPerPage?: number;
}

const ChooseARecommendedPath = ({ autoRotate = true, itemsPerPage = 2 }: ChooseARecommendedPathProps) => {
  const { recommendedPaths, handlePathClick } = useRecommendedPath();

  const renderRecommendedPath = (item: CompanyPathType) => (
    <div
      className="p-3 flex gap-3 items-center border border-[#363645] hover:bg-[#212431] rounded-xl cursor-pointer"
      onClick={() => handlePathClick(item?.pathUrl, item?.title)}
    >
      <img src={item?.companyLogo} alt="company-logo.svg" className="h-[56px] w-[56px] rounded-xl" />
      <div className="space-y-2">
        <p className="text-sm text-[#DDDDDF] font-medium font-bricolage-grotesque -tracking-[0.14px]">{item?.title}</p>
        <div className="flex gap-x-1.5 items-center">
          <div className="flex gap-1 items-center">
            <p className="text-[#94939F] text-[12px] leading-[13px] whitespace-nowrap">{item?.questions} Questions</p>
            <img src={LeetcodeIcon} alt="platform-logo.svg" className="h-[16px] w-[16px]" />
          </div>
          <img src={VerticalLineDeepGray} className="h-full" />
          <p className="text-[#94939F] text-[12px] leading-[13px] whitespace-nowrap">{item?.learners} Learners</p>
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-4">
      <div className="space-y-1">
        <p className="text-[#FFF] text-[16px] leading-normal font-semibold font-bricolage-grotesque -tracking-[0.16px]">
          Choose a recommended path
        </p>
        <p className="text-[#94939F] text-[12px] font-medium leading-[18px] font-manrope">
          Paths recommended for your specific goals
        </p>
      </div>

      <SlidingCarousel
        data={recommendedPaths}
        itemsPerPage={itemsPerPage}
        autoRotate={autoRotate}
        autoRotateInterval={7000}
        renderItem={renderRecommendedPath}
        showNavigation={true}
      />
    </div>
  );
};

export default ChooseARecommendedPath;
