import React from "react";
import ChatIcon from "../../../../../../assets/extension-plan-features/chat.svg";
import ChatFadeIcon from "../../../../../../assets/extension-plan-features/chat-fade.svg";
import CompanyPathsIcon from "../../../../../../assets/extension-plan-features/company-paths.svg";
import CompanyPathsFadeIcon from "../../../../../../assets/extension-plan-features/company-paths-fade.svg";
import QuizzesIcon from "../../../../../../assets/extension-plan-features/quizzes.svg";
import QuizzesFadeIcon from "../../../../../../assets/extension-plan-features/quizzes-fade.svg";
import TrackProgressIcon from "../../../../../../assets/extension-plan-features/track-progress.svg";
import TrackProgressFadeIcon from "../../../../../../assets/extension-plan-features/track-progress-fade.svg";
import AiModelIcon from "../../../../../../assets/extension-plan-features/ai-model.svg";
import AiModelFadeIcon from "../../../../../../assets/extension-plan-features/ai-model-fade.svg";

const useFeatures = () => {
  const PlanFeaturesData = [
    {
      text: "Unlimited Chat Credits",
      subText: "Chat endlessly with Leeco AI",
      primaryIcon: ChatIcon,
      secondaryIcon: ChatFadeIcon,
    },
		{
      text: "50+ Company Paths",
      subText: "Path for MAANF+ companies",
      primaryIcon: CompanyPathsIcon,
      secondaryIcon: CompanyPathsFadeIcon,
    },
		{
      text: "Interactive Quizzes",
      subText: "Convert any YT video to Quiz",
      primaryIcon: QuizzesIcon,
      secondaryIcon: QuizzesFadeIcon,
    },
		{
      text: "Save & Track Progress",
      subText: "Never lose your learning process",
      primaryIcon: TrackProgressIcon,
      secondaryIcon: TrackProgressFadeIcon,
    },
		{
      text: "Advance AI Model",
      subText: "Unlock GPT5 for improved experience",
      primaryIcon: AiModelIcon,
      secondaryIcon: AiModelFadeIcon,
    },
  ];

  const scrollLeft = (containerRef: React.RefObject<HTMLDivElement>) => {
    if (containerRef.current) {
      const container = containerRef.current;
      const scrollAmount = Math.min(258, container.scrollLeft);
      container.scrollBy({ left: -scrollAmount, behavior: "smooth" });
    }
  };

  const scrollRight = (containerRef: React.RefObject<HTMLDivElement>) => {
    if (containerRef.current) {
      const container = containerRef.current;
      const maxScroll = container.scrollWidth - container.clientWidth;
      const scrollAmount = Math.min(258, maxScroll - container.scrollLeft);
      container.scrollBy({ left: scrollAmount, behavior: "smooth" });
    }
  };

  return {
		PlanFeaturesData,
		scrollLeft,
		scrollRight
	};
};

export default useFeatures;
