import { useContext, useEffect } from "react"
import { useState } from "react"
import { MenteeContext } from "../../../../context/mentee-context/mentee-context"
import { PageContext } from "../../../../context/page-context/page-context"
import WhatsappIcon2 from "../../../../assets/whatsapp.svg"
import LinkedInIcon from "../../../../assets/linkedin.svg"
import SlackIcon from "../../../../assets/slack.svg"


const useShareExtension = ( handleCloseSheet: () => void ) => {
    const [copied, setCopied] = useState(false)
    const { activeTabUrl } = useContext(PageContext)
    const { menteeData } = useContext(MenteeContext)
    const [ctaRedirectUrl, setCtaRedirectUrl] = useState({
        whatsapp: "",
        slack: "",
        linkedin: "",
    });
    const [selectedShareOption, setSelectedShareOption] = useState({
        popupView: "primary",
        cta: "",
        copiedAgain: false,
        open: false
    })

    const generateRedirectUrls = (link: any) => ({
        whatsapp: `https://wa.me/?text=${encodeURIComponent(link.text + ' ' + link.url)}`,
        linkedin: `https://www.linkedin.com/sharing/share-offsite/?mini=true&url=${encodeURIComponent(link.url)}`,
        slack: `https://slack.com`,
      });
    
    useEffect(() => {
        if (menteeData?.profileId) {
          setCtaRedirectUrl({
            whatsapp: generateRedirectUrls(links[0]).whatsapp,
            linkedin: generateRedirectUrls(links[1]).linkedin,
            slack: generateRedirectUrls(links[2]).slack,
          })
        }
      }, [menteeData])

    const handleShareWhatsapp = () => {
        chrome.runtime.sendMessage({
          action: "sendAnalytics", url: activeTabUrl, eventName: 'MentorAi Share Extension Medium Clicked', eventProperties: {
            medium: "WhatsApp"
          }
        })
        window.open(ctaRedirectUrl.whatsapp, '_blank');
      }
    
      const links = [
        {
          url: `https://explore.preplaced.in/Ibv5Ol?utm_content=${menteeData?.profileId}`,
          text: "I've been using this Chrome extension that works like an AI Mentor while solving DSA problems on LeetCode. It's really helped me improve my problem-solving skills, so I thought you might find it useful too. Here's the link: ",
        },
        {
          url: ` https://explore.preplaced.in/gw0oYp?utm_content=${menteeData?.profileId}`,
          text: ""
        },
        {
          url: `https://explore.preplaced.in/nv0fKq?utm_content=${menteeData?.profileId}`,
          text: "I've been using this Chrome extension that works like an AI Mentor while solving DSA problems on LeetCode. It's really helped me improve my problem-solving skills, so I thought you might find it useful too. Here's the link: ",
        },
      ];
    
      const handleShareLinkedin = () => {
        navigator.clipboard.writeText(`🔥 Just tried something that made solving LeetCode problems way easier for me I've been using the Preplaced AI Mentor Chrome extension while solving DSA problems lately. 
          It reads the question and my code in real-time, helps me debug, optimise, and discuss approaches—exactly like a mentor sitting beside me. 
          It doesn't just throw the answer at me. Instead, it helps me understand why something works, shows how to fix mistakes when I'm stuck on tough problems, and saves so much time — I don't have to jump between tabs or try to explain my code to a chatbot. 
          Sharing this here in case you're serious about improving your problem-solving skills: 
          
          ${links[1].url}
    
          #DSA #LeetCode #AImentor #ProductivityTools #PreplacedAI
          `)
        setSelectedShareOption((prev: any) => ({ ...prev, popupView: "secondary", cta: "LinkedIn", copiedAgain: false, open: true }))
        chrome.runtime.sendMessage({
          action: "sendAnalytics", url: activeTabUrl, eventName: 'MentorAi Share Extension Medium Clicked', eventProperties: {
            medium: "LinkedIn"
          }
        })
        window.open(ctaRedirectUrl.linkedin, '_blank');
      }
    
      const handleShareSlack = () => {
        setSelectedShareOption((prev: any) => ({ ...prev, popupView: "secondary", cta: "Slack", copiedAgain: false, open: true }))
        navigator.clipboard.writeText(`
           ${links[2].text} 
    
    
           ${links[2].url}
           `)
        chrome.runtime.sendMessage({
          action: "sendAnalytics", url: activeTabUrl, eventName: 'MentorAi Share Extension Medium Clicked', eventProperties: {
            medium: "Slack"
          }
        })
        window.open(ctaRedirectUrl.slack, '_blank');
      }
    
      const handleCopyAgain = (selectedShareOption: any) => {
        if (selectedShareOption.cta === "Slack") {
          navigator.clipboard.writeText(`${links[2].text} ${links[2].url}`)
        } else if (selectedShareOption.cta === "LinkedIn") {
          navigator.clipboard.writeText(`🔥Just tried something that made solving LeetCode problems way easier for me I've been using the Preplaced AI Mentor Chrome extension while solving DSA problems lately. 
            It reads the question and my code in real-time, helps me debug, optimise, and discuss approaches—exactly like a mentor sitting beside me. 
            It doesn't just throw the answer at me. Instead, it helps me understand why something works, shows how to fix mistakes when I'm stuck on tough problems, and saves so much time — I don't have to jump between tabs or try to explain my code to a chatbot. 
            Sharing this here in case you're serious about improving your problem-solving skills: 
           
            ${links[1].url}
    
            #DSA #LeetCode #AImentor #ProductivityTools #PreplacedAI
             `)
        }
        setSelectedShareOption((prev: any) => ({ ...prev, copiedAgain: true }))
        setTimeout(() => {
          setSelectedShareOption((prev: any) => ({ ...prev, copiedAgain: false }))
        }, 1500)
      }
    


    useEffect(() => {       
        if (copied) {
            setTimeout(() => {
                setCopied(false)
            }, 1500)
        }
    }, [copied])

    const ctaButtons = [
        {
            icon: WhatsappIcon2,
            text: "WhatsApp",
            handleClick: () => handleShareWhatsapp()
        },
        {
            icon: LinkedInIcon,
            text: "LinkedIn",
            handleClick: () => handleShareLinkedin()
        },
        {
            icon: SlackIcon,
            text: "Slack",
            handleClick: () => handleShareSlack()
        }
    ]

    const handleCopyExtensionLink = () => {
        chrome.runtime.sendMessage({
            action: "sendAnalytics", url: activeTabUrl,
            eventName: 'MentorAi Share Extension Medium Clicked',
            eventProperties: {
                medium: "Copy Link"
            }
        })
        navigator.clipboard.writeText(`https://explore.preplaced.in/ENjfGK?utm_content=${menteeData?.profileId}`)
        setCopied(true)
    }

  const handleClose=() => {
    handleCloseSheet()
  }

  return {
    selectedShareOption,
    ctaRedirectUrl,
    copied,
    ctaButtons,
    handleCopyExtensionLink,
    handleCopyAgain,
    handleClose
  }
}

export default useShareExtension