import { RefObject, memo, useCallback, useEffect, useDeferredValue, useContext, useState } from "react"
import { useVoiceVisualizer } from "react-voice-visualizer";
import { MessageInput } from "@chatscope/chat-ui-kit-react"

import { useSidepanelSyncContext } from "../../../context/sidepanel-sync-context/sidepanel-sync-context"
import { useAudioRecorder } from "../../../custom-hooks/use-audio-recorder"
import { cn } from "../../../../utils/cn"
import VoiceRecorder from "./voice-recorder/voice-recorder"
import MicrophoneButton from "../microphone-button/microphone-button"

import controlIcon from "../../../assets/control-icon.svg"
import altIcon from "../../../assets/alt.svg"
import { getBrowserInfo } from "../../../../core/Analytics"
import useKeyboardShortcutsV2 from "../../../custom-hooks/use-keyboard-shortcuts-v2"

import styles from "./message-input-container.module.css"
import { PageContext } from "../../../context/page-context/page-context";

interface MessageInputContainerProps {
  messageInputRef: RefObject<any>
  mentorAiData: any
  inputText: string
  setInputText: Function
  handleSubmit: any
  isLiveMessageStreaming: boolean
  upgradeBanners?: any
}

const AnimatedContainer = memo(({ children, upgradeBanners }: { children: React.ReactNode, upgradeBanners?: any }) => (
  <div
    className={cn(
      "relative flex flex-col items-end p-[8px] m-[2px  ] bg-[#14161F] border border-[#363645]",
      upgradeBanners()?.show ? "rounded-b-[12px]" : "rounded-[12px]"
    )}
  >
    {children}
  </div>
));

const MessageInputContainer = ({
  messageInputRef,
  inputText,
  setInputText,
  handleSubmit,
  isLiveMessageStreaming,
  upgradeBanners
}: MessageInputContainerProps) => {
  const { activeTabUrl } = useContext(PageContext)
  const { isAudioLive, setIsAudioLive } = useSidepanelSyncContext();
  const browserInfo = getBrowserInfo();

  // Defer the inputText updates to prevent blocking the UI during fast typing
  const deferredInputText = useDeferredValue(inputText);
  const { startRecording, stopRecording, transcription, isTranscriptionLoading } = useAudioRecorder(deferredInputText)
  const recorderControls = useVoiceVisualizer();
  useKeyboardShortcutsV2({ startRecording, stopRecording, recorderControls });

  const isWindows = browserInfo?.os_family?.includes("Windows");

  useEffect(() => {
    if (transcription) {
      setInputText(transcription);
    }
  }, [transcription, setInputText]);

  useEffect(() => {
    chrome.storage.onChanged.addListener((changes, namespace) => {
      if (changes.toggleMicrophone.newValue) {
        toggleMicrophone("Easy Action")
      }
    })

    return () => {
      chrome.storage.onChanged.removeListener((changes, namespace) => {
        if (changes.toggleMicrophone.newValue) {
          toggleMicrophone("Easy Action")
        }
      })
    }
  }, []);

  const toggleMicrophone = useCallback(
    async (from: "Easy Action" | "Button" | "Keyboard" = "Button") => {
      const microphonePermissionStatus = await navigator.permissions.query({ name: 'microphone' as PermissionName });
      if (microphonePermissionStatus.state === "granted") {
        if (isAudioLive) {
          stopRecording(false);
          setIsAudioLive(false);
          recorderControls.stopRecording();
        } else {
          startRecording();
          setIsAudioLive(true);
          recorderControls.startRecording();
          chrome.runtime.sendMessage({
            action: "sendAnalytics",
            url: activeTabUrl,
            eventName: 'MentorAi Voice-to-Text Used',
            eventProperties: {
              triggered_by: from,
              trigger_in: "Inside Sidebar"
            }
          });
        }
      } else {
        const activeTab = await chrome.tabs.query({ active: true, currentWindow: true });
        chrome.tabs.create({
          url: `${window.location.href}?action=microphone-permission&originalTabId=${activeTab[0].id}`,
          active: true
        });
      }
    },
    [isAudioLive, startRecording, stopRecording, setIsAudioLive, recorderControls, activeTabUrl]
  );

  const handleSendMessage = useCallback((text: string) => {
    handleSubmit(text)
  }, [handleSubmit]);

  const handleOnInputChange = useCallback((text: string) => {
    setInputText(text);
  }, [setInputText]);

  if (isAudioLive) {
    return <VoiceRecorder
      recorderControls={recorderControls}
      isTranscriptionLoading={isTranscriptionLoading}
      stopRecording={stopRecording}
    />
  }

  return (
    <div
      className={cn(
        "absolute bottom-[40px] left-0 right-0 z-10 pt-2 mx-2",
        styles.container,
        "bg-transparent",
        upgradeBanners()?.show ? "rounded-b-[12px]" : "rounded-[12px]"
      )}
    >
      <AnimatedContainer
        upgradeBanners={upgradeBanners}
      >
        <div className="relative flex-1 w-full">
          <MessageInput
            ref={messageInputRef}
            id="message-input-container"
            className={cn(
              "!flex-1 !bg-[#14161F]"
            )}
            value={inputText}
            onChange={handleOnInputChange}
            onSend={handleSubmit}
            attachButton={false}
            sendButton={false}
            disabled={isLiveMessageStreaming}
          />
        </div>
        {(inputText.length === 0 || inputText === "<br>") && (
          <div className="absolute top-2 left-2 flex items-center gap-[2px] text-[#66666B] text-[14px] leading-[22px] tracking-[0.14px] font-medium pointer-events-none">
            <span className="">Type or hold </span>
            <span className="flex items-center font-normal gap-[2px] font-fira-code text-[#66666B] tracking-[-0.56px]">
              <img
                src={isWindows ? altIcon : controlIcon}
                className="w-[16px] h-[16px]"
                alt="Command key"
              /> {
                isWindows ? "alt" : "control"
              }
            </span>
            <span className="">to speak</span>
          </div>
        )}
        <div className="flex items-center gap-1">
          <MicrophoneButton toggleMicrophone={toggleMicrophone} />
          <CustomSendButton inputText={inputText} handleSendMessage={handleSendMessage} />
        </div>

        {upgradeBanners()?.show &&
          upgradeBanners()?.value
        }
      </AnimatedContainer>
    </div>
  )
}

const CustomSendButton = memo(({ inputText, handleSendMessage }: { inputText: string, handleSendMessage: (text: string) => void }) => {
  const [isHover, setIsHover] = useState(false);
  return (
    <button
      onMouseEnter={() => setIsHover(true)}
      onMouseLeave={() => setIsHover(false)}
      onClick={() => handleSendMessage(inputText)}
      className={cn("rounded-full transition-all duration-300 ease-in-out",
        inputText.length > 0 && inputText !== "<br>" ? " !cursor-pointer" : " !cursor-not-allowed"
      )}>
      {inputText.length > 0 && inputText !== "<br>" ?
        isHover ?
          <svg width="24" height="24" viewBox="0 0 26 26" fill="none" xmlns="http://www.w3.org/2000/svg">
            <rect x="1" y="1" width="24" height="24" rx="12" fill="#A5A1F7" />
            <rect x="1" y="1" width="24" height="24" rx="12" stroke="#A5A1F7" />
            <path d="M12.2505 9.871V19H13.7505V9.871L17.7735 13.894L18.834 12.8335L13.0005 7L7.16698 12.8335L8.22748 13.894L12.2505 9.871Z" fill="#F2F2F2" />
          </svg>

          :
          <svg width="24" height="24" viewBox="0 0 26 26" fill="none" xmlns="http://www.w3.org/2000/svg">
            <rect x="1" y="1" width="24" height="24" rx="12" fill="#736DF2" />
            <rect x="1" y="1" width="24" height="24" rx="12" stroke="#736DF2" />
            <path d="M12.25 9.871V19H13.75V9.871L17.773 13.894L18.8335 12.8335L13 7L7.1665 12.8335L8.227 13.894L12.25 9.871Z" fill="#F2F2F2" />
          </svg>
        :
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
          <rect width="24" height="24" rx="12" fill="#212431" />
          <path d="M11.3249 9.18388V17.4H12.6749V9.18388L16.2956 12.8046L17.25 11.8501L11.9999 6.59998L6.7497 11.8501L7.70415 12.8046L11.3249 9.18388Z" fill="#45475F" />
        </svg>
      }
    </button>
  )
})

export default memo(MessageInputContainer) 