import { useContext, useState } from 'react'
import SupportWidget from './support-widget'
import { PageContext } from '../../../context/page-context/page-context'
import MentorAiActiveAvatar from '../../../../content/components/mentorai-active-avatar/mentorai-active-avatar';
import { MentorAiContext } from '../../../context/mentorai-context/mentorai-context';
import LeecoMic from "../../../assets/LeecoMic.webp";
import MentorAiButton from '../../../../common/button/mentorai-button';
import CloseIcon from "../../../assets/close-icon.svg";
import CloseIconHovered from "../../../assets/close-icon-hovered.svg";

const SupportCenter = ({ setSupportCenterOpen, supportCenterOpen, onClose }: { setSupportCenterOpen: (open: boolean) => void, supportCenterOpen: boolean, onClose?: () => void }) => {
  const [hoverSupport, setHoverSupport] = useState<string | null>(null)
  const { activeTabUrl } = useContext(PageContext)
  const { mentoraiData } = useContext(MentorAiContext)
  const [supportWidget, setSupportWidget] = useState<{ show: boolean, value: string | null }>({
    show: false,
    value: null
  })

  const supports = [
    {
      icon: "✨",
      supportName: "Feature Request",
      clickHandler: () => {
        setSupportWidget({
          show: true,
          value: "Feature Request"
        })
        chrome.runtime.sendMessage({
          action: "sendAnalytics", url: activeTabUrl, eventName: 'MentorAi Support Centre Option Clicked', eventProperties: {
            option: "Feature Request"
          }
        })
      },
      title: "✨ Feature Request",
      description: "Have an idea? Help make us better",
      buttonText: "Send Idea"
    },
    {
      icon: "🐞",
      supportName: "Report a Bug",
      clickHandler: () => {
        setSupportWidget({
          show: true,
          value: "Report a Bug"
        })
        chrome.runtime.sendMessage({
          action: "sendAnalytics", url: activeTabUrl, eventName: 'MentorAi Support Centre Option Clicked', eventProperties: {
            option: "Report a Bug"
          }
        })
      },
      title: "🐞 Report a Bug",
      description: "Report a technical issue or bug",
      buttonText: "Report Issue"
    },
    {
      icon: "🛠️",
      supportName: "Support Request",
      clickHandler: () => {
        setSupportWidget({
          show: true,
          value: "Support Request"
        })
        chrome.runtime.sendMessage({
          action: "sendAnalytics", url: activeTabUrl, eventName: 'MentorAi Support Centre Option Clicked', eventProperties: {
            option: "Support Request"
          }
        })
      },
      title: "🛠️ Support Request",
      description: "Create a support ticket for any query",
      buttonText: "Request Support"
    },
    {
      icon: "📝",
      supportName: "Give us Feedback",
      clickHandler: () => {
        setSupportWidget({
          show: true,
          value: "Give us Feedback"
        })
        chrome.runtime.sendMessage({
          action: "sendAnalytics", url: activeTabUrl, eventName: 'MentorAi Support Centre Option Clicked', eventProperties: {
            option: "Give us Feedback"
          }
        })
      },
      title: "📝 Give us Feedback",
      description: "We'd love to hear your thoughts",
      buttonText: "Send Feedback"
    }
  ]

  return (
    <>
      {supportCenterOpen && !supportWidget.show &&
        <div className="relative w-full bg-mentorai-bg-black rounded-t-xl flex flex-col font-bricolage-grotesque max-h-[calc(90vh)] overflow-y-auto scrollbar-hide p-5 border-t border-t-mentorai-stroke-strong">
          <MentorAiActiveAvatar avatarSrcOrUrl={LeecoMic} mentoraiData={mentoraiData} indicatorClassName="hidden" avatarClassName="w-[54px] h-[54px] rounded-full object-contain" />
          {!supportWidget.show &&
            <MentorAiButton classNames="!cursor-pointer transition-all duration-100 group !w-[28px] !h-[28px] absolute top-2 right-2"
              type="outlined"
              size="small"
              semiRounded
              onClick={() => {
                setSupportCenterOpen(false);
                onClose?.();
              }}>
              <img src={CloseIcon} alt="close" className="w-[16px] h-[16px] max-w-[16px] max-h-[16px] flex group-hover:hidden" />
              <img src={CloseIconHovered} alt="close" className="w-[16px] h-[16px] max-w-[16px] max-h-[16px] hidden group-hover:flex" />
            </MentorAiButton>
          }


          <div className="flex flex-col gap-1"
            style={{
              marginTop: "16px",
              marginBottom: "32px"
            }}>
            <div className="font-medium text-[18px] leading-[22px] text-mentorai-text-white tracking-[-0.36px]">
              Support Centre
            </div>
            <div className="text-[12px] leading-[16px] text-mentorai-text-sub font-manrope font-medium">
              Report your issues or make a suggestion
            </div>
          </div>

          {supports.map((support, index) => (
            <div className='flex flex-col'>
              <div className="flex gap-4 w-full justify-between cursor-pointer" onClick={support.clickHandler} onMouseEnter={() => setHoverSupport(support.supportName)} onMouseLeave={() => setHoverSupport(null)}>
                <button key={support.supportName} className="flex flex-col gap-0.5">
                  <span className="text-mentorai-text-white font-[500] text-[14px] tracking-[0.12px] whitespace-nowrap leading-[17px] text-left">
                    {support.icon} {support.supportName}
                  </span>
                  <span className="ml-[23px] text-mentorai-text-sub text-[12px] leading-[16px] font-manrope font-medium ">
                    {support.description}
                  </span>
                </button>
                <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 18 18" fill="none">
                  <path d="M9.71625 8.99931L6.375 5.65806L7.32945 4.70361L11.6251 8.99931L7.32945 13.295L6.375 12.3406L9.71625 8.99931Z" fill="#5C5C5C" />
                </svg>
              </div>
              {supports.length - 1 !== index &&
                <div className='h-[0.5px] w-full bg-mentorai-stroke-base my-4'> <span className='invisible'>.</span> </div>
              }
            </div>
          ))}
        </div >
      }
      {supportWidget.show && (
        <SupportWidget
          handleClose={() => {
            setSupportWidget({ show: false, value: null });
          }}
          setSupportCenterOpen={setSupportCenterOpen}
          onClose={onClose}
          title={supports.find(support => support.supportName === supportWidget.value)?.title || ""}
          description={supports.find(support => support.supportName === supportWidget.value)?.description || ""}
          buttonText={supports.find(support => support.supportName === supportWidget.value)?.buttonText || ""}
        />
      )}
    </>
  )
}

export default SupportCenter