const useSignIn = () => {
  const webUrl = import.meta.env.VITE_LEECO_WEB_URL;

  const handleSignInClicked = (extraQueryParams?: Record<string, string>) => {
    chrome.tabs.query({ active: true, currentWindow: true }, async (tabs) => {
      if (!tabs[0]?.id) {
        console.error("No active tab found");
        return;
      }

      const { utmParams } = await chrome.storage.local.get("utmParams");

      // Create URL with UTM parameters
      const url = new URL(`${webUrl}/authenticate-extension`);
      url.searchParams.append("originalTabId", tabs[0].id.toString());

      if (utmParams) {
        url.searchParams.append("utm_campaign", utmParams.utm_campaign);
        url.searchParams.append("utm_content", utmParams.utm_content);
        url.searchParams.append("utm_medium", utmParams.utm_medium);
        url.searchParams.append("utm_source", utmParams.utm_source);
        url.searchParams.append("utm_term", utmParams.utm_term);
      }

      // Add extra query parameters if provided
      if (extraQueryParams) {
        Object.entries(extraQueryParams).forEach(([key, value]) => {
          url.searchParams.append(key, value);
        });
      }

      chrome.tabs
        .create({
          url: url.toString(),
          active: true,
        })
        .catch((err) => {
          console.error("Failed to create tab: ", err);
        });
    });
  };

  return {
    handleSignInClicked,
  };
};

export default useSignIn;
