import React from 'react'
import Tippy from "@tippyjs/react"
import { AnimatePresence, motion } from 'framer-motion'

type Props = {
    isTippyVisible?: boolean
    tippyClassName?: string
    tippyContent?: React.ReactNode
    handleOnMouseEnter?: () => void
    handleOnMouseLeave?: () => void
    handleOnClick?: () => void
    buttonClassName?: string
    hoveredIcon?: React.ReactNode
    defaultIcon?: React.ReactNode
    buttonText?: React.ReactNode
    showHoverIcon?: boolean
}

const FooterCta = ({ isTippyVisible, tippyClassName, tippyContent, showHoverIcon, handleOnMouseEnter, handleOnMouseLeave, handleOnClick, buttonClassName, hoveredIcon, defaultIcon, buttonText }: Props) => {
    return (
        <Tippy
            visible={isTippyVisible}
            content={
                <AnimatePresence>
                    {(isTippyVisible) && (
                        <motion.span
                            initial={{ opacity: 0, y: 5 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, y: 5 }}
                            transition={{ duration: 0.3 }}
                            className={tippyClassName}
                        >
                            {tippyContent}
                        </motion.span>
                    )}
                </AnimatePresence>
            }
        >
            <button
                onMouseEnter={handleOnMouseEnter}
                onMouseLeave={handleOnMouseLeave}
                onClick={handleOnClick}
                className={`${buttonClassName}`}
            >
                {buttonText}
                {(isTippyVisible || showHoverIcon) ? hoveredIcon : defaultIcon}
            </button>
        </Tippy>
    )
}

export default FooterCta