import { useContext } from "react";
import { PageContext } from "../../../context/page-context/page-context";

const useRecommendedPath = () => {

	const { pathsData, activeTabUrl } = useContext(PageContext);

	 const recommendedPaths = pathsData?.filter((item: any) => item?.trending);

	const handlePathClick = async (pathUrl: string, pathTitle: string) => {
		chrome.runtime.sendMessage({
			action: "sendAnalytics",
			url: activeTabUrl,
			eventName: "Path Clicked",
			eventProperties: {
				tab: "Paths",
				type: "recommended",
				path: pathTitle,
			}
		});
		
		await chrome.tabs.create({
			url: pathUrl,
			active: true,
		});
  };

	return {
		recommendedPaths,
		handlePathClick
	};
};

export default useRecommendedPath;