import { useContext, useEffect, useMemo, useState } from "react";
import { npsFeedbackSteps } from "../../constants/constant.d";
import MentorAiButton from "../../../../../../common/button/mentorai-button";
import { cn } from "../../../../../../utils/cn";
import { NPS_STATUS } from "../../../../../context/chat-context/use-chat-conversations";
import { sendAnalyticsWithBackend } from "../../../../../../core/Analytics";
import { MenteeContext } from "../../../../../context/mentee-context/mentee-context";
import { PageContext } from "../../../../../context/page-context/page-context";


type NPSCategory = 'high' | 'medium' | 'low';

type FeedbackFormProps = {
    nps: number | null;
    setStep: Function;
    reasons: string[];
    handleReasonChange: Function;
    handlePostNps: Function;
    removeEmojis: Function;
    setNpsStatus: Function;
}

const getCategoryFromRating = (rating: number): NPSCategory => {
    if (rating >= 9) return "high";
    if (rating >= 7) return "medium";
    return "low";
};

const FeedbackForm = ({ nps, removeEmojis, setNpsStatus }: FeedbackFormProps) => {
    const { menteeData } = useContext(MenteeContext)
    const { activeTabUrl } = useContext(PageContext)
    const [currentStep, setCurrentStep] = useState<number>(0);
    const [formConfig, setFormConfig] = useState<any>({
        type: npsFeedbackSteps[getCategoryFromRating(nps || 0)][0].type,
        question: npsFeedbackSteps[getCategoryFromRating(nps || 0)][0].question,
        options: npsFeedbackSteps[getCategoryFromRating(nps || 0)][0].options,
        comment: "",
        reasons: [],
    });
    const [comment, setComment] = useState<string>("");
    const [reasons, setReasons] = useState<string[]>([]);
    const category = getCategoryFromRating(nps || 0);
    const formLength = npsFeedbackSteps[category as NPSCategory].length;

    const handleReasonChange = (option: string) => {
        if (formConfig.type === "value") {
            setReasons([option]);
        } else {
            if (reasons.includes(option)) {
                setReasons((prev) => prev.filter((item) => item !== option));
            } else {
                setReasons((prev) => [...prev, option]);
            }
        }
    };

    const handleNext = () => {
        if (category !== "low") {
            if (currentStep < formLength - 1) {
                setCurrentStep(prev => prev + 1);
                setFormConfig({
                    type: npsFeedbackSteps[category][currentStep + 1].type,
                    question: npsFeedbackSteps[category][currentStep + 1].question,
                    options: npsFeedbackSteps[category][currentStep + 1].options ?
                        (() => {
                            const opts = [...(npsFeedbackSteps[category][currentStep + 1].options || [])];
                            const lastOption = opts.pop();
                            for (let i = opts.length - 1; i > 0; i--) {
                                const j = Math.floor(Math.random() * (i + 1));
                                [opts[i], opts[j]] = [opts[j], opts[i]];
                            }
                            return lastOption ? [...opts, lastOption] : opts;
                        })() : [],
                });
                sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "NPS Detailed Feedback Submitted", { version: "v2", nps: nps, question: formConfig.type, reason: reasons, comment: comment });
                setReasons([]);
                setComment("");
            } else {
                setNpsStatus(NPS_STATUS.SUBMITTED)
                sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "NPS Detailed Feedback Submitted", { version: "v2", nps: nps, question: formConfig.type, reason: reasons, comment: comment });
            }
        } else {
            // For low category, directly handle submission
            setNpsStatus(NPS_STATUS.SUBMITTED)
            sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "NPS Detailed Feedback Submitted", { version: "v2", nps: nps, question: formConfig.type, reason: reasons ? reasons : [], comment: comment });
        }
    };

    useEffect(() => {
        setCurrentStep(0);
        setFormConfig({
            type: npsFeedbackSteps[getCategoryFromRating(nps || 0)][0].type,
            question: npsFeedbackSteps[getCategoryFromRating(nps || 0)][0].question,
            options: npsFeedbackSteps[getCategoryFromRating(nps || 0)][0].options ?
                (() => {
                    const opts = [...(npsFeedbackSteps[getCategoryFromRating(nps || 0)][0].options || [])];
                    const lastOption = opts.pop();
                    for (let i = opts.length - 1; i > 0; i--) {
                        const j = Math.floor(Math.random() * (i + 1));
                        [opts[i], opts[j]] = [opts[j], opts[i]];
                    }
                    return lastOption ? [...opts, lastOption] : opts;
                })() : [],
        });
    }, [nps]);

    const isButtonDisabled = () => {
        if (formConfig.type === "improvements") {
            return !comment.trim();
        }
        return reasons.length === 0;
    };

    const handleSkip = () => {
        setNpsStatus(NPS_STATUS.SUBMITTED)
        sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "NPS Detailed Feedback Skipped", { version: "v2", question: formConfig.type });
    }

    return (
        <>
            <p className="font-bricolage-grotesque text-mentorai-text-white text-[16px] font-medium leading-[23px] tracking-[-0.16px]">
                {formConfig.question}
            </p>

            <div className="flex flex-col gap-1 mt-2 w-full">
                {formConfig?.options?.map((option: string) => (
                    <label
                        key={option}
                        className={`min-h-[22px] h-fit px-1 cursor-pointer flex items-center rounded  text-xs leading-[18px] font-medium font-manrope hover:!bg-[rgba(223,222,229,0.10)] ${reasons.includes(option) ? "text-[#F2F2F2]" : "text-[#94939F]"}`}
                    >
                        <input
                            type={formConfig.type === "value" ? "radio" : "checkbox"}
                            className="peer hidden"
                            checked={reasons.includes(option)}
                            onChange={() => handleReasonChange(option)}
                            name={formConfig.type === "value" ? "value" : undefined}
                        />

                        <div className={cn(
                            "mr-2 h-3 w-3 flex items-center justify-center border border-[#94939F]",
                            formConfig.type === "value" ? "rounded-full" : "rounded-[3px]",
                            reasons.includes(option) && "bg-[#5149F2] border-[#5149F2]"
                        )}>
                            {reasons.includes(option) && (
                                formConfig.type === "value" ? (
                                    <div className="w-1.5 h-1.5 rounded-full bg-mentorai-bg-sub" />
                                ) : (
                                    <svg xmlns="http://www.w3.org/2000/svg" width="6" height="4" viewBox="0 0 6 4" fill="none">
                                        <path fillRule="evenodd" clipRule="evenodd" d="M5.74979 0.643703L2.3935 4L0.250977 1.85748L0.89468 1.21378L2.3935 2.71259L5.10609 0L5.74979 0.643703Z" fill="#F2F2F2" />
                                    </svg>
                                )
                            )}
                        </div>
                        {option}
                    </label>
                ))}

                {(reasons.includes("Other (Please specify)") || formConfig.type === "improvements") &&
                    <textarea
                        className={cn(
                            "p-2 mt-3 font-manrope bg-mentorai-bg-black text-[#F2F2F2] outline-none border border-[#45475F] rounded-lg placeholder:text-[#66666B] text-xs tracking-[0.12px] leading-[17px] font-medium",
                            formConfig.type === "improvements" && "overflow-y-hidden"
                        )}
                        rows={formConfig.type === "improvements" ? 1 : 3}
                        value={comment}
                        placeholder={formConfig.type === "improvements" ? "e.g. I would want voice to text" : removeEmojis(formConfig.question)}
                        onChange={(e) => setComment(e.target.value)}
                    />
                }
            </div>
            <div className="flex justify-between items-center gap-2 w-full mt-3">
                <MentorAiButton size="xSmall" type="outlined" classNames="flex-1 font-bricolage-grotesque" onClick={() => { handleSkip() }}>
                    Skip For Now
                </MentorAiButton>
                <MentorAiButton
                    size="xSmall"
                    type="primary"
                    disabled={isButtonDisabled()}
                    classNames={cn("flex-1 font-bricolage-grotesque", isButtonDisabled() && "!bg-[#4D45E5] !opacity-[.3] !text-[#f2f2f2]")}
                    onClick={handleNext}
                >
                    {currentStep < formLength - 1 ? 'Next' : 'Submit'}
                </MentorAiButton>
            </div>
        </>
    )
}

export default FeedbackForm