import { useEffect, useMemo, useState } from "react";

const useMentee = () => {
  const [menteeData, setMenteeData] = useState(null);
  const [menteeDataLoading, setMenteeDataLoading] = useState(false);

  const menteeContextValue = useMemo(
    () => ({
      menteeData,
      setMenteeData,
      menteeDataLoading,
    }),
    [menteeData, menteeDataLoading]
  );

  const fetchMenteeData = async () => {
    setMenteeDataLoading(true);

    const menteeDataResponse = await chrome.runtime.sendMessage({
      action: "fetch_calls",
      fetch_call: "fetch_mentee",
    });

    const menteeProfileData = menteeDataResponse.mentee_data;

    setMenteeData(menteeProfileData);
    setMenteeDataLoading(false);
  };

  useEffect(() => {
    const handleMenteeDataChange = (changes: any) => {
      if (changes.menteeData) {
        setMenteeData(changes.menteeData.newValue);
      }
    };

    chrome.storage.local.onChanged.addListener(handleMenteeDataChange);

    return () => {
      chrome.storage.local.onChanged.removeListener(handleMenteeDataChange);
    };
  }, [menteeData]);

  return {
    menteeContextValue,
    fetchMenteeData,
    menteeData,
  };
};

export default useMentee;
