import { motion } from "framer-motion";
import { getFormattedPriceWithSymbol } from "../../../../../../../../utils/currency";
import usePlanCard from "./use-plan-card";
import PlanCardSvg from "../../../../../../../assets/plan-card.svg";

type Props = {
  plan: ExtensionPlan;
  selectedValidity: string;
  handleChangePlan: (plan: string) => void;
  isOfferAvailable: boolean;
  pricingVariant: string;
};

const PlanCard = ({ plan, selectedValidity, handleChangePlan, isOfferAvailable, pricingVariant }: Props) => {
  const { isSelected, planTitle, planSubtitle, planCardHover, setPlanCardHover, isRecommended } = usePlanCard(
    plan,
    selectedValidity,
    isOfferAvailable,
    handleChangePlan,
    pricingVariant,
  );

  return (
    <button
      onMouseEnter={() => setPlanCardHover(plan.validity)}
      onMouseLeave={() => setPlanCardHover("")}
      onClick={() => handleChangePlan(plan.validity)}
      className={`w-full relative rounded-lg p-3 pt-[14px] duration-200 transition-all ${
        isSelected
          ? "bg-[rgba(81,73,242,0.24)] border border-[#5149F2]"
          : "bg-[#14161F] border border-[#363645] hover:border-[#45475F] hover:bg-[#2124313D]"
      }`}
    >
      {isRecommended && (
        <div className="absolute  left-[50%] -translate-x-1/2 -top-[10px] bg-[#FA0] text-[#111] px-[10px] py-[2px] rounded-full text-[10px] font-semibold leading-normal font-inter">
          Save 50%
        </div>
      )}
      <div className="flex justify-center items-center">
        <div className="space-y-[10px]">
          <p className="text-[#F2F2F2] text-[12px] font-semibold -tracking-[0.12px] leading-normal font-bricolage-grotesque">
            {planTitle}
          </p>
          <p className="text-[#94939F] text-[11px] font-medium font-manrope">{planSubtitle}</p>
        </div>
      </div>

      {/* {!isSelected && (
        <motion.img
          src={PlanCardSvg}
          alt="action-card-svg"
          className="absolute top-0 z-[0] translate-all duration-300"
          style={{
            right: plan.validity === planCardHover ? 0 : -55,
          }}
        />
      )} */}
    </button>
  );
};

export default PlanCard;
