import { useEffect, useState, useCallback } from "react";
import { MentorAiContext } from "./context/mentorai-context/mentorai-context";
import { MenteeContext } from "./context/mentee-context/mentee-context";
import useMentorai from "./context/mentorai-context/use-mentorai";
import useMentee from "./context/mentee-context/use-mentee";
import { SCREEN, Mentee, SessionType } from "./types/type";
import ResourcesView from "./screens/resources-view/resources-view";
import SignIn from "./screens/sign-in/sign-in";
import useAuth from "./context/auth-context/use-auth";
import { AuthContext } from "./context/auth-context/auth-context";
import ChatView from "./screens/chat-view/chat-view";
import SignupInProgress from "./screens/signup-in-progress/signup-in-progress";
import Loading from "./screens/loading/loading";
import BlacklistedSite from "./screens/blacklisted-site/blacklisted-site";
import { checkUrlListingStatus } from "../utils/helper";
import usePage from "./context/page-context/use-page";
import { PageContext } from "./context/page-context/page-context";
import { Toaster } from "react-hot-toast";
import { SidepanelSyncProvider } from "./context/sidepanel-sync-context/sidepanel-sync-context";
import { getBrowserInfo } from "../core/Analytics";
import SignupModal from "./components/conversation-container/signup-modal/signup-modal";
import useMenteeSubscription from "./context/mentee-context/use-mentee-subscription";
import MicrophonePermission from "./screens/microphone-permission/microphone-permission";
import { cn } from "../utils/cn";
import Paths from "./screens/paths/paths";
import SidebarNav from "./components/sidebar-nav/sidebar-nav";
import { ChatProvider } from "./context/chat-context/chat-context";
import chatIcon from "./assets/nav-chat.svg";
import pathsIcon from "./assets/nav-paths.svg";
import newIcon from "./assets/nav-new.svg";
import activeChatIcon from "./assets/nav-chat-solid-active.svg";
import activePathsIcon from "./assets/nav-paths-solid-active.svg";
import PathGif from "./assets/gif/paths-load.gif";
import PathHover from "./assets/gif/paths-hover.gif";
import ChatGif from "./assets/gif/chat-load.gif";
import ChatHover from "./assets/gif/chat-hover.gif";
import ChatSelectedLoadGif from "./assets/gif/chat-selected-load.gif";
import PathsSelectedLoadGif from "./assets/gif/paths-selected-load.gif";
import exploreIcon from "./assets/explore-default.svg";
import exploreActiveIcon from "./assets/explore-active.svg";
import exploreHoverGif from "./assets/gif/explore-hover.gif";
import exploreLoadGif from "./assets/gif/explore-load.gif";
import Explore from "./screens/explore/explore";
import FreeTrial from "./screens/free-trial/free-trial";
import JobAgent from "./screens/job-agent/job-agent";
import jobAgentIcon from "./assets/nav-new.svg"; // Reusing newIcon for now



export type NavTabTypes = {
  id: number;
  label: string;
  tippyContent: string;
  screen?: SCREEN;
  type?: string;
  bannerIcon?: any;
  defaultIcon: any;
  activeIcon: any;
  loadGif?: any;
  hoverGif?: any;
  activeLoadHoverGif?: any,
  delayOnFirstLoadAnimation?: number
}

function App() {
  const { mentoraiContextValue } = useMentorai();
  const { authContextValue, currentUser, isAuthLoading } = useAuth();
  const { menteeContextValue, fetchMenteeData, menteeData, menteeDataLoading, }: any = useMentee();
  const { menteeSubscription, setMenteeSubscription } = useMenteeSubscription(
    menteeData,
    mentoraiContextValue.mentoraiData,
  );
  const { pageContextValue, setActiveTabUrl, showSignupModal, setShowSignupModal, screen, setScreen } =
    usePage(menteeSubscription);
  const [sessionState, setSessionState] = useState<SessionType>("");
  const [initialTabVariant, setInitialTabVariant] = useState<string>("v1");
  const [navTabs, setNavTabs] = useState<NavTabTypes[]>([
    {
      id: 1,
      label: "Chat",
      screen: "CHAT" as SCREEN,
      defaultIcon: chatIcon,
      activeIcon: activeChatIcon,
      loadGif: ChatGif,
      hoverGif: ChatHover,
      tippyContent: "Chat",
      activeLoadHoverGif: ChatSelectedLoadGif,
      delayOnFirstLoadAnimation: 100,
    },
    {
      id: 2,
      label: "Paths",
      screen: "PATHS" as SCREEN,
      defaultIcon: pathsIcon,
      activeIcon: activePathsIcon,
      tippyContent: "Create Paths",
      loadGif: PathGif,
      hoverGif: PathHover,
      activeLoadHoverGif: PathsSelectedLoadGif,
      delayOnFirstLoadAnimation: 300
    },
    {
      id: 3,
      label: "Explore",
      screen: "EXPLORE" as SCREEN,
      defaultIcon: exploreIcon,
      activeIcon: exploreActiveIcon,
      tippyContent: "Explore Paths",
      loadGif: exploreLoadGif,
      hoverGif: exploreHoverGif,
      activeLoadHoverGif: exploreHoverGif,
      delayOnFirstLoadAnimation: 500
    },
    {
      id: 4,
      label: "Job Agent",
      screen: "JOB_AGENT" as SCREEN,
      defaultIcon: jobAgentIcon,
      activeIcon: jobAgentIcon, // Using same icon for active state for now
      tippyContent: "Job Agent",
      // No gifs for now
    }
  ]);

  const updateFirstTabScreen = useCallback((newScreen: SCREEN) => {
    setNavTabs((prev: any) => prev.map((tab: any, idx: number) => (idx === 0 ? { ...tab, screen: newScreen } : tab)));
  }, []);

  const isSubscriptionEmptyAndShowTrialTrue = useCallback(async (subscription: any) => {
    const { show_trial_screen } = await chrome.storage.local.get(["show_trial_screen"]);
    if (!subscription && show_trial_screen === "true") return true;
    if ((!subscription.subscriptions || subscription.subscriptions.length === 0) && show_trial_screen === "true") return true;
    return false;
  }, []);

  useEffect(() => {
    updateSidePanel();
  }, [currentUser, isAuthLoading, menteeData, menteeSubscription]);

  useEffect(() => {
    if (currentUser) {
      fetchMenteeData();
    }
  }, [currentUser]);

  useEffect(() => {
    const fetchInitialTabVariant = async () => {
      const result = await chrome.storage.local.get(["initial_default_tab_variant"]);
      if (result.initial_default_tab_variant) {
        setInitialTabVariant(result.initial_default_tab_variant);
      } else {
        setInitialTabVariant("v1");
      }
    };
    fetchInitialTabVariant();
  }, []);

  const updateSidePanel = useCallback(async () => {
    chrome.tabs.query({ active: true, currentWindow: true }, async (tabs) => {
      let mentorai = "pro-pilot";
      const activeTabUrl = tabs?.[0]?.url || "";
      chrome.storage.local.get(["mentorai"], (result) => {
        if (result.mentorai) {
          mentorai = result.mentorai;
        }
      });

      setActiveTabUrl(activeTabUrl);
      const listingStatus = checkUrlListingStatus(activeTabUrl, mentorai);
      const expectedFirstScreens = ['CHAT', 'RESOURCES_VIEW', 'BLACKLISTED_SITE', 'SIGN_IN', 'SIGNUP_IN_PROGRESS', 'LOADING', 'FREE_TRIAL'];
      if (listingStatus === "blacklisted" && !activeTabUrl.includes("preplaced.in")) {
        if (expectedFirstScreens.includes(screen)) {
          setScreen("BLACKLISTED_SITE");
        }
        updateFirstTabScreen("BLACKLISTED_SITE");
      } else if (isAuthLoading) {
        setScreen("LOADING");
      } else if (activeTabUrl.includes("authenticate-extension")) {
        if (currentUser) {
          if (expectedFirstScreens.includes(screen)) {
            if (initialTabVariant === "v1") {
              setScreen("RESOURCES_VIEW");
            } else {
              setScreen("PATHS");
            }
          }
          updateFirstTabScreen("RESOURCES_VIEW");
        } else {
          setScreen("SIGNUP_IN_PROGRESS");
        }
      } else if (currentUser) {
        if (!menteeData || menteeSubscription === undefined) {
          setScreen("LOADING");
        } else {
          if (await isSubscriptionEmptyAndShowTrialTrue(menteeSubscription)) {
            setScreen("FREE_TRIAL");
            updateFirstTabScreen("FREE_TRIAL");
          } else {
            const url = tabs[0]?.url;
            const selfTab = await chrome.tabs.getCurrent();
            const doesQueryContainsMicrophonePermission = url?.includes("action=microphone-permission");
            if (doesQueryContainsMicrophonePermission && selfTab) {
              setScreen("MICROPHONE_PERMISSION");
            } else if (!expectedFirstScreens.includes(screen)) {
              // User is on a non-default screen (EXPLORE, PATHS, JOB_AGENT, etc.)
              // Don't override their navigation - they explicitly clicked there
              // Just make sure first tab reflects CHAT as default
              updateFirstTabScreen("CHAT");
            } else {
              if (expectedFirstScreens.includes(screen)) {
                setScreen("CHAT");
              }
              updateFirstTabScreen("CHAT");
            }
          }
        }
      } else {
        setScreen("SIGN_IN");
      }
    });
  }, [currentUser, screen, isAuthLoading, menteeData, menteeSubscription, initialTabVariant, isSubscriptionEmptyAndShowTrialTrue]);

  const handleMessage = useCallback(
    (message: any, sender: any, sendResponse: any) => {
      if (message.action === "activateResourceView") {
        setScreen("RESOURCES_VIEW");
      }
      if (message.action === "updateSidePanelOnTabUpdate") {
        updateSidePanel();
      }
      if (message.action === "updateSidePanelOnTabActivated") {
        updateSidePanel();
      }
      if (message.action === "activateJobAgent") {
        // Only switch to JOB_AGENT if explicitly requested and not already on another screen
        // This prevents auto-apply from hijacking the screen when user is browsing other tabs
        if (message.force || screen === "LOADING") {
          setScreen("JOB_AGENT");
        }
      }
    },
    [updateSidePanel, screen],
  );

  useEffect(() => {
    chrome.runtime.onMessage.addListener(handleMessage);
    return () => {
      chrome.runtime.onMessage.removeListener(handleMessage);
    };
  }, [handleMessage]);

  const handlePurchaseSheetOpen = useCallback(() => {
    setTimeout(() => {
      const purchaseButton = document.querySelector(".purchase-subscription-button");
      if (purchaseButton) {
        (purchaseButton as HTMLElement).click();
      }
    }, 500);
  }, []);

  useEffect(() => {
    const purchaseSheetListener = (message: any) => {
      if (message.action === "openPurchaseSheet") {
        handlePurchaseSheetOpen();
      }
    };

    chrome.runtime.onMessage.addListener(purchaseSheetListener);
    return () => {
      chrome.runtime.onMessage.removeListener(purchaseSheetListener);
    };
  }, [handlePurchaseSheetOpen]);

  useEffect(() => {
    const browserInfo = getBrowserInfo();
    chrome.storage.local.set({ browserInfo });
  }, []);


  const shouldShowMarginAroundSidePanel = !['LOADING', 'SIGNUP_IN_PROGRESS', 'SIGN_IN', 'MICROPHONE_PERMISSION', 'FREE_TRIAL'].includes(screen);
  return (
    <PageContext.Provider value={pageContextValue}>
      <AuthContext.Provider value={authContextValue}>
        <MenteeContext.Provider
          value={{
            ...menteeContextValue,
            menteeSubscription,
            setMenteeSubscription,
          }}
        >
          <MentorAiContext.Provider value={mentoraiContextValue}>
            <SidepanelSyncProvider>
              <ChatProvider
                menteeData={menteeData}
                mentoraiData={mentoraiContextValue.mentoraiData}
                menteeSubscription={menteeSubscription}
                menteeDataLoading={menteeDataLoading}
                setScreen={setScreen}
              >
                <section className="flex h-screen w-full">
                  <main
                    style={{
                      marginTop: shouldShowMarginAroundSidePanel ? "4px" : "0px",
                      marginLeft: shouldShowMarginAroundSidePanel ? "4px" : "0px",
                      marginBottom: shouldShowMarginAroundSidePanel ? "5px" : "0px",
                    }}
                    className={cn(
                      "flex flex-1 flex-col min-w-0 relative rounded-[14px]",
                      screen === "MICROPHONE_PERMISSION" ? "bg-mentorai-bg-black" : "bg-[#14161F]",
                    )}
                  >
                    {screen === "LOADING" && <Loading />}
                    {screen === "FREE_TRIAL" && <FreeTrial />}
                    {screen === "CHAT" &&
                      <ChatView
                        sessionState={sessionState}
                      />
                    }
                    {screen === "MICROPHONE_PERMISSION" && <MicrophonePermission />}
                    {screen === "SIGNUP_IN_PROGRESS" && <SignupInProgress />}
                    {screen === "BLACKLISTED_SITE" && <BlacklistedSite />}
                    {screen === "SIGN_IN" && <SignIn />}
                    {screen === "RESOURCES_VIEW" && <ResourcesView menteeData={menteeData} />}
                    {screen === "EXPLORE" && <Explore />}
                    {screen === "PATHS" && <Paths />}
                    {screen === "JOB_AGENT" && <JobAgent />}
                    <Toaster />
                    {showSignupModal && (
                      <SignupModal show={showSignupModal} handleClose={() => setShowSignupModal(false)} />
                    )}
                  </main>
                  <SidebarNav
                    navTabs={navTabs}
                    currentScreen={screen}
                    onScreenChange={setScreen}
                    mentoraiData={mentoraiContextValue.mentoraiData}
                    menteeData={menteeData}
                    menteeSubscription={menteeSubscription}
                    show={shouldShowMarginAroundSidePanel}
                  />
                </section>
              </ChatProvider>
            </SidepanelSyncProvider>
          </MentorAiContext.Provider>
        </MenteeContext.Provider>
      </AuthContext.Provider>
    </PageContext.Provider>
  );
}

export default App;
