import { AnimatePresence, motion } from "framer-motion";

import MentorAiButton from "../../../../../common/button/mentorai-button";
import { VoiceVisualizer } from "react-voice-visualizer";

import CrossIcon from "../../../../assets/cross.svg"
import CheckIcon from "../../../../assets/check.svg" 
import { useSidepanelSyncContext } from "../../../../context/sidepanel-sync-context/sidepanel-sync-context";
import { cn } from "../../../../../utils/cn";
import LoaderIcon from "../../../../assets/loading.gif"
import Tippy from "@tippyjs/react";
import { useState } from "react";

const PulsatingDot = ({isTranscriptionLoading}: {isTranscriptionLoading: boolean}) => (
    <motion.span 
      className={cn("inline-block w-[6px] h-[6px] rounded-full bg-[#A5A1F7]", isTranscriptionLoading && "bg-mentorai-text-soft")}
      style={{
        verticalAlign: 'middle',
        position: 'relative',
        top: '-1px',
        marginLeft: '2px'
      }}
      animate={!isTranscriptionLoading ? {
        scale: [1, 0.8, 1],
        opacity: [1, 0.5, 1],
      } : {}}
      transition={{
        duration: 1,
        ease: "easeInOut",
        repeat: Infinity,
      }}
    />
  );

type VoiceRecorderProps = {
  recorderControls: any;
  isTranscriptionLoading: boolean;
  stopRecording: (wasCancelled: boolean) => void;    
}

const VoiceRecorder = ({recorderControls, isTranscriptionLoading, stopRecording}: VoiceRecorderProps) => {
  const { setIsAudioLive }=useSidepanelSyncContext()
  const [hoverCancelButton, setHoverCancelButton] = useState(false);
  const [hoverDoneButton, setHoverDoneButton] = useState(false);

    
  const handleStopRecording = () => {
    stopRecording(false); // not cancelled
    recorderControls.stopRecording();
  };
  
  const handleCancelRecording = () => {
    setIsAudioLive(false);
    stopRecording(true); // mark as cancelled
    recorderControls.stopRecording();
  };
  
  return (
    <div className={cn("absolute bottom-[40px] h-[74px] p-[2px] left-0 right-0 z-10 rounded-xl mx-2 flex flex-col bg-gradient-to-r from-[#382A98] via-[#5A34CB] to-[#775BDC]", isTranscriptionLoading && "p-[1px] bg-mentorai-bg-sub")}>
        <div className="px-1 pt-[9px] pb-[7px] max-h-[34px] w-full flex items-center justify-center">
            <div className="flex items-center gap-1">
                <PulsatingDot isTranscriptionLoading={isTranscriptionLoading} />
                <span className={cn("text-mentorai-primary-lighter text-[12px] font-semibold leading-[18px] tracking-[0.12px]", isTranscriptionLoading && "text-mentorai-text-soft")}>
                    {!isTranscriptionLoading ? "Listening..." : "Transcribing..."}
                </span>
            </div>
        </div>
        <div className={cn("bg-[#1E0655] h-[36px] rounded-b-xl flex items-center justify-between px-2 py-2 overflow-hidden", isTranscriptionLoading && "bg-mentorai-bg-strong")}>
          <Tippy
            visible={hoverCancelButton}
            content={
              <AnimatePresence>
                {(hoverCancelButton) && (
                  <motion.span
                    initial={{ opacity: 0, y: 5 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: 5 }}
                    transition={{ duration: 0.3 }}
                    className={"bg-[#4B4E63] flex items-center h-[23px] justify-center text-mentorai-text-white font-manrope text-xs leading-[normal] tracking-[-0.12px] px-1.5 rounded-md"}
                  >
                    Redo
                  </motion.span>
                )}
              </AnimatePresence>
            }
          >
            <div 
              onMouseEnter={() => setHoverCancelButton(true)} 
              onMouseLeave={() => setHoverCancelButton(false)}
            >
              <MentorAiButton 
                disabled={isTranscriptionLoading} 
                type="outlined" 
                size="medium" 
                classNames="rounded-full !h-5 !w-5 !p-0" 
                onClick={handleCancelRecording}
              >
                <img src={CrossIcon} alt="cross"/>
              </MentorAiButton>
            </div>
          </Tippy>
          <VoiceVisualizer
              controls={recorderControls}
              isControlPanelShown={false}
              barWidth={1.5}
              gap={1.5}
              mainBarColor={isTranscriptionLoading ? "#94939F" : "#f2f2f2"}
              isDefaultUIShown={false}
              isDownloadAudioButtonShown={false}
              isProgressIndicatorShown={false}
              isProgressIndicatorTimeShown={false}
              isProgressIndicatorOnHoverShown={false}
              isProgressIndicatorTimeOnHoverShown={false}
              isAudioProcessingTextShown={false}
              secondaryBarColor="#f2f2f2"
              height={isTranscriptionLoading ? 20 : 50}
              fullscreen={true}
          />
          <Tippy
            visible={hoverDoneButton}
            content={
              <AnimatePresence>
                {(hoverDoneButton) && (
                  <motion.span
                    initial={{ opacity: 0, y: 5 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: 5 }}
                    transition={{ duration: 0.3 }}
                    className={"bg-[#4B4E63] flex items-center h-[23px] justify-center text-mentorai-text-white font-manrope text-xs leading-[normal] tracking-[-0.12px] px-1.5 rounded-md"}
                  >
                    Done
                  </motion.span>
                )}
              </AnimatePresence>
            }
          >
            <div 
              onMouseEnter={() => setHoverDoneButton(true)} 
              onMouseLeave={() => setHoverDoneButton(false)}
            >
              <MentorAiButton 
                type="neutral" 
                size="medium" 
                classNames={cn("rounded-full !h-5 !w-5 !p-0", isTranscriptionLoading && "!pointer-events-none cursor-not-allowed")} 
                onClick={handleStopRecording}
              >  
                {
                  isTranscriptionLoading ? <img src={LoaderIcon} className="w-[14px] h-[14px]" alt="loader"/> : <img src={CheckIcon} alt="check"/>
                }
              </MentorAiButton>
            </div>
          </Tippy>
        </div>
    </div>
  )
}

export default VoiceRecorder