import { useEffect, useState } from "react"

const useExtensionPlansContainer = () => {
  const [extensionPlans, setExtensionPlans] = useState<ExtensionPlan[] | null>(null);

  const plansMapper = (plans: any) => {
    if (!plans) return [];

    const filteredPlans = plans.reverse().filter((plan: any) => plan.validity === "1 month" || plan.validity === "1 year");

    return filteredPlans.map((plan: any) => {
      const mappedPlan: ExtensionPlan = {
        totalPrice: plan.totalPrice,
        originalPrice: plan.originalPrice,
        discount: plan.discount,
        validity: plan.validity,
        offer: plan.offer,
        pricingVariant: plan?.pricingVariant || "",
      }
      return mappedPlan;
    });
  }

  const fetchExtensionPlans = async () => {
    const response = await chrome.runtime.sendMessage({
      action: "fetch_calls",
      fetch_call: "fetch_extension_plans",
    })

    const plansResponseData = response.extension_plans;

    const mappedPlans = plansMapper(plansResponseData.pricing);
    setExtensionPlans(mappedPlans);
  };

  useEffect(() => {
    fetchExtensionPlans();
  }, []);


  const isOfferAvailable = extensionPlans?.find((plan) => plan?.validity === "1 month")?.offer || false;
  const pricingVariant = extensionPlans?.find((plan) => plan?.validity === "1 month")?.pricingVariant || "";


  return {
    extensionPlans,
    isOfferAvailable,
    pricingVariant,
  }
}

export default useExtensionPlansContainer
