import { useRef, useEffect, useContext, useState } from 'react';
import { motion } from 'framer-motion';
import { redirectToCheckout } from '../../utils/checkout-redirect';
import { shouldShowCancelledSoftTrigger } from '../../../utils/subscription-ui-helpers';
import { ChatContext } from '../../context/chat-context/chat-context';
import { getUserStatus } from '../../../utils/subscription-helpers';
import MentorAiButton from '../../../common/button/mentorai-button';
import { trackSoftTriggerEvent } from '../../../core/Analytics';


const CancelledSoftTrigger = ({ chatUsageData }: { chatUsageData: any }) => {
    const { menteeSubscription } = useContext(ChatContext);
    const userStatus = getUserStatus(menteeSubscription);
    const [showComponent, setShowComponent] = useState(false);
    const [shouldShowComponent, setShouldShowComponent] = useState(false);
    const { daysRemaining, isTrial, triggerPeriod } = userStatus
    const isComponentMounted = useRef(false);

    useEffect(() => {
        if (isComponentMounted.current) {
            return;
        }
        if (shouldShowComponent) {
            trackSoftTriggerEvent(
                `cancelled_soft_trigger_${isTrial ? 'trial' : 'pro'}_${triggerPeriod}`,
                "Soft Trigger Shown",
                {
                    soft_trigger_type: `${isTrial ? 'Trial Cancelled' : 'Pro Cancelled'}`,
                }
            );
        }
        isComponentMounted.current = true;
        setTimeout(() => {
            setShowComponent(true);
        }, 1300);
    }, [isTrial, triggerPeriod, shouldShowComponent]);

    useEffect(() => {
        return () => {
            isComponentMounted.current = false;
        };
    }, []);

    useEffect(() => {
        const checkShouldShow = async () => {
            try {
                const result = await shouldShowCancelledSoftTrigger(userStatus);
                setShouldShowComponent(result);
            } catch (error) {
                console.error('Error checking shouldShowCancelledSoftTrigger:', error);
                setShouldShowComponent(false);
            }
        };
        checkShouldShow();
    }, [userStatus]);

    let title = triggerPeriod === 'last_day' ? (isTrial ? 'Your Pro Trial ends today' : 'Your Pro Plan expires today')
        : (isTrial ? `${daysRemaining} days of Pro Trial remaining` : `${daysRemaining} days of Pro remaining`)

    if (!shouldShowComponent || !showComponent) return null;

    return (
        <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            transition={{ duration: 0.3 }}
            className={`relative cursor-pointer rounded-[11px] mt-5 mb-3 w-full ${triggerPeriod === 'last_day' ? " bg-[linear-gradient(32deg,_rgba(255,_83,_83,_0.12)_35.65%,_rgba(166,_47,_47,_0.24)_60.96%,_rgba(255,_57,_57,_0.80)_98.67%)] hover:bg-[linear-gradient(32deg,_rgba(255,_83,_83,_0.16)_35.65%,_rgba(166,_47,_47,_0.38)_60.96%,_rgba(255,_57,_57,_0.90)_98.67%)]" : "bg-[linear-gradient(32deg,_rgba(57,_44,_17,_0.16)_35.65%,_rgba(253,_138,_15,_0.20)_60.96%,_rgba(255,_172,_57,_0.75)_98.67%)] hover:bg-[linear-gradient(32deg,_rgba(57,_44,_17,_0.36)_35.65%,_rgba(253,_138,_15,_0.28)_60.96%,_rgba(255,_172,_57,_0.90)_98.67%)]"}`}
        >
            <div
                onClick={() => redirectToCheckout({
                    chatUsageData,
                    location: "Soft Trigger",
                    menteeSubscription: menteeSubscription
                })}
                className="w-full cursor-pointer"
            >
                <div className="flex items-center justify-between border border-[rgba(255,255,255,0.16)] px-3 pt-3 pb-[14px] rounded-[12px] w-full">
                    <div className="flex flex-col gap-0.5 max-w-[198px]">
                        <h3 className="text-white font-bold text-[11px] leading-[16px] whitespace-nowrap font-manrope text-left">
                            {title}
                        </h3>
                        <h3 className="text-[rgba(255,255,255,0.55)] font-semibold text-[11px] leading-[16px] font-manrope text-left">
                            Keep access to unlimited <br /> credits, paths and more.
                        </h3>
                    </div>
                    <MentorAiButton
                        onClick={() => { }}
                        type='neutral'
                        size='xSmall'
                        classNames='w-fit font-bricolage-grotesque font-semibold'
                    >
                        {isTrial ? 'Upgrade' : 'Renew Plan'}
                    </MentorAiButton>
                </div>
            </div>
        </motion.div>
    );
};

export default CancelledSoftTrigger;
