export const validatePracticeCount = (value: any): number => {
  // Convert to number if it's a string
  const numValue = typeof value === 'string' ? parseInt(value, 10) : Number(value);
  
  // Check if it's a valid number
  if (isNaN(numValue) || numValue < 0) {
    return 0;
  }
  
  return numValue;
};

export const safeIncrementPracticeCount = async (
  currentCount: number,
  setPracticeCount: (value: number | ((prev: number) => number)) => void
): Promise<number> => {
  const validatedCurrent = validatePracticeCount(currentCount);
  const newCount = validatedCurrent + 1;
  
  // Update state
  setPracticeCount(newCount);
  
  // Update storage
  await chrome.storage.local.set({ practiceCount: newCount });
  return newCount;
};

export const getPracticeCountFromStorage = async (): Promise<number> => {
  try {
    const result = await chrome.storage.local.get('practiceCount');
    return validatePracticeCount(result.practiceCount);
  } catch (error) {
    return 0;
  }
};

export const setPracticeCountInStorage = async (value: any): Promise<void> => {
  try {
    const validatedValue = validatePracticeCount(value);
    await chrome.storage.local.set({ practiceCount: validatedValue });
  } catch (error) {
  }
};
