import usePurchaseSuccessNotification from './use-purchase-success-notification';
import BottomSheet from '../../../common/bottom-sheet/bottom-sheet';
import SuccessFeatureItem from './components/success-feature-item';

// Icons
import ChatCheckIcon from '../../assets/chat-check-fill.svg?react';
import UserStarIcon from '../../assets/user-star-fill.svg?react';
import RoadMapIcon from '../../assets/road-map-fill.svg?react';
import SparklingIcon from '../../assets/sparkling-fill.svg?react';
import CloseIcon from '../../assets/close-line.svg?react';
import SuccessIconImg from '../../assets/success-icon.png';

type Props = {
  sendMessage: Function
}

const PurchaseSuccessNotification = ({
  sendMessage
}: Props) => {
  const { isOpen, handleClose } = usePurchaseSuccessNotification(sendMessage);

  return (
    <BottomSheet open={isOpen} handleClose={handleClose}>
      <div className="relative h-full overflow-y-auto bg-gradient-to-b from-[#083c20] to-black">

        {/* Close button */}
        <button className="absolute top-4 right-4 bg-[#3a604b] rounded-full p-1.5" onClick={handleClose}>
          <CloseIcon className="w-2 h-2 text-white" />
        </button>

        {/* Main content */}
        <div className="flex flex-col justify-between items-center gap-5 px-5 py-7 pb-5 min-h-full">
          {/* Top section */}
          <div className="flex flex-col gap-7 w-full max-w-[311px]">
            {/* Hero section */}
            <div className="flex flex-col items-center gap-2.5">
              <img
                src={SuccessIconImg}
                alt="Success"
                className="w-10 h-10"
              />
              <div className="flex flex-col items-center gap-1 w-full">
                <h1 className="text-white font-medium text-xl leading-[1.4] tracking-[0.04em] text-center font-bricolage-grotesque">
                  Welcome to Pro!
                </h1>
                <p className="text-white/50 font-medium text-[13px] leading-[1.54] text-center">
                  You've unlocked the full PRO experience — no limits, no restrictions at all.
                </p>
              </div>
            </div>

            {/* Divider */}
            <div className="w-full h-px bg-[#F2F2F2]/5" />

            {/* Features section */}
            <div className="flex flex-col gap-5 w-full">
              <h2 className="text-white/60 font-medium text-[10px] leading-[1.8] tracking-[0.05em] uppercase">
                FEATURES UNLOCKED:
              </h2>
              <div className="flex flex-col gap-5">
                <SuccessFeatureItem
                  icon={<ChatCheckIcon />}
                  iconColor="text-[#4ACD87]"
                  title="Unlimited Chat Credits"
                  description="Ask anything, anytime, anywhere — no limits"
                />
                <SuccessFeatureItem
                  icon={<UserStarIcon />}
                  iconColor="text-[#F7C143]"
                  title="Interview Mode"
                  description="Practice AI driven interviews and get better"
                />
                <SuccessFeatureItem
                  icon={<RoadMapIcon />}
                  iconColor="text-[#FB5DAC]"
                  title="Unlimited Roadmap Creation"
                  description="Create as many proven learning paths as you want"
                />
                <SuccessFeatureItem
                  icon={<SparklingIcon />}
                  iconColor="text-[#47C2FF]"
                  title="Advanced Learning Model"
                  description="Uses ChatGPT 3o Model for advanced reasoning"
                />
              </div>
            </div>
          </div>

          {/* Action button */}
          <button onClick={handleClose} className="w-full max-w-[311px] bg-[#5149F2] text-[#F2F2F2] font-medium text-base leading-[1.5] tracking-[0.006em] px-8 py-3 rounded-xl flex items-center justify-center gap-1.5 shadow-[inset_0px_-3px_0px_0px_rgba(255,255,255,0.25)] hover:bg-[#5149F2]/90 transition-colors">
            Let's Dive In →
          </button>
        </div>

      </div>
    </BottomSheet>
  )
}

export default PurchaseSuccessNotification