import PlayFillDarkGray from "../../../assets/play-fill-dark-gray.svg";
import ArrowRight from "../../../assets/arrow-right-white.svg";
import { MenteeCreatedPathType } from "../../../context/page-context/index.type";
import useContinueLatestPath from "./use-continue-latest-path";

type ContinueLatestPathProps = {
  latestPath: MenteeCreatedPathType;
};

const ContinueLatestPath = ({ latestPath }: ContinueLatestPathProps) => {

  const { handlePathClick, handleStartLesson, nextLesson } = useContinueLatestPath({latestPath});

  return (
    <div className="space-y-4">
      <div className="space-y-1">
        <p className="text-[#F2F2F2] text-[16px] font-medium -tracking-[0.16px] font-bricolage-grotesque">
          Continue your latest path
        </p>
        <p className="text-[#94939F] text-[12px] leading-[18px] font-medium font-manrope">
          Pick up right where you left off
        </p>
      </div>

      <div className="p-3 space-y-5 border border-[#363645] rounded-xl cursor-pointer" onClick={() => handlePathClick(latestPath?.recordId)}>
        <div className="flex gap-3 items-center">
          <div className="h-[56px] w-[56px] shrink-0">
            <img src={latestPath?.coverImage} alt="continue-latest-path-icon.svg" className="h-[56px] w-[56px] rounded-[10px]" />
          </div>
          <div className="flex-1 min-w-0">
            <p className="font-bricolage-grotesque text-[#DDDDDF] text-[14px] font-medium -tracking-[0.14px] truncate">
              {latestPath?.title}
            </p>
            <div className="mt-2 h-[6px] w-full bg-[#2F3241] rounded-full">
              <div
                className="h-full bg-[#3EE089] rounded-full"
                style={{ width: `${Number(latestPath?.completionPercentage)}%` }}
              />
            </div>
            <p className="mt-1.5 text-[#DDDDDF] text-[12px] font-medium font-manrope">
              {latestPath?.completionPercentage?.toFixed(0)}% complete
            </p>
          </div>
        </div>
        <div className="p-2 space-y-3 bg-[#212431] rounded-lg">
          <div className="flex gap-3">
            <img
              src={nextLesson?.thumbnail}
              alt="continue-latest-path-icon.svg"
              className="h-[32px] w-[48px] rounded-md"
            />
            <div className="flex-1 min-w-0">
              <div className="flex">
                <p className="text-[#94939F] text-[10px] leading-[13px] font-semibold font-bricolage-grotesque -tracking-[0.1px]">
                  UP NEXT
                </p>
                <img src={PlayFillDarkGray} alt="play-fill-dark-gray.svg" />
              </div>
              <p className="text-[#DDDDDF] text-[12px] leading-[16px] font-medium font-manrope truncate">
                {nextLesson?.title}
              </p>
            </div>
          </div>
          <button 
            onClick={(e) => {
              e.stopPropagation();
              handleStartLesson(latestPath?.recordId);
            }}
            className="w-full h-[28px] bg-[#5149F2] hover:bg-[#736DF2] text-[#DDDDDF] text-[12px] font-semibold leading-[18px] font-bricolage-grotesque p-3 rounded-lg flex items-center justify-center gap-[4px]"
          >
            Start Lesson
            <img src={ArrowRight} alt="arrow-right.svg" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default ContinueLatestPath;
