import MentorAiButton from "../../../../../common/button/mentorai-button"
import ScannerIcon from "../../../../assets/scanner.svg";
import WhatsappIcon from "../../../../assets/whatsapp.svg";
import CopiedIcon from "../../../../assets/copied2.svg";
import CopyIcon from "../../../../assets/copy.svg";
import CopiedWhiteIcon from "../../../../assets/copiedwhite.svg";
import CopyWhiteIcon from "../../../../assets/copywhite.svg";
import checked from "../../../../assets/gif/checked.gif";
import { QRCodeSVG } from "qrcode.react"
import CloseIcon from "../../../../assets/close-icon.svg";
import CloseIconHovered from "../../../../assets/close-icon-hovered.svg";
import useShareExtension from "./use-share-extension";

const ShareExtensionV2 = ({ handleCloseSheet, mentoraiData }: { handleCloseSheet: () => void, mentoraiData: any }) => {
    const { selectedShareOption, ctaRedirectUrl, copied, ctaButtons, handleCopyExtensionLink, handleCopyAgain, handleClose } = useShareExtension(handleCloseSheet)

    return (
        <div className="relative w-full bg-mentorai-bg-black rounded-t-xl flex flex-col font-bricolage-grotesque max-h-[calc(90vh)] overflow-y-auto scrollbar-hide p-5  border-t border-t-mentorai-stroke-strong">
            {selectedShareOption.popupView === "primary" ?
                <>
                    <div className="flex flex-col gap-0.5">
                        <div className="text-mentorai-text-white font-[500] text-[18px] tracking-[-0.36px] whitespace-nowrap leading-[22px] text-center">
                            Help us keep AI Mentor FREE by
                        </div>
                        <div className="text-center bg-clip-text text-transparent bg-gradient-text font-[500] text-[18px] tracking-[-0.36px] whitespace-nowrap leading-[22px]">sharing with a friend!</div>
                    </div>
                    <div className="flex flex-col items-center self-stretch">
                        <div className="flex flex-col items-center gap-3 self-stretch">
                            <div className="!h-[120px] !max-h-[120px] w-fit mx-auto mt-4">
                                {ctaRedirectUrl.whatsapp && (
                                    <QRCodeSVG
                                        value={ctaRedirectUrl.whatsapp}
                                        size={120}
                                        bgColor="#ffffff"
                                        fgColor="#000000"
                                        level="L"
                                        marginSize={4}
                                    />
                                )}
                            </div>
                            <div className="flex justify-center items-center gap-1 self-stretch">
                                <img src={ScannerIcon} alt="scanner" className="w-[14px] h-[14px]" />
                                <p className="text-mentorai-text-soft text-[12px] font-medium leading-[14px]">Scan to share on </p>
                                <img src={WhatsappIcon} alt="whatsapp" className="w-[14px] h-[14px]" />
                                <p className="text-mentorai-text-soft text-[12px] font-medium leading-[14px]">WhatsApp</p>
                            </div>
                        </div>
                        <div className="flex justify-center items-center mt-5 self-stretch">
                            <button onClick={handleCopyExtensionLink} className="flex flex-col justify-center items-center  gap-2 py-2 px-1 w-[68px] h-[67px] rounded-[4px]  hover:bg-mentorai-bg-sub">
                                <div className="flex justify-center items-center w-7 h-7">
                                    <img src={copied ? CopiedIcon : CopyIcon} alt="icon" className="w-7 h-7" />
                                </div>
                                <p className=" flex whitespace-nowrap text-mentorai-text-sub hover:text-mentorai-text-soft text-center  text-[10px] font-semibold leading-[normal] font-manrope">{copied ? "Copied!" : "Copy Link"}</p>
                            </button >
                            {ctaButtons.map((button, index) => (
                                <ShareButton key={index} {...button} />
                            ))}
                        </div>
                    </div>
                    <p className="w-full h-px bg-[#363645] my-3" ></p>
                    <p className="text-mentorai-text-sub font-medium text-center text-xs leading-[normal] tracking-[0.24px] font-manrope">20,000+ users and counting ❤️</p>
                </>
                :
                <>
                    <div className="mx-auto h-[120px] max-h-[120px] w-auto overflow-hidden">
                        <img src={checked} alt="checked" className="w-full h-full" />
                    </div>
                    <p className="text-mentorai-primary-lighter text-center text-xl font-semibold leading-7 tracking-[-0.2px]">Invite message copied!</p>
                    <p className="mt-0.5 text-white text-center text-sm font-medium leading-[1.375rem] tracking-[0.084px]">You can now paste it on {selectedShareOption.cta === "Slack" ? "Slack" : "LinkedIn"}</p>
                    <MentorAiButton
                        onClick={() => handleCopyAgain(selectedShareOption.cta)}
                        classNames="mt-6 w-full"
                        type="outlined"
                        size="small"
                    >
                        <div className="flex gap-1 justify-center items-center">
                            <img src={selectedShareOption.copiedAgain ? CopiedWhiteIcon : CopyWhiteIcon} alt="icon" className="w-[14px] h-[14px]" />
                            <span className="text-mentorai-text-soft text-xs font-medium leading-[18px]">{selectedShareOption.copiedAgain ? "Copied!" : "Copy again"}</span>
                        </div>
                    </MentorAiButton>
                </>
            }
        </div>
    )
}

export default ShareExtensionV2

const ShareButton = ({ icon, text, handleClick }: { icon: any, text: string, handleClick: any }) => {
    return (
        <button onClick={handleClick} className="flex flex-col justify-center items-center  gap-2 py-2 px-1 w-[68px] h-[67px] rounded-[4px] group hover:bg-mentorai-bg-sub">
            <div className="flex justify-center items-center w-7 h-7">
                <img src={icon} alt="icon" className="w-7 h-7" />
            </div>
            <p className=" text-mentorai-text-sub text-center  text-[10px] font-semibold leading-[normal] group-hover:text-mentorai-text-soft font-manrope">{text}</p>
        </button >
    )
}
