import { useState, useEffect, useContext, useMemo, useRef } from "react";
import toast from "react-hot-toast";
import { MentorAiContext } from "../../../../context/mentorai-context/mentorai-context";
import { MenteeContext } from "../../../../context/mentee-context/mentee-context";
import { PageContext } from "../../../../context/page-context/page-context";
import { useChatContext } from "../../../../context/chat-context/chat-context";
import { handleAibackendDelete } from "../../../../../core/Axios";
import { cn } from "../../../../../utils/cn";
import MentorAiButton from "../../../../../common/button/mentorai-button";
import { LoaderWithThreeDots } from "../../../common/loader";
import { ChatUsageData } from "../../../../context/chat-context/use-chat-conversations";
import { sendAnalyticsWithBackend } from "../../../../../core/Analytics";
import MentorAiActiveAvatar from "../../../../../content/components/mentorai-active-avatar/mentorai-active-avatar";
import LeecoMech from "../../../../assets/LeecoMech.webp";
import ClickAwayListener from "../../../../custom-hooks/use-clickaway-listner";
import { AnimatePresence, motion } from "framer-motion";
import RadioSelectedIcon from '../../../../assets/radio-selected2.svg';
import RadioUnselectedIcon from '../../../../assets/radio-unselected2.svg';
import RadioHoveredIcon from '../../../../assets/radio-hovered.svg';
import PaperPlane from "../../../../assets/paper-plane.svg"
import PaperPlaneActive from "../../../../assets/paper-plane-active.svg"
import BlockIcon from "../../../../assets/block-icon.svg?react"
import ArrowRightLineIcon from "../../../../assets/arrow-up-s-line.svg?react"
import SearchIcon from "../../../../assets/search.svg?react"
import RemoveIcon from "../../../../assets/remove.svg?react"
import Tippy from "@tippyjs/react";
interface ContextData {
  [key: string]: {
    "profile-data"?: {
      timestamp: string;
    };
  };
}

const SettingsV2 = ({ setShowSettings, setLiveMessages, fetchMessages, chatUsageData, handleToggleSettings }: { setShowSettings: Function, setLiveMessages: Function, fetchMessages: Function, chatUsageData: ChatUsageData, handleToggleSettings: Function }) => {
  const { mentoraiData } = useContext(MentorAiContext);
  const { menteeData } = useContext(MenteeContext);
  const { activeTabUrl } = useContext(PageContext);
  const { setChatMessages } = useChatContext();
  const [contextData, setContextData] = useState<ContextData | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [lastAnalyzedDate, setLastAnalyzedDate] = useState('Never');
  const [isClearingChat, setIsClearingChat] = useState(false);
  const [showClearChatPopup, setShowClearChatPopup] = useState(false);
  const [blockedListHovered, setBlockedListHovered] = useState<string | null>(null);
  const showAnalyzeButton = activeTabUrl?.includes("https://leetcode.com")
  const clearChatPopupRef = useRef<HTMLDivElement>(null);
  const TONE_OPTIONS = ['Friendly', 'Professional', 'Default', 'Strict'];
  const LANGUAGE_OPTIONS = ['Hinglish', 'English', 'Hindi', 'Kannada', 'Other (specify)'];
  const [language, setLanguage] = useState('English');
  const [otherLanguage, setOtherLanguage] = useState('');
  const [tone, setTone] = useState('Default');
  const [showCustomLanguageInput, setShowCustomLanguageInput] = useState(false);
  const [languageFromStorage, setLanguageFromStorage] = useState('');
  const [showLanguagePopup, setShowLanguagePopup] = useState(false);
  const [showTonePopup, setShowTonePopup] = useState(false);
  const [isLanguageOptionHovered, setIsLanguageOptionHovered] = useState<string | null>(null);
  const [isToneOptionHovered, setIsToneOptionHovered] = useState<string | null>(null);
  const [showBlockedSitesPopup, setShowBlockedSitesPopup] = useState(false);  
  const [disabledSites, setDisabledSites] = useState<string[]>([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [debouncedQuery, setDebouncedQuery] = useState("");
  const [filteredSites, setFilteredSites] = useState<{ site: string; indices: number[] }[]>([]);
  const listRef = useRef<HTMLDivElement>(null);
  const [listHeight, setListHeight] = useState<number | null>(null);

  const handleLanguageChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.value !== "Other (specify)") {
      const newLanguage = event.target.value;
      setLanguage(newLanguage);
      setShowCustomLanguageInput(false);
      setShowLanguagePopup(false);
      chrome.storage.local.set({ "menteePreferedLanguage": newLanguage });
      sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "MentorAi Setting Changed", {
        setting_type: "language",
        language: newLanguage
      });
    } else {
      setShowCustomLanguageInput(true);
    }
  };

  const handleToneChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const newTone = event.target.value;
    setTone(newTone);
    setShowTonePopup(false);
    chrome.storage.local.set({ "menteePreferedMentorTone": newTone });
    sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "MentorAi Setting Changed", {
      setting_type: "tone",
      tone: newTone
    });
  };

  const updateOtherLanguage = () => {
    if (otherLanguage.trim() !== "") {
      setLanguage(otherLanguage);
      chrome.storage.local.set({ "menteePreferedLanguage": otherLanguage });
      sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "MentorAi Setting Changed", {
        setting_type: "language",
        language: otherLanguage
      });
      setOtherLanguage('');
      setShowCustomLanguageInput(false);
      setShowLanguagePopup(false);
      toast(
        <div className="bg-transparent pr-[40px]">
          <div className="flex items-center gap-2 py-2 px-3 h-7 rounded bg-[#4b4e63] text-[#f2f2f2] text-xs font-medium leading-[1.125rem] mb-[96px]">
            Language Saved!
          </div>
        </div>
        ,
        {
          position: 'bottom-center',
          icon: <></>
        }
      );
    }
  };
  const isCurrentLanguageInOptionsList = useMemo(() => LANGUAGE_OPTIONS.slice(0, -1).includes(language), [language])
  const isLanguageSelected = (option: string) => {
    if (option === "Other (specify)") {
      return !LANGUAGE_OPTIONS.slice(0, -1).includes(language) || showCustomLanguageInput;
    }
    return language === option;
  };
  useEffect(() => {
    const getPreferences = async () => {
      const languageResult = await chrome.storage.local.get("menteePreferedLanguage");
      const toneResult = await chrome.storage.local.get("menteePreferedMentorTone");
      setLanguageFromStorage(languageResult.menteePreferedLanguage);
      if (languageResult.menteePreferedLanguage) {
        if (LANGUAGE_OPTIONS.slice(0, -1).includes(languageResult.menteePreferedLanguage)) {
          setLanguage(languageResult.menteePreferedLanguage);
          setShowCustomLanguageInput(false);
        } else {
          setLanguage(languageResult.menteePreferedLanguage);
          setShowCustomLanguageInput(false);
        }
      }
      if (toneResult.menteePreferedMentorTone) {
        setTone(toneResult.menteePreferedMentorTone);
      }
    };
    const getDisabledSites = async () => {
      const disabledSites = await chrome.storage.local.get("widget_disabled_sites");
      setDisabledSites(disabledSites.widget_disabled_sites || []);
    }
    getPreferences();
    getDisabledSites();
  }, []);

  useEffect(() => {
    const t = setTimeout(() => setDebouncedQuery(searchQuery.trim()), 300);
    return () => clearTimeout(t);
  }, [searchQuery]);

  const fuzzyMatch = (text: string, query: string): { isMatch: boolean; indices: number[] } => {
    if (!query) return { isMatch: true, indices: [] };
    const t = text.toLowerCase();
    const q = query.toLowerCase();
    const indices: number[] = [];
    let ti = 0;
    for (let qi = 0; qi < q.length; qi++) {
      const ch = q[qi];
      const found = t.indexOf(ch, ti);
      if (found === -1) return { isMatch: false, indices: [] };
      indices.push(found);
      ti = found + 1;
    }
    return { isMatch: true, indices };
  };

  const renderHighlighted = (text: string, indices: number[]) => {
    if (!indices?.length) return text;
    const runs: Array<[number, number]> = [];
    for (let i = 0; i < indices.length; i++) {
      const idx = indices[i];
      if (runs.length === 0 || idx !== runs[runs.length - 1][1] + 1) {
        runs.push([idx, idx]);
      } else {
        runs[runs.length - 1][1] = idx;
      }
    }
    const parts: JSX.Element[] = [];
    let last = 0;
    runs.forEach(([start, end], i) => {
      if (start > last) parts.push(<span key={`n-${i}-${last}`}>{text.slice(last, start)}</span>);
      parts.push(
        <span key={`h-${i}-${start}`} style={{ color: '#FFD268' }}>
          {text.slice(start, end + 1)}
        </span>
      );
      last = end + 1;
    });
    if (last < text.length) parts.push(<span key={`n-end-${last}`}>{text.slice(last)}</span>);
    return parts;
  };

  useEffect(() => {
    if (!debouncedQuery) {
      setFilteredSites(disabledSites.map((s) => ({ site: s, indices: [] })));
      return;
    }
    const results = disabledSites
      .map((site) => {
        const res = fuzzyMatch(site, debouncedQuery);
        return res.isMatch ? { site, indices: res.indices } : null;
      })
      .filter(Boolean) as { site: string; indices: number[] }[];
    setFilteredSites(results);
  }, [disabledSites, debouncedQuery]);

  useEffect(() => {
    if (!showBlockedSitesPopup) setListHeight(null);
  }, [showBlockedSitesPopup]);

  useEffect(() => {
    if (!showBlockedSitesPopup) return;
    const measure = () => {
      const el = listRef.current;
      if (el) setListHeight(el.clientHeight);
    };
    if (!debouncedQuery || listHeight == null) {
      requestAnimationFrame(measure);
    }
  }, [showBlockedSitesPopup, debouncedQuery, filteredSites.length, listHeight]);

  useEffect(() => {
    // Initial check for context value
    chrome.storage.local.get(['context'], (result) => {
      setContextData(result.context);
    });

    // Add listener for storage changes
    const handleStorageChange = (changes: { [key: string]: chrome.storage.StorageChange }, areaName: string) => {
      if (areaName === 'local' && changes.context) {
        setContextData(changes.context.newValue);
        setIsLoading(false);
      }
    };

    chrome.storage.onChanged.addListener(handleStorageChange);

    // Cleanup listener on unmount
    return () => {
      chrome.storage.onChanged.removeListener(handleStorageChange);
    };
  }, []);

  useEffect(() => {
    getLastAnalyzedDate().then(date => setLastAnalyzedDate(date));
  }, [contextData]);

  const removeChatMessagesFromLocalStorage = async () => {
    try {
      await chrome.storage.local.remove(['chatMessages']);
    } catch (error) {
      console.error('Error removing chat messages from storage:', error);
    }
  };

  const handleClearChat = async () => {
    setIsClearingChat(true);
    await handleAibackendDelete(`/extension/delete_conversation`, {
      mentor_ai_id: mentoraiData?.recordId,
      user_id: menteeData?.recordId
    });
    fetchMessages();
    setChatMessages([]);
    await removeChatMessagesFromLocalStorage();
    chrome.runtime.sendMessage({
      action: "sendAnalytics", url: window.location.href, eventName: 'Button Clicked', eventProperties: {
        button_name: "Clear Chat",
        location: "Popup"
      }
    })
    setIsClearingChat(false);
    setShowClearChatPopup(false);
    setShowSettings(false);
    toast(
      <div className="bg-transparent pr-[40px]">
        <div className="flex items-center gap-2 py-2 px-3 h-7 rounded bg-[#4b4e63] text-[#f2f2f2] text-xs font-medium leading-[1.125rem] mb-[96px]">
          Chat Cleared
        </div>
      </div>
      , {
        position: 'bottom-center',
        icon: <></>
      });
  }

  const handleReAnalyze = (e: React.MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    setIsLoading(true);
    chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
      const tabId = tabs[0].id;
      if (tabId) {
        chrome.tabs.sendMessage(tabId, { action: "triggerProfileDataCollection" }).then((response) => {
          if (response.status === "error") {
            setTimeout(async () => {
              setLiveMessages([{
                props: {
                  model: {
                    id: new Date().getTime().toString(),
                    message: `It seems like you are logged out of leetcode. Thus I'm unable to access your profile. Continuing with your query for now. I can later analyse your profile. Once you've signed in to leetcode, you can re-analyse from the settings icon below ⬇️.
                        `,
                    sentTime: new Date().getTime().toString(),
                    sender: "assistant",
                    direction: "incoming",
                    position: "single",
                    senderPhotoUrl: mentoraiData?.aiPhotoUrl,
                    senderName: mentoraiData?.name,
                  },
                  children: <></>,
                },
              }]);
            }, 2000)
          }
        });
      }
    });
    setShowSettings(false);
    chrome.runtime.sendMessage({
      action: "sendAnalytics", url: window.location.href, eventName: 'Button Clicked', eventProperties: {
        button_name: contextData ? "Re-Analyze" : "Allow",
        location: "Settings"
      }
    })
  }

  const getLastAnalyzedDate = async () => {
    const activeTab = await chrome.tabs.query({ active: true, currentWindow: true });
    const currentUrlOrigin = activeTab[0].url ? new URL(activeTab[0].url).origin : '';
    if (currentUrlOrigin) {
      const profileAnalysisData = contextData?.[currentUrlOrigin]?.["profile-data"]?.timestamp;

      if (profileAnalysisData) {
        const lastAnalyzedDate = new Date(profileAnalysisData);
        const daysSinceLastAnalyzed = Math.floor((new Date().getTime() - lastAnalyzedDate.getTime()) / (1000 * 60 * 60 * 24));
        if (daysSinceLastAnalyzed < 1) {
          return 'Today';
        } else if (daysSinceLastAnalyzed < 7) {
          return `${daysSinceLastAnalyzed} days ago`;
        } else if (daysSinceLastAnalyzed < 30) {
          return `${daysSinceLastAnalyzed} weeks ago`;
        } else if (daysSinceLastAnalyzed < 365) {
          return `${daysSinceLastAnalyzed} months ago`;
        } else {
          return `${daysSinceLastAnalyzed} years ago`;
        }
        // return lastAnalyzedDate.toLocaleString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
      }
    }
    return 'Never';
  }

  const buttonText = contextData ? 'Re-Analyze' : 'Allow'
  const subText = contextData
    ? `Last analysed ${lastAnalyzedDate}`
    : 'For personalised responses'


  const handleClickOutsideOfClearChatPopup = (e: React.MouseEvent<HTMLDivElement>) => {
    if (clearChatPopupRef.current && !clearChatPopupRef.current.contains(e.target as Node)) {
      setShowClearChatPopup(false);
    }
  }

  const [showBlockedSitesDisabledTooltip, setShowBlockedSitesDisabledTooltip] = useState(false)

  return (
    <div className="relative w-full bg-mentorai-bg-black rounded-t-xl flex flex-col font-bricolage-grotesque max-h-[calc(90vh)] overflow-y-auto scrollbar-hide p-5  border-t border-t-mentorai-stroke-strong">
      <MentorAiActiveAvatar avatarSrcOrUrl={LeecoMech} mentoraiData={mentoraiData} indicatorClassName="hidden" avatarClassName="w-[54px] h-[54px] rounded-full object-contain" />
      <div className="flex flex-col gap-1 mt-[12px]">
        <div className="font-medium text-[18px] leading-[22px] text-mentorai-text-white tracking-[-0.36px]">
          Settings
        </div>
        <div className="text-[12px] leading-[16px] text-mentorai-text-sub font-manrope font-medium">
          Configure the way Leeco Interacts with you
        </div>
      </div>

      <div className="flex flex-col gap-6 mt-[32px]">
        {showAnalyzeButton &&
          <div className="flex gap-1 justify-between">
            <div className="flex flex-col gap-1">
              <h6 className="text-mentorai-text-white font-[500] text-[14px] tracking-[0.12px] whitespace-nowrap leading-[17px]">LeetCode Profile Analysis</h6>
              <p className={cn("text-mentorai-text-sub text-[12px] leading-[16px] font-manrope font-medium ")}>{subText}</p>
            </div>
            <MentorAiButton style={{
              minWidth: "90px",
              maxWidth: "90px"
            }}
              disabled={isLoading} type="outlined" size="small" classNames="!text-xs   !whitespace-nowrap !px-2" onClick={handleReAnalyze}>
              {isLoading ?
                <LoaderWithThreeDots height="10px" width="18px" /> :
                buttonText}
            </MentorAiButton>
          </div>
        }

        <div className="flex gap-1 justify-between">
          <div className="flex flex-col gap-1">
            <h6 className="text-mentorai-text-white font-[500] text-[14px] tracking-[0.12px] whitespace-nowrap leading-[17px]">
              Chat History
            </h6>
            <p className={cn("text-mentorai-text-sub text-[12px] leading-[16px] font-manrope font-medium ")}>
              {chatUsageData.isPaidUser ? 'Start fresh by clearing your chat' : 'Clear Chat is available for paid users'}
            </p>
          </div>
          <MentorAiButton disabled={isClearingChat || !chatUsageData.isPaidUser} type="outlined" size="small" classNames="!text-xs   !whitespace-nowrap !max-w-[90px] !min-w-[90px] !w-[90px] !px-2"
            onClick={() => {
              setShowClearChatPopup(true)
              chrome.runtime.sendMessage({
                action: "sendAnalytics", url: window.location.href, eventName: 'Button Clicked', eventProperties: {
                  button_name: "Clear Chat",
                  location: "Settings"
                }
              })
            }}
          >
            Clear Chat
          </MentorAiButton>
        </div>
      </div>

      {showClearChatPopup && (
        <>
          <div
            onClick={handleClickOutsideOfClearChatPopup}
            className={`absolute w-full h-full bottom-0 left-0 bg-[rgba(0,0,0,0.6)]`}
          >
            <span className="invisible">.</span>
          </div>
          <motion.div
            ref={clearChatPopupRef}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 20 }}
            transition={{ type: "spring", stiffness: 500, damping: 30 }}
            className="flex flex-col p-4 absolute bottom-0 left-0 right-0 w-full bg-mentorai-bg-strong rounded-t-xl z-10">
            <p className="text-mentorai-text-white text-[14px] leading-[17px] font-medium tracking-[-0.14px]">All Chat will be deleted</p>
            <p className="text-[#94939F] text-[12px] leading-[18px] mt-1 font-manrope"> You will not be able to restore old messages. Mentor will also lose context of your current conversation.</p>
            <div className="flex gap-3 justify-between w-full mt-4">
              <MentorAiButton type="outlined" size="small" classNames="!text-xs !leading-[18px]   w-full !whitespace-nowrap !px-2" onClick={() => setShowClearChatPopup(false)}>
                Go Back
              </MentorAiButton>
              <MentorAiButton disabled={isClearingChat} type="error" size="small" classNames="!text-xs !leading-[18px]  w-full   !whitespace-nowrap !text-mentorai-red-300 hover:!bg-active-topic-hover !px-2" onClick={handleClearChat}>
                {isClearingChat ?
                  <LoaderWithThreeDots height="10px" width="18px" color="rgba(255,104,117,0.20)" /> :
                  "Okay, Clear"}
              </MentorAiButton>
            </div>
          </motion.div>
        </>
      )}


      <div className="flex justify-between items-center relative mt-[24px]">
        <div className="flex flex-col gap-1">
          <span className="text-mentorai-text-white font-[500] text-[14px] tracking-[0.12px] whitespace-nowrap leading-[17px]">Language</span>
          <span className="text-mentorai-text-sub text-[12px] leading-[16px] font-manrope font-medium ">Choose what you’re comfortable in</span>
        </div>

        <MentorAiButton style={{
          minWidth: "90px",
          maxWidth: "90px"
        }}
          customAttribute={{
            name: "data-clickaway-ignore",
            value: "language-popup"
          }}
          disabled={isClearingChat} type="outlined" size="small" classNames="!text-xs   !whitespace-nowrap !px-2" onClick={() => {
            setShowLanguagePopup(!showLanguagePopup)
            sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "MentorAi Settings Dropdown Clicked", {
              dropdown_type: "language",
              toggle_state: showLanguagePopup ? "closed" : "opened"
            });
          }}>
          <div className="flex gap-1 items-center justify-between w-full">
            <span className="max-w-[56px] truncate"> {language}</span>
            <span className={`${showLanguagePopup ? "-rotate-90" : ""}`} >
              <svg className={`w-[14px] h-[14px]`} xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 14 14" fill="none">
                <path d="M7.557 6.99955L4.95825 4.4008L5.7006 3.65845L9.0417 6.99955L5.7006 10.3406L4.95825 9.5983L7.557 6.99955Z" fill="#DDDDDF" />
              </svg>
            </span>
          </div>
        </MentorAiButton>


        {showLanguagePopup && (
          <ClickAwayListener onClickAway={() => setShowLanguagePopup(false)} ignoreKey="language-popup" triggerUseEffect className=" absolute bottom-[40px] right-0">
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: 20 }}
              transition={{ type: "spring", stiffness: 500, damping: 30 }}
              className={`shadow-[0px_4px_24px_0px_rgba(242,242,242,0.06)] w-[220px] bg-mentorai-bg-strong rounded-xl p-2 z-10`}
            >
              <div className="flex flex-col gap-2">
                {LANGUAGE_OPTIONS.map((option) => (
                  <label
                    onMouseEnter={() => setIsLanguageOptionHovered(option)}
                    onMouseLeave={() => setIsLanguageOptionHovered(null)}
                    key={option}
                    className={`flex items-center gap-2 py-0.5 pl-1 pr-1.5 h-[22px] text-xs cursor-pointer leading-[14px] hover:bg-[#2F3241] hover:text-[#DDDDDF] rounded ${language === option ? "text-[#DDDDDF]" : "text-[#94939F]"}`}
                    onClick={(e) => e.stopPropagation()}
                  >
                    {showCustomLanguageInput ? (option === "Other (specify)" ?
                      <img src={RadioSelectedIcon} alt="radio" /> : <img src={isLanguageOptionHovered === option ? RadioHoveredIcon : RadioUnselectedIcon} alt="radio" />) :
                      (<img src={isLanguageSelected(option) ? RadioSelectedIcon : isLanguageOptionHovered === option ? RadioHoveredIcon : RadioUnselectedIcon} alt="radio" />)}
                    <input
                      type="radio"
                      name="language"
                      className="hidden"
                      value={option}
                      checked={isLanguageSelected(option)}
                      onChange={handleLanguageChange}
                    />
                    {option}
                  </label>
                ))}
                {showCustomLanguageInput && (
                  <div className="relative mt-[-6px]">
                    <div className="cursor-pointer absolute right-[5px] top-[7px]" onClick={updateOtherLanguage}>
                      {otherLanguage ? (
                        <img src={PaperPlaneActive} alt='plane' />
                      ) : (
                        <img src={PaperPlane} alt='plane' />
                      )}
                    </div>
                    <input
                      type="text"
                      value={otherLanguage}
                      onChange={(e) => {
                        setOtherLanguage(e.target.value);
                        e.stopPropagation();
                        e.preventDefault();
                      }}
                      placeholder="e.g. Tamil"
                      className="w-[calc(100%-24px)] ml-6 focus:outline-none focus:ring-0 h-[32px] p-2 bg-mentorai-bg-strong placeholder:text-mentorai-text-disabled text-mentorai-text-soft border border-mentorai-stroke-strong text-xs rounded-[8px] text-[14px] leading-[18px] tracking-[-0.12px]"
                    />
                  </div>
                )}
              </div>
            </motion.div>
          </ClickAwayListener>
        )}
      </div>

      {mentoraiData?.name === "Leeco" &&
        <div className="flex justify-between items-center relative mt-[24px]">
          <div className="flex flex-col gap-1">
            <span className="text-mentorai-text-white font-[500] text-[14px] tracking-[0.12px] whitespace-nowrap leading-[17px]">Leeco’s Tone</span>
            <span className="text-mentorai-text-sub text-[12px] leading-[16px] font-manrope font-medium ">Choose what sounds best to you</span>
          </div>


          <MentorAiButton style={{
            minWidth: "90px",
            maxWidth: "90px"
          }}
            customAttribute={{
              name: "data-clickaway-ignore",
              value: "tone-popup"
            }}
            disabled={isClearingChat} type="outlined" size="small" classNames="!text-xs   !whitespace-nowrap !px-2" onClick={() => {
              setShowTonePopup(!showTonePopup)
              sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "MentorAi Settings Dropdown Clicked", {
                dropdown_type: "tone",
                toggle_state: showTonePopup ? "closed" : "opened"
              });
            }}>
            <div className="flex gap-1 items-center justify-between w-full">
              <span className="max-w-[56px] truncate"> {tone}</span>
              <span className={`${showTonePopup ? "-rotate-90" : ""}`} >
                <svg className={`w-[14px] h-[14px]`} xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 14 14" fill="none">
                  <path d="M7.557 6.99955L4.95825 4.4008L5.7006 3.65845L9.0417 6.99955L5.7006 10.3406L4.95825 9.5983L7.557 6.99955Z" fill="#DDDDDF" />
                </svg>
              </span>
            </div>
          </MentorAiButton>


          {showTonePopup && (
            <ClickAwayListener onClickAway={() => setShowTonePopup(false)} ignoreKey="tone-popup" triggerUseEffect className=" absolute bottom-[40px] right-0 ">
              <AnimatePresence>
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: 20 }}
                  transition={{ type: "spring", stiffness: 500, damping: 30 }}
                  className="shadow-[0px_4px_24px_0px_rgba(242,242,242,0.06)] w-[220px] bg-mentorai-bg-strong rounded-xl p-2 z-10"
                >
                  <div className="flex flex-col gap-2">
                    {TONE_OPTIONS.map((option) => (
                      <label
                        onMouseEnter={() => setIsToneOptionHovered(option)}
                        onMouseLeave={() => setIsToneOptionHovered(null)}
                        key={option}
                        className={`flex items-center gap-2 py-0.5 pl-1 pr-1.5 h-[22px] text-xs cursor-pointer leading-[14px] hover:bg-[#2F3241] hover:text-[#DDDDDF] rounded ${tone === option ? "text-[#DDDDDF]" : "text-[#94939F]"}`}
                        onClick={(e) => e.stopPropagation()}
                      >
                        <img src={tone === option ? RadioSelectedIcon : (isToneOptionHovered === option ? RadioHoveredIcon : RadioUnselectedIcon)} alt="radio" />
                        <input
                          type="radio"
                          name="tone"
                          className="hidden"
                          value={option}
                          checked={tone === option}
                          onChange={handleToneChange}
                        />
                        {option}
                      </label>
                    ))}
                  </div>
                </motion.div>
              </AnimatePresence>
            </ClickAwayListener>
          )}
        </div>
      }
        <hr className="border-mentorai-stroke-strong my-6" />
        <div className="flex gap-1 justify-between">
          <div className="flex items-center gap-1">
            <BlockIcon/>
            <p className="text-mentorai-text-white text-[14px] tracking-[0.12px] whitespace-nowrap leading-[17px]">
              Disabled Websites
            </p>
          </div>
          <Tippy
            delay={0}
            duration={0}
            visible={showBlockedSitesDisabledTooltip}
            content={
              <div className="bg-[#4B4E63] flex items-center h-[23px] justify-center text-mentorai-text-white font-manrope text-xs leading-[normal] tracking-[-0.12px] px-1.5 rounded-md">
                You haven't disabled Leeco on any website
              </div>
            }
            placement="top"
            key={`blocked-sites-popup`}
          >
            <button
              onMouseEnter={() => disabledSites.length === 0 && setShowBlockedSitesDisabledTooltip(true)}
              onMouseLeave={() => disabledSites.length === 0 && setShowBlockedSitesDisabledTooltip(false)}
              data-clickaway-ignore="blocked-sites-popup"
              className={cn("flex items-center cursor-pointer text-mentorai-text-sub", disabledSites.length === 0 && "cursor-not-allowed text-mentorai-text-disabled")} onClick={() => {
                if(disabledSites.length === 0) {
                  return
                }
                setShowBlockedSitesPopup((prev) => !prev)
            }}> 
              <p className="text-[12px] font-medium">{disabledSites.length}</p>
              <ArrowRightLineIcon className={`${showBlockedSitesPopup ? "rotate-0" : "rotate-90"} transition-all duration-300`} />
            </button>
          </Tippy>
        </div>
        {showBlockedSitesPopup && (
          <ClickAwayListener onClickAway={() => setShowBlockedSitesPopup(false)} ignoreKey="blocked-sites-popup" triggerUseEffect className=" absolute bottom-10 right-6">
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: 20 }}
              transition={{ type: "spring", stiffness: 500, damping: 30 }}
              className={`shadow-[0px_4px_24px_0px_rgba(242,242,242,0.06)] w-[221px] max-h-[205px] bg-mentorai-bg-strong rounded-xl p-2 z-10`}
            >
              <div className="flex flex-col gap-2">
                <div className="h-6 w-full rounded-lg overflow-hidden bg-mentorai-bg-sub flex items-center gap-2 p-2">
                  <SearchIcon/>
                  <input type="text" placeholder="Search a site..." className="w-full h-4 bg-transparent outline-none focus:outline-none" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
                </div>
                <div
                  ref={listRef}
                  className="flex flex-col gap-2 overflow-y-auto scrollbar-hide max-h-[157px]"
                  style={debouncedQuery ? { height: listHeight ?? undefined } : undefined}
                >
                  {filteredSites.length === 0 ? (
                    <div className="p-1 font-medium text-mentorai-text-disabled text-[12px] leading-[17px]">No results for your search :(</div>
                  ) : (
                    filteredSites.map(({ site, indices }) => (
                      <Tippy
                        key={site}
                        visible={blockedListHovered === site}
                        content={<div className="bg-[#4B4E63] flex items-center h-[23px] justify-center text-mentorai-text-white font-manrope text-xs leading-[normal] tracking-[-0.12px] px-1.5 rounded-md">
                          Remove
                        </div>}
                        placement="top"
                        delay={0}
                        duration={0}
                        offset={[-6, -7]}
                      >
                      <div 
                      key={site} onMouseEnter={() => setBlockedListHovered(site)} onMouseLeave={() => setBlockedListHovered(null)} 
                      className="p-1 rounded-lg transition-all duration-300 hover:bg-mentorai-bg-sub flex items-center gap-2 cursor-pointer" 
                      onClick={(e) => {
                        e.stopPropagation()
                        const newDisabledSites = disabledSites.filter((s) => s !== site)
                        if(newDisabledSites.length === 0) {
                          setShowBlockedSitesPopup(false)
                        }
                        setDisabledSites(newDisabledSites)
                        chrome.storage.local.set({
                          widget_disabled_sites: newDisabledSites
                        })
                        sendAnalyticsWithBackend(menteeData?.email || '', activeTabUrl, "Extension Enabled", {
                          disabled_for:"site",
                          disabled_url:site,
                          disabled_url_domain:site,
                        })
                      }}
                      >
                        <button>
                          <RemoveIcon/>
                        </button>
                        <p className="text-mentorai-text-soft text-[12px] leading-[17px] font-semibold">{debouncedQuery ? renderHighlighted(site, indices) : site}</p>
                      </div>
                      </Tippy>
                    ))
                  )}
                </div>
              </div>  
            </motion.div>
          </ClickAwayListener>
        )}
    </div>
  )
}

export default SettingsV2