import { useContext } from "react";
import CreateFirstPath from "./create-first-path/create-first-path";
import ChooseARecommendedPath from "./choose-recommended-path/choose-a-recommended-path";
import PathHeroImage from "../../assets/path-hero-image.webp";
import LearnSomethingNew from "./learn-something-new/learn-something-new";
import ContinueLatestPath from "./continue-latest-path/continue-latest-path";
import OtherActivePaths from "./other-active-paths/other-active-paths";
import { PageContext } from "../../context/page-context/page-context";

const Paths = () => {
  const { menteeCreatedPathsData } = useContext(PageContext);
  const latestPath = menteeCreatedPathsData?.length > 0 ? menteeCreatedPathsData[0] : null;
  const otherActivePaths = menteeCreatedPathsData?.length > 1 ? menteeCreatedPathsData?.slice(1) : [];

  return (
    <>
      {menteeCreatedPathsData?.length === 0 ? (
        <div className="p-3 flex flex-col h-full">
          <div className="flex-1 flex justify-center">
            <CreateFirstPath />
          </div>
          <div className="">
            <ChooseARecommendedPath itemsPerPage={1} />
          </div>
        </div>
      ) : (
        <main className="w-full h-full overflow-y-auto scrollbar-hide">
          <img src={PathHeroImage} alt="path-hemo-image.svg" className="w-full rounded-t-2xl mb-4 h-[128px]" />
          <div className="px-3 pb-3 space-y-10">
            <LearnSomethingNew />
            {latestPath && <ContinueLatestPath latestPath={latestPath} />}
            {otherActivePaths?.length > 0 && <OtherActivePaths autoRotate={false} otherActivePaths={otherActivePaths} />}
            <ChooseARecommendedPath autoRotate={false} />
          </div>
        </main>
      )}
    </>
  );
};

export default Paths;
