export const INTERVIEW_PROGRESS_THRESHOLDS = {
  Easy: {
    startTime: 1200, // 20 minutes in seconds
    thresholds: {
      WARNING: 300,  // 15 minutes in seconds
      DANGER: 10   // 5 minutes in seconds
    }
  },
  Medium: {
    startTime: 2400, // 40 minutes in seconds
    thresholds: {
      WARNING: 1800, // 30 minutes in seconds
      DANGER: 10   // 10 minutes in seconds
    }
  },
  Hard: {
    startTime: 3600, // 60 minutes in seconds
    thresholds: {
      WARNING: 2700, // 45 minutes in seconds
      DANGER: 10   // 15 minutes in seconds
    }
  },
  Unknown: {
    startTime: 1200,
    thresholds: {
      WARNING: 900,
      DANGER: 10
    }
  }
}

export const getInterviewProgress = (
  remainingTime: number,
  difficulty: 'Easy' | 'Medium' | 'Hard' | 'Unknown'
): number => {
  const difficultyThresholds = INTERVIEW_PROGRESS_THRESHOLDS[difficulty].thresholds;
  
  if (remainingTime <= difficultyThresholds.DANGER) {
    return 2;
  } else if (remainingTime <= difficultyThresholds.WARNING) {
    return 1;
  }
  return 0;
} 