import { useEffect, useState } from "react"
import { getFormattedPriceWithSymbol } from "../../../../../../../../utils/currency"

const usePlanCard = (plan: ExtensionPlan, selectedValidity: string, isOfferAvailable: boolean, handleChangePlan: (plan: string) => void, pricingVariant: string) => {
  const [planCardHover, setPlanCardHover] = useState('');
  // useEffect(() => {
  //   if (isOfferAvailable) {
  //     handleChangePlan("1 month")
  //   }
  // }, [isOfferAvailable]);

  let planTitle = ""
  let planSubtitle = ""
  let isRecommended = false
  let isSelected = false

  switch (plan.validity) {
    case "1 month":
      planTitle = "Monthly Plan"
      planSubtitle = `${getFormattedPriceWithSymbol(Math.round(plan.originalPrice))} / month`
      isRecommended = false
      isSelected = plan.validity === selectedValidity
      break;
    case "1 year":
      planTitle = "Yearly Plan"
      planSubtitle = `${getFormattedPriceWithSymbol(Math.round(plan.totalPrice / 12))} / month`
      isRecommended = true
      isSelected = plan.validity === selectedValidity
      break;
  }

  return {
    planTitle,
    planSubtitle,
    isRecommended,
    isSelected,
    planCardHover,
    setPlanCardHover
  }
}

export default usePlanCard
