import useLearnSomethingNew from "./use-learn-something-new";
import CreatePathSparkleVector from "../../../assets/create-path-sparkle-vector.svg";

const LearnSomethingNew = () => {
  const { search, handleSearchChange, searchQueriesList, handleCreatePathClick, handleKeyDown  } = useLearnSomethingNew();

  return (
    <div className="space-y-4">
      <div className="space-y-1">
        <p className="text-[#F2F2F2] text-[16px] font-medium -tracking-[0.16px] font-bricolage-grotesque">
          Learn something new today ✨
        </p>
        <p className="text-[#94939F] text-[12px] leading-[18px] font-medium font-manrope">What do you want to learn?</p>
      </div>

      <div className="p-3 space-y-5 border border-[#363645] rounded-xl">
        <div className="space-y-2">
          <div className="flex items-center gap-6">
            <input
              type="text"
              placeholder="I want to learn..."
              value={search}
              onChange={handleSearchChange}
              onKeyDown={handleKeyDown}
              className="flex-1 border-none outline-none placeholder:text-[#606071] text-[#fff] text-[14px] font-medium font-manrope bg-transparent w-[60%]"
            />
            <button
              onClick={() => handleCreatePathClick(search, false)}
              className="shrink-0 bg-[#5149F2] hover:bg-[#736DF2] text-[#DDDDDF] text-[12px] font-semibold leading-[18px] font-manrope py-1 px-2 rounded-lg"
            >
              Create Path
            </button>
          </div>
          <div className="w-full h-[1px] border-b border-[#45475F]" style={{ borderStyle: 'dashed', borderWidth: '0 0 1px 0', borderImage: 'repeating-linear-gradient(to right, #45475F 0, #45475F 4px, transparent 4px, transparent 8px) 1' }} />
        </div>
        <div className="w-full overflow-x-auto scrollbar-hide">
          <div className="flex gap-2 items-center">
            {searchQueriesList?.map((query) => (
              <button
                key={query}
                className="flex gap-1 shrink-0 items-center py-1.5 px-2 bg-[#212431] hover:bg-[#2F3241] rounded-lg border border-[#363645] text-[#DDDDDF] text-[12px] font-medium font-manrope"
                onClick={() => handleCreatePathClick(`I want to learn about ${query}`, true)}
              >
                <img src={CreatePathSparkleVector} alt="create-path-sparkle-vector.svg" />
                {query}
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default LearnSomethingNew;
