import Modal from "../../../../common/modal/modal"
import MentorAiButton from "../../../../common/button/mentorai-button"
import { useContext, useEffect, useState } from "react"
import ParticalAbstract from "../../../assets/partical-abstract.svg"
import { PageContext } from "../../../context/page-context/page-context"
import Loading from "../../../assets/loading.gif"
import YellowWarning from "../../../../src/assets/yellow-warning.svg"
import usePracticeFeedbackPopup from "./use-practice-feedback-popup"
import { motion } from "framer-motion"

type Props = {
  show: boolean
  handleClose: () => void
  chatMessages: any[]
}

const PracticeFeedbackPopup = ({ show, handleClose, chatMessages }: Props) => {
  const { setPracticeModeStatus, timer, scrapedData } = useContext(PageContext)
  const [isGeneratedPracticeFeedbackNotValid, setIsGeneratedPracticeFeedbackNotValid] = useState(false)
  const {
    ratingValues,
    selectedRatingAndOption,
    setSelectedRatingAndOption,
    ratingSelected,
    handleSelectRating,
    feedbackSubmitted,
    handleSubmitFeedback,
    isLoading,
    feedback,
    setFeedback,
    isSentMessagesLessThanFiveInPracticeMode
  } = usePracticeFeedbackPopup(chatMessages)

  const handleViewOnChat = () => {
    setPracticeModeStatus("PM_IDLE")
    chrome.storage.local.set({
      practiceModeStatus: "PM_IDLE",
    })
  }

  useEffect(() => {
    chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
      if (message.action === "generatedPracticeFeedbackIsNotValid") {
        setIsGeneratedPracticeFeedbackNotValid(true)
      }
    })
    return () => {
      chrome.runtime.onMessage.removeListener((message, sender, sendResponse) => {
        if (message.action === "generatedPracticeFeedbackIsNotValid") {
          setIsGeneratedPracticeFeedbackNotValid(true)
        }
      })
    }
  }, [])


  const getFeedbackHeader = () => {
    if (isLoading) {
      return (
        <div className="flex flex-col gap-1 font-bricolage-grotesque">
          <p className="flex items-center gap-1 text-xl font-medium leading-7 -tracking-[0.2px] text-mentorai-text-white">
            <img
              src={Loading}
              alt="loading"
              className="inline-block h-6 w-6"
            />
            Generating your report...
          </p>
          <span
            className="text-mentorai-primary-lighter cursor-pointer ml-[28px] text-sm leading-[22px] tracking-[-0.14px] opacity-50"
            onClick={() => { }}
          >
            View on Chat →
          </span>
        </div>
      )
    } else if (isGeneratedPracticeFeedbackNotValid) {
      return (
        <div className="flex flex-col gap-1 font-bricolage-grotesque">
          <p className="flex items-center gap-1 text-xl font-medium leading-7 -tracking-[0.2px] text-mentorai-text-white">
            <div className="w-6 h-6">
              <img src={YellowWarning} alt="yellow-warning" className="w-6 h-6" />
            </div>
            Could not generate your report
          </p>
          <span className="text-mentorai-text-sub text-sm leading-[1.375rem] tracking-[-0.14px]">Your responses were not detailed enough to make a proper report. Next time, try to aim for a minimum of 10 <span className="font-semibold text-mentorai-text-soft">detailed</span> messages! </span>
        </div>
      )
    } else {
      return (
        <div className="flex flex-col gap-1 font-bricolage-grotesque ">
          <p className="flex items-center gap-1 text-xl font-medium leading-7 -tracking-[0.2px] text-mentorai-text-white">
            <div className="w-6 h-6">
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="20"
                height="20"
                viewBox="0 0 20 20"
                fill="none"
              >
                <rect
                  x="2"
                  y="2"
                  width="16"
                  height="16"
                  rx="8"
                  fill="#3EE089"
                />
                <path
                  fillRule="evenodd"
                  clipRule="evenodd"
                  d="M14.5294 8.03039L8.99908 13.5607L5.46875 10.0304L6.52941 8.96973L8.99908 11.4394L13.4688 6.96973L14.5294 8.03039Z"
                  fill="#0B4627"
                />
              </svg>
            </div>
            Report generated!
          </p>
          <span
            className="text-mentorai-primary-lighter cursor-pointer ml-[28px] text-sm leading-[22px] tracking-[-0.14px]"
            onClick={handleViewOnChat}
          >
            View on Chat →
          </span>
        </div>
      )
    }
  }

  return (
    <Modal
      open={show}
      handleCloseOutside={isLoading ? () => { } : handleClose}
      className={{
        container: "rounded-t-[20px] rounded-b-[0px]",
        overlay:
          "!bg-[rgba(0,0,0,0.60)] backdrop-blur-[2px] !rounded-tl-[6px] !rounded-bl-[6px]",
      }}
    >
      <div className=" fixed bottom-0 left-0 flex items-center justify-center flex-col p-4 w-screen rounded-t-[20px] rounded-b-[0px] border-t border-t-mentorai-stroke-strong bg-practice-feedback-popup-bg font-bricolage-grotesque">
        <div className="absolute bottom-0 left-0 w-screen h-[102px] z-[0]">
          <img src={ParticalAbstract} alt="partical-abstract" className="w-full h-full" />
        </div>
        <div className="w-full">
          {getFeedbackHeader()}
        </div>

        {!isLoading &&
          <div className=" w-full h-px bg-mentorai-stroke-strong my-5"><span className="invisible">.</span> </div>
        }
        {!isLoading && !isGeneratedPracticeFeedbackNotValid &&
          (!feedbackSubmitted && (
            <div className="rounded-xl bg-[rgba(33,36,49,0.70)] p-3 gap-1 flex flex-col text-sm leading-[1.375rem] tracking-[0.084px] z-[1000]">
              <span className="text-mentorai-text-soft font-medium">
                How was this practice for you?
              </span>
              <span className="text-mentorai-text-sub mb-1">
                Your feedback will shape the future of this feature for developers.
              </span>
              <div className="flex justify-between mb-3">
                {ratingValues.map((item: any, index: number) => {
                  return (
                    <div
                      key={index}
                      className="flex flex-col items-start gap-1 self-stretch"
                    >
                      <div
                        className={`max-w-[42px] duration-50 flex h-[42px] w-[42px] cursor-pointer items-center justify-center rounded-xl gap-1 px-1 py-2 transition-all hover:rotate-[25deg] ${item.rating === selectedRatingAndOption.rating
                          ? "border border-mentorai-primary-base bg-mentorai-primary-darker"
                          : "hover:bg-[rgba(223,222,229,0.10)] "
                          }`}
                        onClick={() => {
                          setSelectedRatingAndOption({
                            rating: item.rating,
                            options: item.options,
                            text: item.text,
                            id: item.id,
                          })
                          handleSelectRating(item.rating)
                        }}
                      >
                        {item.emoji && (
                          <img src={item.emoji} alt={item.rating} />
                        )}
                      </div>
                      <p
                        className={`w-[42px] text-center text-xs leading-[normal] tracking-[0.12px] ${item.rating === selectedRatingAndOption.rating
                          ? "text-mentorai-text-white"
                          : "text-mentorai-text-sub "
                          }`}
                      >
                        {item.rating}
                      </p>
                    </div>
                  )
                })}
              </div>
              {ratingSelected && (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: 10 }}
                  transition={{ duration: 0.15, ease: "easeInOut" }}
                  className="flex flex-col items-start gap-1 self-stretch mb-3">
                  <textarea
                    className="w-full h-20 rounded-xl border border-mentorai-stroke-strong bg-mentorai-bg-base p-2 text-sm leading-[1.375rem] tracking-[0.084px] text-mentorai-text-white placeholder:text-mentorai-text-disabled placeholder:text-sm placeholder:leading-[1.375rem] placeholder:tracking-[0.14px]"
                    placeholder="Can you tell us a bit more? (optional)"
                    autoFocus={false}
                    onChange={(e) => {
                      setFeedback(e.target.value)
                    }}
                  />
                </motion.div>
              )}
              <MentorAiButton
                onClick={() => handleSubmitFeedback(selectedRatingAndOption.rating)}
                type="neutral"
                size="medium"
                classNames="w-full z-[1]"
                disabled={!ratingSelected || isLoading}
              >
                <div className="text-sm font-medium leading-[1.375rem]">
                  Submit Feedback →
                </div>
              </MentorAiButton>
            </div>
          ))}

        {!isLoading && isGeneratedPracticeFeedbackNotValid &&
          <MentorAiButton
            onClick={() => handleViewOnChat()}
            type="primary"
            size="medium"
            classNames="w-full z-[1]"
          >
            <div className="text-sm font-medium leading-[1.375rem]">
              ← Back to Chat
            </div>
          </MentorAiButton>
        }

        {feedbackSubmitted && (
          <div className="rounded-xl border border-mentorai-stroke-strong bg-mentorai-bg-strong p-3 w-full">
            <p className="text-mentorai-text-sub text-center text-sm leading-[1.375rem] tracking-[0.084px]">{`Thanks for the feedback :)`}</p>
          </div>
        )}
      </div>
    </Modal>
  )
}

export default PracticeFeedbackPopup
