import { useEffect, useRef, MutableRefObject } from 'react';

type Props = {
  triggerUseEffect: boolean;
  onClickAway?: () => void;
  children: React.ReactElement;
  className?: string;
  ignoreKey?: string;
};

const useClickAwayHandler = (
  ref: MutableRefObject<HTMLElement | null>,
  onClickAway: () => void,
  triggerUseEffect: boolean,
  ignoreKey?: string
) => {
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      event.stopPropagation();
      // If click is inside the wrapper, do nothing
      if (ref.current && ref.current.contains(event.target as Node)) {
        return;
      }
      // If click is on an element (or its ancestor) with data-clickaway-ignore matching ignoreKey, do nothing
      let node = event.target as HTMLElement | null;
      if (ignoreKey) {
        while (node) {
          if (node.getAttribute && node.getAttribute('data-clickaway-ignore') === ignoreKey) {
            return;
          }
          node = node.parentElement;
        }
      }
      onClickAway();
    }

    // Bind the event listener
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      // Unbind the event listener on clean up
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [ref, triggerUseEffect, onClickAway, ignoreKey]);
};

const ClickAwayListener = (props: Props) => {
  const { onClickAway = () => { }, triggerUseEffect, children, className, ignoreKey } = props;
  const wrapperRef = useRef<HTMLDivElement | null>(null);
  useClickAwayHandler(wrapperRef, onClickAway, triggerUseEffect, ignoreKey);

  return <div className={className} ref={wrapperRef}>{children}</div>;
};

ClickAwayListener.defaultProps = {
  triggerUseEffect: false,
  onClickAway: () => { },
  className: ''
};

export default ClickAwayListener;
