import { createContext } from "react"
import { Mentee } from "../../types/type"

type MenteeContextType = {
  menteeData: Mentee | null
  setMenteeData: Function
  menteeSubscription: any
  setMenteeSubscription: Function
  menteeDataLoading: boolean
}

const defaultFunction = () => {
  console.log("Default function called")
}

const defaultContextValues: MenteeContextType = {
  menteeData: null,
  setMenteeData: defaultFunction,
  menteeSubscription: null,
  setMenteeSubscription: defaultFunction,
  menteeDataLoading: false,
}

export const MenteeContext =
  createContext<MenteeContextType>(defaultContextValues)
