import { useEffect, useState } from "react";

const usePurchaseSuccessNotification = (sendMessage: Function) => {
  const [isOpen, setIsOpen] = useState(false);

  const handlePurchaseSuccess = (message: any) => {
    if (message.action === "purchaseSuccess") {
      setIsOpen(true);
      chrome.storage.local.set({ 'isExpiredPopupShownAlready': false });
    }
  };

  useEffect(() => {
    chrome.runtime.onMessage.addListener(handlePurchaseSuccess);

    return () => {
      chrome.runtime.onMessage.removeListener(handlePurchaseSuccess);
    };
  }, []);

  const handleClose = async () => {
    const activeTab: any = await chrome.tabs.query({ active: true, currentWindow: true });

    if (activeTab?.[0]?.url.includes("/checkout/extension")) {
      await chrome.tabs.remove(activeTab[0].id);
    }

    const { pendingMessage } = await chrome.storage.local.get("pendingMessage");
    if (pendingMessage && pendingMessage?.message) {
      sendMessage(pendingMessage?.message, true);
      chrome.storage.local.remove("pendingMessage");
    }

    setIsOpen(false);
  };

  return {
    isOpen,
    handleClose,
  };
};

export default usePurchaseSuccessNotification;
